R["Wave/Modules/Services.lua"] = function(...)
local ServiceCache = {}
local GetService = game.GetService

local CloneRefServices = {
    CoreGui = true,
    RunService = true
}

local NoCloneRefServices = {
    Players = true
}

getgenv().Services = setmetatable({}, {
    __index = function(self, ServiceName)
        local Cache = ServiceCache[ServiceName]
        if Cache then
            return Cache
        end
        
        local ShouldCloneRef = CloneRefServices[ServiceName] and not NoCloneRefServices[ServiceName]
        local Service = ShouldCloneRef and cloneref(GetService(game, ServiceName)) or GetService(game, ServiceName)
        
        ServiceCache[ServiceName] = Service
        return Service
    end
})

return Services
end

R["Wave/Modules/Utility.lua"] = function(...)
local Utility = {}
Utility.__index = Utility

local MetaUtility = setmetatable({
	NameCallMethods = {},
	_initialized = false
}, {
	__index = function(self, key)
		return Utility[key]
	end,
	__newindex = function(self, key, value)
		rawset(self, key, value)
	end,
	__call = function(self)
		return setmetatable({}, self)
	end
})

