function Utility:PrintTable(Table, Index)
	Index = Index or 0
	local Spacing = string.rep("  ", Index)

	if type(Table) ~= "table" then
		print("The provided argument is not a table.")
		return
	end

	for Key, Value in pairs(Table) do
		if type(Value) == "table" then
			print(Spacing .. tostring(Key) .. ":")
			self:PrintTable(Value, Index + 1)
		else
			print(Spacing .. tostring(Key) .. " = " .. tostring(Value))
		end
	end
end

function Utility:CheckFile(File)
	return isfile("Wave-Hub/" .. File)
end

function Utility:ListFiles(Location)
	return listfiles("Wave-Hub/" .. Location)
end

function Utility:ListManager(Location, KeepExtension)
	local Files = listfiles("Wave-Hub/" .. Location)
	local Results = {}

	for _, Path in ipairs(Files) do
		local Name = string.match(Path, "[^\\/]+$") or Path

		if not KeepExtension then
			Name = string.match(Name, "^(.*)%.") or Name
		end

		Results[Name] = Path
	end

	return Results
end

function Utility:ReadFile(File, Parameter)
	local FilePath
	local FileName = string.match(File, "[^/\\]+$") or File

	if string.sub(File, 1, 9) == "Wave-Hub/" or string.sub(File, 1, 9) == "Wave-Hub\\" then
		FilePath = File
	else
		FilePath = "Wave-Hub/" .. File
	end

	local Success, Result = pcall(function()
		return loadstring(readfile(FilePath) or nil)
	end)

	if not Success then
		print("Error in " .. FileName .. "| ReadFile:", Result)
		return nil
	end

	return Result
end

function Utility:LoadFile(File, Parameter)
	local FileName = string.match(File, "[^/\\]+$") or File
	local FilePath = (string.sub(File, 1, 9) == "Wave-Hub/" or string.sub(File, 1, 9) == "Wave-Hub\\")
		and File or "Wave-Hub/" .. File

	local FileContent
	local Success, ErrorMessage = pcall(function()
		FileContent = readfile(FilePath)
	end)

	if not Success then
		warn("Failed to read file:", FileName, "| Error:", ErrorMessage)
		return nil
	end

	if type(FileContent) == "table" then
		return FileContent
	elseif type(FileContent) ~= "string" then
		warn("Unsupported file content type for:", FileName, "| Got:", typeof(FileContent))
		return nil
	end

	local Chunk, LoadError = loadstring(FileContent, Parameter or FileName)
	if not Chunk then
		warn("Failed to compile file:", FileName, "| Error:", LoadError)
		return nil
	end

	local Result
	local ExecSuccess, ExecError = pcall(function()
		Result = Chunk()
	end)

	if not ExecSuccess then
		warn("Failed to execute file:", FileName, "| Error:", ExecError)
		return nil
	end

	return Result
end

function Utility:LoadAddon(AddonName)
	local FileDirectory = ("Wave-Hub/Games/Addons/%s Addons/"):format(GameLoading) .. AddonName .. ".lua"
	local FileToCheck = isfile(FileDirectory)

	if not FileToCheck then
		return nil
	end

	return loadstring(readfile(FileDirectory))()
end

function Utility:IsSetting(Setting, Globalize, Path)
	local FileDirectory = "WaveHubSettings/settings/startup/" .. Setting .. ".wave"
	local FileToCheck = isfile(FileDirectory)

	if Globalize then
		getgenv()[Setting] = FileToCheck
	end

	return Path and FileDirectory or FileToCheck
end

function Utility:SaveOpened(Check, Save)
	local FullPath = self:IsSetting("TerminalSaved", false, true)

	if Check then
		if not isfile(FullPath) and Save then
			writefile(FullPath, "")
		elseif isfile(FullPath) and not Save then
			delfile(FullPath)
		end
	end

	return isfile(FullPath)
end

function Utility:LoadActor(File, Actor)
	if getgenv().WaveRunningOnActor then
		return "Running"
	end

	if getgenv().WAVE_BUNDLE_MODE and getgenv().WAVE_ACTOR_INIT then
		local InitCode = getgenv().WAVE_ACTOR_INIT()
		run_on_actor(Actor, InitCode)

		run_on_actor(Actor, [=[
			getgenv().WaveRunningOnActor = true
		]=])
	else
		run_on_actor(Actor, [=[
			getgenv().WaveRunningOnActor = true
		]=])
	end

	local FilePath
	if string.sub(File, 1, 9) == "Wave-Hub/" or string.sub(File, 1, 9) == "Wave-Hub\\" then
		FilePath = File
	else
		FilePath = "Wave-Hub/" .. File
	end

	local FileContent = readfile(FilePath)
	run_on_actor(Actor, FileContent)

	return "Initiated"
end

function Utility:SecureCallFunction(DesiredOutcome)
	local function SecuredFunction()
		setthreadidentity(2)
		DesiredOutcome()
		setthreadidentity(7)
	end
	
	return SecuredFunction()
end

-- GUI-only edition: unused remote interception utilities removed.

function Utility:VirtualInputMachineClick(Element)
	local Inset = Services.Services.GuiService:GetGuiInset()
	local GuiElement = Element
	local AbsPos = GuiElement.AbsolutePosition
	local AbsSize = GuiElement.AbsoluteSize

	local ClickX = AbsPos.X + (AbsSize.X / 2) + Inset.X
	local ClickY = AbsPos.Y + (AbsSize.Y / 2) + Inset.Y

	VirtualInputMachine:SendMouseButtonEvent(ClickX or 0, ClickY or 0, 0, true, game, 1)
	task.wait(0.1)
	VirtualInputMachine:SendMouseButtonEvent(ClickX or 0, ClickY or 0, 0, false, game, 1)
end

function Utility:SendKey(Key, Time, EndTime)
	VirtualInputMachine:SendKeyEvent(true, Enum.KeyCode[Key], false, game)
	task.wait(Time or 0)
	VirtualInputMachine:SendKeyEvent(false, Enum.KeyCode[Key], false, game)
end

function Utility:FindBestServer(GameId)
	local Success, Result = pcall(function()
		return self:ExecuteHTTPGet("https://games.roblox.com/v1/games/" .. GameId .. "/servers/Public?sortOrder=Asc&limit=100")
	end)

	if not Success then
		return nil
	end

	local Data = Services.Services.HttpService:JSONDecode(Result)
	if not Data or not Data.data then
		return nil
	end

	for _, Server in ipairs(Data.data) do
		if Server.playing > 5 and Server.playing < Server.maxPlayers - 2 then
			return Server.id
		end
	end

	if #Data.data > 0 then
		return Data.data[1].id
	end

	return nil
end

function Utility:TeleportToGame(GameName, Options)
	Options = Options or {}

	local GameInfo = nil
	for _, Game in ipairs(GameData) do
		if Game.Name == GameName then
			GameInfo = Game
			break
		end
	end

	if not GameInfo then
		self:Notify("Teleport Error", "Game '" .. GameName .. "' not found in database.", 5)
		return false
	end

	if not GameInfo.Available then
		self:Notify("Coming Soon", GameName .. " teleport will be available soon!", 3)
		return false
	end

	local GameId = GameInfo.Id
	if type(GameId) == "table" then
		GameId = GameId[1]
	end

	if GameId == 0 then
		self:Notify("Coming Soon", GameName .. " teleport will be available soon!", 3)
		return false
	end

	self:Notify("Teleporting", "Preparing to teleport to " .. GameName .. "...", 3)

	wait(1)

	local TeleportOptions = Instance.new("TeleportOptions")

	if Options.ReserveServer then
		TeleportOptions.ReservedServerAccessCode = Options.ReserveServer
	end

	if Options.ServerJobId then
		TeleportOptions.ServerInstanceId = Options.ServerJobId
	elseif Options.FindBestServer then
		local BestServerId = self:FindBestServer(GameId)
		if BestServerId then
			TeleportOptions.ServerInstanceId = BestServerId
			self:Notify("Server Found", "Found a good server! Teleporting...", 2)
		end
	end

	local Success, ErrorMessage = pcall(function()
		Services.Services.TeleportService:TeleportAsync(GameId, {self:GetPlayer()}, TeleportOptions)
	end)

	if not Success then
		local FriendlyMessage = "Failed to teleport. Please check your internet connection."

		if string.find(ErrorMessage, "unauthorized") or string.find(ErrorMessage, "Unauthorized") then
			FriendlyMessage = "Please enable 'Allow Third Party Teleports' in your Roblox account settings."
		elseif string.find(ErrorMessage, "flooded") then
			FriendlyMessage = "Too many teleport requests. Please wait 30 seconds and try again."
		elseif string.find(ErrorMessage, "not found") then
			FriendlyMessage = "Game is currently unavailable. Please try again later."
		end

		self:Notify("Teleport Failed", FriendlyMessage, 7)
		return false
	end

	return true
end

function Utility:TeleportWithPrompt(GameName, Options)
	self:Prompt(false, "Are you sure you want to teleport to " .. GameName .. "?", {
		FirstName = "Yes",
		SecondName = "Cancel",
		FirstCallback = function()
			self:TeleportToGame(GameName, Options)
		end,
		SecondCallback = function()
			self:Notify("Cancelled", "Teleport cancelled.", 2)
		end,
	})
end

function Utility:GetGameLink(GameName)
	for _, GameInfo in ipairs(GameData) do
		if GameInfo.Name == GameName then
			return GameInfo.Link
		end
	end
	return nil
end

function Utility:CopyGameLink(GameName)
	local Link = self:GetGameLink(GameName)
	if Link then
		setclipboard(Link)
		self:Notify("Link Copied", "Game link copied to clipboard!", 3)
	else
		self:Notify("Error", "Game link not available.", 3)
	end
end

function Utility:QueueScript()
	if not getgenv().QueuedTeleport then
		queue_on_teleport(readfile("Wave-Hub/Script-Loader.lua"))
		getgenv().QueuedTeleport = true
	end
end

function Utility:DisableResetOnSpawn()
	Maid.ScreenGuisWithResetOnSpawn = {}
	local UserInterface = self:GetUserInterface()
	if UserInterface then
		for _, Object in pairs(UserInterface:GetChildren()) do
			if Object:IsA("ScreenGui") and Object.ResetOnSpawn then
				table.insert(Maid.ScreenGuisWithResetOnSpawn, Object)
				Object.ResetOnSpawn = false
			end
		end
	end
end

function Utility:EnableResetOnSpawn()
	for _, ScreenGui in pairs(Maid.ScreenGuisWithResetOnSpawn) do
		if ScreenGui and ScreenGui.Parent then
			ScreenGui.ResetOnSpawn = true
		end
	end
	Maid.ScreenGuisWithResetOnSpawn = {}
end

function Utility:CreateCommunicationChannel()
	local Identity, Channel = create_comm_channel()
	return Identity, Channel
end

function Utility:ExecuteFunction(Arguments)
	return function()
		local OnStart = Arguments.OnStart
		local Callback = Arguments.Callback
		local OnCompleted = Arguments.OnCompleted

		local Results = {
			OnStartResult = nil,
			CallbackResult = nil,
			OnCompletedResult = nil,
			StartingNotification = nil,
			Success = true,
			Errors = {},
		}

		if OnStart and type(OnStart) == "function" then
			local Success, Result = pcall(OnStart)
			if Success then
				Results.OnStartResult = Result
			else
				Results.Success = false
				table.insert(Results.Errors, {Stage = "OnStart", Error = Result})
			end
		elseif OnStart and type(OnStart) == "string" then
			local Notification = WaveLibrary:Notify({
				Title = getgenv().WaveLibrary.Settings.Title,
				Description = (OnStart)
			})

			if Arguments.StartingLoadingEffect then
				Results.StartingNotification = Notification

				task.spawn(function()
					local Dots = {"", ".", "..", "..."}
					local Index = 1

					while Arguments.StartingLoadingEffect do
						Notification:UpdateDescription(OnStart .. Dots[Index])
						Index = Index % #Dots + 1
						task.wait(0.25)
					end
				end)
			end
		end

		if Callback and type(Callback) == "function" then
			local Success, Result = pcall(Callback)
			if Success then
				Results.CallbackResult = Result
			else
				Results.Success = false
				table.insert(Results.Errors, {Stage = "Callback", Error = Result})
			end
		end

		if OnCompleted and type(OnCompleted) == "function" then
			local Success, Result = pcall(OnCompleted)
			if Success then
				Results.OnCompletedResult = Result
			else
				Results.Success = false
				table.insert(Results.Errors, {Stage = "OnCompleted", Error = Result})
			end
		elseif OnCompleted and type(OnCompleted) == "string" then
			if Results.StartingNotification then
				Results.StartingNotification:Cancel()
			end

			WaveLibrary:Notify({
				Title = getgenv().WaveLibrary.Settings.Title,
				Description = (OnCompleted)
			})
		end

		return Results
	end
end

function Utility:ExecuteHTTPGet(Link, Async)
	return Async and game:HttpGetAsync(Link) or game:HttpGet(Link)
end

function Utility:RenderWait(Time)
	return function()
		local Current = tick()
		Time = Time or 0

		repeat Services.RunService.Heartbeat:Wait()
		until tick() - Current >= Time

		return tick() - Current
	end
end

function Utility:KillMaidInstance(Name)
	if Maid[Name] then
		if type(Maid[Name]) == "thread" then
			task.cancel(Maid[Name])
		elseif type(Maid[Name]) == "RBXScriptConnection" then
			Maid[Name]:Disconnect()
		end
	end
	Maid[Name] = nil
end

function Utility:Reload()
	if getgenv().WaveLibrary then
		WaveLibrary:Unload()
	end
end

function Utility:IsWaveExecutor()
	return getexecutorname():match("Wave") ~= nil
end

function Utility:IsPremiumHubUser()
	return true
end

function Utility:CheckHubStatus(PrimaryAccentColor)
	if self:IsWaveExecutor() and not self:IsPremiumHubUser() then
		return '<font color="rgb(0,255,0)">Free</font>'
	elseif self:IsWaveExecutor() and self:IsPremiumHubUser() then
		return string.format('<font color="rgb(%d,%d,%d)">Premium</font>', PrimaryAccentColor.R * 255, PrimaryAccentColor.G * 255, PrimaryAccentColor.B * 255)
	end

	return '<font color="rgb(128,128,128)">Demo</font>'
end

-- [packed] Services is provided by the bundle bootstrap

return MetaUtility
end

R["Wave/Modules/Maid.lua"] = function(...)
local Maid = {}
Maid.ClassName = "Maid"

function Maid.New()
	return setmetatable({
		_Tasks = {}
	}, Maid)
end

function Maid.IsMaid(Value)
	return type(Value) == "table" and Value.ClassName == "Maid"
end

function Maid:__index(Index)
	if Maid[Index] then
		return Maid[Index]
	else
		return self._Tasks[Index]
	end
end

function Maid:__newindex(Index, NewTask)
	if Maid[Index] ~= nil then
		error(string.format("Cannot use '%s' as a Maid key", tostring(Index)), 2)
	end

	local Tasks = self._Tasks
	local OldTask = Tasks[Index]

	if OldTask == NewTask then
		return
	end

	Tasks[Index] = NewTask

	if OldTask then
		self:_CleanupTask(OldTask)
	end
end

function Maid:_CleanupTask(Task)
	local TaskType = typeof(Task)

	if TaskType == "function" then
		Task()
	elseif TaskType == "thread" then
		local Success = pcall(function()
			if coroutine.status(Task) ~= "dead" then
				task.cancel(Task)
			end
		end)

		if not Success then
			task.defer(function()
				pcall(task.cancel, Task)
			end)
		end
	elseif TaskType == "RBXScriptConnection" then
		if Task.Connected then
			Task:Disconnect()
		end
	elseif TaskType == "Instance" then
		if Task.Parent ~= nil then
			Task:Destroy()
		end
	elseif TaskType == "table" then
		if type(Task.Destroy) == "function" then
			Task:Destroy()
		elseif type(Task.Disconnect) == "function" then
			Task:Disconnect()
		end
	end
end

function Maid:Add(Task)
	if not Task then
		error("Task cannot be false or nil", 2)
	end

	local TaskId = #self._Tasks + 1
	self._Tasks[TaskId] = Task

	if type(Task) == "table" and (not Task.Destroy) and (not Task.Disconnect) then
		warn("[Maid.Add] - Gave table task without .Destroy or .Disconnect\n\n" .. debug.traceback())
	end

	return Task
end

function Maid:GiveTask(Task)
	if not Task then
		error("Task cannot be false or nil", 2)
	end

	local TaskId = #self._Tasks + 1
	self._Tasks[TaskId] = Task

	if type(Task) == "table" and (not Task.Destroy) and (not Task.Disconnect) then
		warn("[Maid.GiveTask] - Gave table task without .Destroy or .Disconnect\n\n" .. debug.traceback())
	end

	return TaskId
end

function Maid:GivePromise(Promise)
	if not Promise:IsPending() then
		return Promise
	end

	local NewPromise = Promise.resolved(Promise)
	local Id = self:GiveTask(NewPromise)

	NewPromise:Finally(function()
		self[Id] = nil
	end)

	return NewPromise
end

function Maid:AddCleanupTask(Task)
	if typeof(Task) ~= "function" then
		return
	end

	if not self._CleanupTasks then
		self._CleanupTasks = {}
	end
	
	table.insert(self._CleanupTasks, Task)
end

function Maid:DoCleaning()
	local PrecleanupTasks = self._CleanupTasks
	local Tasks = self._Tasks

	if PrecleanupTasks then
		for _, Task in pairs (PrecleanupTasks) do
			Task()
		end
	end

	local TasksToClean = {}
	for Index, Task in pairs(Tasks) do
		TasksToClean[Index] = Task
		Tasks[Index] = nil
	end

	for _, Task in pairs(TasksToClean) do
		self:_CleanupTask(Task)
	end
end

function Maid:Destroy()
	local Tasks = self._Tasks

	local TaskSnapshot = {}
	for Index, Task in pairs(Tasks) do
		table.insert(TaskSnapshot, Task)
		Tasks[Index] = nil
	end

	for _, Task in ipairs(TaskSnapshot) do
		pcall(function()
			self:_CleanupTask(Task)
		end)
	end

	table.clear(self._Tasks)

	setmetatable(self, nil)
end

return Maid
end

R["Wave/Modules/Sound.lua"] = function(...)
local Sound = {}
Sound.__index = Sound

function Sound.New(FilePath, Speed, Volume, IsLink, Link)
    local self = setmetatable({}, Sound)
    
    if IsLink and not isfile(FilePath) then
        writefile(FilePath, Utility:ExecuteHTTPGet(Link))
    end

    self.SoundAsset = getcustomasset(FilePath)
    self.Speed = Speed or 1
    self.Volume = Volume or 1
    self.Sound = Instance.new("Sound", Services.CoreGui)
    self.Sound.SoundId = self.SoundAsset
    self.Sound.PlaybackSpeed = self.Speed
    self.Sound.Volume = self.Volume
    
    return self
end

function Sound:Play()
    self.Sound:Play()
end

function Sound:Stop()
    self.Sound:Stop()
end

function Sound:SetSpeed(Speed)
    self.Speed = Speed
    self.Sound.PlaybackSpeed = Speed
end

function Sound:SetVolume(Volume)
    self.Volume = Volume
    self.Sound.Volume = Volume
end

function Sound:Destroy()
    self.Sound:Destroy()
    self.Sound = nil
end

return Sound
end

R["Wave/UserInterface/WaveUI.lua"] = function(...)
local WaveLibrary = { Options = {}, LoadedFully = false, Folder = "WaveHubSettings", TabSettings = {}, Unloaded = false, WindowState = nil, AcrylicBlur = true, InitializedGlobalSettings = false, Tabs = {} }

function WaveLibrary:CreateShadow(Options)
	local ShadowContainer = Instance.new("ImageLabel")
	ShadowContainer.Name = "Shadow" .. math.random(0, 10000)

	ShadowContainer.Size = UDim2.new(1, 100, 1, 96)
	ShadowContainer.Position = UDim2.new(0, -50, 0, -28)
	ShadowContainer.AnchorPoint = Vector2.new(0, 0)
	ShadowContainer.BackgroundTransparency = 1
	ShadowContainer.BackgroundColor3 = Color3.new(0.639216, 0.635294, 0.647059)

	ShadowContainer.Image = Assets.ShadowImage
	ShadowContainer.ImageTransparency = 0.3
	ShadowContainer.ImageColor3 = Color3.new(1, 1, 1)
	ShadowContainer.ImageRectOffset = Vector2.new(0, 0)
	ShadowContainer.ImageRectSize = Vector2.new(0, 0)
	ShadowContainer.ScaleType = Enum.ScaleType.Slice
	ShadowContainer.SliceCenter = Rect.new(99, 99, 99, 99)
	ShadowContainer.SliceScale = 1
	ShadowContainer.TileSize = UDim2.new(1, 0, 1, 0)

	ShadowContainer.BorderSizePixel = 0
	ShadowContainer.BorderColor3 = Color3.new(0.105882, 0.164706, 0.207843)
	ShadowContainer.BorderMode = Enum.BorderMode.Outline

	ShadowContainer.ZIndex = -1

	ShadowContainer.Visible = true
	ShadowContainer.Active = false
	ShadowContainer.ClipsDescendants = false
	ShadowContainer.Selectable = false
	ShadowContainer.AutoLocalize = true
	ShadowContainer.SizeConstraint = Enum.SizeConstraint.RelativeXY

	ShadowContainer.NextSelectionUp = nil
	ShadowContainer.NextSelectionDown = nil
	ShadowContainer.NextSelectionLeft = nil
	ShadowContainer.NextSelectionRight = nil
	ShadowContainer.SelectionImageObject = nil

	if Options.Gradient then
		local UIGradient = Instance.new("UIGradient")

		if Options.Gradient.Color then
			UIGradient.Color = Options.Gradient.Color
		end

		if Options.Gradient.Transparency then
			UIGradient.Transparency = Options.Gradient.Transparency
		end

		if Options.Gradient.Rotation then
			UIGradient.Rotation = Options.Gradient.Rotation
		end

		if Options.Gradient.Offset then
			UIGradient.Offset = Options.Gradient.Offset
		end

		UIGradient.Parent = ShadowContainer
	end

	if Options.Color and not Options.Gradient then
		ShadowContainer.ImageColor3 = Options.Color
	end

	table.insert(Maid.Shadows, ShadowContainer)

	local ReplicationConnection
	if Options.ObjectReplication then
		local function UpdateShadowProperties()
			local TargetObject = Options.ObjectReplication

			local AbsoluteSize = TargetObject.AbsoluteSize
			ShadowContainer.Size = UDim2.new(0, AbsoluteSize.X + 100, 0, AbsoluteSize.Y + 106)

			local AbsolutePosition = TargetObject.AbsolutePosition
			ShadowContainer.Position = UDim2.new(0, AbsolutePosition.X - 50, 0, AbsolutePosition.Y + 10)

			if Options.ReplicateVisible then
				if Options.ReplicateVisible[2] then
					if not Options.ReplicateVisible[1].Visible then
						ShadowContainer.Visible = Options.ReplicateVisible[1].Visible
					elseif Options.ReplicateVisible[1].Visible and not Options.ReplicateVisible[2].Visible then
						ShadowContainer.Visible = Options.ReplicateVisible[2].Visible
					else
						ShadowContainer.Visible = Options.ReplicateVisible[1].Visible
					end
				else
					ShadowContainer.Visible = Options.ReplicateVisible[1].Visible
				end
			else
				ShadowContainer.Visible = TargetObject.Visible
			end

			ShadowContainer.AnchorPoint = Vector2.new(0, 0)
			ShadowContainer.ZIndex = TargetObject.ZIndex - 1

			if TargetObject.Rotation then
				ShadowContainer.Rotation = TargetObject.Rotation
			end

			if TargetObject.LayoutOrder then
				ShadowContainer.LayoutOrder = TargetObject.LayoutOrder - 1
			end
		end

		UpdateShadowProperties()

		ReplicationConnection = Services.RunService.Heartbeat:Connect(UpdateShadowProperties)
	end

	if Options.Object:FindFirstChildOfClass("UIListLayout") then
		ShadowContainer.LayoutOrder = -9999
	else
		ShadowContainer.Parent = Options.Object
	end

	if ReplicationConnection then
		ShadowContainer.AncestryChanged:Connect(function()
			if not ShadowContainer.Parent then
				ReplicationConnection:Disconnect()
			end
		end)
	end

	return ShadowContainer
end

function WaveLibrary:SetupSettings(Settings)
	if WaveLibrary.TabSettings then
		WaveLibrary.TabSettings = nil
	end

	WaveLibrary.TabSettings = {}

	WaveLibrary.LoadedFully = false

	WaveLibrary.TabSettings.InitializeTab = nil
	WaveLibrary.TabSettings.CurrentTab = nil

	if Maid.Shadows ~= {} and Maid.Shadows ~= nil then
		for _, Container in pairs(Maid.Shadows) do
			Container:Destroy()
		end

		Maid.Shadows = nil
	end

	Maid.Shadows = {}

	if Settings.AcrylicBlur ~= nil then
		WaveLibrary.AcrylicBlur = Settings.AcrylicBlur
	end

	if Maid.MenuKeybind ~= nil then
		Maid.MenuKeybind:Disconnect()
	end

	Maid.MenuKeybind = nil
	Maid.TabIndex = 0

	Maid.RegisteredKeybinds = {}
	Maid.HiddenKeybinds = {}

	WaveLibrary.Unloaded = false
	WaveLibrary.InitializedGlobalSettings = false

	WaveLibrary.WindowState = nil

	WaveLibrary.Tabs = {}
	WaveLibrary.Options = {}
end

