	-- Key-system status line under the username (premium/free + remaining time).
	-- Wrapped in a do-block so its locals are freed immediately (this whole
	-- function sits near Luau's per-function local limit). Reads the loader's
	-- getgenv().UserDataTable { IsUserPremium, UserTime (hours) }.
	do
		local KeyStatus = Instance.new("TextLabel")
		KeyStatus.Name = "KeyStatus"
		KeyStatus.FontFace = Font.new(
			Assets.InterFont,
			Enum.FontWeight.SemiBold,
			Enum.FontStyle.Normal
		)
		KeyStatus.RichText = true
		KeyStatus.Text = ""
		KeyStatus.TextColor3 = Color3.fromRGB(255, 255, 255)
		KeyStatus.TextSize = 11
		KeyStatus.TextTransparency = 0.15
		KeyStatus.TextTruncate = Enum.TextTruncate.SplitWord
		KeyStatus.TextXAlignment = Enum.TextXAlignment.Left
		KeyStatus.TextYAlignment = Enum.TextYAlignment.Top
		KeyStatus.AutomaticSize = Enum.AutomaticSize.XY
		KeyStatus.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
		KeyStatus.BackgroundTransparency = 1
		KeyStatus.BorderColor3 = Color3.fromRGB(0, 0, 0)
		KeyStatus.BorderSizePixel = 0
		KeyStatus.LayoutOrder = 2
		KeyStatus.Size = UDim2.fromScale(1, 0)
		KeyStatus.Parent = UserAndDisplayFrame

		local function FormatKeyDuration(Hours)
			Hours = math.max(0, math.floor(tonumber(Hours) or 0))
			if Hours <= 0 then
				return nil
			elseif Hours < 24 then
				return Hours .. "h"
			end
			local Days = math.floor(Hours / 24)
			local RemHours = Hours % 24
			if RemHours == 0 then
				return Days .. "d"
			end
			return Days .. "d " .. RemHours .. "h"
		end

		local function UpdateKeyStatus()
			local Data
			pcall(function()
				if typeof(getgenv) == "function" then
					Data = getgenv().UserDataTable
				end
			end)
			local Hours = Data and tonumber(Data.UserTime) or 0
			-- premium if the key system flagged it, or more than 13 hours remain
			local IsPremium = (Data and Data.IsUserPremium == true) or (Hours > 13)
			local Word = IsPremium and "Premium" or "Free"
			local WordColor = IsPremium and "#FFCF85" or "#AEB2BE"
			local Text = string.format('<font color="%s">%s</font>', WordColor, Word)
			local Duration = FormatKeyDuration(Hours)
			if Duration then
				Text = Text .. string.format(' <font color="#8A8E9A">·  %s left</font>', Duration)
			end
			KeyStatus.Text = Text
		end

		UpdateKeyStatus()
		task.spawn(function()
			-- settle quickly (the key check may fill the table just after load),
			-- then refresh slowly so the remaining time stays roughly current.
			for _ = 1, 10 do
				task.wait(0.5)
				if not KeyStatus.Parent then
					return
				end
				UpdateKeyStatus()
			end
			while KeyStatus.Parent do
				task.wait(60)
				UpdateKeyStatus()
			end
		end)
	end

