	local Dragging = false
	local DragInput
	local DragStart
	local StartPos

	local function Update(Input)
		local Delta = Input.Position - DragStart
		Base.Position = UDim2.new(StartPos.X.Scale, StartPos.X.Offset + Delta.X, StartPos.Y.Scale, StartPos.Y.Offset + Delta.Y)
	end

	local function OnDragStart(Input)
		-- Don't start a window drag when the press began over an element that
		-- captures its own drag (e.g. a viewport being orbited). Those set a
		-- flag on WaveLibrary while hovered / pressed.
		if WaveLibrary.ViewportHovering or WaveLibrary.ViewportCapturingDrag then
			return
		end
		if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
			Dragging = true
			DragStart = Input.Position
			StartPos = Base.Position

			Input.Changed:Connect(function()
				if Input.UserInputState == Enum.UserInputState.End then
					Dragging = false
				end
			end)
		end
	end

	local function OnDragUpdate(Input)
		if Dragging and (Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch) then
			DragInput = Input
		end
	end

	if not Settings.DragStyle or Settings.DragStyle == 1 then
		Interact.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
				OnDragStart(Input)
			end
		end)

		Interact.InputChanged:Connect(OnDragUpdate)

		Services.UserInputService.InputChanged:Connect(function(Input)
			if Input == DragInput and Dragging then
				Update(Input)
			end
		end)

		Interact.InputEnded:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
				Dragging = false
			end
		end)
	elseif Settings.DragStyle == 2 then
		Base.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
				OnDragStart(Input)
			end
		end)

		Base.InputChanged:Connect(OnDragUpdate)

		Services.UserInputService.InputChanged:Connect(function(Input)
			if Input == DragInput and Dragging then
				Update(Input)
			end
		end)

		Base.InputEnded:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
				Dragging = false
			end
		end)
	end

