	-- Server browser: a slide-out panel of joinable servers (mirrors the Terminal, icon to its left).
	-- Instantiated in a do-block so it adds no persistent local (this function is near Luau's limit);
	-- the API below are separate WindowFunctions methods, which don't count toward that limit.
	do
		local SB = Utility:LoadFile("Wave/UserInterface/Imports/ServerBrowser/ServerBrowserModule.lua")
		if SB then
			WindowFunctions.ServerBrowser = SB.new(Base, TopbarFolder, WaveLibrary, WaveLibraryUI, WindowFunctions)
		end
	end

	function WindowFunctions:AddServer(Options)
		if self.ServerBrowser then
			return self.ServerBrowser:AddServer(Options)
		end
	end
	function WindowFunctions:ClearServers()
		if self.ServerBrowser then
			self.ServerBrowser:ClearServers()
		end
		return self
	end
	function WindowFunctions:SetServerRefresh(Callback)
		if self.ServerBrowser then
			self.ServerBrowser:SetRefreshCallback(Callback)
		end
		return self
	end
	function WindowFunctions:SetServerTitle(Text)
		if self.ServerBrowser then
			self.ServerBrowser:SetTitle(Text)
		end
		return self
	end
	function WindowFunctions:ToggleServerBrowser(State)
		if self.ServerBrowser then
			if State == nil then
				State = not self.ServerBrowser.Open
			end
			self.ServerBrowser:SetOpen(State)
		end
		return self
	end

	local Hovering
	local Toggled = GlobalSettingsUIScale.Scale == 1 and true or false

	local function Toggle()
		if not Toggled then
			local InTween = Utility:PropertyTween(GlobalSettingsUIScale, TweenInfo.new(0.2, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {
				Scale = 1
			})
			InTween:Play()
			InTween.Completed:Wait()
			Toggled = true
		elseif Toggled then
			local OutTween = Utility:PropertyTween(GlobalSettingsUIScale, TweenInfo.new(0.2, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {
				Scale = 0
			})
			OutTween:Play()
			OutTween.Completed:Wait()
			Toggled = false
		end
	end

