		if Inp.UserInputType == Enum.UserInputType.MouseButton1 and Toggled and not Hovering then
			Toggle()
		end
	end)

	local BlurTargets = {Base, Base.Terminal}
	local Camera = Utility:GetCamera()
	local WedgeGuid = Services.HttpService:GenerateGUID(true)
	local Binds = {}
	local DepthOfField
	local CreatedInstances = {}

	local function CleanupExistingBlur()
		for _, LightInstance in pairs(Services.Lighting:GetChildren()) do
			if LightInstance:IsA("DepthOfFieldEffect") and LightInstance:HasTag(".") then
				LightInstance:Destroy()
			end
		end

		for _, BlurTarget in ipairs(BlurTargets) do
			for _, Child in pairs(BlurTarget:GetChildren()) do
				if Child:IsA("Frame") and Child.Name:match("%x+-%x+-%x+-%x+-%x+") then
					Child:Destroy()
				end
			end
		end

		for _, Part in pairs(Camera:GetChildren()) do
			if Part:IsA("Part") and Part.Name:match("%x+-%x+-%x+-%x+-%x+") then
				Part:Destroy()
			end
		end
	end

	CleanupExistingBlur()

	for _, LightInstance in pairs(Services.Lighting:GetChildren()) do
		if LightInstance:IsA("DepthOfFieldEffect") and LightInstance:HasTag(".") then
			DepthOfField = LightInstance
			break
		end
	end

	if not DepthOfField then
		DepthOfField = Instance.new('DepthOfFieldEffect')
		DepthOfField.FarIntensity = 0
		DepthOfField.FocusDistance = 51.6
		DepthOfField.InFocusRadius = 50
		DepthOfField.NearIntensity = 1
		DepthOfField.Name = Services.HttpService:GenerateGUID(true)
		DepthOfField:AddTag(".")
	end

	table.insert(CreatedInstances, DepthOfField)

	local function IsNotNaN(Value)
		return Value == Value
	end

	local Continue = IsNotNaN(Camera:ScreenPointToRay(0, 0).Origin.x)
	while not Continue do
		Services.RunService.RenderStepped:wait()
		Continue = IsNotNaN(Camera:ScreenPointToRay(0, 0).Origin.x)
	end

	local ArcCosine = math.acos
	local Maximum = math.max
	local Pi = math.pi
	local SquareRoot = math.sqrt
	local Size = 0.2

	local function DrawTriangle(Vertex1, Vertex2, Vertex3, Part0, Part1)
		local Side1 = (Vertex1 - Vertex2).magnitude
		local Side2 = (Vertex2 - Vertex3).magnitude
		local Side3 = (Vertex3 - Vertex1).magnitude
		local SideMaximum = Maximum(Side1, Side2, Side3)

		local VertexA, VertexB, VertexC
		if Side1 == SideMaximum then
			VertexA, VertexB, VertexC = Vertex1, Vertex2, Vertex3
		elseif Side2 == SideMaximum then
			VertexA, VertexB, VertexC = Vertex2, Vertex3, Vertex1
		else
			VertexA, VertexB, VertexC = Vertex3, Vertex1, Vertex2
		end

		local Parallel = ((VertexB - VertexA).x * (VertexC - VertexA).x + (VertexB - VertexA).y * (VertexC - VertexA).y + (VertexB - VertexA).z * (VertexC - VertexA).z) / (VertexA - VertexB).magnitude
		local Perpendicular = SquareRoot((VertexC - VertexA).magnitude^2 - Parallel * Parallel)
		local DifferenceParallel = (VertexA - VertexB).magnitude - Parallel

		local Start = CFrame.new(VertexB, VertexA)
		local ZAngle = CFrame.Angles(Pi / 2, 0, 0)
		local CoordinateFrame0 = Start
		local TopLookVector = (CoordinateFrame0 * ZAngle).lookVector
		local MidPoint = VertexA + CFrame.new(VertexA, VertexB).lookVector * Parallel
		local NeededLookVector = CFrame.new(MidPoint, VertexC).lookVector
		local DotProduct = TopLookVector.x * NeededLookVector.x + TopLookVector.y * NeededLookVector.y + TopLookVector.z * NeededLookVector.z
		local AngleCFrame = CFrame.Angles(0, 0, ArcCosine(DotProduct))

		CoordinateFrame0 = CoordinateFrame0 * AngleCFrame
		if ((CoordinateFrame0 * ZAngle).lookVector - NeededLookVector).magnitude > 0.01 then
			CoordinateFrame0 = CoordinateFrame0 * CFrame.Angles(0, 0, -2 * ArcCosine(DotProduct))
		end
		CoordinateFrame0 = CoordinateFrame0 * CFrame.new(0, Perpendicular / 2, -(DifferenceParallel + Parallel / 2))

		local CoordinateFrame1 = Start * AngleCFrame * CFrame.Angles(0, Pi, 0)
		if ((CoordinateFrame1 * ZAngle).lookVector - NeededLookVector).magnitude > 0.01 then
			CoordinateFrame1 = CoordinateFrame1 * CFrame.Angles(0, 0, 2 * ArcCosine(DotProduct))
		end
		CoordinateFrame1 = CoordinateFrame1 * CFrame.new(0, Perpendicular / 2, DifferenceParallel / 2)

		if not Part0 or not Part0:IsA("Part") or not Part0.Parent then
			Part0 = Instance.new('Part')
			Part0.FormFactor = 'Custom'
			Part0.TopSurface = 0
			Part0.BottomSurface = 0
			Part0.Anchored = true
			Part0.CanCollide = false
			Part0.CastShadow = false
			Part0.Material = "Glass"
			Part0.Size = Vector3.new(Size, Size, Size)
			Part0.Name = Services.HttpService:GenerateGUID(true)

			local Mesh = Instance.new('SpecialMesh', Part0)
			Mesh.MeshType = 2
			Mesh.Name = WedgeGuid
		end

		if Part0 and Part0:FindFirstChild(WedgeGuid) then
			Part0[WedgeGuid].Scale = Vector3.new(0, Perpendicular / Size, Parallel / Size)
			Part0.CFrame = CoordinateFrame0
		end

		if not Part1 or not Part1:IsA("Part") or not Part1.Parent then
			Part1 = Part0:clone()
		end

		if Part1 and Part1:FindFirstChild(WedgeGuid) then
			Part1[WedgeGuid].Scale = Vector3.new(0, Perpendicular / Size, DifferenceParallel / Size)
			Part1.CFrame = CoordinateFrame1
		end

		return Part0, Part1
	end

	function DrawQuad(Vertex1, Vertex2, Vertex3, Vertex4, Parts)
		Parts[1], Parts[2] = DrawTriangle(Vertex1, Vertex2, Vertex3, Parts[1], Parts[2])
		Parts[3], Parts[4] = DrawTriangle(Vertex3, Vertex2, Vertex4, Parts[3], Parts[4])
	end

	local function CleanupBlur()
		for Frame, Data in pairs(Binds) do
			if Data.Connection then
				Data.Connection:Disconnect()
				Data.Connection = nil
			end

			if Data.Parts then
				for _, Part in pairs(Data.Parts) do
					if Part and Part.Parent then
						Part.Parent = nil
					end
					if Part then
						pcall(function() Part:Destroy() end)
					end
				end
				Data.Parts = {}
			end

			if Frame and Frame.Parent then
				pcall(function() Frame:Destroy() end)
			end
		end

		Binds = {}

		if DepthOfField then
			DepthOfField.Enabled = false
			if DepthOfField.Parent then
				DepthOfField.Parent = nil
			end
			pcall(function() DepthOfField:Destroy() end)
			DepthOfField = nil
		end

		if WaveLibrary.UpdateOrientation then
			WaveLibrary.UpdateOrientation:Disconnect()
			WaveLibrary.UpdateOrientation = nil
		end

		for _, Instance in ipairs(CreatedInstances) do
			if Instance and Instance.Parent then
				pcall(function() Instance:Destroy() end)
			end
		end

		CreatedInstances = {}
	end

	if WaveLibrary.Unloaded then
		CleanupBlur()
		return
	end

	for _, BlurTarget in ipairs(BlurTargets) do
		local Frame = Instance.new('Frame')
		Frame.Parent = BlurTarget
		Frame.Size = UDim2.new(0.97, 0, 0.97, 0)
		Frame.Position = UDim2.new(0.5, 0, 0.5, 0)
		Frame.AnchorPoint = Vector2.new(0.5, 0.5)
		Frame.BackgroundTransparency = 1
		Frame.Name = Services.HttpService:GenerateGUID(true)

		table.insert(CreatedInstances, Frame)

		if Binds[Frame] then
			continue
		end

		local Parts = {}
		local Parents = {}

		local function Add(Child)
			if Child:IsA'GuiObject' then
				Parents[#Parents + 1] = Child
				Add(Child.Parent)
			end
		end
		Add(Frame)

		local function IsVisible(Instance)
			while Instance do
				if Instance:IsA("GuiObject") then
					if not Instance.Visible then
						return false
					end
				elseif Instance:IsA("ScreenGui") then
					if not Instance.Enabled then
						return false
					end
					break
				end
				Instance = Instance.Parent
			end
			return true
		end

		local function UpdateOrientation(FetchProperties)
			if not IsVisible(Frame) or not WaveLibrary.AcrylicBlur or WaveLibrary.Unloaded then
				for i, Part in pairs(Parts) do
					if Part and Part.Parent then
						Part.Parent = nil
					end
					if Part then
						pcall(function() Part:Destroy() end)
					end
					Parts[i] = nil
				end

				if DepthOfField then
					pcall(function()
						DepthOfField.Enabled = false
						DepthOfField.Parent = nil
					end)
				end
				return
			end

			if DepthOfField and not DepthOfField.Parent then
				pcall(function()
					DepthOfField.Parent = Services.Lighting
				end)
			end

			if DepthOfField then
				pcall(function()
					DepthOfField.Enabled = true
				end)
			end

			local Properties = {
				Transparency = 0.98;
				BrickColor = BrickColor.new('Institutional white');
			}

			local ZIndex = 1 - 0.05 * Frame.ZIndex

			local TopLeft = Frame.AbsolutePosition
			local BottomRight = Frame.AbsolutePosition + Frame.AbsoluteSize
			local TopRight = Vector2.new(BottomRight.x, TopLeft.y)
			local BottomLeft = Vector2.new(TopLeft.x, BottomRight.y)

			local Rotation = 0
			for _, Parent in ipairs(Parents) do
				Rotation = Rotation + Parent.Rotation
			end

			if Rotation ~= 0 and Rotation % 180 ~= 0 then
				local Middle = TopLeft:lerp(BottomRight, 0.5)
				local Sine = math.sin(math.rad(Rotation))
				local Cosine = math.cos(math.rad(Rotation))

				TopLeft = Vector2.new(Cosine * (TopLeft.x - Middle.x) - Sine * (TopLeft.y - Middle.y), Sine * (TopLeft.x - Middle.x) + Cosine * (TopLeft.y - Middle.y)) + Middle
				TopRight = Vector2.new(Cosine * (TopRight.x - Middle.x) - Sine * (TopRight.y - Middle.y), Sine * (TopRight.x - Middle.x) + Cosine * (TopRight.y - Middle.y)) + Middle
				BottomLeft = Vector2.new(Cosine * (BottomLeft.x - Middle.x) - Sine * (BottomLeft.y - Middle.y), Sine * (BottomLeft.x - Middle.x) + Cosine * (BottomLeft.y - Middle.y)) + Middle
				BottomRight = Vector2.new(Cosine * (BottomRight.x - Middle.x) - Sine * (BottomRight.y - Middle.y), Sine * (BottomRight.x - Middle.x) + Cosine * (BottomRight.y - Middle.y)) + Middle
			end

			DrawQuad(
				Camera:ScreenPointToRay(TopLeft.x, TopLeft.y, ZIndex).Origin,
				Camera:ScreenPointToRay(TopRight.x, TopRight.y, ZIndex).Origin,
				Camera:ScreenPointToRay(BottomLeft.x, BottomLeft.y, ZIndex).Origin,
				Camera:ScreenPointToRay(BottomRight.x, BottomRight.y, ZIndex).Origin,
				Parts
			)

			if FetchProperties then
				for _, Part in pairs(Parts) do
					if Part and Part:IsA("Part") then
						Part.Parent = Camera
					end
				end

				for PropertyName, PropertyValue in pairs(Properties) do
					for _, Part in pairs(Parts) do
						if Part and Part:IsA("Part") then
							pcall(function()
								Part[PropertyName] = PropertyValue
							end)
						end
					end
				end
			end
		end

		local Connection = Services.RunService.RenderStepped:Connect(UpdateOrientation)
		WaveLibrary.UpdateOrientation = Connection
		Binds[Frame] = {Parts = Parts, Connection = Connection}
	end

	task.spawn(function()
		while not WaveLibrary.Unloaded do
			task.wait(0.1)
		end

		CleanupBlur()
	end)

	function WindowFunctions:AdjustSidebars(ValueOne, ValueTwo)
		Sidebar.Size = UDim2.new(0, ValueOne, 1, 0)
		Content.Size = UDim2.new(0, ValueTwo, 1, 0)
	end

	function WindowFunctions:GlobalSetting(Settings)
		WaveLibrary.InitializedGlobalSettings = true

		local GlobalSettingFunctions = {}
		local GlobalSetting = Instance.new("TextButton")
		GlobalSetting.Name = "GlobalSetting"
