		TabGroup.BorderColor3 = Color3.fromRGB(0, 0, 0)
		TabGroup.BorderSizePixel = 0
		TabGroup.Size = UDim2.fromScale(1, 0)

		-- (The old full-width straight "Divider" line was removed — the labelled
		--  dot + gradient divider below is the only group separator now.)

		local SectionTabSwitchers = Instance.new("Frame")
		SectionTabSwitchers.Name = "SectionTabSwitchers"
		SectionTabSwitchers.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
		SectionTabSwitchers.BackgroundTransparency = 1
		SectionTabSwitchers.BorderColor3 = Color3.fromRGB(0, 0, 0)
		SectionTabSwitchers.BorderSizePixel = 0
		SectionTabSwitchers.Size = UDim2.fromScale(1, 1)

		local UIListLayout1 = Instance.new("UIListLayout")
		UIListLayout1.Name = "UIListLayout"
		UIListLayout1.Padding = UDim.new(0, 15)
		UIListLayout1.HorizontalAlignment = Enum.HorizontalAlignment.Center
		UIListLayout1.SortOrder = Enum.SortOrder.LayoutOrder
		UIListLayout1.Parent = SectionTabSwitchers

		local UIPadding1 = Instance.new("UIPadding")
		UIPadding1.Name = "UIPadding"
		UIPadding1.PaddingBottom = UDim.new(0, 15)
		UIPadding1.Parent = SectionTabSwitchers

		if GroupLabel and GroupLabel ~= "" then
			-- GetCurrentThemeAttribute is only attached after Initialize() (which
			-- runs on the first tab). Some scripts call Window:Divider() BEFORE the
			-- first tab, which would call a missing method and crash the whole UI
			-- build — so resolve theme colours defensively.
			local function GroupAttr(Name, Fallback)
				local Getter = WindowFunctions.GetCurrentThemeAttribute
				if Getter then
					local ok, value = pcall(Getter, WindowFunctions, Name)
					if ok and value ~= nil then
						return value
					end
				end
				return Fallback
			end

			local Accent = GroupAttr("AccentPrimary", Color3.fromRGB(96, 165, 250))

			local LabelHolder = Instance.new("Frame")
			LabelHolder.Name = "TabGroupLabel"
			LabelHolder.BackgroundTransparency = 1
			LabelHolder.ClipsDescendants = true
			LabelHolder.Size = UDim2.new(1, 0, 0, 24)
			LabelHolder.LayoutOrder = -100
			LabelHolder:SetAttribute("NoApplyTheme", true)

			local LabelPadding = Instance.new("UIPadding")
			LabelPadding.PaddingLeft = UDim.new(0, 18)
			LabelPadding.PaddingRight = UDim.new(0, 16)
			LabelPadding.PaddingBottom = UDim.new(0, 4)
			LabelPadding.Parent = LabelHolder

