			function TabFunctions:CreateLoading()
				local LoadingContainer = Instance.new("Frame")
				LoadingContainer.Name = "LoadingContainer"
				LoadingContainer.BackgroundTransparency = 1
				LoadingContainer.Size = UDim2.fromScale(1, 1)
				LoadingContainer.Position = UDim2.fromScale(0, 0)
				LoadingContainer.Parent = ElementsScrolling

				local LoadingFrame = Instance.new("Frame")
				LoadingFrame.Name = "LoadingFrame"
				LoadingFrame.BackgroundTransparency = 1
				LoadingFrame.Size = UDim2.fromOffset(120, 40)
				LoadingFrame.Position = UDim2.fromScale(0.5, 0.5)
				LoadingFrame.AnchorPoint = Vector2.new(0.5, 0.5)
				LoadingFrame.Parent = LoadingContainer

				local Dots = {}
				local DotCount = 5
				local DotSize = 8
				local Spacing = 20

				for I = 1, DotCount do
					local Dot = Instance.new("Frame")
					Dot.Name = "LoadingDot" .. I
					Dot.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
					Dot.BackgroundTransparency = 0.3
					Dot.BorderSizePixel = 0
					Dot.Size = UDim2.fromOffset(DotSize, DotSize)
					Dot.Position = UDim2.fromOffset((I - 1) * Spacing + (120 - (DotCount - 1) * Spacing) / 2, 16)
					Dot.Parent = LoadingFrame

					local Corner = Instance.new("UICorner")
					Corner.CornerRadius = UDim.new(1, 0)
					Corner.Parent = Dot

					table.insert(Dots, Dot)
				end

				local function AnimateDots()
					local AnimationDelay = 0.15
					local AnimationDuration = 0.4
					local ScaleFactor = 1.5

					spawn(function()
						while LoadingContainer.Parent do
							for I, Dot in ipairs(Dots) do
								spawn(function()
									local ScaleUpTween = Services.TweenService:Create(
										Dot,
										TweenInfo.new(AnimationDuration / 2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
										{
											Size = UDim2.fromOffset(DotSize * ScaleFactor, DotSize * ScaleFactor),
											BackgroundTransparency = 0.1
										}
									)

									local ScaleDownTween = Services.TweenService:Create(
										Dot,
										TweenInfo.new(AnimationDuration / 2, Enum.EasingStyle.Quart, Enum.EasingDirection.In),
										{
											Size = UDim2.fromOffset(DotSize, DotSize),
											BackgroundTransparency = 0.3
										}
									)

									ScaleUpTween:Play()
									ScaleUpTween.Completed:Connect(function()
										ScaleDownTween:Play()
									end)
								end)

								task.wait(AnimationDelay)
							end

							task.wait(0.3)
						end
					end)
				end

				AnimateDots()

				return LoadingContainer
			end

			function TabFunctions:RemoveLoading()
				local LoadingContainer = ElementsScrolling:FindFirstChild("LoadingContainer")
				if LoadingContainer then
					LoadingContainer:Destroy()
				end
			end

