		local OptionIcon = Instance.new("ImageLabel")
		OptionIcon.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
		OptionIcon.Position = UDim2.new(0, 5, 0.5, 0)
		OptionIcon.AnchorPoint = Vector2.new(0, 0.25)
		OptionIcon.Name = "OptionIcon"
		OptionIcon.BackgroundTransparency = 1
		OptionIcon.BorderSizePixel = 0
		OptionIcon.Size = UDim2.new(0, 17.5, 0, 17.5)
		OptionIcon.Image = Assets["Search" .. Option.Class]
		OptionIcon.Parent = OptionInstance

		local OptionDetails = Instance.new("TextLabel")
		OptionDetails.FontFace = Font.new(Assets.InterFont)
		OptionDetails.Name = "OptionDetails"
		OptionDetails.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
		OptionDetails.AnchorPoint = Vector2.new(0, 0.25)
		OptionDetails.Position = UDim2.new(0, 30, 0.5, 0)
		OptionDetails.BackgroundTransparency = 1
		OptionDetails.BorderSizePixel = 0
		OptionDetails.Size = UDim2.new(1, -30, 0, 20)
		OptionDetails.TextTruncate = Enum.TextTruncate.SplitWord
		OptionDetails.TextSize = 10
		OptionDetails.RichText = true
		OptionDetails.Text = "<b>" .. Option.Settings.Name .. "</b>  |  <font transparency=\"0.5\">" .. Option:ReturnClass() .. " - " .. Option:ReturnTab() .. "</font>"
		OptionDetails.TextXAlignment = Enum.TextXAlignment.Left
		OptionDetails.Parent = OptionInstance

		local OptionButton = Instance.new("TextButton")
		OptionButton.Name = "OptionButton"
		OptionButton.BackgroundTransparency = 1
		OptionButton.BorderSizePixel = 0
		OptionButton.Size = UDim2.new(1, 0, 1, 0)
		OptionButton.Position = UDim2.new(0, 0, 0, 0)
		OptionButton.Text = ""
		OptionButton.ZIndex = 5
		OptionButton.Parent = OptionInstance

		local function CreateHoverAnimation()
			local IconTween = Services.TweenService:Create(
				OptionIcon,
				TweenInfo.new(0.2, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
				{Size = UDim2.new(0, 22, 0, 22)}
			)

			local TextTween = Services.TweenService:Create(
				OptionDetails,
				TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
				{Position = UDim2.new(0, 35, 0.5, 0)}
			)

			return {IconTween, TextTween}
		end

		local function CreateUnhoverAnimation()
			local IconTween = Services.TweenService:Create(
				OptionIcon,
				TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
				{Size = UDim2.new(0, 20, 0, 20)}
			)

			local TextTween = Services.TweenService:Create(
				OptionDetails,
				TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
				{Position = UDim2.new(0, 30, 0.5, 0)}
			)

			return {IconTween, TextTween}
		end

		local function CreateClickAnimation()
			local ShrinkTween = Services.TweenService:Create(
				OptionInstance,
				TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
				{Size = UDim2.new(0.98, 0, 0, 18)}
			)

			local IconShrinkTween = Services.TweenService:Create(
				OptionIcon,
				TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
				{Size = UDim2.new(0, 18, 0, 18)}
			)

			local FlashTween = Services.TweenService:Create(
				OptionInstance,
				TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
				{BackgroundTransparency = 0.85}
			)

			ShrinkTween:Play()
			IconShrinkTween:Play()
			FlashTween:Play()

			ShrinkTween.Completed:Connect(function()
				local BounceTween = Services.TweenService:Create(
					OptionInstance,
					TweenInfo.new(0.15, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
					{Size = UDim2.new(1, 0, 0, 20)}
				)

				local IconBounceTween = Services.TweenService:Create(
					OptionIcon,
					TweenInfo.new(0.15, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
					{Size = UDim2.new(0, 22, 0, 22)}
				)

				BounceTween:Play()
				IconBounceTween:Play()
			end)
		end

		OptionButton.MouseEnter:Connect(function()
			local Animations = CreateHoverAnimation()
			for _, Animation in ipairs(Animations) do
				Animation:Play()
			end
		end)

		OptionButton.MouseLeave:Connect(function()
			local Animations = CreateUnhoverAnimation()
			for _, Animation in ipairs(Animations) do
				Animation:Play()
			end
		end)

		OptionButton.MouseButton1Down:Connect(function()
			CreateClickAnimation()
		end)

		OptionButton.MouseButton1Click:Connect(function()
			self:SelectTab(Option:ReturnTab())
		end)

		return OptionInstance
	end

