		ProgressFill.BackgroundColor3 = Accent
		ProgressFill.BackgroundTransparency = 1
		ProgressFill.BorderSizePixel = 0
		ProgressFill:SetAttribute("NoApplyTheme", true)
		ProgressFill.Parent = ProgressTrack

		local Lifetime = Settings.Lifetime == nil and 3 or Settings.Lifetime
		local FinalScale = Settings.Scale or 1
		local Alive = true

		-- Elements faded together on enter / exit (CanvasGroup proved unreliable).
		local FadeTargets = {
			{ Notification, "BackgroundTransparency", 0.03 },
			{ NotificationUIStroke, "Transparency", StrokeTransparency },
			{ AccentBar, "BackgroundTransparency", 0.1 },
			{ IconHolder, "BackgroundTransparency", 0.82 },
			{ IconGlyph, "TextTransparency", 0 },
			{ NotificationTitle, "TextTransparency", 0 },
			{ NotificationDescription, "TextTransparency", 0.15 },
			{ Close, "TextTransparency", 0.3 },
			{ ProgressTrack, "BackgroundTransparency", 0.85 },
			{ ProgressFill, "BackgroundTransparency", 0.1 },
		}

		local function Dismiss()
			if not Alive then
				return
			end
			Alive = false
			Utility:PropertyTween(NotificationUIScale, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Scale = 0.9 }):Play()
			local last
			for _, item in ipairs(FadeTargets) do
				last = Utility:PropertyTween(item[1], TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { [item[2]] = 1 })
				last:Play()
			end
			if last then
				last.Completed:Once(function()
					Notification:Destroy()
				end)
			else
				Notification:Destroy()
			end
		end

		Close.MouseButton1Click:Connect(function()
			Dismiss()
			if Settings.Callback then
				task.spawn(Settings.Callback)
			end
		end)
		Close.MouseEnter:Connect(function()
			if Alive then
				Utility:QuickTween(Close, { TextTransparency = 0 })
			end
		end)
		Close.MouseLeave:Connect(function()
			if Alive then
				Utility:QuickTween(Close, { TextTransparency = 0.3 })
			end
		end)

		local AnimateNotification = task.spawn(function()
			Utility:PropertyTween(NotificationUIScale, TweenInfo.new(0.34, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { Scale = FinalScale }):Play()
			for _, item in ipairs(FadeTargets) do
				Utility:PropertyTween(item[1], TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { [item[2]] = item[3] }):Play()
			end

			if Lifetime and Lifetime > 0 then
				Utility:PropertyTween(ProgressFill, TweenInfo.new(Lifetime, Enum.EasingStyle.Linear), { Size = UDim2.fromScale(0, 1) }):Play()
				task.wait(Lifetime)
				Dismiss()
			else
				ProgressTrack.Visible = false
			end
		end)

		function NotificationFunctions:UpdateTitle(New)
			NotificationTitle.Text = New
		end

		function NotificationFunctions:UpdateDescription(New)
			NotificationDescription.Text = New
			NotificationDescription.Visible = New ~= nil and New ~= ""
		end

		function NotificationFunctions:Resize(X)
			Notification.Size = UDim2.fromOffset(X or 285, 0)
		end

		function NotificationFunctions:Cancel()
			pcall(task.cancel, AnimateNotification)
			Dismiss()
		end

		return NotificationFunctions
	end

