				CardTitle.Parent = Card
			end

			if CardSettings.Description then
				local CardDescription = Instance.new("TextLabel")
				CardDescription.Name = "CardDescription"
				CardDescription.FontFace = Font.new(Assets.InterFont)
				CardDescription.Text = CardSettings.Description
