		TBCorner.Parent = ToggleButton

		local TBStroke = Instance.new("UIStroke")
		TBStroke.Color = Color3.fromRGB(255, 255, 255)
		TBStroke.Transparency = 0.82
		TBStroke.Thickness = 1
		TBStroke.Parent = ToggleButton

		local Glyph = Instance.new("Frame")
		Glyph.Name = "Glyph"
		Glyph.AnchorPoint = Vector2.new(0.5, 0.5)
		Glyph.Position = UDim2.fromScale(0.5, 0.5)
		Glyph.Size = UDim2.fromOffset(16, 16)
		Glyph.BackgroundTransparency = 1
		Glyph.ZIndex = 10000
		Glyph.Parent = ToggleButton

		local DotAnchors = { Vector2.new(0, 0), Vector2.new(1, 0), Vector2.new(0, 1), Vector2.new(1, 1) }
		local DotPositions = { UDim2.fromScale(0, 0), UDim2.fromScale(1, 0), UDim2.fromScale(0, 1), UDim2.fromScale(1, 1) }
		for i = 1, 4 do
			local Dot = Instance.new("Frame")
			Dot.Size = UDim2.fromOffset(6, 6)
			Dot.AnchorPoint = DotAnchors[i]
			Dot.Position = DotPositions[i]
			Dot.BackgroundColor3 = Color3.fromRGB(236, 236, 245)
			Dot.BorderSizePixel = 0
			Dot.ZIndex = 10000
			Dot.Parent = Glyph
			local DotCorner = Instance.new("UICorner")
			DotCorner.CornerRadius = UDim.new(0, 2)
			DotCorner.Parent = Dot
		end

		local Dragging, DragInput, DragStart, StartPos, Moved = false, nil, nil, nil, false
		ToggleButton.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
				Dragging, Moved = true, false
				DragStart, StartPos = Input.Position, ToggleButton.Position
			end
		end)
		ToggleButton.InputChanged:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch then
				DragInput = Input
			end
		end)
		Maid.ToggleButtonMove = Services.UserInputService.InputChanged:Connect(function(Input)
			if Dragging and Input == DragInput then
				local Delta = Input.Position - DragStart
				if Delta.Magnitude > 6 then
					Moved = true
				end
				-- only move once it's clearly a drag, so a tap never nudges it
				if Moved then
					ToggleButton.Position = UDim2.new(StartPos.X.Scale, StartPos.X.Offset + Delta.X, StartPos.Y.Scale, StartPos.Y.Offset + Delta.Y)
				end
			end
		end)
		Maid.ToggleButtonEnd = Services.UserInputService.InputEnded:Connect(function(Input)
			if (Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch) and Dragging then
				Dragging = false
				if not Moved then
					ToggleMenu()
				end
			end
		end)

		ToggleButton.MouseEnter:Connect(function()
			Utility:PropertyTween(ToggleButton, TweenInfo.new(0.15), { BackgroundTransparency = 0 }):Play()
			Utility:PropertyTween(TBStroke, TweenInfo.new(0.15), { Transparency = 0.6 }):Play()
		end)
		ToggleButton.MouseLeave:Connect(function()
			Utility:PropertyTween(ToggleButton, TweenInfo.new(0.15), { BackgroundTransparency = 0.08 }):Play()
			Utility:PropertyTween(TBStroke, TweenInfo.new(0.15), { Transparency = 0.82 }):Play()
		end)
	end

