		local SBStroke = Instance.new("UIStroke")
		SBStroke.Name = "StatusStroke"
		SBStroke.Color = Color3.fromRGB(255, 255, 255)
		SBStroke.Transparency = 0.85
		SBStroke.Thickness = 1
		SBStroke.Parent = StatusBar

		local SBPadding = Instance.new("UIPadding")
		SBPadding.PaddingLeft = UDim.new(0, 9)
		SBPadding.PaddingRight = UDim.new(0, 9)
		SBPadding.Parent = StatusBar

		local SBLayout = Instance.new("UIListLayout")
		SBLayout.FillDirection = Enum.FillDirection.Horizontal
		SBLayout.VerticalAlignment = Enum.VerticalAlignment.Center
		SBLayout.SortOrder = Enum.SortOrder.LayoutOrder
		SBLayout.Padding = UDim.new(0, 0) -- no layout gap; the arrow gap collapses with the drawer, the eye gap is a spacer
		SBLayout.Parent = StatusBar

		-- Responsive scale: the bar is a sibling of the window (not under BaseUIScale), so we size it
		-- for small / mobile screens ourselves, toward the top-right anchor. The floor is higher than
		-- the window's so text stays legible and the arrow / eye stay tappable. Viewport changes are
		-- picked up by WindowFunctions:UpdateResponsiveScale (below); here we set the initial value.
		-- (Kept to a single new local on purpose -- CreateWindow is near Luau's 200-locals limit.)
		do
			local StatusScale = Instance.new("UIScale")
			StatusScale.Name = "StatusScale"
			local Camera = Services.Workspace.CurrentCamera
			local V = Camera and Camera.ViewportSize
			if V and V.X >= 1 and V.Y >= 1 then
				local Margin = (V.X < 700) and 12 or 36
				StatusScale.Scale = math.clamp(math.min(1, (V.X - Margin) / 868, (V.Y - Margin) / 650), 0.72, 1)
			end
			StatusScale.Parent = StatusBar
		end

		-- the drawer: clips so its content slides in / out on expand & collapse
		local ContentClip = Instance.new("Frame")
		ContentClip.Name = "StatusContentClip"
		ContentClip.BackgroundTransparency = 1
		ContentClip.ClipsDescendants = true
		ContentClip.Size = UDim2.new(0, 0, 1, 0)
		ContentClip.LayoutOrder = 0
		ContentClip.ZIndex = 9999
		ContentClip.Parent = StatusBar

