		FpsText.Size = UDim2.new(0, 0, 1, 0)
		FpsText.BackgroundTransparency = 1
		FpsText.TextXAlignment = Enum.TextXAlignment.Left
		FpsText.LayoutOrder = 1
		FpsText.ZIndex = 9999
		FpsText.Parent = FpsHolder

