		UserHolder.Name = "UserHolder"
		UserHolder.BackgroundTransparency = 1
		UserHolder.AutomaticSize = Enum.AutomaticSize.X
		UserHolder.Size = UDim2.new(0, 0, 1, 0)
		UserHolder.LayoutOrder = 2
		UserHolder.ZIndex = 9999
		UserHolder.Parent = Content

		local UserRow = Instance.new("UIListLayout")
		UserRow.FillDirection = Enum.FillDirection.Horizontal
		UserRow.VerticalAlignment = Enum.VerticalAlignment.Center
		UserRow.SortOrder = Enum.SortOrder.LayoutOrder
		UserRow.Padding = UDim.new(0, 6)
		UserRow.Parent = UserHolder

		local Avatar = Instance.new("ImageLabel")
		Avatar.Name = "StatusAvatar"
		Avatar.Size = UDim2.fromOffset(18, 18)
		Avatar.BackgroundColor3 = Color3.fromRGB(44, 44, 54)
		Avatar.BackgroundTransparency = 0.2
		Avatar.BorderSizePixel = 0
		Avatar.Image = ""
		Avatar.ScaleType = Enum.ScaleType.Crop
		Avatar.LayoutOrder = 0
		Avatar.ZIndex = 9999
		Avatar.Parent = UserHolder
		local AvatarCorner = Instance.new("UICorner")
		AvatarCorner.CornerRadius = UDim.new(1, 0)
		AvatarCorner.Parent = Avatar
		local AvatarStroke = Instance.new("UIStroke")
		AvatarStroke.Color = Color3.fromRGB(255, 255, 255)
		AvatarStroke.Transparency = 0.8
		AvatarStroke.Thickness = 1
		AvatarStroke.Parent = Avatar

		local UserText = Instance.new("TextLabel")
		UserText.Name = "StatusMuted"
		UserText.FontFace = Font.new(Assets.InterFont, Enum.FontWeight.Medium, Enum.FontStyle.Normal)
		UserText.Text = "@" .. (Player and Player.Name or "player")
		UserText.TextColor3 = Color3.fromRGB(170, 170, 182)
		UserText.TextSize = 13
		UserText.AutomaticSize = Enum.AutomaticSize.X
		UserText.Size = UDim2.new(0, 0, 1, 0)
		UserText.BackgroundTransparency = 1
		UserText.TextXAlignment = Enum.TextXAlignment.Left
		UserText.LayoutOrder = 1
		UserText.ZIndex = 9999
		UserText.Parent = UserHolder

		MakeDivider(3)

		local GameText = Instance.new("TextLabel")
		GameText.Name = "StatusMuted"
		GameText.FontFace = Font.new(Assets.InterFont, Enum.FontWeight.Medium, Enum.FontStyle.Normal)
		GameText.Text = "…"
		GameText.TextColor3 = Color3.fromRGB(170, 170, 182)
		GameText.TextSize = 13
		GameText.AutomaticSize = Enum.AutomaticSize.X
		GameText.Size = UDim2.new(0, 0, 1, 0)
		GameText.TextTruncate = Enum.TextTruncate.AtEnd
		GameText.BackgroundTransparency = 1
		GameText.TextXAlignment = Enum.TextXAlignment.Left
		GameText.LayoutOrder = 4
		GameText.ZIndex = 9999
		GameText.Parent = Content
		local GameConstraint = Instance.new("UISizeConstraint")
		GameConstraint.MaxSize = Vector2.new(190, math.huge)
		GameConstraint.Parent = GameText

		-- arrow toggle (collapses the drawer; rotates 180 between states)
		local Arrow = Instance.new("TextButton")
		Arrow.Name = "StatusArrow"
		Arrow.AutoButtonColor = false
		Arrow.Text = ""
		Arrow.BackgroundTransparency = 1
		Arrow.Size = UDim2.fromOffset(18, 18)
		Arrow.LayoutOrder = 1
		Arrow.ZIndex = 9999
		Arrow.Parent = StatusBar

		local Chevron = Instance.new("ImageLabel")
		Chevron.Name = "StatusChevron"
		Chevron.AnchorPoint = Vector2.new(0.5, 0.5)
		Chevron.Position = UDim2.fromScale(0.5, 0.5)
		Chevron.Size = UDim2.fromOffset(16, 16)
		Chevron.BackgroundTransparency = 1
		Chevron.ImageColor3 = Color3.fromRGB(192, 192, 206)
		Chevron.ImageTransparency = 0.1
		Chevron.ZIndex = 9999
		Chevron.Parent = Arrow
		if IconSheet then
			pcall(function() IconSheet:SetIcon(Chevron, "chevron-left") end)
		end

		-- eye toggle: shows / hides the whole UI, sitting to the right of the arrow. Always on
		-- screen (even when the UI is hidden) so it's the way back in -- replaces the old floating
		-- button. Icon is "eye" while the UI is shown and "eye-off" while it's hidden.
		local EyeIcon
		local function SetEyeIcon(Shown)
			if EyeIcon and IconSheet then
				pcall(function() IconSheet:SetIcon(EyeIcon, Shown and "eye" or "eye-off") end)
			end
		end
		if Settings.ToggleButton then
			-- fixed gap between the arrow and the eye (the layout itself has no padding)
			local EyeGap = Instance.new("Frame")
			EyeGap.Name = "StatusEyeGap"
			EyeGap.BackgroundTransparency = 1
			EyeGap.Size = UDim2.fromOffset(6, 1)
			EyeGap.LayoutOrder = 2
			EyeGap.ZIndex = 9999
			EyeGap.Parent = StatusBar

			local EyeButton = Instance.new("TextButton")
			EyeButton.Name = "StatusEye"
			EyeButton.AutoButtonColor = false
			EyeButton.Text = ""
			EyeButton.BackgroundTransparency = 1
			EyeButton.Size = UDim2.fromOffset(20, 18)
			EyeButton.LayoutOrder = 3
			EyeButton.ZIndex = 9999
			EyeButton.Parent = StatusBar

			EyeIcon = Instance.new("ImageLabel")
			EyeIcon.Name = "StatusEyeIcon"
			EyeIcon.AnchorPoint = Vector2.new(0.5, 0.5)
			EyeIcon.Position = UDim2.fromScale(0.5, 0.5)
			EyeIcon.Size = UDim2.fromOffset(17, 17)
			EyeIcon.BackgroundTransparency = 1
			EyeIcon.ImageColor3 = Color3.fromRGB(192, 192, 206)
			EyeIcon.ImageTransparency = 0.1
			EyeIcon.ZIndex = 9999
			EyeIcon.Parent = EyeButton
			SetEyeIcon(WaveLibrary.WindowState ~= false)

			EyeButton.MouseButton1Click:Connect(function()
				ToggleMenu()
			end)
			EyeButton.MouseEnter:Connect(function()
				Utility:PropertyTween(EyeIcon, TweenInfo.new(0.12), { ImageTransparency = 0 }):Play()
			end)
			EyeButton.MouseLeave:Connect(function()
				Utility:PropertyTween(EyeIcon, TweenInfo.new(0.12), { ImageTransparency = 0.1 }):Play()
			end)
		end

		-- expand / collapse.  The clip width is driven explicitly from the row's measured width.
		-- (The clip can't AutomaticSize itself: the row is anchored to the clip's right edge, so the
		-- size would be circular and resolve to 0.)  Content auto-sizes its *own* children reliably,
		-- so FullWidth is cached every time the row re-measures -- even while collapsed (the FPS digits
		-- keep it fresh) -- and reopening tweens straight to that cached width instead of reading a
		-- stale/under-measured value mid-collapse and snapping.  Re-sync is suppressed during the
		-- animation so a re-measure can't jump the drawer to full while it's tweening open.
		local StatusExpanded = true
		local Animating = false
		-- AbsoluteSize already includes StatusScale, but the clip width we set is a local offset, so
		-- divide the scale back out (otherwise it would be applied twice and the drawer would mis-size).
		local FullWidth = Content.AbsoluteSize.X / StatusBar.StatusScale.Scale
		local function SyncWidth()
			local Scale = StatusBar.StatusScale.Scale
			local w = Content.AbsoluteSize.X / (Scale > 0 and Scale or 1)
			if w > 0 then
				FullWidth = w
			end
			if StatusExpanded and not Animating then
				ContentClip.Size = UDim2.new(0, FullWidth, 1, 0)
			end
		end
		Content:GetPropertyChangedSignal("AbsoluteSize"):Connect(SyncWidth)
		task.defer(SyncWidth)

		local function SetExpanded(State, Animate)
			if StatusExpanded == State then
				return
			end
			StatusExpanded = State
			Animating = true
			local Info = TweenInfo.new(Animate and 0.34 or 0, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
			local Tween = Utility:PropertyTween(ContentClip, Info, { Size = UDim2.new(0, State and FullWidth or 0, 1, 0) })
			Tween.Completed:Connect(function(playState)
				if playState ~= Enum.PlaybackState.Completed then
					return -- superseded by a newer toggle; let that one settle
				end
				Animating = false
				if StatusExpanded then
					ContentClip.Size = UDim2.new(0, FullWidth, 1, 0) -- settle on the exact width
				end
			end)
			Tween:Play()
			Utility:PropertyTween(Chevron, Info, { Rotation = State and 0 or 180 }):Play()
		end

		Arrow.MouseButton1Click:Connect(function()
			SetExpanded(not StatusExpanded, true)
		end)
		Arrow.MouseEnter:Connect(function()
			Utility:PropertyTween(Chevron, TweenInfo.new(0.12), { ImageTransparency = 0 }):Play()
		end)
		Arrow.MouseLeave:Connect(function()
			Utility:PropertyTween(Chevron, TweenInfo.new(0.12), { ImageTransparency = 0.1 }):Play()
		end)

		-- avatar headshot (async)
		task.spawn(function()
			local url
			pcall(function()
				url = Services.Players:GetUserThumbnailAsync(Player.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size48x48)
			end)
			if url and Avatar and Avatar.Parent then
				Avatar.Image = url
			end
		end)

		-- game name (async, non-blocking)
		task.spawn(function()
			local name
			pcall(function()
				name = game:GetService("MarketplaceService"):GetProductInfo(game.PlaceId).Name
			end)
			if not name or name == "" then
				pcall(function() name = game.Name end)
			end
			name = (name and name ~= "") and name or "Roblox"
			if not (GameText and GameText.Parent) then
				return
			end
			GameText.Text = name
			-- Freeze GameText to a fixed width. Because it uses TextTruncate, while the drawer is clipped
			-- shut it would otherwise measure 0 (it "truncates to nothing"), making the row under-measure
			-- so the open animation under-shoots and snaps the last chunk in at the end. A fixed width
			-- measures the same open or closed. Capped at 190 (truncation still applies past that).
			local w
			pcall(function()
				local Params = Instance.new("GetTextBoundsParams")
				Params.Text = name
				Params.Font = GameText.FontFace
				Params.Size = GameText.TextSize
				Params.Width = 100000
				w = game:GetService("TextService"):GetTextBoundsAsync(Params).X
			end)
			w = math.min(math.ceil((w and w > 0) and w or 90) + 1, 190)
			GameText.AutomaticSize = Enum.AutomaticSize.None
			GameText.Size = UDim2.new(0, w, 1, 0)
		end)

		-- live FPS + follow the window's shown/hidden state
		local Accum, Frames, LastUiState = 0, 0, true
		Maid.StatusFps = Services.RunService.RenderStepped:Connect(function(dt)
			local UiState = (WaveLibrary.WindowState ~= false)
			if UiState ~= LastUiState then
				LastUiState = UiState
				SetExpanded(UiState, true)
				SetEyeIcon(UiState)
			end

			Accum = Accum + dt
			Frames = Frames + 1
			if Accum >= 0.5 then
				local Fps = math.floor(Frames / Accum + 0.5)
				Accum, Frames = 0, 0
				FpsText.Text = Fps .. " FPS"
				local Col = (Fps >= 50 and Color3.fromRGB(80, 220, 130))
					or (Fps >= 30 and Color3.fromRGB(245, 205, 90))
					or Color3.fromRGB(245, 110, 110)
				FpsDot.BackgroundColor3 = Col
				FpsDotGlow.Color = Col
			end
		end)
	end

	Maid.MenuKeybind = Services.UserInputService.InputEnded:Connect(function(Input, Typing)
		if Typing then
			return
		end

		if Input.KeyCode == MenuKeybind then
			ToggleMenu()
		end
	end)

	Minimize.MouseButton1Click:Connect(ToggleMenu)

	Exit.MouseButton1Click:Connect(function()
		WindowFunctions:Dialog({
			Title = Settings.Title,
			Description = "Are you sure you want to exit the menu? You will lose any unsaved configurations.",
			Buttons = {
				{
					Name = "Confirm",
					Callback = function()
						WindowFunctions:Unload()
						if Services.CoreGui:FindFirstChild("StartupScreen") then
							Services.CoreGui:FindFirstChild("StartupScreen"):Destroy()
						end
					end,
				},
				{
					Name = "Cancel"
				}
			}
		})
	end)

	function WindowFunctions:SetKeybind(Keycode)
		local KeybindFile = WaveLibrary.Folder .. "/settings/startup/KeybindSaved.wave"
		writefile(KeybindFile, Keycode.Name)
		MenuKeybind = Keycode
	end

	function WindowFunctions:SetAcrylicBlurState(State)
		WaveLibrary.AcrylicBlur = State
		Base.BackgroundTransparency = WindowFunctions:GetCurrentThemeAttribute("BackgroundTransparency")
	end

	function WindowFunctions:GetAcrylicBlurState()
		return WaveLibrary.AcrylicBlur
	end

	local function _SetUserInfoState(State)
		ShowUserInfo = State

		task.spawn(function()
			if State then
				Headshot.Image = (IsReady and HeadshotImage) or Assets.Null
				if Utility:GetPlayer() then
					Username.Text = "@" .. Utility:GetPlayer().Name
					DisplayName.Text = Utility:GetPlayer().DisplayName
				else
					Username.Text = "@" .. "Unknown"
					DisplayName.Text = "Unknown"
				end
			else
				Headshot.Image = Assets.UserInfoBlurred
				local nameLength = #Utility:GetPlayer().Name
				local displayNameLength = #Utility:GetPlayer().DisplayName
				Username.Text = "@" .. string.rep(".", nameLength)
				DisplayName.Text = string.rep(".", displayNameLength)
			end
		end)
	end

	function WindowFunctions:SetUserInfoState(State)
		_SetUserInfoState(State)
	end _SetUserInfoState(Settings.ShowUserInfo ~= nil and Settings.ShowUserInfo or true)

	function WindowFunctions:GetUserInfoState(State)
		return ShowUserInfo
	end

	function WindowFunctions:SetSize(Size)
		Base.Size = Size
	end

	function WindowFunctions:GetSize(Size)
		return Base.Size
	end

	function WindowFunctions:SetScale(Scale)
		BaseUIScale.Scale = Scale
	end

	function WindowFunctions:GetScale()
		return BaseUIScale.Scale
	end

	function WindowFunctions:GetResponsiveScale()
		local Camera = Services.Workspace.CurrentCamera
		if not Camera then
			return 1
		end
		local Viewport = Camera.ViewportSize
		if Viewport.X < 1 or Viewport.Y < 1 then
			return 1
		end
		local DesignWidth = (Settings.Size and Settings.Size.X.Offset) or 868
		local DesignHeight = (Settings.Size and Settings.Size.Y.Offset) or 650
		local Margin = (Viewport.X < 700) and 12 or 36
		local Fit = math.min(1, (Viewport.X - Margin) / DesignWidth, (Viewport.Y - Margin) / DesignHeight)
		return math.clamp(Fit, 0.4, 1)
	end

	function WindowFunctions:UpdateResponsiveScale()
		local Scale = WindowFunctions:GetResponsiveScale()
		BaseUIScale.Scale = Scale
		-- keep the top-right status bar in step (it lives outside BaseUIScale), with a higher floor
		local SB = BaseUIScale.Parent and BaseUIScale.Parent.Parent and BaseUIScale.Parent.Parent:FindFirstChild("WaveStatusBar")
		local SS = SB and SB:FindFirstChild("StatusScale")
		if SS then
			SS.Scale = math.clamp(Scale, 0.72, 1)
		end
	end

	local function HookResponsiveScale()
		local Camera = Services.Workspace.CurrentCamera
		if Camera then
			Maid.ResponsiveViewport = Camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
				WindowFunctions:UpdateResponsiveScale()
			end)
		end
	end

	HookResponsiveScale()
	Maid.ResponsiveCameraSwap = Services.Workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(HookResponsiveScale)

	function WindowFunctions:ReturnFeatures()
		return WaveLibrary.Options
	end

	function WindowFunctions:RetrieveFeature(Feature)
		return WaveLibrary.Options[Feature]
	end

	function WindowFunctions:GetKeybindSet(Flag)
		for BoundFlag, BoundKey in pairs(Maid.ToggleKeybinds) do
			if BoundFlag == Flag then
				return BoundKey
			end
		end

		return nil
	end

	local function BuildFolderTree()
		local Paths = {
			WaveLibrary.Folder,
			WaveLibrary.Folder .. "/settings",
			WaveLibrary.Folder .. "/settings/" .. game.GameId,
		}

		for Index = 1, #Paths do
			local PathString = Paths[Index]
			if not isfolder(PathString) then
				makefolder(PathString)
			end
		end
	end

	function WaveLibrary:LoadAutoLoadConfig()
		if isfile(WaveLibrary.Folder .. "/settings/" .. game.GameId .. "/" .. "autoload.txt") then
			local Name = readfile(WaveLibrary.Folder .. "/settings/" .. game.GameId .. "/" .. "autoload.txt")

			local Success, ErrorMessage = WaveLibrary:LoadConfig(Name)
			if not Success then
				WindowFunctions:Notify({
					Title = "Interface",
					Description = "Error loading autoload config: " .. ErrorMessage
				})
			end

			WindowFunctions:Notify({
				Title = "Interface",
				Description = string.format("Autoloaded config: %q", Name),
			})
		end
	end

	function WaveLibrary:SetFolder(Folder)
		WaveLibrary.Folder = Folder or "WaveHubSettings"
		BuildFolderTree()
	end

	function WaveLibrary:SaveConfig(Path)
		if (not Path) then
			return false, "Please select a config file."
		end

		local FullPath = WaveLibrary.Folder .. "/settings/" .. game.GameId .. "/" .. Path .. ".json"

		local Data = {
			Objects = {}
		}

		for Flag, Option in next, WaveLibrary.Options do
			if not ClassParser[Option.Class] then
				continue
			end

			if Option.IgnoreConfig then
				continue
			end

			table.insert(Data.Objects, ClassParser[Option.Class].Save(Flag, Option))
		end

		local Success, Encoded = pcall(Services.HttpService.JSONEncode, Services.HttpService, Data)
		if not Success then
			return false, "Unable to encode into JSON data"
		end

		writefile(FullPath, Encoded)
		return true
	end

	function WaveLibrary:LoadConfig(Path)
		if (not Path) then
			return false, "Please select a config file."
		end

		local File = WaveLibrary.Folder .. "/settings/" .. game.GameId .. "/" .. Path .. ".json"

		if not isfile(File) then
			return false, "Invalid file"
		end

		local Success, Decoded = pcall(Services.HttpService.JSONDecode, Services.HttpService, readfile(File))
		if not Success then
			return false, "Unable to decode JSON data."
		end

		for _, Option in next, Decoded.Objects do
			if ClassParser[Option.ClassType] then
				ClassParser[Option.ClassType].Load(Option.Flag, Option)
			end
		end

		return true
	end

	function WaveLibrary:DeleteConfig(Path)
		if (not Path) then
			return false, "Please select a config file."
		end

		local FullPath = WaveLibrary.Folder .. "/settings/" .. game.GameId .. "/" .. Path .. ".json"

		if not isfile(FullPath) then
			return false, "Config file does not exist."
		end

		local Success, Error = pcall(delfile, FullPath)
		if not Success then
			return false, "Unable to delete config file: " .. tostring(Error)
		end

		return true
	end

	function WaveLibrary:DeleteAllConfigs()
		local ConfigFolder = WaveLibrary.Folder .. "/settings/" .. game.GameId

		if not isfolder(ConfigFolder) then
			return false, "No configs folder found."
		end

		local Files = listfiles(ConfigFolder)
		local DeletedCount = 0
		local Errors = {}

		for _, FilePath in next, Files do
			if FilePath:match("%.json$") then
				local Success, Error = pcall(delfile, FilePath)
				if Success then
					DeletedCount = DeletedCount + 1
				else
					table.insert(Errors, FilePath .. ": " .. tostring(Error))
				end
			end
		end

		if #Errors > 0 then
			return false, "Deleted " .. DeletedCount .. " configs, but encountered errors: " .. table.concat(Errors, ", ")
		end

		return true, "Successfully deleted " .. DeletedCount .. " config(s)."
	end

	function WaveLibrary:RefreshConfigList()
		if not isfolder(WaveLibrary.Folder) or not isfolder(WaveLibrary.Folder .. "/settings") or not isfolder(WaveLibrary.Folder .. "/settings/" .. game.GameId) then
			WaveLibrary:SetFolder("WaveHubSettings")
		end

		local List = listfiles(WaveLibrary.Folder .. "/settings/" .. game.GameId .. "/")

		local Out = {}
		for Index = 1, #List do
			local File = List[Index]
			if File:sub(-5) == ".json" then
				local Pos = File:find(".json", 1, true)
				local Start = Pos

				local Char = File:sub(Pos, Pos)
				while Char ~= "/" and Char ~= "\\" and Char ~= "" do
					Pos = Pos - 1
					Char = File:sub(Pos, Pos)
				end

				if Char == "/" or Char == "\\" then
					local Name = File:sub(Pos + 1, Start - 1)
					if Name ~= "options" then
						table.insert(Out, Name)
					end
				end
			end
		end

		return Out
	end

	local _ = HiddenMode and WindowFunctions:SetWindowState(false)

	WaveLibrary.WindowState = true
	Base.Visible = false

	Base.Position = UDim2.fromScale(0.5, 0.5)
	Base.AnchorPoint = Vector2.new(0.5, 0.5)
	BaseUIScale.Scale = WindowFunctions:GetResponsiveScale() * 0.93
	Base.BackgroundTransparency = 1

	for _, Child in ipairs(Base:GetChildren()) do
		if Child:IsA("GuiObject") and Child.Name ~= "Terminal" then
			ThemeUtility:MakeInvisible(Child)
		end
	end

	if Base:FindFirstChild("Terminal") then
		local Terminal = Base.Terminal

		Terminal:SetAttribute("OriginalBackgroundTransparency", Terminal.BackgroundTransparency)

		Terminal.BackgroundTransparency = 1

		for _, Element in pairs(Terminal:GetDescendants()) do
			if Element:IsA("GuiObject") then
				Element:SetAttribute("OriginalBackgroundTransparency", Element.BackgroundTransparency)
				Element.BackgroundTransparency = 1

				if Element:IsA("TextLabel") or Element:IsA("TextButton") or Element:IsA("TextBox") then
					Element:SetAttribute("OriginalTextTransparency", Element.TextTransparency)
					Element.TextTransparency = 1
				elseif Element:IsA("ImageLabel") or Element:IsA("ImageButton") then
					Element:SetAttribute("OriginalImageTransparency", Element.ImageTransparency)
					Element.ImageTransparency = 1
				end

				local Stroke = Element:FindFirstChildOfClass("UIStroke")
				if Stroke then
					Element:SetAttribute("OriginalStrokeTransparency", Stroke.Transparency)
					Stroke.Transparency = 1
				end
			end
		end

		if Terminal:FindFirstChild("OutputUIStroke") then
			Terminal.OutputUIStroke:SetAttribute("OriginalTransparency", Terminal.OutputUIStroke.Transparency)
			Terminal.OutputUIStroke.Transparency = 1
		end

		Terminal.Visible = Utility:SaveOpened()
	end

	local function AnimateOutputScreen(DelayTime, Duration)
		if not Base:FindFirstChild("Terminal") then return end

		local Terminal = Base.Terminal
		local ShouldBeVisible = Terminal:GetAttribute("OriginalVisibility")

		if ShouldBeVisible == false then
			return
		end

		Utility:PropertyTween(Terminal, TweenInfo.new(Duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
			BackgroundTransparency = WindowFunctions:GetCurrentThemeAttribute("BackgroundTransparency")
		}):Play()

		if Terminal:FindFirstChild("OutputUIStroke") then
			Utility:PropertyTween(Terminal.OutputUIStroke, TweenInfo.new(Duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				Transparency = Terminal:GetAttribute("StrokeTransparency")
			}):Play()
		end

		local DescendantDelay = 0
		for _, Element in pairs(Terminal:GetDescendants()) do
			if Element:IsA("GuiObject") and Element.Name ~= "OutputWallpaper" then
				task.delay(DelayTime + DescendantDelay, function()
					local Properties = {}

					local BackgroundTransparency = Element:GetAttribute("OriginalBackgroundTransparency")
					if BackgroundTransparency ~= nil then
						Properties.BackgroundTransparency = BackgroundTransparency
					end

					if Element:IsA("TextLabel") or Element:IsA("TextButton") or Element:IsA("TextBox") then
						local TextTransparency = Element:GetAttribute("OriginalTextTransparency")
						if TextTransparency ~= nil then
							Properties.TextTransparency = TextTransparency
						end
					elseif Element:IsA("ImageLabel") or Element:IsA("ImageButton") then
						local ImageTransparency = Element:GetAttribute("OriginalImageTransparency")
						if ImageTransparency ~= nil then
							Properties.ImageTransparency = ImageTransparency
						end
					end

					if next(Properties) ~= nil then
						Utility:PropertyTween(Element, TweenInfo.new(Duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), Properties):Play()
					end

					local Stroke = Element:FindFirstChildOfClass("UIStroke")
					if Stroke then
						local StrokeTransparency = Element:GetAttribute("OriginalStrokeTransparency")
						if StrokeTransparency ~= nil then
							Utility:PropertyTween(Stroke, TweenInfo.new(Duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
								Transparency = StrokeTransparency
							}):Play()
						end
					end
				end)

				DescendantDelay = DescendantDelay + 0.01
			end
		end

		if Terminal:FindFirstChild("OutputWallpaper") then
			Utility:PropertyTween(Terminal.OutputWallpaper, TweenInfo.new(Duration, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				ImageTransparency = WindowFunctions:GetCurrentThemeAttribute("WallpaperTransparency")
			}):Play()
		end
	end

	task.delay(0.1, function()
		if not HiddenMode then
			Base.Visible = true
		end

		Utility:PropertyTween(BaseUIScale, TweenInfo.new(0.5, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
			Scale = WindowFunctions:GetResponsiveScale()
		}):Play()

		Utility:PropertyTween(Base, TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
			BackgroundTransparency = WindowFunctions:GetCurrentThemeAttribute("BackgroundTransparency")
		}):Play()

		if Wallpaper then
			Utility:PropertyTween(Wallpaper, TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				ImageTransparency = WindowFunctions:GetCurrentThemeAttribute("WallpaperTransparency")
			}):Play()
		end

		if BaseUIStroke then
			Utility:PropertyTween(BaseUIStroke, TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				Transparency = WindowFunctions:GetCurrentThemeAttribute("StrokeTransparency")
			}):Play()
		end

		task.delay(0.1, function()
			if Sidebar then
				Utility:PropertyTween(Sidebar, TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
					BackgroundTransparency = WindowFunctions:GetCurrentThemeAttribute("SidebarTransparency")
				}):Play()

				if SidebarDivider then
					Utility:PropertyTween(SidebarDivider, TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
						Transparency = WindowFunctions:GetCurrentThemeAttribute("StrokeTransparency")
					}):Play()
				end

				ThemeUtility:AnimateIn(Sidebar, 0.1, 0.3)
			end

			if Content then
				ThemeUtility:AnimateIn(Content, 0.2, 0.3)

				task.delay(0.3, function()
					if TabSwitcher and TabSelection then
						TabSelection()
					end
				end)
			end

			task.delay(0.1, function()
				AnimateOutputScreen(0.1, 0.4)
			end)
		end)
	end)

	return WindowFunctions
end

return WaveLibrary
end

R["Wave/UserInterface/Managers/ComponentManager.lua"] = function(...)
local ComponentManager = {}
ComponentManager.__index = ComponentManager


local ActiveKeybindListeners = {}
local RegisteredKeybinds = {}
local KeybindElements = {}

local KeyShortcuts = {
    Space = "SP",
    LeftShift = "LS",
    RightShift = "RS",
    LeftControl = "LC",
    RightControl = "RC",
    LeftAlt = "LA",
    RightAlt = "RA",

    MouseButton1 = "M1",
    MouseButton2 = "M2",
    MouseButton3 = "M3",

    CapsLock = "CL",
    NumLock = "NL",
    ScrollLock = "SL",

    Backspace = "BS",
    Return = "RT",
    Escape = "ES",
    Delete = "DL",
    Insert = "IN",
    PageUp = "PU",
    PageDown = "PD",
    Home = "HM",
    End = "EN",

    F1 = "F1",
    F2 = "F2",
    F3 = "F3",
    F4 = "F4",
    F5 = "F5",
    F6 = "F6",
    F7 = "F7",
    F8 = "F8",
    F9 = "F9",
    F10 = "F10",
    F11 = "F11",
    F12 = "F12",

    KeypadEnter = "KE",
    KeypadPlus = "KP+",
    KeypadMinus = "KP-",
    KeypadMultiply = "KP*",
    KeypadDivide = "KP/",
    KeypadZero = "K0",
    KeypadOne = "K1",
    KeypadTwo = "K2",
    KeypadThree = "K3",
    KeypadFour = "K4",
    KeypadFive = "K5",
    KeypadSix = "K6",
    KeypadSeven = "K7",
    KeypadEight = "K8",
    KeypadNine = "K9",

    Up = "UP",
    Down = "DN",
    Left = "LT",
    Right = "RT",

    Print = "PR",
    Pause = "PA",
    Menu = "MN",

    Unknown = "NA"
}

local ClassOffsets = {
    Button = 0.9,
    Toggle = 0.825,
}

local function CleanupConnection(ConnectionTable, Key)
    if ConnectionTable[Key] then
        if type(ConnectionTable[Key]) == "userdata" and ConnectionTable[Key].Disconnect then
            ConnectionTable[Key]:Disconnect()
        end

        ConnectionTable[Key] = nil
    end
end

local function FormatKeyDisplay(InputDescription)
    local DisplayKey = InputDescription:gsub("Enum.KeyCode.", ""):gsub("Enum.UserInputType.", "")
    return KeyShortcuts[DisplayKey] or DisplayKey
end

function ComponentManager.RemoveComponentBind(KeybindButton, KeybindLabel, Flag)
    if not RegisteredKeybinds[Flag] then
        Utility:Notify("Keybind Action", "No Keybind set for this feature.", 1)
        return
    end

    Utility:Notify("Keybind Action", "Keep holding to Unbind.", 1)

    task.delay(1, function()
        if Services.UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then
            RegisteredKeybinds[Flag] = nil

            Utility:Notify("Keybind Action", "Unbounded Key " .. Flag, 1)

            local TextTween = Utility:PropertyTween(
                KeybindLabel,
                TweenInfo.new(0.25, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                {TextTransparency = 1}
            )

            TextTween:Play()
            TextTween.Completed:Wait()
            KeybindLabel.Text = ""
        end
    end)
end

function ComponentManager.RegisterComponentKeybind(KeybindButton, KeybindLabel, Flag, MaidTable)
    if ActiveKeybindListeners[Flag] then
        return
    end

    ActiveKeybindListeners[Flag] = true
    
    Utility:Notify("Keybind Action", "The next key you click will be the keybind!", 3)
    
    MaidTable.KeybindInput = Services.UserInputService.InputBegan:Connect(function(Key, Typing)
        if Typing then
            return
        end

        local InputData = {}

        if Key.KeyCode ~= Enum.KeyCode.Unknown then
            InputData.Input = Key.KeyCode
            InputData.Description = tostring(Key.KeyCode.Name)
        elseif Key.UserInputType and string.find(tostring(Key.UserInputType), "MouseButton") then
            InputData.Input = Key.UserInputType
            InputData.Description = tostring(Key.UserInputType.Name)
        else
            InputData.Input = Key
            InputData.Description = tostring(Key)
        end

        InputData.KeybindSetTime = os.time()

        RegisteredKeybinds[Flag] = InputData

        if KeybindLabel == "" then
            KeybindLabel.TextTransparency = 1
        end

        Utility:Notify("Keybind Action", "Set Keybind to " .. InputData.Description, 3)
        KeybindLabel.Text = FormatKeyDisplay(InputData.Description)

        Utility:PropertyTween(
            KeybindLabel,
            TweenInfo.new(0.25, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
            {TextTransparency = 0.45}
        ):Play()

        CleanupConnection(MaidTable, "KeybindInput")
        ActiveKeybindListeners[Flag] = nil
    end)
end

function ComponentManager.CreateKeybindAssignments(KeybindButton, KeybindLabel, Arguments)
    Arguments.Maid.KeybindClick = KeybindButton.MouseButton1Click:Connect(function()
        if not Arguments.Functions:ReturnHidden() then
            ComponentManager.RegisterComponentKeybind(KeybindButton, KeybindLabel, Arguments.Flag, Arguments.Maid)
        end
    end)
    
    Arguments.Maid.KeybindRightClick = KeybindButton.MouseButton2Down:Connect(function()
        if not Arguments.Functions:ReturnHidden() then
            ComponentManager.RemoveComponentBind(KeybindButton, KeybindLabel, Arguments.Flag, Arguments.Maid)
        end
    end)

    local PreviousKeybindTransparency = KeybindButton.ImageTransparency
    
    Arguments.Maid.KeybindHover = KeybindButton.MouseEnter:Connect(function()
        if not Arguments.Functions:ReturnHidden() then
            PreviousKeybindTransparency = KeybindButton.ImageTransparency
            Utility:QuickTween(KeybindButton, {ImageTransparency = 0})
        end
    end)

    Arguments.Maid.KeybindLeave = KeybindButton.MouseLeave:Connect(function()
        if not Arguments.Functions:ReturnHidden() then
            Utility:QuickTween(KeybindButton, {ImageTransparency = PreviousKeybindTransparency})
        end
    end)
end

function ComponentManager.CreateKeybindComponents(Arguments)
    if not Arguments.Settings.KeybindEnabled then
        return
    end

    local KeybindButton = Instance.new("ImageButton")
    KeybindButton.Name = "KeybindButton"
    KeybindButton.Image = Assets.Fingerprint
    KeybindButton.ImageColor3 = Color3.fromRGB(255, 255, 255)
    KeybindButton.AutoButtonColor = false
    KeybindButton.AnchorPoint = Vector2.new(1, 0.5)
    KeybindButton.BackgroundTransparency = 1
    KeybindButton.BorderSizePixel = 0
    KeybindButton.Position = UDim2.fromScale(ClassOffsets[Arguments.Class], 0.5)
    KeybindButton.Size = UDim2.fromOffset(20, 20)
    KeybindButton.ImageTransparency = 0.45
    KeybindButton.Parent = Arguments.Ancestor

    local KeybindLabel = Instance.new("TextLabel")
    KeybindLabel.Name = "KeybindLabel"
    KeybindLabel.Size = UDim2.fromScale(1, 1)
    KeybindLabel.TextTransparency = 1
    KeybindLabel.TextStrokeTransparency = 0
    KeybindLabel.BackgroundTransparency = 1
    KeybindLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
    KeybindLabel.TextScaled = true
    KeybindLabel.Font = Enum.Font.SourceSansBold
    KeybindLabel.Text = ""
    KeybindLabel.Parent = KeybindButton

    ComponentManager.CreateKeybindAssignments(KeybindButton, KeybindLabel, Arguments)

    local Elements = {
        KeybindButton = KeybindButton,
        KeybindLabel = KeybindLabel
    }

    KeybindElements[Arguments.Flag] = Elements

    return Elements
end

function ComponentManager.UpdateKeybindDetection(State, Flag, Elements)
    if RegisteredKeybinds[Flag] then
        RegisteredKeybinds[Flag].DetectionState = State
    end

    local TWEEN_INFO = TweenInfo.new(0.2, Enum.EasingStyle.Sine)

    if not Elements.KeybindButton or not Elements.KeybindLabel then
        return
    end

    if State then
        Services.TweenService:Create(Elements.KeybindButton, TWEEN_INFO, {ImageTransparency = 0.9}):Play()
        Services.TweenService:Create(Elements.KeybindLabel, TWEEN_INFO, {TextTransparency = 0.8}):Play()
    else
        Services.TweenService:Create(Elements.KeybindButton, TWEEN_INFO, {ImageTransparency = 0.45}):Play()
        Services.TweenService:Create(Elements.KeybindLabel, TWEEN_INFO, {TextTransparency = 0.45}):Play()
    end
end

function ComponentManager.AddFlagKeybind(Flag, Input)
    if not Flag or not Input then
        return false
    end

    local InputData = {}

    if typeof(Input) == "string" then
        local Keycode, UserInput
        
        pcall(function()
            Keycode = Enum.KeyCode[Input]
        end)

        pcall(function()
            UserInput = Enum.UserInputType[Input]
        end)

        if Keycode then
            InputData.Input = Keycode
            InputData.Description = Keycode.Name
        elseif UserInput then
            InputData.Input = UserInput
            InputData.Description = UserInput.Name
        else
            return false
        end
    elseif typeof(Input) == "EnumItem" then
        InputData.Input = Input
        InputData.Description = Input.Name
    else
        return false
    end

    InputData.KeybindSetTime = os.time()
    InputData.DetectionState = true

    RegisteredKeybinds[Flag] = InputData

    if KeybindElements[Flag] and KeybindElements[Flag].KeybindLabel then
        local KeybindLabel = KeybindElements[Flag].KeybindLabel
        KeybindLabel.Text = FormatKeyDisplay(InputData.Description)
        Utility:PropertyTween(
            KeybindLabel,
            TweenInfo.new(0.25, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
            {TextTransparency = 0.45}
        ):Play()
    end

    return true
end

function ComponentManager:CheckFlagKeybind(Flag)
    if not Flag then
        return
    end

    if RegisteredKeybinds[Flag] then
        Utility:PrintTable(RegisteredKeybinds[Flag])
        return RegisteredKeybinds[Flag].Description
    end

    return nil
end

function ComponentManager:Unload()
    if ComponentManager.KeybindHandler ~= nil then
        ComponentManager.KeybindHandler:Disconnect()
    end

    ComponentManager.KeybindHandler = nil
end

ComponentManager.KeybindHandler = Services.UserInputService.InputBegan:Connect(function(Key, Typing)
    if Typing then
        return
    end

    local InputData = {}

    if Key.KeyCode ~= Enum.KeyCode.Unknown then
        InputData.Input = Key.KeyCode
    elseif Key.UserInputType and string.find(tostring(Key.UserInputType), "MouseButton") then
        InputData.Input = Key.UserInputType
    else
        InputData.Input = Key
    end

    InputData.KeybindHit = os.time()

    for Flag, Data in pairs(RegisteredKeybinds) do
        if Data.DetectionState ~= nil and not Data.DetectionState then
            continue
        end
        
        if Data.Input == InputData.Input and (InputData.KeybindHit - Data.KeybindSetTime) ~= 0 then
            local ClassType, Component = WaveLibrary:ReturnFeatures()[Flag]:ReturnClass(), WaveLibrary:ReturnFeatures()[Flag]

            if ClassType == "Toggle" then
                Component:Toggle()
            elseif ClassType == "Button" then
                Component:RunCallback()
            end
        end
    end
end)

return ComponentManager
end

R["Wave/UserInterface/Managers/SettingManager.lua"] = function(...)

end

R["Wave/UserInterface/Components/Button.lua"] = function(...)
return function(Requirements)
    local Section = Requirements.Section
    local WindowFunctions = Requirements.WindowFunctions
    local WaveLibraryUI = Requirements.WaveLibraryUI
    local WaveLibrary = Requirements.WaveLibrary
    local SectionFunctions = Requirements.SectionFunctions
    local BaseUIScale = Requirements.BaseUIScale

    local ComponentManager = Requirements.ComponentManager

    function SectionFunctions:Button(Settings, Flag)
        local ButtonFunctions = {
            Settings = Settings,
            IgnoreConfig = Settings.IgnoreConfig,
            Tab = Requirements.TabName,
            Class = "Button",
            IsHidden = false,
            Maid = {},
            Elements = {}
        }

        if not Flag or Flag == "WriteHere" or Flag == "AutoWriteFlag" then
            Flag = string.gsub(Settings.Name, " ", "_")
        end

        local TWEEN_INFO = TweenInfo.new(0.2, Enum.EasingStyle.Sine)
        local TRANSPARENCY = {
            Default = 0.5,
            Hover = 0,
            Hidden = 0.9
        }

        local ButtonAccent = WindowFunctions:GetCurrentThemeAttribute("AccentPrimary") or Color3.fromRGB(96, 165, 250)
        local ButtonBaseColor = WindowFunctions:GetCurrentThemeAttribute("ButtonColor") or Color3.fromRGB(40, 40, 48)

        local function CreateElements()
            local Elements = {}

            Elements.Button = Instance.new("Frame")
            Elements.Button.Name = "Button"
            Elements.Button.AutomaticSize = Enum.AutomaticSize.Y
            Elements.Button.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
            Elements.Button.BackgroundTransparency = 1
            Elements.Button.BorderSizePixel = 0
            Elements.Button.Size = UDim2.new(1, 0, 0, 38)
            Elements.Button.Parent = Section

            Elements.ButtonBackground = Instance.new("Frame")
            Elements.ButtonBackground.Name = "ButtonBG"
            Elements.ButtonBackground.BackgroundColor3 = WindowFunctions:GetCurrentThemeAttribute("HoverColor") or Color3.fromRGB(255, 255, 255)
            Elements.ButtonBackground.BackgroundTransparency = 1
            Elements.ButtonBackground.BorderSizePixel = 0
            Elements.ButtonBackground.AnchorPoint = Vector2.new(0.5, 0.5)
            Elements.ButtonBackground.Position = UDim2.fromScale(0.5, 0.5)
            Elements.ButtonBackground.Size = UDim2.new(1, 16, 1, 2)
            Elements.ButtonBackground.ZIndex = 0
            Elements.ButtonBackground:SetAttribute("NoApplyTheme", true)
            Elements.ButtonBackground.Parent = Elements.Button

            local ButtonBGCorner = Instance.new("UICorner")
            ButtonBGCorner.CornerRadius = UDim.new(0, 8)
            ButtonBGCorner.Parent = Elements.ButtonBackground

            Elements.ButtonInteract = Instance.new("TextButton")
            Elements.ButtonInteract.Name = "ButtonInteract"
            Elements.ButtonInteract.FontFace = Font.new(Assets.InterFont)
            Elements.ButtonInteract.RichText = true
            Elements.ButtonInteract.TextColor3 = Color3.fromRGB(255, 255, 255)
            Elements.ButtonInteract.TextSize = 13
            Elements.ButtonInteract.TextTransparency = TRANSPARENCY.Default
            Elements.ButtonInteract.TextTruncate = Enum.TextTruncate.AtEnd
            Elements.ButtonInteract.TextXAlignment = Enum.TextXAlignment.Left
            Elements.ButtonInteract.BackgroundTransparency = 1
            Elements.ButtonInteract.BorderSizePixel = 0
            Elements.ButtonInteract.Size = UDim2.fromScale(1, 1)
            Elements.ButtonInteract.Text = Settings.Name
            Elements.ButtonInteract.Parent = Elements.Button

            if Settings.PremiumFeature then
                Elements.ButtonInteract.TextTransparency = 0
                local PremiumGradient = Instance.new("UIGradient")
                PremiumGradient.Color = WindowFunctions:GetCurrentThemeAttribute("PremiumGradientColor") or ColorSequence.new({
                    ColorSequenceKeypoint.new(0, Color3.fromRGB(0, 106, 255)),
                    ColorSequenceKeypoint.new(0.2, Color3.fromRGB(163, 201, 255)),
                    ColorSequenceKeypoint.new(0.4, Color3.fromRGB(255, 255, 255)),
                    ColorSequenceKeypoint.new(1, Color3.fromRGB(163, 201, 255))
                })
                PremiumGradient.Parent = Elements.ButtonInteract
            end

            Elements.ButtonImage = Instance.new("ImageLabel")
            Elements.ButtonImage.Name = "ButtonImage"
            Elements.ButtonImage.Image = Assets.ButtonImage
            Elements.ButtonImage.ImageTransparency = TRANSPARENCY.Default
            Elements.ButtonImage.AnchorPoint = Vector2.new(1, 0.5)
            Elements.ButtonImage.BackgroundTransparency = 1
            Elements.ButtonImage.BorderSizePixel = 0
            Elements.ButtonImage.Position = UDim2.fromScale(1, 0.5)
            Elements.ButtonImage.Size = UDim2.fromOffset(15, 15)
            Elements.ButtonImage.Parent = Elements.Button

            return Elements
        end

        local function CreateKeybind()
            local KeybindComponents = ComponentManager.CreateKeybindComponents({
                Ancestor = ButtonFunctions.Elements.Button,
                Class = ButtonFunctions.Class,
                Maid = ButtonFunctions.Maid,
                Functions = ButtonFunctions,
                Settings = Settings,
                Flag = Flag
            })

            if KeybindComponents then
                ButtonFunctions.Elements.KeybindButton = KeybindComponents.KeybindButton
                ButtonFunctions.Elements.KeybindLabel = KeybindComponents.KeybindLabel
            end
        end

        local function HandleButtonClick()
            if ButtonFunctions.IsHidden then return end
            if Settings.Callback then
                Settings.Callback()
            end
        end

        local function ChangeState(State)
            if ButtonFunctions.IsHidden then return end

            local Hovering = State == "Hover"
            local TextTransparency = Hovering and TRANSPARENCY.Hover or TRANSPARENCY.Default
            local ImageTransparency = Hovering and TRANSPARENCY.Hover or TRANSPARENCY.Default

            Utility:PropertyTween(ButtonFunctions.Elements.ButtonBackground, TWEEN_INFO, {
                BackgroundTransparency = Hovering and 0.93 or 1
            }):Play()

            if not Settings.PremiumFeature then
                Utility:PropertyTween(ButtonFunctions.Elements.ButtonInteract, TWEEN_INFO, {
                    TextTransparency = TextTransparency
                }):Play()
            end

            if Utility:IsPremiumHubUser() then
                Utility:PropertyTween(ButtonFunctions.Elements.ButtonImage, TWEEN_INFO, {
                    ImageTransparency = ImageTransparency
                }):Play()
            end
        end

        local function SetupConnections()
            ButtonFunctions.Maid.ButtonClick = ButtonFunctions.Elements.ButtonInteract.MouseButton1Click:Connect(HandleButtonClick)

            ButtonFunctions.Maid.ButtonPress = ButtonFunctions.Elements.ButtonInteract.MouseButton1Down:Connect(function()
                if ButtonFunctions.IsHidden then return end
                Utility:PropertyTween(ButtonFunctions.Elements.ButtonBackground, TweenInfo.new(0.08), {BackgroundTransparency = 0.86}):Play()
            end)

            ButtonFunctions.Maid.ButtonRelease = ButtonFunctions.Elements.ButtonInteract.MouseButton1Up:Connect(function()
                Utility:PropertyTween(ButtonFunctions.Elements.ButtonBackground, TweenInfo.new(0.14), {BackgroundTransparency = 0.93}):Play()
            end)

            ButtonFunctions.Maid.ButtonHover = ButtonFunctions.Elements.ButtonInteract.MouseEnter:Connect(function()
                if ButtonFunctions.IsHidden then return end
                ChangeState("Hover")
            end)

            ButtonFunctions.Maid.ButtonLeave = ButtonFunctions.Elements.ButtonInteract.MouseLeave:Connect(function()
                ChangeState("Idle")
                if WaveLibraryUI:FindFirstChild("HoverFrame") then
                    WaveLibraryUI:FindFirstChild("HoverFrame"):Destroy()
                end
            end)
        end

        local function IsPlaceIdAllowed(PlaceIdSetting)
            if not PlaceIdSetting then return true end
            local CurrentPlaceId = game.PlaceId

            if type(PlaceIdSetting) == "table" then
                for _, PlaceId in pairs(PlaceIdSetting) do
                    if CurrentPlaceId == PlaceId then return true end
                end
                return false
            else
                return CurrentPlaceId == PlaceIdSetting
            end
        end

        local function IsPlaceIdForbidden(PlaceIdSetting)
            if not PlaceIdSetting then return false end
            local CurrentPlaceId = game.PlaceId

            if type(PlaceIdSetting) == "table" then
                for _, PlaceId in pairs(PlaceIdSetting) do
                    if CurrentPlaceId == PlaceId then return true end
                end
                return false
            else
                return CurrentPlaceId == PlaceIdSetting
            end
        end

        function ButtonFunctions:UpdateName(Name)
            ButtonFunctions.Elements.ButtonInteract.Text = Name
        end

        function ButtonFunctions:SetVisibility(State)
            ButtonFunctions.Elements.Button.Visible = State
        end

        function ButtonFunctions:GetState()
            return not ButtonFunctions.IsHidden
        end
        
        function ButtonFunctions:ReturnHidden()
            return ButtonFunctions.IsHidden
        end

        function ButtonFunctions:ReturnSettings()
            return Settings
        end

        function ButtonFunctions:ReturnClass()
            return ButtonFunctions.Class
        end

        function ButtonFunctions:ReturnTab()
            return ButtonFunctions.Tab
        end

        function ButtonFunctions:RunCallback()
            HandleButtonClick()
        end

        function ButtonFunctions:SetHidden(State, Reason)
            if Reason then
                self:SetToolTip(Reason)
            end

            ButtonFunctions.IsHidden = State
            ComponentManager.UpdateKeybindDetection(State, Flag, {
                KeybindButton = ButtonFunctions.Elements.KeybindButton,
                KeybindLabel = ButtonFunctions.Elements.KeybindLabel,
            })

            if State then
                Services.TweenService:Create(ButtonFunctions.Elements.ButtonImage, TWEEN_INFO, {ImageTransparency = TRANSPARENCY.Hidden}):Play()

                if not Settings.PremiumFeature then
                    Services.TweenService:Create(ButtonFunctions.Elements.ButtonInteract, TWEEN_INFO, {TextTransparency = TRANSPARENCY.Hidden}):Play()
                end

                if ButtonFunctions.Maid.ButtonClick then
                    ButtonFunctions.Maid.ButtonClick:Disconnect()
                    ButtonFunctions.Maid.ButtonClick = nil
                end
            else
                Services.TweenService:Create(ButtonFunctions.Elements.ButtonImage, TWEEN_INFO, {ImageTransparency = TRANSPARENCY.Default}):Play()

                if not Settings.PremiumFeature then
                    Services.TweenService:Create(ButtonFunctions.Elements.ButtonInteract, TWEEN_INFO, {TextTransparency = TRANSPARENCY.Default}):Play()
                end

                ButtonFunctions.Maid.ButtonClick = ButtonFunctions.Elements.ButtonInteract.MouseButton1Click:Connect(HandleButtonClick)
            end
        end

        function ButtonFunctions:SetToolTip(Tip)
            if ButtonFunctions.Elements.Button:FindFirstChild("ToolTipFrame") then
                ButtonFunctions.Elements.Button:FindFirstChild("ToolTipFrame"):Destroy()
            end

            if not Tip or Tip == "" then return end

            local ToolTipFrame = Instance.new("Frame")
            ToolTipFrame.Name = "ToolTipFrame"
            ToolTipFrame.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
            ToolTipFrame.BackgroundTransparency = 1
            ToolTipFrame.BorderSizePixel = 0
            ToolTipFrame.AnchorPoint = Vector2.new(0.5, 1)
            ToolTipFrame.Position = UDim2.new(0.5, 0, 0, -5)
            ToolTipFrame.Visible = false
            ToolTipFrame.ZIndex = 200
            ToolTipFrame.Parent = ButtonFunctions.Elements.Button

            local TooltipCorner = Instance.new("UICorner")
            TooltipCorner.CornerRadius = UDim.new(0, 6)
            TooltipCorner.Parent = ToolTipFrame

            local TooltipStroke = Instance.new("UIStroke")
            TooltipStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            TooltipStroke.LineJoinMode = Enum.LineJoinMode.Round
            TooltipStroke.Color = Color3.fromRGB(255, 255, 255)
            TooltipStroke.Thickness = 0.1
            TooltipStroke.Transparency = 0.2
            TooltipStroke.Parent = ToolTipFrame

            local TooltipText = Instance.new("TextLabel")
            TooltipText.Text = Tip
            TooltipText.FontFace = Font.new(Assets.InterFont)
            TooltipText.TextColor3 = Color3.fromRGB(200, 220, 200)
            TooltipText.TextSize = 12
            TooltipText.TextTransparency = 1
            TooltipText.BackgroundTransparency = 1
            TooltipText.TextXAlignment = Enum.TextXAlignment.Center
            TooltipText.TextYAlignment = Enum.TextYAlignment.Center
            TooltipText.Size = UDim2.new(1, -12, 1, 0)
            TooltipText.Position = UDim2.new(0, 6, 0, 0)
            TooltipText.Parent = ToolTipFrame

            local TextBounds = Services.TextService:GetTextSize(Tip, TooltipText.TextSize, Enum.Font.SourceSansBold, Vector2.new(math.huge, math.huge))
            local TooltipWidth = math.max(80, TextBounds.X + 50)
            local TooltipHeight = math.max(28, TextBounds.Y + 12)
            ToolTipFrame.Size = UDim2.new(0, TooltipWidth, 0, TooltipHeight)

            local function ShowTooltip()
                ToolTipFrame.Visible = true
                Services.TweenService:Create(ToolTipFrame, TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {BackgroundTransparency = 0.1}):Play()
                Services.TweenService:Create(TooltipText, TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {TextTransparency = 0}):Play()
                Services.TweenService:Create(TooltipStroke, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Transparency = 0.8}):Play()
            end

            local function HideTooltip()
                Services.TweenService:Create(ToolTipFrame, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {BackgroundTransparency = 1}):Play()
                Services.TweenService:Create(TooltipText, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {TextTransparency = 1}):Play()
                Services.TweenService:Create(TooltipStroke, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Transparency = 1}):Play()
                task.spawn(function()
                    task.wait(0.2)
                    if ToolTipFrame and ToolTipFrame.Parent then
                        ToolTipFrame.Visible = false
                    end
                end)
            end

            ButtonFunctions.Maid.TooltipShow = ButtonFunctions.Elements.ButtonInteract.MouseEnter:Connect(ShowTooltip)
            ButtonFunctions.Maid.TooltipHide = ButtonFunctions.Elements.ButtonInteract.MouseLeave:Connect(HideTooltip)
        end

        function ButtonFunctions:Destroy()
            for ConnectionName, Connection in pairs(ButtonFunctions.Maid) do
                if type(Connection) == "userdata" and Connection.Disconnect then
                    Connection:Disconnect()
                end
            end
            table.clear(ButtonFunctions.Maid)

            if ButtonFunctions.Elements.Button then
                ButtonFunctions.Elements.Button:Destroy()
            end

            if Flag and WaveLibrary.Options[Flag] then
                WaveLibrary.Options[Flag] = nil
            end
        end

        ButtonFunctions.Elements = CreateElements()
        CreateKeybind()
        SetupConnections()

        if Settings.Hidden then
            if typeof(Settings.Hidden) == "table" then
                ButtonFunctions:SetHidden(Settings.Hidden[1], Settings.Hidden[2])
            else
                ButtonFunctions:SetHidden(Settings.Hidden)
            end
        end

        if Settings.ToolTip then
            ButtonFunctions:SetToolTip(Settings.ToolTip)
        end

        if Settings.PremiumFeature and not Utility:IsPremiumHubUser() then
            ButtonFunctions:SetHidden(true, "Premium Feature")
        end

        if not IsPlaceIdAllowed(Settings.AllowedPlaceId) then
            ButtonFunctions:SetHidden(true, "Not in the right PlaceId to use this feature.")
        end

        if IsPlaceIdForbidden(Settings.ForbiddenPlaceId) then
            ButtonFunctions:SetHidden(true, "Not in the right PlaceId to use this feature.")
        end

        if Flag then
            WaveLibrary.Options[Flag] = ButtonFunctions
        end

        return ButtonFunctions
    end
end
end

R["Wave/UserInterface/Components/Callout.lua"] = function(...)
return function(Requirements)
    local Section = Requirements.Section
    local WindowFunctions = Requirements.WindowFunctions
    local WaveLibrary = Requirements.WaveLibrary
    local SectionFunctions = Requirements.SectionFunctions

    local function ThemeAttr(Name, Fallback)
        local ok, value = pcall(function()
            return WindowFunctions:GetCurrentThemeAttribute(Name)
        end)
        if ok and value ~= nil then return value end
        return Fallback
    end

    function SectionFunctions:Callout(Settings, Flag)
        Settings = Settings or {}

        local CalloutFunctions = { Settings = Settings, Class = "Callout", Tab = Requirements.TabName }

        local AccentMap = {
            Info = ThemeAttr("InfoColor", Color3.fromRGB(96, 165, 250)),
            None = ThemeAttr("AccentPrimary", Color3.fromRGB(96, 165, 250)),
            Success = ThemeAttr("SuccessColor", Color3.fromRGB(74, 222, 128)),
            Warning = ThemeAttr("WarningColor", Color3.fromRGB(250, 204, 21)),
            Error = ThemeAttr("ErrorColor", Color3.fromRGB(248, 113, 113)),
        }
        local Glyphs = { Info = "i", None = "i", Success = "✓", Warning = "!", Error = "✕" }

        local Style = Settings.Style or "Info"
        local Accent = AccentMap[Style] or AccentMap.Info
        local Glyph = Glyphs[Style] or "i"
        local TextPrimary = ThemeAttr("TextPrimary", Color3.fromRGB(236, 236, 241))
        local TextSecondary = ThemeAttr("TextSecondary", Color3.fromRGB(168, 168, 178))

        local HasTitle = (Settings.Title ~= nil and Settings.Title ~= "")
        local BodyValue = Settings.Content or Settings.Text or Settings.Description or ""

        local Card = Instance.new("Frame")
        Card.Name = "Callout"
        Card.BackgroundColor3 = Accent
        Card.BackgroundTransparency = 0.9
        Card.BorderSizePixel = 0
        Card.AutomaticSize = Enum.AutomaticSize.Y
        Card.Size = UDim2.new(1, 0, 0, 0)
        Card:SetAttribute("NoApplyTheme", true)
        Card.Parent = Section

        local CardCorner = Instance.new("UICorner")
        CardCorner.CornerRadius = UDim.new(0, 10)
        CardCorner.Parent = Card

        local CardStroke = Instance.new("UIStroke")
        CardStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        CardStroke.Color = Accent
        CardStroke.Transparency = 0.78
        CardStroke.Parent = Card

        local AccentBar = Instance.new("Frame")
        AccentBar.Name = "AccentBar"
        AccentBar.BackgroundColor3 = Accent
        AccentBar.BackgroundTransparency = 0.05
        AccentBar.BorderSizePixel = 0
        AccentBar.AnchorPoint = Vector2.new(0, 0.5)
        AccentBar.Position = UDim2.new(0, 6, 0.5, 0)
        AccentBar.Size = UDim2.new(0, 3, 1, -18)
        AccentBar:SetAttribute("NoApplyTheme", true)
        AccentBar.Parent = Card

        local AccentBarCorner = Instance.new("UICorner")
        AccentBarCorner.CornerRadius = UDim.new(1, 0)
        AccentBarCorner.Parent = AccentBar

        local Content = Instance.new("Frame")
        Content.Name = "Content"
        Content.BackgroundTransparency = 1
        Content.AutomaticSize = Enum.AutomaticSize.Y
        Content.Size = UDim2.new(1, 0, 0, 0)
        Content.Parent = Card

        local ContentPadding = Instance.new("UIPadding")
        ContentPadding.PaddingTop = UDim.new(0, 11)
        ContentPadding.PaddingBottom = UDim.new(0, 12)
        ContentPadding.PaddingLeft = UDim.new(0, 17)
        ContentPadding.PaddingRight = UDim.new(0, 13)
        ContentPadding.Parent = Content

        local ColumnLayout = Instance.new("UIListLayout")
        ColumnLayout.SortOrder = Enum.SortOrder.LayoutOrder
        ColumnLayout.Padding = UDim.new(0, 3)
        ColumnLayout.Parent = Content

        -- Top line: the main line (title, or body when there's no title) on the
        -- left and the status icon docked right, vertically centred with it.
        local TopLine = Instance.new("Frame")
        TopLine.Name = "TopLine"
        TopLine.BackgroundTransparency = 1
        TopLine.Parent = Content
        if HasTitle then
            TopLine.Size = UDim2.new(1, 0, 0, 22)
        else
            TopLine.AutomaticSize = Enum.AutomaticSize.Y
            TopLine.Size = UDim2.new(1, 0, 0, 0)
        end

        local IconHolder = Instance.new("Frame")
        IconHolder.Name = "IconHolder"
        IconHolder.Size = UDim2.fromOffset(22, 22)
        IconHolder.BackgroundColor3 = Accent
        IconHolder.BackgroundTransparency = 0.8
        IconHolder.BorderSizePixel = 0
        IconHolder:SetAttribute("NoApplyTheme", true)
        if HasTitle then
            IconHolder.AnchorPoint = Vector2.new(1, 0.5)
            IconHolder.Position = UDim2.new(1, 0, 0.5, 0)
        else
            IconHolder.AnchorPoint = Vector2.new(1, 0)
            IconHolder.Position = UDim2.new(1, 0, 0, 0)
        end
        IconHolder.Parent = TopLine

        local IconCorner = Instance.new("UICorner")
        IconCorner.CornerRadius = UDim.new(1, 0)
        IconCorner.Parent = IconHolder

        local IconGlyph = Instance.new("TextLabel")
        IconGlyph.Name = "Result_Glyph"
        IconGlyph.BackgroundTransparency = 1
        IconGlyph.Size = UDim2.fromScale(1, 1)
        IconGlyph.Text = Glyph
        IconGlyph.TextColor3 = Accent
        IconGlyph.FontFace = Font.new(Assets.InterFont, Enum.FontWeight.Bold, Enum.FontStyle.Normal)
        IconGlyph.TextSize = 13
        IconGlyph:SetAttribute("NoApplyTheme", true)
        IconGlyph.Parent = IconHolder

        local MainText = Instance.new("TextLabel")
        MainText.Name = HasTitle and "Result_Title" or "Result_Body"
        MainText.FontFace = Font.new(Assets.InterFont, HasTitle and Enum.FontWeight.SemiBold or Enum.FontWeight.Medium, Enum.FontStyle.Normal)
        MainText.RichText = true
        MainText.Text = HasTitle and Settings.Title or BodyValue
        MainText.TextColor3 = HasTitle and TextPrimary or TextSecondary
        MainText.TextTransparency = HasTitle and 0 or 0.1
        MainText.TextSize = HasTitle and 13 or 12
        MainText.TextXAlignment = Enum.TextXAlignment.Left
        MainText.BackgroundTransparency = 1
        MainText:SetAttribute("NoApplyTheme", true)
        if HasTitle then
            MainText.TextYAlignment = Enum.TextYAlignment.Center
            MainText.TextTruncate = Enum.TextTruncate.AtEnd
            MainText.Size = UDim2.new(1, -30, 1, 0)
        else
            MainText.TextYAlignment = Enum.TextYAlignment.Top
            MainText.TextWrapped = true
            MainText.AutomaticSize = Enum.AutomaticSize.Y
            MainText.Size = UDim2.new(1, -30, 0, 0)
        end
        MainText.Parent = TopLine

        local BodyText
        if HasTitle then
            BodyText = Instance.new("TextLabel")
            BodyText.Name = "Result_Body"
            BodyText.FontFace = Font.new(Assets.InterFont, Enum.FontWeight.Medium, Enum.FontStyle.Normal)
            BodyText.RichText = true
            BodyText.Text = BodyValue
            BodyText.TextColor3 = TextSecondary
            BodyText.TextTransparency = 0.1
            BodyText.TextSize = 12
            BodyText.TextXAlignment = Enum.TextXAlignment.Left
            BodyText.TextYAlignment = Enum.TextYAlignment.Top
            BodyText.TextWrapped = true
            BodyText.AutomaticSize = Enum.AutomaticSize.Y
            BodyText.BackgroundTransparency = 1
            BodyText.LayoutOrder = 1
            BodyText.Size = UDim2.new(1, 0, 0, 0)
            BodyText.Visible = (BodyValue ~= "")
            BodyText:SetAttribute("NoApplyTheme", true)
            BodyText.Parent = Content
        else
            BodyText = MainText
        end

        function CalloutFunctions:SetContent(New)
            BodyText.Text = New
            if HasTitle then BodyText.Visible = (New ~= nil and New ~= "") end
            return self
        end
        CalloutFunctions.SetValue = CalloutFunctions.SetContent

        function CalloutFunctions:SetTitle(New)
            if HasTitle then MainText.Text = New end
            return self
        end

        function CalloutFunctions:SetVisibility(State)
            Card.Visible = State
        end

        function CalloutFunctions:ReturnClass()
            return "Callout"
        end

        function CalloutFunctions:Destroy()
            Card:Destroy()
        end

        if Flag then
            WaveLibrary.Options[Flag] = CalloutFunctions
        end

        return CalloutFunctions
    end
end
end

R["Wave/UserInterface/Components/CheckBox.lua"] = function(...)
return function(Requirements)
    local Section = Requirements.Section
    local WindowFunctions = Requirements.WindowFunctions
    local WaveLibraryUI = Requirements.WaveLibraryUI
    local WaveLibrary = Requirements.WaveLibrary
    local SectionFunctions = Requirements.SectionFunctions
    local BaseUIScale = Requirements.BaseUIScale

    function SectionFunctions:CheckBox(Settings, Flag)
        local CheckBoxFunctions = {
            Settings = Settings,
            IgnoreConfig = Settings.IgnoreConfig,
            Tab = Requirements.TabName,
            Class = "CheckBox",
            State = Settings.Default or false,
            IsHidden = false,
            Maid = {},
            Elements = {}
        }

        if not Flag or Flag == "WriteHere" or Flag == "AutoWriteFlag" then
            Flag = string.gsub(Settings.Name, " ", "_")
        end

        local TWEEN_INFO = TweenInfo.new(0.2, Enum.EasingStyle.Sine)

        local function CreateElements()
            local Elements = {}

            Elements.CheckBox = Instance.new("Frame")
            Elements.CheckBox.Name = "CheckBox"
            Elements.CheckBox.AutomaticSize = Enum.AutomaticSize.Y
            Elements.CheckBox.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
            Elements.CheckBox.BackgroundTransparency = 1
            Elements.CheckBox.BorderSizePixel = 0
            Elements.CheckBox.Size = UDim2.new(1, 0, 0, 38)
            Elements.CheckBox.Parent = Section

            Elements.CheckBoxName = Instance.new("TextLabel")
            Elements.CheckBoxName.Name = "CheckBoxName"
            Elements.CheckBoxName.FontFace = Font.new(Assets.InterFont)
            Elements.CheckBoxName.Text = Settings.Name
            Elements.CheckBoxName.RichText = true
            Elements.CheckBoxName.TextColor3 = WindowFunctions:GetCurrentThemeAttribute("TextPrimary")
            Elements.CheckBoxName.TextSize = 13
            Elements.CheckBoxName.TextTransparency = 0.5
            Elements.CheckBoxName.TextTruncate = Enum.TextTruncate.AtEnd
            Elements.CheckBoxName.TextXAlignment = Enum.TextXAlignment.Left
            Elements.CheckBoxName.TextYAlignment = Enum.TextYAlignment.Top
            Elements.CheckBoxName.AnchorPoint = Vector2.new(0, 0.5)
            Elements.CheckBoxName.AutomaticSize = Enum.AutomaticSize.Y
            Elements.CheckBoxName.BackgroundTransparency = 1
            Elements.CheckBoxName.Position = UDim2.fromScale(0, 0.5)
            Elements.CheckBoxName.Size = UDim2.new(1, -35, 0, 0)
            Elements.CheckBoxName.Parent = Elements.CheckBox

            if Settings.PremiumFeature then
                Elements.CheckBoxName.TextTransparency = 0
                local PremiumGradient = Instance.new("UIGradient")
                PremiumGradient.Color = WindowFunctions:GetCurrentThemeAttribute("PremiumGradientColor") or ColorSequence.new({
                    ColorSequenceKeypoint.new(0, Color3.fromRGB(0, 106, 255)),
                    ColorSequenceKeypoint.new(0.2, Color3.fromRGB(163, 201, 255)),
                    ColorSequenceKeypoint.new(0.4, Color3.fromRGB(255, 255, 255)),
                    ColorSequenceKeypoint.new(1, Color3.fromRGB(163, 201, 255))
                })
                PremiumGradient.Parent = Elements.CheckBoxName
            end

            Elements.CheckBoxButton = Instance.new("TextButton")
            Elements.CheckBoxButton.Name = "CheckBoxButton"
            Elements.CheckBoxButton.Text = ""
            Elements.CheckBoxButton.AutoButtonColor = false
            Elements.CheckBoxButton.AnchorPoint = Vector2.new(1, 0.5)
            Elements.CheckBoxButton.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
            Elements.CheckBoxButton.BackgroundTransparency = 0.9
            Elements.CheckBoxButton.BorderSizePixel = 0
            Elements.CheckBoxButton.Position = UDim2.fromScale(1, 0.5)
            Elements.CheckBoxButton.Size = UDim2.fromOffset(18, 18)
            Elements.CheckBoxButton.Parent = Elements.CheckBox

            local CheckBoxUICorner = Instance.new("UICorner")
            CheckBoxUICorner.CornerRadius = UDim.new(0, 4)
            CheckBoxUICorner.Parent = Elements.CheckBoxButton

            local CheckBoxUIStroke = Instance.new("UIStroke")
            CheckBoxUIStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            CheckBoxUIStroke.Color = Color3.fromRGB(255, 255, 255)
            CheckBoxUIStroke.Thickness = 1
            CheckBoxUIStroke.Transparency = 0.8
            CheckBoxUIStroke.Parent = Elements.CheckBoxButton

            Elements.Checkmark = Instance.new("TextLabel")
            Elements.Checkmark.Name = "Checkmark"
            Elements.Checkmark.Text = "✓"
            Elements.Checkmark.FontFace = Font.new(Assets.InterFont, Enum.FontWeight.Bold)
            Elements.Checkmark.TextColor3 = Color3.fromRGB(255, 255, 255)
            Elements.Checkmark.TextSize = 12
            Elements.Checkmark.TextScaled = true
            Elements.Checkmark.TextTransparency = 1
            Elements.Checkmark.BackgroundTransparency = 1
            Elements.Checkmark.BorderSizePixel = 0
            Elements.Checkmark.Position = UDim2.fromScale(0, 0)
            Elements.Checkmark.Size = UDim2.fromScale(1, 1)
            Elements.Checkmark.TextXAlignment = Enum.TextXAlignment.Center
            Elements.Checkmark.TextYAlignment = Enum.TextYAlignment.Center
            Elements.Checkmark.ZIndex = 2
            Elements.Checkmark.Parent = Elements.CheckBoxButton

            return Elements
        end

        local function UpdateCheckBoxState(State)
            if State then
                Utility:PropertyTween(CheckBoxFunctions.Elements.CheckBoxButton, TWEEN_INFO, {
                    BackgroundTransparency = 0.7,
                    BackgroundColor3 = WindowFunctions:GetCurrentThemeAttribute("AccentPrimary")
                }):Play()

                Utility:PropertyTween(CheckBoxFunctions.Elements.CheckBoxButton.UICorner, TWEEN_INFO, {
                    CornerRadius = UDim.new(0, 1)
                }):Play()

                Utility:PropertyTween(CheckBoxFunctions.Elements.Checkmark, TWEEN_INFO, {
                    TextTransparency = 0
                }):Play()

                local StrokeTween = Utility:PropertyTween(CheckBoxFunctions.Elements.CheckBoxButton:FindFirstChild("UIStroke"), TWEEN_INFO, {
                    Transparency = 0.3,
                    Color = WindowFunctions:GetCurrentThemeAttribute("AccentPrimary")
                })
                if StrokeTween then StrokeTween:Play() end
            else
                Utility:PropertyTween(CheckBoxFunctions.Elements.CheckBoxButton, TWEEN_INFO, {
                    BackgroundTransparency = 0.9,
                    BackgroundColor3 = Color3.fromRGB(255, 255, 255)
                }):Play()

                Utility:PropertyTween(CheckBoxFunctions.Elements.CheckBoxButton.UICorner, TWEEN_INFO, {
                    CornerRadius = UDim.new(0, 12)
                }):Play()

                Utility:PropertyTween(CheckBoxFunctions.Elements.Checkmark, TWEEN_INFO, {
                    TextTransparency = 1
                }):Play()

                local StrokeTween = Utility:PropertyTween(CheckBoxFunctions.Elements.CheckBoxButton:FindFirstChild("UIStroke"), TWEEN_INFO, {
                    Transparency = 0.8,
                    Color = Color3.fromRGB(255, 255, 255)
                })
                if StrokeTween then StrokeTween:Play() end
            end

            CheckBoxFunctions.State = State
        end

        local function CheckBoxTrigger()
            if Settings.Fixed or CheckBoxFunctions.IsHidden then return end

            CheckBoxFunctions.State = not CheckBoxFunctions.State
            UpdateCheckBoxState(CheckBoxFunctions.State)

            if Settings.Callback then
                Settings.Callback(CheckBoxFunctions.State)
            end
        end

        local function SetupConnections()
            CheckBoxFunctions.Maid.CheckBoxClick = CheckBoxFunctions.Elements.CheckBoxButton.MouseButton1Click:Connect(CheckBoxTrigger)

            if not Settings.PremiumFeature then
                local PreviousTransparency = CheckBoxFunctions.Elements.CheckBoxName.TextTransparency

                CheckBoxFunctions.Maid.CheckBoxHover = CheckBoxFunctions.Elements.CheckBoxButton.MouseEnter:Connect(function()
                    if CheckBoxFunctions.IsHidden then return end
                    PreviousTransparency = CheckBoxFunctions.Elements.CheckBoxName.TextTransparency
                    Utility:QuickTween(CheckBoxFunctions.Elements.CheckBoxName, {TextTransparency = 0})
                end)

                CheckBoxFunctions.Maid.CheckBoxLeave = CheckBoxFunctions.Elements.CheckBoxButton.MouseLeave:Connect(function()
                    if CheckBoxFunctions.IsHidden then return end
                    Utility:QuickTween(CheckBoxFunctions.Elements.CheckBoxName, {TextTransparency = PreviousTransparency})
                end)
            end
        end

        local function IsPlaceIdAllowed(PlaceIdSetting)
            if not PlaceIdSetting then return true end
            local CurrentPlaceId = game.PlaceId

            if type(PlaceIdSetting) == "table" then
                for _, PlaceId in pairs(PlaceIdSetting) do
                    if CurrentPlaceId == PlaceId then return true end
                end
                return false
            else
                return CurrentPlaceId == PlaceIdSetting
            end
        end

        local function IsPlaceIdForbidden(PlaceIdSetting)
            if not PlaceIdSetting then return false end
            local CurrentPlaceId = game.PlaceId

            if type(PlaceIdSetting) == "table" then
                for _, PlaceId in pairs(PlaceIdSetting) do
                    if CurrentPlaceId == PlaceId then return true end
                end
                return false
            else
                return CurrentPlaceId == PlaceIdSetting
            end
        end

        function CheckBoxFunctions:Check()
            CheckBoxTrigger()
        end

        function CheckBoxFunctions:ServerCheck()
            CheckBoxFunctions.State = not CheckBoxFunctions.State
            UpdateCheckBoxState(CheckBoxFunctions.State)
            if Settings.Callback then
                Settings.Callback(CheckBoxFunctions.State)
            end
        end

        function CheckBoxFunctions:UpdateState(State, Callback)
            CheckBoxFunctions.State = State
            UpdateCheckBoxState(CheckBoxFunctions.State)
            
            if Callback then
                if Settings.Callback then
                    Settings.Callback(CheckBoxFunctions.State)
                end
            end
        end

        function CheckBoxFunctions:GetState()
            return CheckBoxFunctions.State
        end

        function CheckBoxFunctions:ReturnSettings()
            return Settings
        end

        function CheckBoxFunctions:ReturnTab()
            return CheckBoxFunctions.Tab
        end

        function CheckBoxFunctions:ReturnClass()
            return CheckBoxFunctions.Class
        end

        function CheckBoxFunctions:UpdateName(Name)
            CheckBoxFunctions.Elements.CheckBoxName.Text = Name
        end

        function CheckBoxFunctions:SetToolTip(Tip)
            if CheckBoxFunctions.Elements.CheckBox:FindFirstChild("ToolTipFrame") then
                CheckBoxFunctions.Elements.CheckBox:FindFirstChild("ToolTipFrame"):Destroy()
            end

            if not Tip or Tip == "" then return end

            local ToolTipFrame = Instance.new("Frame")
            ToolTipFrame.Name = "ToolTipFrame"
            ToolTipFrame.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
            ToolTipFrame.BackgroundTransparency = 1
            ToolTipFrame.BorderSizePixel = 0
            ToolTipFrame.AnchorPoint = Vector2.new(0.5, 1)
            ToolTipFrame.Position = UDim2.new(0.5, 0, 0, -5)
            ToolTipFrame.Visible = false
            ToolTipFrame.ZIndex = 200
            ToolTipFrame.Parent = CheckBoxFunctions.Elements.CheckBox

            local TooltipCorner = Instance.new("UICorner")
            TooltipCorner.CornerRadius = UDim.new(0, 6)
            TooltipCorner.Parent = ToolTipFrame

            local TooltipStroke = Instance.new("UIStroke")
            TooltipStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            TooltipStroke.LineJoinMode = Enum.LineJoinMode.Round
            TooltipStroke.Color = Color3.fromRGB(255, 255, 255)
            TooltipStroke.Thickness = 0.1
            TooltipStroke.Transparency = 0.2
            TooltipStroke.Parent = ToolTipFrame

            local TooltipText = Instance.new("TextLabel")
            TooltipText.Text = Tip
            TooltipText.FontFace = Font.new(Assets.InterFont)
            TooltipText.TextColor3 = Color3.fromRGB(200, 220, 200)
            TooltipText.TextSize = 12
            TooltipText.TextTransparency = 1
            TooltipText.BackgroundTransparency = 1
            TooltipText.TextXAlignment = Enum.TextXAlignment.Center
            TooltipText.TextYAlignment = Enum.TextYAlignment.Center
            TooltipText.Size = UDim2.new(1, -12, 1, 0)
            TooltipText.Position = UDim2.new(0, 6, 0, 0)
            TooltipText.Parent = ToolTipFrame

            local TextBounds = Services.TextService:GetTextSize(Tip, TooltipText.TextSize, Enum.Font.SourceSansBold, Vector2.new(math.huge, math.huge))
            local TooltipWidth = math.max(80, TextBounds.X + 50)
            local TooltipHeight = math.max(28, TextBounds.Y + 12)
            ToolTipFrame.Size = UDim2.new(0, TooltipWidth, 0, TooltipHeight)

            CheckBoxFunctions.Maid.TooltipShow = CheckBoxFunctions.Elements.CheckBoxButton.MouseEnter:Connect(function()
                ToolTipFrame.Visible = true
                Services.TweenService:Create(ToolTipFrame, TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {BackgroundTransparency = 0.1}):Play()
                Services.TweenService:Create(TooltipText, TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {TextTransparency = 0}):Play()
                Services.TweenService:Create(TooltipStroke, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Transparency = 0.8}):Play()
            end)

            CheckBoxFunctions.Maid.TooltipHide = CheckBoxFunctions.Elements.CheckBoxButton.MouseLeave:Connect(function()
                Services.TweenService:Create(ToolTipFrame, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {BackgroundTransparency = 1}):Play()
                Services.TweenService:Create(TooltipText, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {TextTransparency = 1}):Play()
                Services.TweenService:Create(TooltipStroke, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Transparency = 1}):Play()
                task.wait(0.2)
                if ToolTipFrame and ToolTipFrame.Parent then
                    ToolTipFrame.Visible = false
                end
            end)
        end

        function CheckBoxFunctions:SetHidden(State, Reason)
            if Reason then
                self:SetToolTip(Reason)
            end

            CheckBoxFunctions.IsHidden = State

            if State then
                Services.TweenService:Create(CheckBoxFunctions.Elements.CheckBoxButton, TweenInfo.new(0.2), {BackgroundTransparency = 0.99}):Play()
                Services.TweenService:Create(CheckBoxFunctions.Elements.Checkmark, TweenInfo.new(0.2), {TextTransparency = 0.9}):Play()

                local Stroke = CheckBoxFunctions.Elements.CheckBoxButton:FindFirstChild("UIStroke")
                if Stroke then
                    Services.TweenService:Create(Stroke, TweenInfo.new(0.2), {Transparency = 0.95}):Play()
                end

                if not Settings.PremiumFeature then
                    Services.TweenService:Create(CheckBoxFunctions.Elements.CheckBoxName, TweenInfo.new(0.2), {TextTransparency = 0.9}):Play()
                end

                if CheckBoxFunctions.Maid.CheckBoxClick then
                    CheckBoxFunctions.Maid.CheckBoxClick:Disconnect()
                    CheckBoxFunctions.Maid.CheckBoxClick = nil
                end
            else
                UpdateCheckBoxState(CheckBoxFunctions.State)

                if not Settings.PremiumFeature then
                    Services.TweenService:Create(CheckBoxFunctions.Elements.CheckBoxName, TweenInfo.new(0.2), {TextTransparency = 0.5}):Play()
                end

                CheckBoxFunctions.Maid.CheckBoxClick = CheckBoxFunctions.Elements.CheckBoxButton.MouseButton1Click:Connect(CheckBoxTrigger)
            end
        end

        function CheckBoxFunctions:SetVisibility(State)
            CheckBoxFunctions.Elements.CheckBox.Visible = State
        end

        function CheckBoxFunctions:Destroy()
            for ConnectionName, Connection in pairs(CheckBoxFunctions.Maid) do
                if type(Connection) == "userdata" and Connection.Disconnect then
                    Connection:Disconnect()
                end
            end
            table.clear(CheckBoxFunctions.Maid)

            if CheckBoxFunctions.Elements.CheckBox then
                CheckBoxFunctions.Elements.CheckBox:Destroy()
            end

            if Flag and WaveLibrary.Options[Flag] then
                WaveLibrary.Options[Flag] = nil
            end
        end

        CheckBoxFunctions.Elements = CreateElements()
        SetupConnections()
        UpdateCheckBoxState(CheckBoxFunctions.State)

        if Settings.Hidden then
            if typeof(Settings.Hidden) == "table" then
                CheckBoxFunctions:SetHidden(Settings.Hidden[1], Settings.Hidden[2])
            else
                CheckBoxFunctions:SetHidden(Settings.Hidden)
            end
        end

        if Settings.Default == true and Settings.Callback then
            task.defer(function()
                Settings.Callback(Settings.Default)
            end)
        end

        if Settings.ToolTip then
            CheckBoxFunctions:SetToolTip(Settings.ToolTip)
        end

        if Settings.PremiumFeature and not Utility:IsPremiumHubUser() then
            CheckBoxFunctions:SetHidden(true, "Premium Feature")
        end

        if not IsPlaceIdAllowed(Settings.AllowedPlaceId) then
            CheckBoxFunctions:SetHidden(true, "Not in the right PlaceId to use this feature.")
        end

        if IsPlaceIdForbidden(Settings.ForbiddenPlaceId) then
            CheckBoxFunctions:SetHidden(true, "Not in the right PlaceId to use this feature.")
        end

        if Flag then
            WaveLibrary.Options[Flag] = CheckBoxFunctions
        end

        return CheckBoxFunctions
    end
end
end

R["Wave/UserInterface/Components/ColorPicker.lua"] = function(...)
return function(Requirements)
    local Section = Requirements.Section
    local WindowFunctions = Requirements.WindowFunctions
    local WaveLibraryUI = Requirements.WaveLibraryUI
    local WaveLibrary = Requirements.WaveLibrary
    local SectionFunctions = Requirements.SectionFunctions
    local BaseUIScale = Requirements.BaseUIScale
    local Base = Requirements.Base
    
    function SectionFunctions:ColorPicker(Settings, Flag)
        local ColorPickerFunctions = {
            Settings = Settings,
            Class = "ColorPicker",
            IgnoreConfig = Settings.IgnoreConfig,
            Tab = Requirements.TabName,
            Color = Settings.Default or Color3.new(1, 1, 1),
            Alpha = Settings.Alpha or 0,
            IsHidden = false,
            Maid = {},
            Elements = {},
            State = {
                Hue = 0,
                Saturation = 0,
                Value = 1,
                WheelDown = false,
                SlideDown = false
            }
        }

        if not Flag or Flag == "WriteHere" or Flag == "AutoWriteFlag" then
            Flag = string.gsub(Settings.Name, " ", "_")
        end

        local TWEEN_INFO = TweenInfo.new(0.2, Enum.EasingStyle.Sine)
        local TRANSPARENCY = {
            Default = 0.5,
            Hover = 0,
            Hidden = 0.9
        }

        local UI_CONSTANTS = {
            MAIN_HEIGHT = 38,
            COLOR_SIZE = 21,
            CORNER_RADIUS = {
                Small = UDim.new(0, 4),
                Medium = UDim.new(0, 6),
                Large = UDim.new(0, 10)
            },
            PADDING = {
                Small = UDim.new(0, 5),
                Medium = UDim.new(0, 10),
                Large = UDim.new(0, 20)
            }
        }

        local function CreateMainElements()
            local Elements = {}

            Elements.ColorPicker = Instance.new("Frame")
            Elements.ColorPicker.Name = "ColorPicker"
            Elements.ColorPicker.AutomaticSize = Enum.AutomaticSize.Y
            Elements.ColorPicker.BackgroundTransparency = 1
            Elements.ColorPicker.BorderSizePixel = 0
            Elements.ColorPicker.Size = UDim2.new(1, 0, 0, UI_CONSTANTS.MAIN_HEIGHT)
            Elements.ColorPicker.Parent = Section

            Elements.ColorPickerName = Instance.new("TextLabel")
            Elements.ColorPickerName.Name = "ColorPickerName"
            Elements.ColorPickerName.FontFace = Font.new(Assets.InterFont)
            Elements.ColorPickerName.Text = Settings.Name
            Elements.ColorPickerName.RichText = true
            Elements.ColorPickerName.TextColor3 = Color3.fromRGB(255, 255, 255)
            Elements.ColorPickerName.TextSize = 13
            Elements.ColorPickerName.TextTransparency = TRANSPARENCY.Default
            Elements.ColorPickerName.TextTruncate = Enum.TextTruncate.AtEnd
            Elements.ColorPickerName.TextXAlignment = Enum.TextXAlignment.Left
            Elements.ColorPickerName.TextYAlignment = Enum.TextYAlignment.Top
            Elements.ColorPickerName.AnchorPoint = Vector2.new(0, 0.5)
            Elements.ColorPickerName.AutomaticSize = Enum.AutomaticSize.XY
            Elements.ColorPickerName.BackgroundTransparency = 1
            Elements.ColorPickerName.Position = UDim2.fromScale(0, 0.5)
            Elements.ColorPickerName.Parent = Elements.ColorPicker

            if Settings.PremiumFeature then
                Elements.ColorPickerName.TextTransparency = 0
                local PremiumGradient = Instance.new("UIGradient")
                PremiumGradient.Color = WindowFunctions:GetCurrentThemeAttribute("PremiumGradientColor") or ColorSequence.new({
                    ColorSequenceKeypoint.new(0, Color3.fromRGB(0, 106, 255)),
                    ColorSequenceKeypoint.new(0.2, Color3.fromRGB(163, 201, 255)),
                    ColorSequenceKeypoint.new(0.4, Color3.fromRGB(255, 255, 255)),
                    ColorSequenceKeypoint.new(1, Color3.fromRGB(163, 201, 255))
                })
                PremiumGradient.Parent = Elements.ColorPickerName
            end

            Elements.ColorBackground = Instance.new("ImageLabel")
            Elements.ColorBackground.Name = "ColorBackground"
            Elements.ColorBackground.Image = Assets.Grid
            Elements.ColorBackground.ScaleType = Enum.ScaleType.Tile
            Elements.ColorBackground.TileSize = UDim2.fromOffset(500, 500)
            Elements.ColorBackground.AnchorPoint = Vector2.new(1, 0.5)
            Elements.ColorBackground.BackgroundTransparency = 1
            Elements.ColorBackground.Position = UDim2.fromScale(1, 0.5)
            Elements.ColorBackground.Size = UDim2.fromOffset(UI_CONSTANTS.COLOR_SIZE, UI_CONSTANTS.COLOR_SIZE)
            Elements.ColorBackground.Parent = Elements.ColorPicker

            Elements.ColorDisplay = Instance.new("Frame")
            Elements.ColorDisplay.Name = "ColorDisplay"
            Elements.ColorDisplay.AnchorPoint = Vector2.new(0.5, 0.5)
            Elements.ColorDisplay.BackgroundColor3 = ColorPickerFunctions.Color
            Elements.ColorDisplay.BorderSizePixel = 0
            Elements.ColorDisplay.Position = UDim2.fromScale(0.5, 0.5)
            Elements.ColorDisplay.Size = UDim2.fromScale(1, 1)
            Elements.ColorDisplay.BackgroundTransparency = ColorPickerFunctions.Alpha
            Elements.ColorDisplay.Parent = Elements.ColorBackground

            Elements.ColorInteract = Instance.new("TextButton")
            Elements.ColorInteract.Name = "ColorInteract"
            Elements.ColorInteract.Text = ""
            Elements.ColorInteract.BackgroundTransparency = 1
            Elements.ColorInteract.Size = UDim2.fromScale(1, 1)
            Elements.ColorInteract.Parent = Elements.ColorDisplay

            local DisplayCorner = Instance.new("UICorner")
            DisplayCorner.CornerRadius = UI_CONSTANTS.CORNER_RADIUS.Medium
            DisplayCorner.Parent = Elements.ColorDisplay

            local BackgroundCorner = Instance.new("UICorner")
            BackgroundCorner.CornerRadius = UDim.new(0, 8)
            BackgroundCorner.Parent = Elements.ColorBackground

            return Elements
        end

        local function CreateColorDialog()
            local Dialog = {}

            Dialog.Overlay = Instance.new("Frame")
            Dialog.Overlay.Name = "ColorPickerOverlay"
            Dialog.Overlay.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
            Dialog.Overlay.BackgroundTransparency = 0.5
            Dialog.Overlay.BorderSizePixel = 0
            Dialog.Overlay.Size = UDim2.fromScale(1, 1)
            Dialog.Overlay.Visible = false

            local OverlayCorner = Instance.new("UICorner")
            OverlayCorner.CornerRadius = UI_CONSTANTS.CORNER_RADIUS.Large
