end
end

R["Wave/UserInterface/Components/Paragraph.lua"] = function(...)
return function(Requirements)
    local Section = Requirements.Section
    local WindowFunctions = Requirements.WindowFunctions
    local WaveLibraryUI = Requirements.WaveLibraryUI
    local WaveLibrary = Requirements.WaveLibrary
    local SectionFunctions = Requirements.SectionFunctions
    local BaseUIScale = Requirements.BaseUIScale

    function SectionFunctions:Paragraph(Settings, Flag)
        local ParagraphFunctions = { Settings = Settings }

        local Paragraph = Instance.new("Frame")
        Paragraph.Name = "Paragraph"
        Paragraph.AutomaticSize = Enum.AutomaticSize.Y
        Paragraph.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
        Paragraph.BackgroundTransparency = 1
        Paragraph.BorderColor3 = Color3.fromRGB(0, 0, 0)
        Paragraph.BorderSizePixel = 0
        Paragraph.Size = UDim2.new(1, 0, 0, 38)
        Paragraph.Parent = Section

        local ParagraphHeader = Instance.new("TextLabel")
        ParagraphHeader.Name = "ParagraphHeader"
        ParagraphHeader.FontFace = Font.new(Assets.InterFont, Enum.FontWeight.Medium, Enum.FontStyle.Normal)
        ParagraphHeader.RichText = true
        ParagraphHeader.Text = ParagraphFunctions.Settings.Header
        ParagraphHeader.TextColor3 = Color3.fromRGB(255, 255, 255)
        ParagraphHeader.TextSize = 15
        ParagraphHeader.TextTransparency = 0.4
        ParagraphHeader.TextWrapped = true
        ParagraphHeader.TextXAlignment = Enum.TextXAlignment.Left
        ParagraphHeader.AutomaticSize = Enum.AutomaticSize.Y
        ParagraphHeader.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        ParagraphHeader.BackgroundTransparency = 1
        ParagraphHeader.BorderColor3 = Color3.fromRGB(0, 0, 0)
        ParagraphHeader.BorderSizePixel = 0
        ParagraphHeader.Size = UDim2.fromScale(1, 0)
        ParagraphHeader.Parent = Paragraph

        local UIListLayout = Instance.new("UIListLayout")
        UIListLayout.Name = "UIListLayout"
        UIListLayout.Padding = UDim.new(0, 5)
        UIListLayout.SortOrder = Enum.SortOrder.LayoutOrder
        UIListLayout.Parent = Paragraph

        local ParagraphBody = Instance.new("TextLabel")
        ParagraphBody.Name = "ParagraphBody"
        ParagraphBody.FontFace = Font.new(Assets.InterFont)
        ParagraphBody.RichText = true
        ParagraphBody.Text = ParagraphFunctions.Settings.Body
        ParagraphBody.TextColor3 = Color3.fromRGB(255, 255, 255)
        ParagraphBody.TextSize = 13
        ParagraphBody.TextTransparency = 0.5
        ParagraphBody.TextWrapped = true
        ParagraphBody.TextXAlignment = Enum.TextXAlignment.Left
        ParagraphBody.AutomaticSize = Enum.AutomaticSize.Y
        ParagraphBody.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        ParagraphBody.BackgroundTransparency = 1
        ParagraphBody.BorderColor3 = Color3.fromRGB(0, 0, 0)
        ParagraphBody.BorderSizePixel = 0
        ParagraphBody.LayoutOrder = 1
        ParagraphBody.Size = UDim2.fromScale(1, 0)
        ParagraphBody.Parent = Paragraph

        function ParagraphFunctions:UpdateHeader(New)
            ParagraphHeader.Text = New
        end

        function ParagraphFunctions:UpdateBody(New)
            ParagraphBody.Text = New
        end

        function ParagraphFunctions:SetVisibility(State)
            Paragraph.Visible = State
        end

        if Flag then
            WaveLibrary.Options[Flag] = ParagraphFunctions
        end

        return ParagraphFunctions
    end
end
end

R["Wave/UserInterface/Components/PlayerDropdown.lua"] = function(...)
return function(Requirements)
    local Section = Requirements.Section
    local WindowFunctions = Requirements.WindowFunctions
    local WaveLibraryUI = Requirements.WaveLibraryUI
    local WaveLibrary = Requirements.WaveLibrary
    local SectionFunctions = Requirements.SectionFunctions
    local BaseUIScale = Requirements.BaseUIScale

    function SectionFunctions:PlayerDropdown(Settings, Flag)
        local DropdownFunctions = {
            Settings = Settings,
            IgnoreConfig = false,
            Class = "PlayerDropdown",
            Tab = Requirements.TabName,
            Value = nil
        }

        if not Flag or Flag == "WriteHere" or Flag == "AutoWriteFlag" then
            Flag = string.gsub(DropdownFunctions.Settings.Name, " ", "_")
        end

        local Selected = {}
        local OptionObjs = {}
        local PlayerConnections = {}
        local Dropped = false
        local DB = false
        local IsHidden = false
        local PreviousTransparency = 0.5
        local TooltipConnections = {}

        local Dropdown = Instance.new("Frame")
        Dropdown.Name = "PlayerDropdown"
        Dropdown.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        Dropdown.BackgroundTransparency = 0.985
        Dropdown.BorderColor3 = Color3.fromRGB(0, 0, 0)
        Dropdown.BorderSizePixel = 0
        Dropdown.Size = UDim2.new(1, 0, 0, 38)
        Dropdown.Parent = Section
        Dropdown.ClipsDescendants = true

        local DropdownUIPadding = Instance.new("UIPadding")
        DropdownUIPadding.Name = "DropdownUIPadding"
        DropdownUIPadding.PaddingLeft = UDim.new(0, 15)
        DropdownUIPadding.PaddingRight = UDim.new(0, 15)
        DropdownUIPadding.Parent = Dropdown

        local Interact = Instance.new("TextButton")
        Interact.Name = "Interact"
        Interact.FontFace = Font.new("rbxasset://fonts/families/SourceSansPro.json")
        Interact.Text = ""
        Interact.TextColor3 = Color3.fromRGB(0, 0, 0)
        Interact.TextSize = 14
        Interact.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        Interact.BackgroundTransparency = 1
        Interact.BorderColor3 = Color3.fromRGB(0, 0, 0)
        Interact.BorderSizePixel = 0
        Interact.Size = UDim2.new(1, 0, 0, 38)
        Interact.Parent = Dropdown

        local DropdownName = Instance.new("TextLabel")
        DropdownName.Name = "DropdownName"
        DropdownName.FontFace = Font.new(Assets.InterFont)
        DropdownName.Text = Settings.Default and (DropdownFunctions.Settings.Name .. " • " .. table.concat(Selected, ", ")) or (DropdownFunctions.Settings.Name .. "...")
        DropdownName.RichText = true
        DropdownName.TextColor3 = WindowFunctions:GetCurrentThemeAttribute("TextPrimary")
        DropdownName.TextSize = 13
        DropdownName.TextTransparency = 0.5
        DropdownName.TextTruncate = Enum.TextTruncate.SplitWord
        DropdownName.TextXAlignment = Enum.TextXAlignment.Left
        DropdownName.AutomaticSize = Enum.AutomaticSize.Y
        DropdownName.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        DropdownName.BackgroundTransparency = 1
        DropdownName.BorderColor3 = Color3.fromRGB(0, 0, 0)
        DropdownName.BorderSizePixel = 0
        DropdownName.Size = UDim2.new(1, -20, 0, 38)
        DropdownName.Parent = Dropdown

        if Settings.PremiumFeature then
            DropdownName.TextTransparency = 0
            local PremiumGradient = Instance.new("UIGradient")
            PremiumGradient.Color = WindowFunctions:GetCurrentThemeAttribute("PremiumGradientColor") or ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.fromRGB(0, 106, 255)),
                ColorSequenceKeypoint.new(0.2, Color3.fromRGB(163, 201, 255)),
                ColorSequenceKeypoint.new(0.4, Color3.fromRGB(255, 255, 255)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(163, 201, 255))
            })
            PremiumGradient.Rotation = 0
            PremiumGradient.Parent = DropdownName
        end

        local DropdownUIStroke = Instance.new("UIStroke")
        DropdownUIStroke.Name = "DropdownUIStroke"
        DropdownUIStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        DropdownUIStroke.Color = Color3.fromRGB(255, 255, 255)
        DropdownUIStroke.Transparency = 0.95
        DropdownUIStroke.Parent = Dropdown

        local DropdownUICorner = Instance.new("UICorner")
        DropdownUICorner.Name = "DropdownUICorner"
        DropdownUICorner.CornerRadius = UDim.new(0, 6)
        DropdownUICorner.Parent = Dropdown

        local DropdownImage = Instance.new("ImageLabel")
        DropdownImage.Name = "DropdownImage"
        DropdownImage.Image = Assets.Dropdown
        DropdownImage.ImageTransparency = 0.5
        DropdownImage.AnchorPoint = Vector2.new(1, 0)
        DropdownImage.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        DropdownImage.BackgroundTransparency = 1
        DropdownImage.BorderColor3 = Color3.fromRGB(0, 0, 0)
        DropdownImage.BorderSizePixel = 0
        DropdownImage.Position = UDim2.new(1, 0, 0, 12)
        DropdownImage.Size = UDim2.fromOffset(14, 14)
        DropdownImage.Parent = Dropdown

        -- Inner option list is a ScrollingFrame below the 38px header so long
        -- player lists scroll inside the dropdown on mobile (see Dropdown.lua).
        local DropdownFrame = Instance.new("ScrollingFrame")
        DropdownFrame.Name = "DropdownFrame"
        DropdownFrame.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        DropdownFrame.BackgroundTransparency = 1
        DropdownFrame.BorderColor3 = Color3.fromRGB(0, 0, 0)
        DropdownFrame.BorderSizePixel = 0
        DropdownFrame.ClipsDescendants = true
        DropdownFrame.Position = UDim2.new(0, 0, 0, 38)
        DropdownFrame.Size = UDim2.new(1, 0, 1, -38)
        DropdownFrame.Visible = false
        DropdownFrame.Active = true
        DropdownFrame.AutomaticCanvasSize = Enum.AutomaticSize.Y
        DropdownFrame.CanvasSize = UDim2.new()
        DropdownFrame.ScrollingDirection = Enum.ScrollingDirection.Y
        DropdownFrame.ScrollBarThickness = 3
        DropdownFrame.ScrollBarImageColor3 = Color3.fromRGB(255, 255, 255)
        DropdownFrame.ScrollBarImageTransparency = 0.5
        DropdownFrame.BottomImage = ""
        DropdownFrame.TopImage = ""

        local DropdownFrameUIPadding = Instance.new("UIPadding")
        DropdownFrameUIPadding.Name = "DropdownFrameUIPadding"
        DropdownFrameUIPadding.PaddingTop = UDim.new(0, 4)
        DropdownFrameUIPadding.PaddingBottom = UDim.new(0, 10)
        DropdownFrameUIPadding.Parent = DropdownFrame

        local DropdownFrameUIListLayout = Instance.new("UIListLayout")
        DropdownFrameUIListLayout.Name = "DropdownFrameUIListLayout"
        DropdownFrameUIListLayout.Padding = UDim.new(0, 5)
        DropdownFrameUIListLayout.SortOrder = Enum.SortOrder.LayoutOrder
        DropdownFrameUIListLayout.Parent = DropdownFrame

        local Search = Instance.new("Frame")
        Search.Name = "Search"
        Search.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        Search.BackgroundTransparency = 0.95
        Search.BorderColor3 = Color3.fromRGB(0, 0, 0)
        Search.BorderSizePixel = 0
        Search.LayoutOrder = -1
        Search.Size = UDim2.new(1, 0, 0, 30)
        Search.Parent = DropdownFrame
        Search.Visible = DropdownFunctions.Settings.Search ~= false

        local SectionUICorner = Instance.new("UICorner")
        SectionUICorner.Name = "SectionUICorner"
        SectionUICorner.Parent = Search

        local SearchIcon = Instance.new("ImageLabel")
        SearchIcon.Name = "SearchIcon"
        SearchIcon.Image = Assets.SearchIcon
        SearchIcon.ImageColor3 = Color3.fromRGB(180, 180, 180)
        SearchIcon.AnchorPoint = Vector2.new(0, 0.5)
        SearchIcon.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        SearchIcon.BackgroundTransparency = 1
        SearchIcon.BorderColor3 = Color3.fromRGB(0, 0, 0)
        SearchIcon.BorderSizePixel = 0
        SearchIcon.Position = UDim2.fromScale(0, 0.5)
        SearchIcon.Size = UDim2.fromOffset(12, 12)
        SearchIcon.Parent = Search

        if not Utility:IsPremiumHubUser() and Settings.PremiumFeature then
            SearchIcon.ImageTransparency = 0.6
            DropdownImage.ImageTransparency = 0.9
        end

        local UIPadding = Instance.new("UIPadding")
        UIPadding.Name = "UIPadding"
        UIPadding.PaddingLeft = UDim.new(0, 15)
        UIPadding.Parent = Search

        local SearchBox = Instance.new("TextBox")
        SearchBox.Name = "SearchBox"
        SearchBox.FontFace = Font.new(Assets.InterFont, Enum.FontWeight.Medium, Enum.FontStyle.Normal)
        SearchBox.PlaceholderColor3 = Color3.fromRGB(150, 150, 150)
        SearchBox.PlaceholderText = "Search players..."
        SearchBox.Text = ""
        SearchBox.TextColor3 = Color3.fromRGB(200, 200, 200)
        SearchBox.TextSize = 14
        SearchBox.TextXAlignment = Enum.TextXAlignment.Left
        SearchBox.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        SearchBox.BackgroundTransparency = 1
        SearchBox.BorderColor3 = Color3.fromRGB(0, 0, 0)
        SearchBox.BorderSizePixel = 0
        SearchBox.Size = UDim2.fromScale(1, 1)

        local UIPadding1 = Instance.new("UIPadding")
        UIPadding1.Name = "UIPadding"
        UIPadding1.PaddingLeft = UDim.new(0, 23)
        UIPadding1.Parent = SearchBox

        SearchBox.Parent = Search
        DropdownFrame.Parent = Dropdown

        local TweenSettings = {
            Duration = 0.2,
            EasingStyle = Enum.EasingStyle.Quint,
            TransparencyIn = 0,
            TransparencyOut = 0.5,
            CheckSizeIncrease = 12,
            CheckSizeDecrease = -13,
            WaitTime = 1
        }

        local DROPDOWN_HEADER_HEIGHT = 38
        local MAX_OPTIONS_HEIGHT = 200

        local function CalculateDropdownSize()
            local TotalHeight = 0
            local VisibleChildrenCount = 0
            local Padding = DropdownFrame:FindFirstChild("DropdownFrameUIPadding")
            local PaddingOffset = Padding and (Padding.PaddingTop.Offset + Padding.PaddingBottom.Offset) or 0

            for _, V in pairs(DropdownFrame:GetChildren()) do
                if not V:IsA("UIComponent") and V.Visible then
                    TotalHeight += V.AbsoluteSize.Y
                    VisibleChildrenCount += 1
                end
            end

            local Spacing = DropdownFrameUIListLayout.Padding.Offset * math.max(0, VisibleChildrenCount - 1)
            local OptionsHeight = TotalHeight + Spacing + PaddingOffset
            if OptionsHeight > MAX_OPTIONS_HEIGHT then
                OptionsHeight = MAX_OPTIONS_HEIGHT
            end
            return DROPDOWN_HEADER_HEIGHT + OptionsHeight
        end

        local function FindOption()
            local SearchTerm = SearchBox.Text:lower()

            for _, V in pairs(OptionObjs) do
                local OptionText = V.NameLabel.Text:lower()
                local IsVisible = string.find(OptionText, SearchTerm) ~= nil
                V.Button.Visible = IsVisible
            end

            if Dropped then
                Dropdown.Size = UDim2.new(1, 0, 0, CalculateDropdownSize())
            end
        end

        SearchBox:GetPropertyChangedSignal("Text"):Connect(FindOption)

        local function Toggle(OptionName, State)
            local Option = OptionObjs[OptionName]
            if not Option then return end

            local Checkmark = Option.Checkmark
            local OptionNameLabel = Option.NameLabel

            if State then
                if DropdownFunctions.Settings.Multi then
                    if not table.find(Selected, OptionName) then
                        table.insert(Selected, OptionName)
                        DropdownFunctions.Value = Selected
                    end
                else

                    for Name, Opt in pairs(OptionObjs) do
                        if Name ~= OptionName then
                            Utility:PropertyTween(Opt.Checkmark, TweenInfo.new(TweenSettings.Duration, TweenSettings.EasingStyle), {
                                Size = UDim2.new(Opt.Checkmark.Size.X.Scale, TweenSettings.CheckSizeDecrease, Opt.Checkmark.Size.Y.Scale, Opt.Checkmark.Size.Y.Offset)
                            }):Play()
                            Utility:PropertyTween(Opt.NameLabel, TweenInfo.new(TweenSettings.Duration, TweenSettings.EasingStyle), {
                                TextTransparency = TweenSettings.TransparencyOut
                            }):Play()
                            Opt.Checkmark.TextTransparency = 1
                        end
                    end
                    Selected = {OptionName}
                    DropdownFunctions.Value = Selected[1]
                end

                Utility:PropertyTween(Checkmark, TweenInfo.new(TweenSettings.Duration, TweenSettings.EasingStyle), {
                    Size = UDim2.new(Checkmark.Size.X.Scale, TweenSettings.CheckSizeIncrease, Checkmark.Size.Y.Scale, Checkmark.Size.Y.Offset)
                }):Play()
                Utility:PropertyTween(OptionNameLabel, TweenInfo.new(TweenSettings.Duration, TweenSettings.EasingStyle), {
                    TextTransparency = TweenSettings.TransparencyIn
                }):Play()
                Checkmark.TextTransparency = 0
            else
                if DropdownFunctions.Settings.Multi then
                    local Idx = table.find(Selected, OptionName)
                    if Idx then
                        table.remove(Selected, Idx)
                    end
                else
                    Selected = {}
                end

                Utility:PropertyTween(Checkmark, TweenInfo.new(TweenSettings.Duration, TweenSettings.EasingStyle), {
                    Size = UDim2.new(Checkmark.Size.X.Scale, TweenSettings.CheckSizeDecrease, Checkmark.Size.Y.Scale, Checkmark.Size.Y.Offset)
                }):Play()
                Utility:PropertyTween(OptionNameLabel, TweenInfo.new(TweenSettings.Duration, TweenSettings.EasingStyle), {
                    TextTransparency = TweenSettings.TransparencyOut
                }):Play()
                Checkmark.TextTransparency = 1
            end

            if Settings.Required and #Selected == 0 and not State then
                return
            end

            if #Selected > 0 then
                DropdownName.Text = DropdownFunctions.Settings.Name .. " • " .. table.concat(Selected, ", ")
            else
                DropdownName.Text = DropdownFunctions.Settings.Name .. "..."
            end
        end

        local function SetupHoverEffects()
            if not Settings.PremiumFeature then
                Interact.MouseEnter:Connect(function()
                    if IsHidden then return end

                    Utility:QuickTween(DropdownName, {
                        TextTransparency = 0
                    })
                    Utility:QuickTween(DropdownImage, {
                        ImageTransparency = 0
                    })
                end)

                Interact.MouseLeave:Connect(function()
                    if IsHidden then return end

                    Utility:QuickTween(DropdownName, {
                        TextTransparency = 0.5
                    })
                    Utility:QuickTween(DropdownImage, {
                        ImageTransparency = 0.5
                    })
                end)
            end
        end

        SetupHoverEffects()

        local function ToggleDropdown()
            if IsHidden then return end
            if not Utility:IsPremiumHubUser() and Settings.PremiumFeature then return end
            if DB then return end

            DB = true
            local DefaultDropdownSize = 38
            local IsDropdownOpen = not Dropped
            local TargetSize = IsDropdownOpen and UDim2.new(1, 0, 0, CalculateDropdownSize()) or UDim2.new(1, 0, 0, DefaultDropdownSize)

            local DropTween = Utility:PropertyTween(Dropdown, TweenInfo.new(0.2, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {
                Size = TargetSize
            })
            local IconTween = Utility:PropertyTween(DropdownImage, TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Rotation = IsDropdownOpen and -90 or 0
            })

            DropTween:Play()
            IconTween:Play()

            if IsDropdownOpen then
                DropdownFrame.Visible = true
                DropTween.Completed:Connect(function()
                    DB = false
                end)
            else
                DropTween.Completed:Connect(function()
                    DropdownFrame.Visible = false
                    DB = false
                end)
            end

            Dropped = IsDropdownOpen
        end

        Interact.MouseButton1Click:Connect(ToggleDropdown)

        local function AddOption(I, V, Display)
            local Option = Instance.new("TextButton")
            Option.Name = "Option"
            Option.FontFace = Font.new("rbxasset://fonts/families/SourceSansPro.json")
            Option.Text = ""
            Option.TextColor3 = Color3.fromRGB(0, 0, 0)
            Option.TextSize = 14
            Option.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
            Option.BackgroundTransparency = 1
            Option.BorderColor3 = Color3.fromRGB(0, 0, 0)
            Option.BorderSizePixel = 0
            Option.Size = UDim2.new(1, 0, 0, 30)

            local OptionUIPadding = Instance.new("UIPadding")
            OptionUIPadding.Name = "OptionUIPadding"
            OptionUIPadding.PaddingLeft = UDim.new(0, 15)
            OptionUIPadding.Parent = Option

            local OptionUIListLayout = Instance.new("UIListLayout")
            OptionUIListLayout.Name = "OptionUIListLayout"
            OptionUIListLayout.Padding = UDim.new(0, 10)
            OptionUIListLayout.FillDirection = Enum.FillDirection.Horizontal
            OptionUIListLayout.SortOrder = Enum.SortOrder.LayoutOrder
            OptionUIListLayout.VerticalAlignment = Enum.VerticalAlignment.Center
            OptionUIListLayout.Parent = Option

            local Checkmark = Instance.new("TextLabel")
            Checkmark.Name = "Checkmark"
            Checkmark.FontFace = Font.new(Assets.InterFont)
            Checkmark.Text = "✓"
            Checkmark.TextColor3 = Color3.fromRGB(255, 255, 255)
            Checkmark.TextSize = 13
            Checkmark.TextTransparency = 1
            Checkmark.TextXAlignment = Enum.TextXAlignment.Left
            Checkmark.TextYAlignment = Enum.TextYAlignment.Top
            Checkmark.AnchorPoint = Vector2.new(0, 0.5)
            Checkmark.AutomaticSize = Enum.AutomaticSize.Y
            Checkmark.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
            Checkmark.BackgroundTransparency = 1
            Checkmark.BorderColor3 = Color3.fromRGB(0, 0, 0)
            Checkmark.BorderSizePixel = 0
            Checkmark.LayoutOrder = -1
            Checkmark.Position = UDim2.fromScale(1.3e-07, 0.5)
            Checkmark.Size = UDim2.fromOffset(-OptionUIListLayout.Padding.Offset, 0)
            Checkmark.Parent = Option

            local OptionName = Instance.new("TextLabel")
            OptionName.Name = "OptionName"
            OptionName.FontFace = Font.new(Assets.InterFont)
            OptionName.Text = Display
            OptionName.RichText = true
            OptionName.TextColor3 = Color3.fromRGB(255, 255, 255)
            OptionName.TextSize = 13
            OptionName.TextTransparency = 0.5
            OptionName.TextTruncate = Enum.TextTruncate.AtEnd
            OptionName.TextXAlignment = Enum.TextXAlignment.Left
            OptionName.TextYAlignment = Enum.TextYAlignment.Top
            OptionName.AnchorPoint = Vector2.new(0, 0.5)
            OptionName.AutomaticSize = Enum.AutomaticSize.XY
            OptionName.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
            OptionName.BackgroundTransparency = 1
            OptionName.BorderColor3 = Color3.fromRGB(0, 0, 0)
            OptionName.BorderSizePixel = 0
            OptionName.Position = UDim2.fromScale(1.3e-07, 0.5)
            OptionName.Parent = Option

            if not Settings.PremiumFeature then
                Option.MouseEnter:Connect(function()
                    if IsHidden then return end

                    Utility:QuickTween(OptionName, {
                        TextTransparency = 0
                    })
                end)

                Option.MouseLeave:Connect(function()
                    if IsHidden then return end

                    Utility:QuickTween(OptionName, {
                        TextTransparency = table.find(Selected, V) and 0 or 0.5
                    })
                end)
            end

            Option.Parent = DropdownFrame
            OptionObjs[V] = {
                Index = I,
                Button = Option,
                NameLabel = OptionName,
                Checkmark = Checkmark
            }

            Option.MouseButton1Click:Connect(function()
                if IsHidden then return end

                local IsSelected = table.find(Selected, V) and true or false
                local NewSelected = not IsSelected

                if DropdownFunctions.Settings.Required and not NewSelected and #Selected <= 1 then
                    return
                end

                Toggle(V, NewSelected)

                task.spawn(function()
                    if DropdownFunctions.Settings.Callback then
                        if DropdownFunctions.Settings.Multi then
                            local Return = {}
                            for _, Opt in ipairs(Selected) do
                                Return[Opt] = true
                            end
                            DropdownFunctions.Settings.Callback(Return)
                        else
                            if NewSelected then
                                DropdownFunctions.Settings.Callback(Selected[1] or nil)
                            end
                        end
                    end
                end)
            end)

            if Dropped then
                Dropdown.Size = UDim2.new(1, 0, 0, CalculateDropdownSize())
            end
        end

        local function RefreshPlayers()
            for _, OptionData in pairs(OptionObjs) do
                OptionData.Button:Destroy()
            end
            OptionObjs = {}

            local Players = Services.Players:GetPlayers()
            for I, Player in ipairs(Players) do
                if Player ~= Utility:GetPlayer() or DropdownFunctions.Settings.IncludeSelf then
                    AddOption(I, Player.Name, Player.DisplayName)
                end
            end

            if Dropped then
                Dropdown.Size = UDim2.new(1, 0, 0, CalculateDropdownSize())
            end
        end

        local function OnPlayerAdded(Player)
            if Player ~= Utility:GetPlayer() or DropdownFunctions.Settings.IncludeSelf then
                local PlayerCount = 0
                for _ in pairs(OptionObjs) do
                    PlayerCount += 1
                end
                AddOption(PlayerCount + 1, Player.Name, Player.DisplayName)
            end
        end

        local function OnPlayerRemoving(Player)
            local PlayerName = Player.Name
            local OptionData = OptionObjs[PlayerName]

            if OptionData then
                for I = #Selected, 1, -1 do
                    if Selected[I] == PlayerName then
                        table.remove(Selected, I)
                    end
                end

                if #Selected > 0 then
                    DropdownName.Text = DropdownFunctions.Settings.Name .. " • " .. table.concat(Selected, ", ")
                else
                    DropdownName.Text = DropdownFunctions.Settings.Name .. "..."
                end

                OptionData.Button:Destroy()
                OptionObjs[PlayerName] = nil

                if Dropped then
                    Dropdown.Size = UDim2.new(1, 0, 0, CalculateDropdownSize())
                end

                if DropdownFunctions.Settings.Callback then
                    if DropdownFunctions.Settings.Multi then
                        local Return = {}
                        for _, Opt in ipairs(Selected) do
                            Return[Opt] = true
                        end
                        DropdownFunctions.Settings.Callback(Return)
                    else
                        DropdownFunctions.Settings.Callback(Selected[1] or nil)
                    end
                end
            end
        end

        PlayerConnections.PlayerAdded = Services.Players.PlayerAdded:Connect(OnPlayerAdded)
        PlayerConnections.PlayerRemoving = Services.Players.PlayerRemoving:Connect(OnPlayerRemoving)

        RefreshPlayers()

        function DropdownFunctions:SetToolTip(Tip)
            for _, connection in pairs(TooltipConnections) do
                if connection then
                    connection:Disconnect()
                end
            end
            TooltipConnections = {}

            if Dropdown:FindFirstChild("ToolTipFrame") then
                Dropdown:FindFirstChild("ToolTipFrame"):Destroy()
            end

            if not Tip or Tip == "" then
                return
            end

            local ToolTipFrame = Instance.new("Frame")
            ToolTipFrame.Name = "ToolTipFrame"
            ToolTipFrame.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
            ToolTipFrame.BackgroundTransparency = 1
            ToolTipFrame.BorderSizePixel = 0
            ToolTipFrame.AnchorPoint = Vector2.new(0.5, 1)
            ToolTipFrame.Position = UDim2.new(0.5, 0, 0, -5)
            ToolTipFrame.Visible = false
            ToolTipFrame.ZIndex = 200
            ToolTipFrame.Parent = Dropdown

            local TooltipCorner = Instance.new("UICorner")
            TooltipCorner.CornerRadius = UDim.new(0, 6)
            TooltipCorner.Parent = ToolTipFrame

            local TooltipStroke = Instance.new("UIStroke")
            TooltipStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            TooltipStroke.LineJoinMode = Enum.LineJoinMode.Round
            TooltipStroke.Color = Color3.fromRGB(255, 255, 255)
            TooltipStroke.Thickness = 0.1
            TooltipStroke.Transparency = 0.2
            TooltipStroke.Parent = ToolTipFrame

            local TooltipText = Instance.new("TextLabel")
            TooltipText.Name = "TooltipText"
            TooltipText.Text = Tip
            TooltipText.FontFace = Font.new(Assets.InterFont)
            TooltipText.TextColor3 = Color3.fromRGB(200, 220, 200)
            TooltipText.TextSize = 12
            TooltipText.TextTransparency = 1
            TooltipText.BackgroundTransparency = 1
            TooltipText.TextXAlignment = Enum.TextXAlignment.Center
            TooltipText.TextYAlignment = Enum.TextYAlignment.Center
            TooltipText.TextWrapped = false
            TooltipText.Size = UDim2.new(1, -12, 1, 0)
            TooltipText.Position = UDim2.new(0, 6, 0, 0)
            TooltipText.Parent = ToolTipFrame

            local TextBounds = Services.TextService:GetTextSize(
                Tip,
                TooltipText.TextSize,
                Enum.Font.SourceSansBold,
                Vector2.new(math.huge, math.huge)
            )

            local TooltipWidth = math.max(80, TextBounds.X + 50)
            local TooltipHeight = math.max(28, TextBounds.Y + 12)
            ToolTipFrame.Size = UDim2.new(0, TooltipWidth, 0, TooltipHeight)

            local function ShowTooltip()
                Dropdown.ClipsDescendants = false
                ToolTipFrame.Visible = true
                ToolTipFrame.BackgroundTransparency = 1
                TooltipText.TextTransparency = 1

                Services.TweenService:Create(
                    ToolTipFrame,
                    TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                    {BackgroundTransparency = 0.1}
                ):Play()

                Services.TweenService:Create(
                    TooltipText,
                    TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                    {TextTransparency = 0}
                ):Play()

                Services.TweenService:Create(
                    TooltipStroke,
                    TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                    {Transparency = 0.8}
                ):Play()
            end

            local function HideTooltip()
                Dropdown.ClipsDescendants = true
                Services.TweenService:Create(
                    ToolTipFrame,
                    TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                    {BackgroundTransparency = 1}
                ):Play()

                Services.TweenService:Create(
                    TooltipText,
                    TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                    {TextTransparency = 1}
                ):Play()

                Services.TweenService:Create(
                    TooltipStroke,
                    TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                    {Transparency = 1}
                ):Play()

                task.spawn(function()
                    task.wait(0.2)
                    if ToolTipFrame and ToolTipFrame.Parent then
                        ToolTipFrame.Visible = false
                    end
                end)
            end

            if not IsHidden then
                TooltipConnections[#TooltipConnections + 1] = Interact.MouseEnter:Connect(ShowTooltip)
                TooltipConnections[#TooltipConnections + 1] = Interact.MouseLeave:Connect(HideTooltip)
            end
        end

        function DropdownFunctions:SetHidden(State, Reason)
            if Reason then
                self:SetToolTip(Reason)
            end

            IsHidden = State

            if State then

                if not Settings.PremiumFeature then
                    PreviousTransparency = DropdownName.TextTransparency
                end

                Interact.AutoButtonColor = false

                if Dropped then
                    ToggleDropdown()
                end

                Services.TweenService:Create(
                    DropdownName,
                    TweenInfo.new(0.2),
                    { TextTransparency = Settings.PremiumFeature and DropdownName.TextTransparency or 0.9 }
                ):Play()

                Services.TweenService:Create(
                    DropdownImage,
                    TweenInfo.new(0.2),
                    { ImageTransparency = 0.9 }
                ):Play()

                Services.TweenService:Create(
                    Dropdown,
                    TweenInfo.new(0.2),
                    { BackgroundTransparency = 0.99 }
                ):Play()

                Services.TweenService:Create(
                    Dropdown:FindFirstChild("DropdownUIStroke"),
                    TweenInfo.new(0.2),
                    { Transparency = 0.98 }
                ):Play()

                if SearchIcon then
                    Services.TweenService:Create(
                        SearchIcon,
                        TweenInfo.new(0.2),
                        { ImageTransparency = 0.9 }
                    ):Play()
                end

                if SearchBox then
                    Services.TweenService:Create(
                        SearchBox,
                        TweenInfo.new(0.2),
                        { TextTransparency = 0.9 }
                    ):Play()
                    SearchBox.TextEditable = false
                end

                for _, connection in pairs(TooltipConnections) do
                    if connection then
                        connection:Disconnect()
                    end
                end
                TooltipConnections = {}

            else

                Interact.AutoButtonColor = false

                local originalImageTransparency = (not Utility:IsPremiumHubUser() and Settings.PremiumFeature) and 0.9 or 0.5
                local originalSearchTransparency = (not Utility:IsPremiumHubUser() and Settings.PremiumFeature) and 0.6 or 0

                Services.TweenService:Create(
                    DropdownName,
                    TweenInfo.new(0.2),
                    { TextTransparency = Settings.PremiumFeature and DropdownName.TextTransparency or PreviousTransparency }
                ):Play()

                Services.TweenService:Create(
                    DropdownImage,
                    TweenInfo.new(0.2),
                    { ImageTransparency = originalImageTransparency }
                ):Play()

                Services.TweenService:Create(
                    Dropdown,
                    TweenInfo.new(0.2),
                    { BackgroundTransparency = 0.985 }
                ):Play()

                Services.TweenService:Create(
                    Dropdown:FindFirstChild("DropdownUIStroke"),
                    TweenInfo.new(0.2),
                    { Transparency = 0.95 }
                ):Play()

                if SearchIcon then
                    Services.TweenService:Create(
                        SearchIcon,
                        TweenInfo.new(0.2),
                        { ImageTransparency = originalSearchTransparency }
                    ):Play()
                end

                if SearchBox then
                    Services.TweenService:Create(
                        SearchBox,
                        TweenInfo.new(0.2),
                        { TextTransparency = 0 }
                    ):Play()
                    SearchBox.TextEditable = not (not Utility:IsPremiumHubUser() and Settings.PremiumFeature)
                end

                local existingTooltip = Dropdown:FindFirstChild("ToolTipFrame")
                if existingTooltip then
                    local tooltipText = existingTooltip:FindFirstChild("TooltipText")
                    if tooltipText and tooltipText.Text ~= "" then

                        self:SetToolTip(tooltipText.Text)
                    end
                end
            end
        end

        function DropdownFunctions:GetState()
            return not IsHidden
        end

        function DropdownFunctions:UpdateName(New)
            DropdownName.Text = New
        end

        function DropdownFunctions:SetVisibility(State)
            Dropdown.Visible = State
        end

        function DropdownFunctions:ToggleOption(DfOption, DfToggle)
            if IsHidden then return end

            local SelectedOptions = {}

            for CurrentOption, CurrentSelected in pairs(self:GetOptions()) do
                if CurrentSelected then
                    table.insert(SelectedOptions, CurrentOption)
                end
            end

            if table.find(SelectedOptions, DfOption) and not DfToggle then
                Toggle(DfOption, false)
                local index = table.find(SelectedOptions, DfOption)
                if index then
                    table.remove(SelectedOptions, index)
                end
            elseif not table.find(SelectedOptions, DfOption) and DfToggle then
                table.insert(SelectedOptions, DfOption)
                Toggle(DfOption, true)
            end

            if DropdownFunctions.Settings.Callback then
                if DropdownFunctions.Settings.Multi then
                    local Return = {}
                    for _, Opt in ipairs(SelectedOptions) do
                        Return[Opt] = true
                    end
                    DropdownFunctions.Settings.Callback(Return)
                else
                    DropdownFunctions.Settings.Callback(SelectedOptions[1] or nil)
                end
            end
        end

        function DropdownFunctions:UpdateSelection(NewSelection)
            if not NewSelection or IsHidden then return end

            for Option, _ in pairs(OptionObjs) do
                Toggle(Option, false)
            end

            local SelectedOptions = {}
            if type(NewSelection) == "string" then
                for Option, Data in pairs(OptionObjs) do
                    local IsSelected = Option == NewSelection
                    if IsSelected then
                        Toggle(Option, true)
                        table.insert(SelectedOptions, Option)
                    end
                end
            elseif type(NewSelection) == "table" then
                for Option, _ in pairs(OptionObjs) do
                    local IsSelected = table.find(NewSelection, Option) ~= nil
                    if IsSelected then
                        Toggle(Option, true)
                        table.insert(SelectedOptions, Option)
                    end
                end
            end

            if DropdownFunctions.Settings.Callback then
                if DropdownFunctions.Settings.Multi then
                    local Return = {}
                    for _, Opt in ipairs(SelectedOptions) do
                        Return[Opt] = true
                    end
                    DropdownFunctions.Settings.Callback(Return)
                else
                    DropdownFunctions.Settings.Callback(SelectedOptions[1] or nil)
                end
            end
        end

        function DropdownFunctions:RefreshPlayers()
            RefreshPlayers()
        end

        function DropdownFunctions:ReturnTab()
            return DropdownFunctions.Tab
        end

        function DropdownFunctions:ReturnClass()
            return DropdownFunctions.Class
        end

        function DropdownFunctions:GetOptions()
            local OptionsStatus = {}

            for Option, Data in pairs(OptionObjs) do
                local IsSelected = table.find(Selected, Option) and true or false
                OptionsStatus[Option] = IsSelected
            end

            return OptionsStatus
        end

        function DropdownFunctions:GetSelectedPlayers()
            if #Selected <= 0 then
                return {}
            end

            if #Selected > 1 then
                local SelectedPlayers = {}

                for _, PlayerName in ipairs(Selected) do
                    local Player = Services.Players:FindFirstChild(PlayerName)
                    if Player then
                        table.insert(SelectedPlayers, Player)
                    end
                end

                return SelectedPlayers
            else
                local Player = Services.Players:FindFirstChild(Selected[1])
                return Player and {Player} or {}
            end
        end

        function DropdownFunctions:Destroy()

            if PlayerConnections.PlayerAdded then
                PlayerConnections.PlayerAdded:Disconnect()
            end

            if PlayerConnections.PlayerRemoving then
                PlayerConnections.PlayerRemoving:Disconnect()
            end

            for _, connection in pairs(TooltipConnections) do
                if connection then
                    connection:Disconnect()
                end
            end

            if Dropdown then
                Dropdown:Destroy()
            end

            for _, OptionData in pairs(OptionObjs) do
                if OptionData.Button then
                    OptionData.Button:Destroy()
                end
            end

            OptionObjs = {}

            if Flag and WaveLibrary.Options[Flag] then
                WaveLibrary.Options[Flag] = nil
            end
        end

        if DropdownFunctions.Settings.Hidden then
            if typeof(DropdownFunctions.Settings.Hidden) == "table" then
                DropdownFunctions:SetHidden(DropdownFunctions.Settings.Hidden[1], DropdownFunctions.Settings.Hidden[2])
            else
                DropdownFunctions:SetHidden(DropdownFunctions.Settings.Hidden)
            end
        end

        if Flag then
            WaveLibrary.Options[Flag] = DropdownFunctions
        end

        return DropdownFunctions
    end
end
end

R["Wave/UserInterface/Components/ProgressBar.lua"] = function(...)
return function(Requirements)
    local Section = Requirements.Section
    local WindowFunctions = Requirements.WindowFunctions
    local WaveLibraryUI = Requirements.WaveLibraryUI
    local WaveLibrary = Requirements.WaveLibrary
    local SectionFunctions = Requirements.SectionFunctions
    local BaseUIScale = Requirements.BaseUIScale

    function SectionFunctions:ProgressBar(Settings, Flag)
        local ProgressBarFunctions = {
            Settings = Settings,
            IgnoreConfig = false,
            Class = "ProgressBar",
            CurrentValue = Settings.Default or Settings.Minimum or 0,
            IsHidden = false,
            Maid = {},
            Elements = {}
        }

        if not Flag or Flag == "WriteHere" or Flag == "AutoWriteFlag" then
            Flag = string.gsub(Settings.Name, " ", "_")
        end

        local TWEEN_INFO = TweenInfo.new(0.3, Enum.EasingStyle.Sine)
        local TRANSPARENCY = {
            Default = 0.5,
            Hidden = 0.9
        }

        local function CreateElements()
            local Elements = {}

            Elements.ProgressBar = Instance.new("Frame")
            Elements.ProgressBar.Name = "ProgressBar"
            Elements.ProgressBar.AutomaticSize = Enum.AutomaticSize.Y
            Elements.ProgressBar.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
            Elements.ProgressBar.BackgroundTransparency = 1
            Elements.ProgressBar.BorderSizePixel = 0
            Elements.ProgressBar.Size = UDim2.new(1, 0, 0, 48)
            Elements.ProgressBar.Parent = Section

            Elements.ProgressBarName = Instance.new("TextLabel")
            Elements.ProgressBarName.Name = "ProgressBarName"
            Elements.ProgressBarName.FontFace = Font.new(Assets.InterFont)
            Elements.ProgressBarName.Text = Settings.Name
            Elements.ProgressBarName.RichText = true
            Elements.ProgressBarName.TextColor3 = WindowFunctions:GetCurrentThemeAttribute("TextPrimary")
            Elements.ProgressBarName.TextSize = 13
            Elements.ProgressBarName.TextTransparency = 0.5
            Elements.ProgressBarName.TextTruncate = Enum.TextTruncate.AtEnd
            Elements.ProgressBarName.TextXAlignment = Enum.TextXAlignment.Left
            Elements.ProgressBarName.TextYAlignment = Enum.TextYAlignment.Top
            Elements.ProgressBarName.AnchorPoint = Vector2.new(0, 0)
            Elements.ProgressBarName.AutomaticSize = Enum.AutomaticSize.XY
            Elements.ProgressBarName.BackgroundTransparency = 1
            Elements.ProgressBarName.Position = UDim2.fromScale(0, 0)
            Elements.ProgressBarName.Parent = Elements.ProgressBar

            if Settings.PremiumFeature then
                Elements.ProgressBarName.TextTransparency = 0
                local PremiumGradient = Instance.new("UIGradient")
                PremiumGradient.Color = WindowFunctions:GetCurrentThemeAttribute("PremiumGradientColor") or ColorSequence.new({
                    ColorSequenceKeypoint.new(0, Color3.fromRGB(0, 106, 255)),
                    ColorSequenceKeypoint.new(0.2, Color3.fromRGB(163, 201, 255)),
                    ColorSequenceKeypoint.new(0.4, Color3.fromRGB(255, 255, 255)),
                    ColorSequenceKeypoint.new(1, Color3.fromRGB(163, 201, 255))
                })
                PremiumGradient.Parent = Elements.ProgressBarName
            end

            Elements.ProgressValue = Instance.new("TextLabel")
            Elements.ProgressValue.Name = "ProgressValue"
            Elements.ProgressValue.FontFace = Font.new(Assets.InterFont)
            Elements.ProgressValue.TextColor3 = Color3.fromRGB(255, 255, 255)
            Elements.ProgressValue.TextSize = 12
            Elements.ProgressValue.TextTransparency = 0.3
            Elements.ProgressValue.TextXAlignment = Enum.TextXAlignment.Right
            Elements.ProgressValue.TextYAlignment = Enum.TextYAlignment.Top
            Elements.ProgressValue.AnchorPoint = Vector2.new(1, 0)
            Elements.ProgressValue.AutomaticSize = Enum.AutomaticSize.XY
            Elements.ProgressValue.BackgroundTransparency = 1
            Elements.ProgressValue.Position = UDim2.fromScale(1, 0)
            Elements.ProgressValue.Parent = Elements.ProgressBar

            Elements.ProgressContainer = Instance.new("Frame")
            Elements.ProgressContainer.Name = "ProgressContainer"
            Elements.ProgressContainer.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
            Elements.ProgressContainer.BackgroundTransparency = 0.92
            Elements.ProgressContainer.BorderSizePixel = 0
            Elements.ProgressContainer.Position = UDim2.new(0, 0, 0, 20)
            Elements.ProgressContainer.Size = UDim2.new(1, 0, 0, 6)
            Elements.ProgressContainer.Parent = Elements.ProgressBar

            local ProgressContainerUICorner = Instance.new("UICorner")
            ProgressContainerUICorner.CornerRadius = UDim.new(1, 0)
            ProgressContainerUICorner.Parent = Elements.ProgressContainer

            local ProgressContainerUIStroke = Instance.new("UIStroke")
            ProgressContainerUIStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            ProgressContainerUIStroke.Color = Color3.fromRGB(255, 255, 255)
            ProgressContainerUIStroke.Thickness = 0.5
            ProgressContainerUIStroke.Transparency = 0.85
            ProgressContainerUIStroke.Parent = Elements.ProgressContainer

            Elements.ProgressFill = Instance.new("Frame")
            Elements.ProgressFill.Name = "ProgressFill"
            Elements.ProgressFill.BackgroundColor3 = WindowFunctions:GetCurrentThemeAttribute("AccentPrimary") or Color3.fromRGB(0, 162, 255)
            Elements.ProgressFill.BackgroundTransparency = 0.2
            Elements.ProgressFill.BorderSizePixel = 0
            Elements.ProgressFill.Size = UDim2.fromScale(0, 1)
            Elements.ProgressFill.Parent = Elements.ProgressContainer

            local ProgressFillUICorner = Instance.new("UICorner")
            ProgressFillUICorner.CornerRadius = UDim.new(1, 0)
            ProgressFillUICorner.Parent = Elements.ProgressFill

            if Settings.ShowIndicator ~= false then
                Elements.ProgressIndicator = Instance.new("Frame")
                Elements.ProgressIndicator.Name = "ProgressIndicator"
                Elements.ProgressIndicator.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
                Elements.ProgressIndicator.BackgroundTransparency = 0.1
                Elements.ProgressIndicator.BorderSizePixel = 0
                Elements.ProgressIndicator.AnchorPoint = Vector2.new(0.5, 0.5)
                Elements.ProgressIndicator.Position = UDim2.fromScale(0, 0.5)
                Elements.ProgressIndicator.Size = UDim2.fromOffset(10, 10)
                Elements.ProgressIndicator.Parent = Elements.ProgressContainer

                local ProgressIndicatorUICorner = Instance.new("UICorner")
                ProgressIndicatorUICorner.CornerRadius = UDim.new(1, 0)
                ProgressIndicatorUICorner.Parent = Elements.ProgressIndicator

                local ProgressIndicatorUIStroke = Instance.new("UIStroke")
                ProgressIndicatorUIStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
                ProgressIndicatorUIStroke.Color = WindowFunctions:GetCurrentThemeAttribute("AccentPrimary") or Color3.fromRGB(0, 162, 255)
                ProgressIndicatorUIStroke.Thickness = 1.5
                ProgressIndicatorUIStroke.Transparency = 0.3
                ProgressIndicatorUIStroke.Parent = Elements.ProgressIndicator
            end

            if Settings.AnimatedFill then
                local PulseGradient = Instance.new("UIGradient")
                PulseGradient.Color = ColorSequence.new({
                    ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),
                    ColorSequenceKeypoint.new(0.5, WindowFunctions:GetCurrentThemeAttribute("AccentPrimary") or Color3.fromRGB(0, 162, 255)),
                    ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 255, 255))
                })
                PulseGradient.Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 0.8),
                    NumberSequenceKeypoint.new(0.5, 0.2),
                    NumberSequenceKeypoint.new(1, 0.8)
                })
                PulseGradient.Parent = Elements.ProgressFill

                task.spawn(function()
                    while Elements.ProgressFill and Elements.ProgressFill.Parent do
                        Services.TweenService:Create(PulseGradient,
                            TweenInfo.new(1.5, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true),
                            {Offset = Vector2.new(1, 0)}
                        ):Play()
                        task.wait(1.5)
                    end
                end)
            end

            return Elements
        end

        local DisplayMethods = {
            Thousandths = function(Value)
                return string.format("%.3f", Value)
            end,

            Hundredths = function(Value)
                return string.format("%.2f", Value)
            end,

            Tenths = function(Value)
                return string.format("%.1f", Value)
            end,

            Round = function(Value, Precision)
                if Precision then
                    return string.format("%." .. Precision .. "f", Value)
                else
                    return tostring(math.round(Value))
                end
            end,

            Percent = function(Value, Min, Max, Precision)
                local Percentage = ((Value - Min) / (Max - Min)) * 100
                return Precision and string.format("%." .. Precision .. "f", Percentage) .. "%" or tostring(math.round(Percentage)) .. "%"
            end,

            Ratio = function(Value, Min, Max, Precision)
                local Ratio = (Value - Min) / (Max - Min)
                return Precision and string.format("%." .. Precision .. "f", Ratio) or string.format("%.2f", Ratio)
            end,

            Value = function(Value, Precision)
                return Precision and string.format("%." .. Precision .. "f", Value) or tostring(Value)
            end,

            Fraction = function(Value, Min, Max)
                return tostring(math.round(Value)) .. "/" .. tostring(Max - Min)
            end
        }

        local ValueDisplayMethod = DisplayMethods[Settings.DisplayMethod] or DisplayMethods.Value

        local function UpdateProgress(NewValue, IgnoreCallback)
            local MinValue = Settings.Minimum or 0
            local MaxValue = Settings.Maximum or 100

            NewValue = math.clamp(NewValue, MinValue, MaxValue)
            ProgressBarFunctions.CurrentValue = NewValue

            local ProgressPercent = (NewValue - MinValue) / (MaxValue - MinValue)

            Utility:PropertyTween(ProgressBarFunctions.Elements.ProgressFill, TWEEN_INFO, {
                Size = UDim2.fromScale(ProgressPercent, 1)
            }):Play()

            if ProgressBarFunctions.Elements.ProgressIndicator then
                Utility:PropertyTween(ProgressBarFunctions.Elements.ProgressIndicator, TWEEN_INFO, {
                    Position = UDim2.fromScale(ProgressPercent, 0.5)
                }):Play()
            end

            local DisplayText
            if Settings.DisplayMethod == "Percent" then
                DisplayText = ValueDisplayMethod(NewValue, MinValue, MaxValue, Settings.Precision)
            else
                DisplayText = ValueDisplayMethod(NewValue, Settings.Precision)
            end

            ProgressBarFunctions.Elements.ProgressValue.Text = (Settings.Prefix or "") .. DisplayText .. (Settings.Suffix or "")

            if not IgnoreCallback and Settings.Callback then
                task.spawn(function()
                    Settings.Callback(NewValue, ProgressPercent)
                end)
            end
        end

        local function IsPlaceIdAllowed(PlaceIdSetting)
            if not PlaceIdSetting then return true end
            local CurrentPlaceId = game.PlaceId

            if type(PlaceIdSetting) == "table" then
                for _, PlaceId in pairs(PlaceIdSetting) do
                    if CurrentPlaceId == PlaceId then return true end
                end
                return false
            else
                return CurrentPlaceId == PlaceIdSetting
            end
        end

        local function IsPlaceIdForbidden(PlaceIdSetting)
            if not PlaceIdSetting then return false end
            local CurrentPlaceId = game.PlaceId

            if type(PlaceIdSetting) == "table" then
                for _, PlaceId in pairs(PlaceIdSetting) do
                    if CurrentPlaceId == PlaceId then return true end
                end
                return false
            else
                return CurrentPlaceId == PlaceIdSetting
            end
        end

        function ProgressBarFunctions:UpdateProgress(Value)
            UpdateProgress(Value)
        end

        function ProgressBarFunctions:SetProgress(Value)
            UpdateProgress(Value, true)
        end

        function ProgressBarFunctions:GetProgress()
            return ProgressBarFunctions.CurrentValue
        end

        function ProgressBarFunctions:GetProgressPercent()
            local MinValue = Settings.Minimum or 0
            local MaxValue = Settings.Maximum or 100
            return (ProgressBarFunctions.CurrentValue - MinValue) / (MaxValue - MinValue)
        end

        function ProgressBarFunctions:UpdateName(Name)
            ProgressBarFunctions.Elements.ProgressBarName.Text = Name
        end

        function ProgressBarFunctions:SetVisibility(State)
            ProgressBarFunctions.Elements.ProgressBar.Visible = State
        end

        function ProgressBarFunctions:GetState()
            return not ProgressBarFunctions.IsHidden
        end

        function ProgressBarFunctions:ReturnSettings()
            return Settings
        end

        function ProgressBarFunctions:SetToolTip(Tip)
            if ProgressBarFunctions.Elements.ProgressBar:FindFirstChild("ToolTipFrame") then
                ProgressBarFunctions.Elements.ProgressBar:FindFirstChild("ToolTipFrame"):Destroy()
            end

            if not Tip or Tip == "" then return end

            local ToolTipFrame = Instance.new("Frame")
            ToolTipFrame.Name = "ToolTipFrame"
            ToolTipFrame.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
            ToolTipFrame.BackgroundTransparency = 1
            ToolTipFrame.BorderSizePixel = 0
            ToolTipFrame.AnchorPoint = Vector2.new(0.5, 1)
            ToolTipFrame.Position = UDim2.new(0.5, 0, 0, -5)
            ToolTipFrame.Visible = false
            ToolTipFrame.ZIndex = 200
            ToolTipFrame.Parent = ProgressBarFunctions.Elements.ProgressBar

            local TooltipCorner = Instance.new("UICorner")
            TooltipCorner.CornerRadius = UDim.new(0, 6)
            TooltipCorner.Parent = ToolTipFrame

            local TooltipStroke = Instance.new("UIStroke")
            TooltipStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            TooltipStroke.LineJoinMode = Enum.LineJoinMode.Round
            TooltipStroke.Color = Color3.fromRGB(255, 255, 255)
            TooltipStroke.Thickness = 0.1
            TooltipStroke.Transparency = 0.2
            TooltipStroke.Parent = ToolTipFrame

            local TooltipText = Instance.new("TextLabel")
            TooltipText.Text = Tip
            TooltipText.FontFace = Font.new(Assets.InterFont)
            TooltipText.TextColor3 = Color3.fromRGB(200, 220, 200)
            TooltipText.TextSize = 12
            TooltipText.TextTransparency = 1
            TooltipText.BackgroundTransparency = 1
            TooltipText.TextXAlignment = Enum.TextXAlignment.Center
            TooltipText.TextYAlignment = Enum.TextYAlignment.Center
            TooltipText.Size = UDim2.new(1, -12, 1, 0)
            TooltipText.Position = UDim2.new(0, 6, 0, 0)
            TooltipText.Parent = ToolTipFrame

            local TextBounds = Services.TextService:GetTextSize(Tip, TooltipText.TextSize, Enum.Font.SourceSansBold, Vector2.new(math.huge, math.huge))
            local TooltipWidth = math.max(80, TextBounds.X + 50)
            local TooltipHeight = math.max(28, TextBounds.Y + 12)
            ToolTipFrame.Size = UDim2.new(0, TooltipWidth, 0, TooltipHeight)

            local function ShowTooltip()
                ToolTipFrame.Visible = true
                Services.TweenService:Create(ToolTipFrame, TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {BackgroundTransparency = 0.1}):Play()
                Services.TweenService:Create(TooltipText, TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {TextTransparency = 0}):Play()
                Services.TweenService:Create(TooltipStroke, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Transparency = 0.8}):Play()
            end

            local function HideTooltip()
                Services.TweenService:Create(ToolTipFrame, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {BackgroundTransparency = 1}):Play()
                Services.TweenService:Create(TooltipText, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {TextTransparency = 1}):Play()
                Services.TweenService:Create(TooltipStroke, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Transparency = 1}):Play()
                task.spawn(function()
                    task.wait(0.2)
                    if ToolTipFrame and ToolTipFrame.Parent then
                        ToolTipFrame.Visible = false
                    end
                end)
            end

            ProgressBarFunctions.Maid.TooltipShow = ProgressBarFunctions.Elements.ProgressContainer.MouseEnter:Connect(ShowTooltip)
            ProgressBarFunctions.Maid.TooltipHide = ProgressBarFunctions.Elements.ProgressContainer.MouseLeave:Connect(HideTooltip)
        end

        function ProgressBarFunctions:SetHidden(State, Reason)
            if Reason then
                self:SetToolTip(Reason)
            end

            ProgressBarFunctions.IsHidden = State

            if State then
                Services.TweenService:Create(ProgressBarFunctions.Elements.ProgressContainer, TWEEN_INFO, {BackgroundTransparency = 0.98}):Play()
                Services.TweenService:Create(ProgressBarFunctions.Elements.ProgressFill, TWEEN_INFO, {BackgroundTransparency = 0.9}):Play()
                Services.TweenService:Create(ProgressBarFunctions.Elements.ProgressValue, TWEEN_INFO, {TextTransparency = 0.9}):Play()

                if ProgressBarFunctions.Elements.ProgressIndicator then
                    Services.TweenService:Create(ProgressBarFunctions.Elements.ProgressIndicator, TWEEN_INFO, {BackgroundTransparency = 0.9}):Play()
                end

                local ContainerStroke = ProgressBarFunctions.Elements.ProgressContainer:FindFirstChild("UIStroke")
                if ContainerStroke then
                    Services.TweenService:Create(ContainerStroke, TWEEN_INFO, {Transparency = 0.95}):Play()
                end

                if not Settings.PremiumFeature then
                    Services.TweenService:Create(ProgressBarFunctions.Elements.ProgressBarName, TWEEN_INFO, {TextTransparency = 0.9}):Play()
                end
            else
                Services.TweenService:Create(ProgressBarFunctions.Elements.ProgressContainer, TWEEN_INFO, {BackgroundTransparency = 0.92}):Play()
                Services.TweenService:Create(ProgressBarFunctions.Elements.ProgressFill, TWEEN_INFO, {BackgroundTransparency = 0.2}):Play()
                Services.TweenService:Create(ProgressBarFunctions.Elements.ProgressValue, TWEEN_INFO, {TextTransparency = 0.3}):Play()

                if ProgressBarFunctions.Elements.ProgressIndicator then
                    Services.TweenService:Create(ProgressBarFunctions.Elements.ProgressIndicator, TWEEN_INFO, {BackgroundTransparency = 0.1}):Play()
                end

                local ContainerStroke = ProgressBarFunctions.Elements.ProgressContainer:FindFirstChild("UIStroke")
                if ContainerStroke then
                    Services.TweenService:Create(ContainerStroke, TWEEN_INFO, {Transparency = 0.85}):Play()
                end

                if not Settings.PremiumFeature then
                    Services.TweenService:Create(ProgressBarFunctions.Elements.ProgressBarName, TWEEN_INFO, {TextTransparency = 0.5}):Play()
                end
            end
        end

        function ProgressBarFunctions:Destroy()
            for ConnectionName, Connection in pairs(ProgressBarFunctions.Maid) do
                if type(Connection) == "userdata" and Connection.Disconnect then
                    Connection:Disconnect()
                end
            end
            table.clear(ProgressBarFunctions.Maid)

            if ProgressBarFunctions.Elements.ProgressBar then
                ProgressBarFunctions.Elements.ProgressBar:Destroy()
            end

            if Flag and WaveLibrary.Options[Flag] then
                WaveLibrary.Options[Flag] = nil
            end
        end

        ProgressBarFunctions.Elements = CreateElements()
        UpdateProgress(ProgressBarFunctions.CurrentValue, true)

        if Settings.Hidden then
            if typeof(Settings.Hidden) == "table" then
                ProgressBarFunctions:SetHidden(Settings.Hidden[1], Settings.Hidden[2])
            else
                ProgressBarFunctions:SetHidden(Settings.Hidden)
            end
        end

        if Settings.ToolTip then
            ProgressBarFunctions:SetToolTip(Settings.ToolTip)
        end

        if Settings.PremiumFeature and not Utility:IsPremiumHubUser() then
            ProgressBarFunctions:SetHidden(true, "Premium Feature")
        end

        if not IsPlaceIdAllowed(Settings.AllowedPlaceId) then
            ProgressBarFunctions:SetHidden(true, "Not in the right PlaceId to use this feature.")
        end

        if IsPlaceIdForbidden(Settings.ForbiddenPlaceId) then
            ProgressBarFunctions:SetHidden(true, "Not in the right PlaceId to use this feature.")
        end

        if Flag then
            WaveLibrary.Options[Flag] = ProgressBarFunctions
        end

        return ProgressBarFunctions
    end
end
end

R["Wave/UserInterface/Components/RangeSlider.lua"] = function(...)
return function(Requirements)
    local Section = Requirements.Section
    local WindowFunctions = Requirements.WindowFunctions
    local WaveLibraryUI = Requirements.WaveLibraryUI
    local WaveLibrary = Requirements.WaveLibrary
    local SectionFunctions = Requirements.SectionFunctions
    local BaseUIScale = Requirements.BaseUIScale

    function SectionFunctions:RangeSlider(Settings, Flag)
        local RangeSliderFunctions = {
            Settings = Settings,
            IgnoreConfig = Settings.IgnoreConfig,
            Tab = Requirements.TabName,
            Class = "RangeSlider",
            MinValue = Settings.DefaultMin or Settings.Minimum,
            MaxValue = Settings.DefaultMax or Settings.Maximum
        }

        if not Flag then
            Flag = "WriteHere"
        end

        if Flag == "WriteHere" or Flag == "AutoWriteFlag" then
            Flag = string.gsub(RangeSliderFunctions.Settings.Name, " ", "_")
        end

        local RangeSlider = Instance.new("Frame")
        RangeSlider.Name = "RangeSlider"
        RangeSlider.AutomaticSize = Enum.AutomaticSize.Y
        RangeSlider.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
        RangeSlider.BackgroundTransparency = 1
        RangeSlider.BorderSizePixel = 0
        RangeSlider.Size = UDim2.new(1, 0, 0, 38)
        RangeSlider.Parent = Section

        local RangeSliderName = Instance.new("TextLabel")
        RangeSliderName.Name = "RangeSliderName"
        RangeSliderName.FontFace = Font.new(Assets.InterFont)
        RangeSliderName.Text = RangeSliderFunctions.Settings.Name
        RangeSliderName.RichText = true
        RangeSliderName.TextColor3 = WindowFunctions:GetCurrentThemeAttribute("TextPrimary")
        RangeSliderName.TextSize = 13
        RangeSliderName.TextTransparency = 0.5
        RangeSliderName.TextTruncate = Enum.TextTruncate.AtEnd
        RangeSliderName.TextXAlignment = Enum.TextXAlignment.Left
        RangeSliderName.TextYAlignment = Enum.TextYAlignment.Top
        RangeSliderName.AnchorPoint = Vector2.new(0, 0.5)
        RangeSliderName.AutomaticSize = Enum.AutomaticSize.XY
        RangeSliderName.BackgroundTransparency = 1
        RangeSliderName.Position = UDim2.fromScale(0, 0.5)
        RangeSliderName.Parent = RangeSlider

        if Settings.PremiumFeature then
            RangeSliderName.TextTransparency = 0
            local PremiumGradient = Instance.new("UIGradient")
            PremiumGradient.Color = WindowFunctions:GetCurrentThemeAttribute("PremiumGradientColor") or ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.fromRGB(0, 106, 255)),
                ColorSequenceKeypoint.new(0.5, Color3.fromRGB(163, 201, 255)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 255, 255))
            })
            PremiumGradient.Rotation = 0
            PremiumGradient.Parent = RangeSliderName
        end

        local RangeSliderElements = Instance.new("Frame")
        RangeSliderElements.Name = "RangeSliderElements"
        RangeSliderElements.AnchorPoint = Vector2.new(1, 0)
        RangeSliderElements.BackgroundTransparency = 1
        RangeSliderElements.Position = UDim2.fromScale(1, 0)
        RangeSliderElements.Size = UDim2.fromScale(1, 1)
        RangeSliderElements.Parent = RangeSlider

        local MinValueInput = Instance.new("TextBox")
        MinValueInput.Name = "MinValueInput"
        MinValueInput.FontFace = Font.new(Assets.InterFont)
        MinValueInput.TextColor3 = Color3.fromRGB(255, 255, 255)
        MinValueInput.TextSize = 12
        MinValueInput.TextTransparency = 0.1
        MinValueInput.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        MinValueInput.BackgroundTransparency = 0.95
        MinValueInput.BorderSizePixel = 0
        MinValueInput.LayoutOrder = 1
        MinValueInput.Size = UDim2.fromOffset(41, 21)
        MinValueInput.ClipsDescendants = true

        local MinValueUICorner = Instance.new("UICorner")
        MinValueUICorner.CornerRadius = UDim.new(0, 4)
        MinValueUICorner.Parent = MinValueInput

        local MinValueUIStroke = Instance.new("UIStroke")
        MinValueUIStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        MinValueUIStroke.Color = Color3.fromRGB(255, 255, 255)
        MinValueUIStroke.Transparency = 0.9
        MinValueUIStroke.Parent = MinValueInput

        local MinValueUIPadding = Instance.new("UIPadding")
        MinValueUIPadding.PaddingLeft = UDim.new(0, 2)
        MinValueUIPadding.PaddingRight = UDim.new(0, 2)
        MinValueUIPadding.Parent = MinValueInput

        MinValueInput.Parent = RangeSliderElements

        local MaxValueInput = Instance.new("TextBox")
        MaxValueInput.Name = "MaxValueInput"
        MaxValueInput.FontFace = Font.new(Assets.InterFont)
        MaxValueInput.TextColor3 = Color3.fromRGB(255, 255, 255)
        MaxValueInput.TextSize = 12
        MaxValueInput.TextTransparency = 0.1
        MaxValueInput.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        MaxValueInput.BackgroundTransparency = 0.95
        MaxValueInput.BorderSizePixel = 0
        MaxValueInput.LayoutOrder = 3
        MaxValueInput.Size = UDim2.fromOffset(41, 21)
        MaxValueInput.ClipsDescendants = true

        local MaxValueUICorner = Instance.new("UICorner")
        MaxValueUICorner.CornerRadius = UDim.new(0, 4)
        MaxValueUICorner.Parent = MaxValueInput

        local MaxValueUIStroke = Instance.new("UIStroke")
        MaxValueUIStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        MaxValueUIStroke.Color = Color3.fromRGB(255, 255, 255)
        MaxValueUIStroke.Transparency = 0.9
        MaxValueUIStroke.Parent = MaxValueInput

        local MaxValueUIPadding = Instance.new("UIPadding")
        MaxValueUIPadding.PaddingLeft = UDim.new(0, 2)
        MaxValueUIPadding.PaddingRight = UDim.new(0, 2)
        MaxValueUIPadding.Parent = MaxValueInput

        MaxValueInput.Parent = RangeSliderElements

        if not Utility:IsPremiumHubUser() and Settings.PremiumFeature then
            MinValueInput.TextEditable = false
            MinValueInput.ClearTextOnFocus = false
            MinValueInput.TextTransparency = 0.8
            MaxValueInput.TextEditable = false
            MaxValueInput.ClearTextOnFocus = false
            MaxValueInput.TextTransparency = 0.8
        end

        local RangeSliderElementsUIListLayout = Instance.new("UIListLayout")
        RangeSliderElementsUIListLayout.Padding = UDim.new(0, 5)
        RangeSliderElementsUIListLayout.FillDirection = Enum.FillDirection.Horizontal
        RangeSliderElementsUIListLayout.HorizontalAlignment = Enum.HorizontalAlignment.Right
        RangeSliderElementsUIListLayout.SortOrder = Enum.SortOrder.LayoutOrder
        RangeSliderElementsUIListLayout.VerticalAlignment = Enum.VerticalAlignment.Center
        RangeSliderElementsUIListLayout.Parent = RangeSliderElements

        local SliderBarContainer = Instance.new("Frame")
        SliderBarContainer.Name = "SliderBarContainer"
        SliderBarContainer.BackgroundTransparency = 1
        SliderBarContainer.LayoutOrder = 2
        SliderBarContainer.Size = UDim2.fromOffset(123, 21)
        SliderBarContainer.Parent = RangeSliderElements

        local SliderBar = Instance.new("ImageLabel")
        SliderBar.Name = "SliderBar"
        SliderBar.Image = Assets.SliderBar
        SliderBar.ImageColor3 = Color3.fromRGB(87, 86, 86)
        SliderBar.BackgroundTransparency = 1
        SliderBar.AnchorPoint = Vector2.new(0, 0.5)
        SliderBar.Position = UDim2.fromScale(0, 0.5)
        SliderBar.Size = UDim2.fromOffset(123, 3)
        SliderBar.Parent = SliderBarContainer

        local RangeBar = Instance.new("Frame")
        RangeBar.Name = "RangeBar"
        RangeBar.BackgroundColor3 = WindowFunctions:GetCurrentThemeAttribute("AccentPrimary") or Color3.fromRGB(0, 162, 255)
        RangeBar.BackgroundTransparency = 0.3
        RangeBar.BorderSizePixel = 0
        RangeBar.AnchorPoint = Vector2.new(0, 0.5)
        RangeBar.Position = UDim2.fromScale(0, 0.5)
        RangeBar.Size = UDim2.fromOffset(0, 3)
        RangeBar.Parent = SliderBarContainer

        local RangeBarUICorner = Instance.new("UICorner")
        RangeBarUICorner.CornerRadius = UDim.new(1, 0)
        RangeBarUICorner.Parent = RangeBar

        local MinSliderHead = Instance.new("ImageButton")
        MinSliderHead.Name = "MinSliderHead"
        MinSliderHead.Image = Assets.SliderHead
        MinSliderHead.AnchorPoint = Vector2.new(0.5, 0.5)
        MinSliderHead.BackgroundTransparency = 1
        MinSliderHead.Position = UDim2.fromScale(0, 0.5)
        MinSliderHead.Size = UDim2.fromOffset(12, 12)
        MinSliderHead.Parent = SliderBarContainer

        local MaxSliderHead = Instance.new("ImageButton")
        MaxSliderHead.Name = "MaxSliderHead"
        MaxSliderHead.Image = Assets.SliderHead
        MaxSliderHead.AnchorPoint = Vector2.new(0.5, 0.5)
        MaxSliderHead.BackgroundTransparency = 1
        MaxSliderHead.Position = UDim2.fromScale(1, 0.5)
        MaxSliderHead.Size = UDim2.fromOffset(12, 12)
        MaxSliderHead.Parent = SliderBarContainer

        local RangeSliderElementsUIPadding = Instance.new("UIPadding")
        RangeSliderElementsUIPadding.PaddingTop = UDim.new(0, 3)
        RangeSliderElementsUIPadding.Parent = RangeSliderElements

        local IsHidden = false
        local DraggingMin = false
        local DraggingMax = false
        local SliderConnection = nil
        local PreviousNameTransparency = 0.5

        local DisplayMethods = {
            Thousandths = function(SliderValue)
                return string.format("%.3f", SliderValue)
            end,

            Hundredths = function(SliderValue)
                return string.format("%.2f", SliderValue)
            end,

            Tenths = function(SliderValue)
                return string.format("%.1f", SliderValue)
            end,

            Round = function(SliderValue, Precision)
                if Precision then
                    return string.format("%." .. Precision .. "f", SliderValue)
                else
                    return tostring(math.round(SliderValue))
                end
            end,

            Degrees = function(SliderValue, Precision)
                local FormattedValue = Precision and string.format("%." .. Precision .. "f", SliderValue) or tostring(SliderValue)
                return FormattedValue .. "°"
            end,

            Percent = function(SliderValue, Precision)
                local Percentage = (SliderValue - RangeSliderFunctions.Settings.Minimum) / (RangeSliderFunctions.Settings.Maximum - RangeSliderFunctions.Settings.Minimum) * 100
                return Precision and string.format("%." .. Precision .. "f", Percentage) .. "%" or tostring(math.round(Percentage)) .. "%"
            end,

            Value = function(SliderValue, Precision)
                return Precision and string.format("%." .. Precision .. "f", SliderValue) or tostring(SliderValue)
            end,

            Time24Hour = function(SliderValue)
                local TotalSeconds = math.floor(SliderValue)
                local Hours = math.floor(TotalSeconds / 3600) % 24
                local Minutes = math.floor((TotalSeconds % 3600) / 60)
                local Seconds = TotalSeconds % 60
                return string.format("%02d:%02d", Hours, Minutes)
            end,

            Time12Hour = function(SliderValue)
                local TotalSeconds = math.floor(SliderValue)
                local Hours24 = math.floor(TotalSeconds / 3600) % 24
                local Minutes = math.floor((TotalSeconds % 3600) / 60)
                
                local Hours12 = Hours24 % 12
                if Hours12 == 0 then Hours12 = 12 end
                local Period = Hours24 >= 12 and "PM" or "AM"
                
                return string.format("%02d:%02d %s", Hours12, Minutes, Period)
            end
        }

        local ValueDisplayMethod = DisplayMethods[RangeSliderFunctions.Settings.DisplayMethod] or DisplayMethods.Value

        local function UpdateRange(IgnoreCallback)
            local MinPercent = (RangeSliderFunctions.MinValue - Settings.Minimum) / (Settings.Maximum - Settings.Minimum)
            local MaxPercent = (RangeSliderFunctions.MaxValue - Settings.Minimum) / (Settings.Maximum - Settings.Minimum)

            MinPercent = math.clamp(MinPercent, 0, 1)
            MaxPercent = math.clamp(MaxPercent, 0, 1)

            MinSliderHead.Position = UDim2.fromScale(MinPercent, 0.5)
            MaxSliderHead.Position = UDim2.fromScale(MaxPercent, 0.5)

            local RangeWidth = MaxPercent - MinPercent
            RangeBar.Position = UDim2.fromScale(MinPercent, 0.5)
            RangeBar.Size = UDim2.new(RangeWidth, 0, 0, 3)

            MinValueInput.Text = (Settings.Prefix or "") .. ValueDisplayMethod(RangeSliderFunctions.MinValue, Settings.Precision) .. (Settings.Suffix or "")
            MaxValueInput.Text = (Settings.Prefix or "") .. ValueDisplayMethod(RangeSliderFunctions.MaxValue, Settings.Precision) .. (Settings.Suffix or "")

            if not IgnoreCallback and Settings.Callback then
                task.spawn(function()
                    Settings.Callback(RangeSliderFunctions.MinValue, RangeSliderFunctions.MaxValue)
                end)
            end
        end

        local function SetMinValue(Val, IgnoreCallback)
            local PosXScale

            if typeof(Val) == "Instance" then
                local Input = Val
                PosXScale = math.clamp((Input.Position.X - SliderBar.AbsolutePosition.X) / SliderBar.AbsoluteSize.X, 0, 1)
            else
                local Value = Val
                PosXScale = (Value - Settings.Minimum) / (Settings.Maximum - Settings.Minimum)
            end

            local NewValue = PosXScale * (Settings.Maximum - Settings.Minimum) + Settings.Minimum
            NewValue = math.clamp(NewValue, Settings.Minimum, RangeSliderFunctions.MaxValue)

            RangeSliderFunctions.MinValue = NewValue
            UpdateRange(IgnoreCallback)
        end

        local function SetMaxValue(Val, IgnoreCallback)
            local PosXScale

            if typeof(Val) == "Instance" then
                local Input = Val
                PosXScale = math.clamp((Input.Position.X - SliderBar.AbsolutePosition.X) / SliderBar.AbsoluteSize.X, 0, 1)
            else
                local Value = Val
                PosXScale = (Value - Settings.Minimum) / (Settings.Maximum - Settings.Minimum)
            end

            local NewValue = PosXScale * (Settings.Maximum - Settings.Minimum) + Settings.Minimum
            NewValue = math.clamp(NewValue, RangeSliderFunctions.MinValue, Settings.Maximum)

            RangeSliderFunctions.MaxValue = NewValue
            UpdateRange(IgnoreCallback)
        end

        UpdateRange(true)

        if not Utility:IsPremiumHubUser() and Settings.PremiumFeature then
            SliderBar.ImageTransparency = 0.6
            MinSliderHead.ImageTransparency = 0.3
            MaxSliderHead.ImageTransparency = 0.3
            RangeBar.BackgroundTransparency = 0.7
        end

        if not Settings.PremiumFeature then
            local function AddHoverEffect(Element)
                Element.MouseEnter:Connect(function()
                    if IsHidden then return end
                    Utility:QuickTween(RangeSliderName, { TextTransparency = 0 })
                end)

                Element.MouseLeave:Connect(function()
                    if IsHidden then return end
                    Utility:QuickTween(RangeSliderName, { TextTransparency = PreviousNameTransparency })
                end)
            end

            AddHoverEffect(MinSliderHead)
            AddHoverEffect(MaxSliderHead)
            AddHoverEffect(MinValueInput)
            AddHoverEffect(MaxValueInput)
        end

        local function ConnectSliderEvents()
            MinSliderHead.InputBegan:Connect(function(Input)
                if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
                    if not Utility:IsPremiumHubUser() and Settings.PremiumFeature then return end
                    if IsHidden then return end
                    DraggingMin = true
                    SetMinValue(Input)
                end
            end)

            MinSliderHead.InputEnded:Connect(function(Input)
                if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
                    DraggingMin = false
                    if Settings.OnInputComplete then
                        Settings.OnInputComplete(RangeSliderFunctions.MinValue, RangeSliderFunctions.MaxValue)
                    end
                end
            end)

            MaxSliderHead.InputBegan:Connect(function(Input)
                if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
                    if not Utility:IsPremiumHubUser() and Settings.PremiumFeature then return end
                    if IsHidden then return end
                    DraggingMax = true
                    SetMaxValue(Input)
                end
            end)

            MaxSliderHead.InputEnded:Connect(function(Input)
                if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
                    DraggingMax = false
                    if Settings.OnInputComplete then
                        Settings.OnInputComplete(RangeSliderFunctions.MinValue, RangeSliderFunctions.MaxValue)
                    end
                end
            end)

            MinValueInput.FocusLost:Connect(function(EnterPressed)
                if IsHidden then return end

                local InputText = MinValueInput.Text
                local Value = tonumber(InputText:match("(%-?%d+%.?%d*)"))

                if Value then
                    local NewValue = math.clamp(Value, Settings.Minimum, RangeSliderFunctions.MaxValue)
                    RangeSliderFunctions.MinValue = NewValue
                    UpdateRange()
                else
                    MinValueInput.Text = ValueDisplayMethod(RangeSliderFunctions.MinValue, Settings.Precision)
                end

                if Settings.OnInputComplete then
                    Settings.OnInputComplete(RangeSliderFunctions.MinValue, RangeSliderFunctions.MaxValue)
                end
            end)

            MaxValueInput.FocusLost:Connect(function(EnterPressed)
                if IsHidden then return end

                local InputText = MaxValueInput.Text
                local Value = tonumber(InputText:match("(%-?%d+%.?%d*)"))

                if Value then
                    local NewValue = math.clamp(Value, RangeSliderFunctions.MinValue, Settings.Maximum)
                    RangeSliderFunctions.MaxValue = NewValue
                    UpdateRange()
                else
                    MaxValueInput.Text = ValueDisplayMethod(RangeSliderFunctions.MaxValue, Settings.Precision)
                end

                if Settings.OnInputComplete then
                    Settings.OnInputComplete(RangeSliderFunctions.MinValue, RangeSliderFunctions.MaxValue)
                end
            end)

            SliderConnection = Services.UserInputService.InputChanged:Connect(function(Input)
                if not IsHidden and (Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch) then
                    if DraggingMin then
                        SetMinValue(Input)
                    elseif DraggingMax then
                        SetMaxValue(Input)
                    end
                end
            end)
        end

        ConnectSliderEvents()

        local function UpdateSliderBarSize()
            local Padding = RangeSliderElementsUIListLayout.Padding.Offset
            local MinValueWidth = MinValueInput.AbsoluteSize.X
            local MaxValueWidth = MaxValueInput.AbsoluteSize.X
            local SliderNameWidth = RangeSliderName.AbsoluteSize.X
            local TotalWidth = RangeSliderElements.AbsoluteSize.X

            local NewBarWidth = (TotalWidth - (Padding + MinValueWidth + MaxValueWidth + SliderNameWidth + 15)) / BaseUIScale.Scale
            SliderBar.Size = UDim2.new(0, NewBarWidth, 0, 3)
            SliderBarContainer.Size = UDim2.new(0, NewBarWidth, 0, 20)
        end

        UpdateSliderBarSize()
        RangeSliderName:GetPropertyChangedSignal("AbsoluteSize"):Connect(UpdateSliderBarSize)
        Section:GetPropertyChangedSignal("AbsoluteSize"):Connect(UpdateSliderBarSize)

        function RangeSliderFunctions:SetToolTip(Tip)
            if RangeSlider:FindFirstChild("ToolTipFrame") then
                RangeSlider:FindFirstChild("ToolTipFrame"):Destroy()
            end

            if not Tip or Tip == "" then return end

            local ToolTipFrame = Instance.new("Frame")
            ToolTipFrame.Name = "ToolTipFrame"
            ToolTipFrame.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
            ToolTipFrame.BackgroundTransparency = 1
            ToolTipFrame.BorderSizePixel = 0
            ToolTipFrame.AnchorPoint = Vector2.new(0.5, 1)
            ToolTipFrame.Position = UDim2.new(0.5, 0, 0, -5)
            ToolTipFrame.Visible = false
            ToolTipFrame.ZIndex = 200
            ToolTipFrame.Parent = RangeSlider

            local TooltipCorner = Instance.new("UICorner")
            TooltipCorner.CornerRadius = UDim.new(0, 6)
            TooltipCorner.Parent = ToolTipFrame

            local TooltipStroke = Instance.new("UIStroke")
            TooltipStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            TooltipStroke.LineJoinMode = Enum.LineJoinMode.Round
            TooltipStroke.Color = Color3.fromRGB(255, 255, 255)
            TooltipStroke.Thickness = 0.1
            TooltipStroke.Transparency = 0.2
            TooltipStroke.Parent = ToolTipFrame

            local TooltipText = Instance.new("TextLabel")
            TooltipText.Name = "TooltipText"
            TooltipText.Text = Tip
            TooltipText.FontFace = Font.new(Assets.InterFont)
            TooltipText.TextColor3 = Color3.fromRGB(200, 220, 200)
            TooltipText.TextSize = 12
            TooltipText.TextTransparency = 1
            TooltipText.BackgroundTransparency = 1
            TooltipText.TextXAlignment = Enum.TextXAlignment.Center
            TooltipText.TextYAlignment = Enum.TextYAlignment.Center
            TooltipText.Size = UDim2.new(1, -12, 1, 0)
            TooltipText.Position = UDim2.new(0, 6, 0, 0)
            TooltipText.Parent = ToolTipFrame

            local TextBounds = Services.TextService:GetTextSize(Tip, TooltipText.TextSize, Enum.Font.SourceSansBold, Vector2.new(math.huge, math.huge))
            local TooltipWidth = math.max(80, TextBounds.X + 50)
            local TooltipHeight = math.max(28, TextBounds.Y + 12)
            ToolTipFrame.Size = UDim2.new(0, TooltipWidth, 0, TooltipHeight)

            local function ShowTooltip()
                ToolTipFrame.Visible = true
                Services.TweenService:Create(ToolTipFrame, TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {BackgroundTransparency = 0.1}):Play()
                Services.TweenService:Create(TooltipText, TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {TextTransparency = 0}):Play()
                Services.TweenService:Create(TooltipStroke, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Transparency = 0.8}):Play()
            end

            local function HideTooltip()
                Services.TweenService:Create(ToolTipFrame, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {BackgroundTransparency = 1}):Play()
                Services.TweenService:Create(TooltipText, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {TextTransparency = 1}):Play()
                Services.TweenService:Create(TooltipStroke, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Transparency = 1}):Play()
                task.spawn(function()
                    task.wait(0.2)
                    if ToolTipFrame and ToolTipFrame.Parent then
                        ToolTipFrame.Visible = false
                    end
                end)
            end

            MinSliderHead.MouseEnter:Connect(ShowTooltip)
            MinSliderHead.MouseLeave:Connect(HideTooltip)
            MaxSliderHead.MouseEnter:Connect(ShowTooltip)
            MaxSliderHead.MouseLeave:Connect(HideTooltip)
        end

        function RangeSliderFunctions:SetHidden(State, Reason)
            if Reason then
                self:SetToolTip(Reason)
            end

            IsHidden = State

            if State then

                Services.TweenService:Create(SliderBar, TweenInfo.new(0.2), {ImageTransparency = 0.9}):Play()
                Services.TweenService:Create(MinSliderHead, TweenInfo.new(0.2), {ImageTransparency = 0.9}):Play()
                Services.TweenService:Create(MaxSliderHead, TweenInfo.new(0.2), {ImageTransparency = 0.9}):Play()
                Services.TweenService:Create(RangeBar, TweenInfo.new(0.2), {BackgroundTransparency = 0.95}):Play()

                if not Settings.PremiumFeature then
                    Services.TweenService:Create(RangeSliderName, TweenInfo.new(0.2), {TextTransparency = 0.9}):Play()
                end

                Services.TweenService:Create(MinValueInput, TweenInfo.new(0.2), {TextTransparency = 0.9, BackgroundTransparency = 0.99}):Play()
                Services.TweenService:Create(MaxValueInput, TweenInfo.new(0.2), {TextTransparency = 0.9, BackgroundTransparency = 0.99}):Play()
                Services.TweenService:Create(MinValueUIStroke, TweenInfo.new(0.2), {Transparency = 0.95}):Play()
                Services.TweenService:Create(MaxValueUIStroke, TweenInfo.new(0.2), {Transparency = 0.95}):Play()

                MinValueInput.TextEditable = false
                MaxValueInput.TextEditable = false

                if SliderConnection then
                    SliderConnection:Disconnect()
                    SliderConnection = nil
                end
            else

                local originalBarTransparency = (not Utility:IsPremiumHubUser() and Settings.PremiumFeature) and 0.6 or 0
                local originalHeadTransparency = (not Utility:IsPremiumHubUser() and Settings.PremiumFeature) and 0.3 or 0

                Services.TweenService:Create(SliderBar, TweenInfo.new(0.2), {ImageTransparency = originalBarTransparency}):Play()
                Services.TweenService:Create(MinSliderHead, TweenInfo.new(0.2), {ImageTransparency = originalHeadTransparency}):Play()
                Services.TweenService:Create(MaxSliderHead, TweenInfo.new(0.2), {ImageTransparency = originalHeadTransparency}):Play()
                Services.TweenService:Create(RangeBar, TweenInfo.new(0.2), {BackgroundTransparency = Settings.PremiumFeature and not Utility:IsPremiumHubUser() and 0.7 or 0.3}):Play()

                if not Settings.PremiumFeature then
                    Services.TweenService:Create(RangeSliderName, TweenInfo.new(0.2), {TextTransparency = PreviousNameTransparency}):Play()
                end

                local valueTransparency = (not Utility:IsPremiumHubUser() and Settings.PremiumFeature) and 0.8 or 0.1
                local valueEditable = not (not Utility:IsPremiumHubUser() and Settings.PremiumFeature)

                Services.TweenService:Create(MinValueInput, TweenInfo.new(0.2), {TextTransparency = valueTransparency, BackgroundTransparency = 0.95}):Play()
                Services.TweenService:Create(MaxValueInput, TweenInfo.new(0.2), {TextTransparency = valueTransparency, BackgroundTransparency = 0.95}):Play()
                Services.TweenService:Create(MinValueUIStroke, TweenInfo.new(0.2), {Transparency = 0.9}):Play()
                Services.TweenService:Create(MaxValueUIStroke, TweenInfo.new(0.2), {Transparency = 0.9}):Play()

                MinValueInput.TextEditable = valueEditable
                MaxValueInput.TextEditable = valueEditable

                if not SliderConnection then
                    ConnectSliderEvents()
                end
            end
        end

        function RangeSliderFunctions:UpdateName(Name)
            RangeSliderName.Text = Name
        end

        function RangeSliderFunctions:SetVisibility(State)
            RangeSlider.Visible = State
        end

        function RangeSliderFunctions:UpdateRange(MinValue, MaxValue)
            RangeSliderFunctions.MinValue = math.clamp(MinValue or RangeSliderFunctions.MinValue, Settings.Minimum, Settings.Maximum)
            RangeSliderFunctions.MaxValue = math.clamp(MaxValue or RangeSliderFunctions.MaxValue, Settings.Minimum, Settings.Maximum)

            if RangeSliderFunctions.MinValue > RangeSliderFunctions.MaxValue then
                RangeSliderFunctions.MinValue = RangeSliderFunctions.MaxValue
            end

            UpdateRange(true)
        end

        function RangeSliderFunctions:GetRange(Tabled)
            return Tabled and {RangeSliderFunctions.MinValue, RangeSliderFunctions.MaxValue} or RangeSliderFunctions.MinValue, RangeSliderFunctions.MaxValue
        end

        function RangeSliderFunctions:GetMinimum()
            return RangeSliderFunctions.MinValue
        end

        function RangeSliderFunctions:GetMaximum()
            return RangeSliderFunctions.MaxValue
        end

        function RangeSliderFunctions:GetState()
            return not IsHidden
        end

        function RangeSliderFunctions:ReturnSettings()
            return Settings
        end

        function RangeSliderFunctions:ReturnTab()
            return RangeSliderFunctions.Tab
        end

        function RangeSliderFunctions:ReturnClass()
            return RangeSliderFunctions.Class
        end

        function RangeSliderFunctions:Destroy()
            if SliderConnection then
                SliderConnection:Disconnect()
            end

            if RangeSlider then
                RangeSlider:Destroy()
            end

            if Flag and WaveLibrary.Options[Flag] then
                WaveLibrary.Options[Flag] = nil
            end
        end

        if Settings.Hidden then
            if typeof(Settings.Hidden) == "table" then
                RangeSliderFunctions:SetHidden(Settings.Hidden[1], Settings.Hidden[2])
            else
                RangeSliderFunctions:SetHidden(Settings.Hidden)
            end
        end

        if Settings.ToolTip then
            RangeSliderFunctions:SetToolTip(Settings.ToolTip)
        end

        local function IsPlaceIdAllowed(PlaceIdSetting)
            if not PlaceIdSetting then return true end
            local CurrentPlaceId = game.PlaceId

            if type(PlaceIdSetting) == "table" then
                for _, PlaceId in pairs(PlaceIdSetting) do
                    if CurrentPlaceId == PlaceId then return true end
                end
                return false
            else
                return CurrentPlaceId == PlaceIdSetting
            end
        end

        local function IsPlaceIdForbidden(PlaceIdSetting)
            if not PlaceIdSetting then return false end
            local CurrentPlaceId = game.PlaceId

            if type(PlaceIdSetting) == "table" then
                for _, PlaceId in pairs(PlaceIdSetting) do
                    if CurrentPlaceId == PlaceId then return true end
                end
                return false
            else
                return CurrentPlaceId == PlaceIdSetting
            end
        end

        if not IsPlaceIdAllowed(Settings.AllowedPlaceId) then
            RangeSliderFunctions:SetHidden(true, "Not in the right PlaceId to use this feature.")
        end

        if IsPlaceIdForbidden(Settings.ForbiddenPlaceId) then
            RangeSliderFunctions:SetHidden(true, "Not in the right PlaceId to use this feature.")
        end

        if Settings.PremiumFeature and not Utility:IsPremiumHubUser() then
            RangeSliderFunctions:SetHidden(true, "Premium Feature")
        end

        if Flag then
            WaveLibrary.Options[Flag] = RangeSliderFunctions
        end

        return RangeSliderFunctions
    end
end
end

R["Wave/UserInterface/Components/Segmented.lua"] = function(...)
return function(Requirements)
    local Section = Requirements.Section
    local WindowFunctions = Requirements.WindowFunctions
    local WaveLibrary = Requirements.WaveLibrary
    local SectionFunctions = Requirements.SectionFunctions

    local function ThemeAttr(Name, Fallback)
        local ok, value = pcall(function()
            return WindowFunctions:GetCurrentThemeAttribute(Name)
        end)
        if ok and value ~= nil then return value end
        return Fallback
    end

    function SectionFunctions:Segmented(Settings, Flag)
        Settings = Settings or {}
        local Options = Settings.Options or Settings.Values or {}

        local SegmentedFunctions = {
            Settings = Settings,
            Class = "Segmented",
            Value = Settings.Default or Options[1],
            Tab = Requirements.TabName,
            _changed = {},
        }

        if not Flag or Flag == "WriteHere" or Flag == "AutoWriteFlag" then
            Flag = string.gsub(Settings.Name or Settings.Title or "Segmented", " ", "_")
        end

        local Accent = ThemeAttr("AccentPrimary", Color3.fromRGB(96, 165, 250))
        local TextPrimary = ThemeAttr("TextPrimary", Color3.fromRGB(235, 235, 240))
        local TextSecondary = ThemeAttr("TextSecondary", Color3.fromRGB(165, 165, 175))

        -- Pick a text colour that reads on top of the accent (dark on light accents).
        local function ContrastText(Color)
            local Luminance = 0.299 * Color.R + 0.587 * Color.G + 0.114 * Color.B
            return Luminance > 0.5 and Color3.fromRGB(18, 18, 22) or Color3.fromRGB(246, 246, 250)
        end
        local ActiveTextColor = ContrastText(Accent)

        local Container = Instance.new("Frame")
        Container.Name = "Segmented"
        Container.BackgroundTransparency = 1
        Container.Size = UDim2.new(1, 0, 0, 38)
        Container.Parent = Section

        local NameLabel = Instance.new("TextLabel")
        NameLabel.Name = "Result_Name"
        NameLabel.FontFace = Font.new(Assets.InterFont)
        NameLabel.Text = Settings.Name or Settings.Title or ""
        NameLabel.TextColor3 = TextPrimary
        NameLabel.TextTransparency = 0.5
        NameLabel.TextSize = 13
        NameLabel.TextXAlignment = Enum.TextXAlignment.Left
        NameLabel.TextTruncate = Enum.TextTruncate.AtEnd
        NameLabel.AnchorPoint = Vector2.new(0, 0.5)
        NameLabel.Position = UDim2.fromScale(0, 0.5)
        NameLabel.Size = UDim2.new(0.4, 0, 1, 0)
        NameLabel.BackgroundTransparency = 1
        NameLabel:SetAttribute("NoApplyTheme", true)
        NameLabel.Parent = Container

        local Bar = Instance.new("Frame")
        Bar.Name = "Bar"
        Bar.AnchorPoint = Vector2.new(1, 0.5)
        Bar.Position = UDim2.fromScale(1, 0.5)
        Bar.Size = UDim2.new(0, 0, 0, 27)
        Bar.AutomaticSize = Enum.AutomaticSize.X
        Bar.BackgroundColor3 = ThemeAttr("DropdownColor", Color3.fromRGB(28, 28, 34))
        Bar.BackgroundTransparency = 0.35
        Bar:SetAttribute("NoApplyTheme", true)
        Bar.Parent = Container

        local BarCorner = Instance.new("UICorner")
        BarCorner.CornerRadius = UDim.new(0, 8)
        BarCorner.Parent = Bar

        local BarPadding = Instance.new("UIPadding")
        BarPadding.PaddingLeft = UDim.new(0, 3)
        BarPadding.PaddingRight = UDim.new(0, 3)
        BarPadding.PaddingTop = UDim.new(0, 3)
        BarPadding.PaddingBottom = UDim.new(0, 3)
        BarPadding.Parent = Bar

        local BarLayout = Instance.new("UIListLayout")
        BarLayout.FillDirection = Enum.FillDirection.Horizontal
        BarLayout.VerticalAlignment = Enum.VerticalAlignment.Center
        BarLayout.SortOrder = Enum.SortOrder.LayoutOrder
        BarLayout.Padding = UDim.new(0, 2)
        BarLayout.Parent = Bar

        local Pills = {}

        local function Select(Option, Fire)
            SegmentedFunctions.Value = Option
            for Value, Pill in pairs(Pills) do
                local Active = (Value == Option)
                Utility:QuickTween(Pill.Bg, { BackgroundTransparency = Active and 0.06 or 1 })
                Utility:QuickTween(Pill.Label, {
                    TextTransparency = Active and 0 or 0.4,
                    TextColor3 = Active and ActiveTextColor or TextSecondary,
                })
            end
            if Fire then
                if Settings.Callback then
                    Settings.Callback(Option)
                end
                for _, fn in ipairs(SegmentedFunctions._changed) do
                    fn(Option)
                end
            end
        end

        for _, Option in ipairs(Options) do
            local Pill = Instance.new("TextButton")
            Pill.Name = "Pill"
            Pill.AutoButtonColor = false
            Pill.Text = ""
            Pill.BackgroundTransparency = 1
            Pill.AutomaticSize = Enum.AutomaticSize.X
            Pill.Size = UDim2.new(0, 0, 1, 0)
            Pill.Parent = Bar

            local Bg = Instance.new("Frame")
            Bg.Name = "Bg"
            Bg.BackgroundColor3 = Accent
            Bg.BackgroundTransparency = 1
            Bg.BorderSizePixel = 0
            Bg.Size = UDim2.fromScale(1, 1)
            Bg:SetAttribute("NoApplyTheme", true)
            Bg.Parent = Pill

            local BgCorner = Instance.new("UICorner")
            BgCorner.CornerRadius = UDim.new(0, 6)
            BgCorner.Parent = Bg

            local Label = Instance.new("TextLabel")
            Label.Name = "Result_PillLabel"
            Label.FontFace = Font.new(Assets.InterFont, Enum.FontWeight.SemiBold, Enum.FontStyle.Normal)
            Label.Text = tostring(Option)
            Label.TextColor3 = TextSecondary
            Label.TextTransparency = 0.4
            Label.TextSize = 12
            Label.AutomaticSize = Enum.AutomaticSize.X
            Label.Size = UDim2.new(0, 0, 1, 0)
            Label.BackgroundTransparency = 1
            Label:SetAttribute("NoApplyTheme", true)
            Label.Parent = Pill

            local LabelPadding = Instance.new("UIPadding")
            LabelPadding.PaddingLeft = UDim.new(0, 11)
            LabelPadding.PaddingRight = UDim.new(0, 11)
            LabelPadding.Parent = Label

            Pills[Option] = { Bg = Bg, Label = Label }
            Pill.MouseButton1Click:Connect(function()
                Select(Option, true)
            end)
        end

        function SegmentedFunctions:OnChanged(fn)
            if type(fn) == "function" then
                table.insert(self._changed, fn)
            end
            return self
        end

        function SegmentedFunctions:SetValue(Option)
            Select(Option, true)
            return self
        end

        function SegmentedFunctions:GetValue()
            return self.Value
        end

        function SegmentedFunctions:SetVisibility(State)
            Container.Visible = State
        end

        function SegmentedFunctions:ReturnClass()
            return "Segmented"
        end

        function SegmentedFunctions:Destroy()
            Container:Destroy()
        end

        Select(SegmentedFunctions.Value, false)

        if Flag then
            WaveLibrary.Options[Flag] = SegmentedFunctions
        end

        return SegmentedFunctions
    end
end
end

R["Wave/UserInterface/Components/Slider.lua"] = function(...)
return function(Requirements)
    local Section = Requirements.Section
    local WindowFunctions = Requirements.WindowFunctions
    local WaveLibraryUI = Requirements.WaveLibraryUI
    local WaveLibrary = Requirements.WaveLibrary
    local SectionFunctions = Requirements.SectionFunctions
    local BaseUIScale = Requirements.BaseUIScale

    function SectionFunctions:Slider(Settings, Flag)
        local SliderFunctions = { 
            Settings = Settings, 
            IgnoreConfig = Settings.IgnoreConfig, 
            Class = "Slider",
            Tab = Requirements.TabName,
        }

        if not Flag then
            Flag = "WriteHere"
        end

        if Flag == "WriteHere" or Flag == "AutoWriteFlag" then
            Flag = string.gsub(SliderFunctions.Settings.Name, " ", "_")
        end

        local Slider = Instance.new("Frame")
        Slider.Name = "Slider"
        Slider.AutomaticSize = Enum.AutomaticSize.Y
        Slider.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
        Slider.BackgroundTransparency = 1
        Slider.BorderColor3 = Color3.fromRGB(0, 0, 0)
        Slider.BorderSizePixel = 0
        Slider.Size = UDim2.new(1, 0, 0, 38)
        Slider.Parent = Section

        local SliderName = Instance.new("TextLabel")
        SliderName.Name = "SliderName"
        SliderName.FontFace = Font.new(Assets.InterFont)
        SliderName.Text = SliderFunctions.Settings.Name
        SliderName.RichText = true
        SliderName.TextColor3 = WindowFunctions:GetCurrentThemeAttribute("TextPrimary")
        SliderName.TextSize = 13
        SliderName.TextTransparency = 0.5
        SliderName.TextTruncate = Enum.TextTruncate.AtEnd
        SliderName.TextXAlignment = Enum.TextXAlignment.Left
        SliderName.TextYAlignment = Enum.TextYAlignment.Top
        SliderName.AnchorPoint = Vector2.new(0, 0.5)
        SliderName.AutomaticSize = Enum.AutomaticSize.XY
        SliderName.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        SliderName.BackgroundTransparency = 1
        SliderName.BorderColor3 = Color3.fromRGB(0, 0, 0)
        SliderName.BorderSizePixel = 0
        SliderName.Position = UDim2.fromScale(1.3e-07, 0.5)
        SliderName.Parent = Slider

        if Settings.PremiumFeature then
            SliderName.TextTransparency = 0
            local PremiumGradient = Instance.new("UIGradient")
            PremiumGradient.Color = WindowFunctions:GetCurrentThemeAttribute("PremiumGradientColor") or ColorSequence.new({
                ColorSequenceKeypoint.new(0, Color3.fromRGB(0, 106, 255)),
                ColorSequenceKeypoint.new(0.5, Color3.fromRGB(163, 201, 255)),
                ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 255, 255))
            })

            PremiumGradient.Rotation = 0
            PremiumGradient.Parent = SliderName
        end

        local SliderElements = Instance.new("Frame")
        SliderElements.Name = "SliderElements"
        SliderElements.AnchorPoint = Vector2.new(1, 0)
        SliderElements.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        SliderElements.BackgroundTransparency = 1
        SliderElements.BorderColor3 = Color3.fromRGB(0, 0, 0)
        SliderElements.BorderSizePixel = 0
        SliderElements.Position = UDim2.fromScale(1, 0)
        SliderElements.Size = UDim2.fromScale(1, 1)

        local SliderValue = Instance.new("TextBox")
        SliderValue.Name = "SliderValue"
        SliderValue.FontFace = Font.new(Assets.InterFont)
        SliderValue.TextColor3 = Color3.fromRGB(255, 255, 255)
        SliderValue.TextSize = 12
        SliderValue.TextTransparency = 0.1

        SliderValue.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        SliderValue.BackgroundTransparency = 0.95
        SliderValue.BorderColor3 = Color3.fromRGB(0, 0, 0)
        SliderValue.BorderSizePixel = 0
        SliderValue.LayoutOrder = 1
        SliderValue.Position = UDim2.fromScale(-0.0789, 0.171)
        SliderValue.Size = UDim2.fromOffset(41, 21)
        SliderValue.ClipsDescendants = true

        if not Utility:IsPremiumHubUser() and Settings.PremiumFeature then
            SliderValue.TextEditable = false
            SliderValue.ClearTextOnFocus = false
            SliderValue.TextTransparency = 0.8
        end

        local SliderValueUICorner = Instance.new("UICorner")
        SliderValueUICorner.Name = "SliderValueUICorner"
        SliderValueUICorner.CornerRadius = UDim.new(0, 4)
        SliderValueUICorner.Parent = SliderValue

        local SliderValueUIStroke = Instance.new("UIStroke")
        SliderValueUIStroke.Name = "SliderValueUIStroke"
        SliderValueUIStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        SliderValueUIStroke.Color = Color3.fromRGB(255, 255, 255)
        SliderValueUIStroke.Transparency = 0.9
        SliderValueUIStroke.Parent = SliderValue

        local SliderValueUIPadding = Instance.new("UIPadding")
        SliderValueUIPadding.Name = "SliderValueUIPadding"
        SliderValueUIPadding.PaddingLeft = UDim.new(0, 2)
        SliderValueUIPadding.PaddingRight = UDim.new(0, 2)
        SliderValueUIPadding.Parent = SliderValue

        SliderValue.Parent = SliderElements

        local SliderElementsUIListLayout = Instance.new("UIListLayout")
        SliderElementsUIListLayout.Name = "SliderElementsUIListLayout"
        SliderElementsUIListLayout.Padding = UDim.new(0, 20)
        SliderElementsUIListLayout.FillDirection = Enum.FillDirection.Horizontal
        SliderElementsUIListLayout.HorizontalAlignment = Enum.HorizontalAlignment.Right
        SliderElementsUIListLayout.SortOrder = Enum.SortOrder.LayoutOrder
        SliderElementsUIListLayout.VerticalAlignment = Enum.VerticalAlignment.Center
        SliderElementsUIListLayout.Parent = SliderElements

        local SliderBar = Instance.new("ImageLabel")
        SliderBar.Name = "SliderBar"
        SliderBar.Image = Assets.SliderBar
        SliderBar.ImageColor3 = Color3.fromRGB(87, 86, 86)
        SliderBar.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        SliderBar.BackgroundTransparency = 1
        SliderBar.BorderColor3 = Color3.fromRGB(0, 0, 0)
        SliderBar.BorderSizePixel = 0
        SliderBar.Position = UDim2.fromScale(0.219, 0.457)
        SliderBar.Size = UDim2.fromOffset(123, 3)

        local SliderHead = Instance.new("ImageButton")
        SliderHead.Name = "SliderHead"
        SliderHead.Image = Assets.SliderHead
        SliderHead.AnchorPoint = Vector2.new(0.5, 0.5)
        SliderHead.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        SliderHead.BackgroundTransparency = 1
        SliderHead.BorderColor3 = Color3.fromRGB(0, 0, 0)
        SliderHead.BorderSizePixel = 0
        SliderHead.Position = UDim2.fromScale(1, 0.5)
        SliderHead.Size = UDim2.fromOffset(12, 12)
        SliderHead.Parent = SliderBar

        local IsHidden = false
        local SliderConnection = nil
        local PreviousNameTransparency = 0.5
        local PreviousValueTransparency = 0.1
        local Dragging = false

        if not Settings.PremiumFeature then
            SliderHead.MouseEnter:Connect(function()
                if IsHidden then return end
                Utility:QuickTween(SliderName, {
                    TextTransparency = 0
                })
            end)

            SliderHead.MouseLeave:Connect(function()
                if IsHidden then return end
                Utility:QuickTween(SliderName, {
                    TextTransparency = PreviousNameTransparency
                })
            end)

            SliderValue.MouseEnter:Connect(function()
                if IsHidden then return end
                Utility:QuickTween(SliderName, {
                    TextTransparency = 0
                })
            end)

            SliderValue.MouseLeave:Connect(function()
                if IsHidden then return end
                Utility:QuickTween(SliderName, {
                    TextTransparency = PreviousNameTransparency
                })
            end)
        end

        if not Utility:IsPremiumHubUser() and Settings.PremiumFeature then
            SliderBar.ImageTransparency = 0.6
            SliderHead.ImageTransparency = 0.3
        end

        SliderBar.Parent = SliderElements

        local SliderElementsUIPadding = Instance.new("UIPadding")
        SliderElementsUIPadding.Name = "SliderElementsUIPadding"
        SliderElementsUIPadding.PaddingTop = UDim.new(0, 3)
        SliderElementsUIPadding.Parent = SliderElements

        SliderElements.Parent = Slider

        local DisplayMethods = {
            Thousandths = function(SliderDisplayValue)
                return string.format("%.3f", SliderDisplayValue)
            end,

            Hundredths = function(SliderDisplayValue)
                return string.format("%.2f", SliderDisplayValue)
            end,

            Tenths = function(SliderDisplayValue)
                return string.format("%.1f", SliderDisplayValue)
            end,

            Round = function(SliderDisplayValue, Precision)
                local NumericValue = tonumber(SliderDisplayValue) or 0
                if Precision then
                    return string.format("%." .. Precision .. "f", NumericValue)
                else
                    return tostring(math.round(NumericValue))
                end
            end,

            Degrees = function(SliderDisplayValue, Precision)
                local FormattedValue = Precision and string.format("%." .. Precision .. "f", SliderDisplayValue) or tostring(SliderDisplayValue)
                return FormattedValue .. "°"
            end,

            Percent = function(SliderDisplayValue, Precision)
                local Percentage = (SliderDisplayValue - SliderFunctions.Settings.Minimum) / (SliderFunctions.Settings.Maximum - SliderFunctions.Settings.Minimum) * 100
                return Precision and string.format("%." .. Precision .. "f", Percentage) .. "%" or tostring(math.round(Percentage)) .. "%"
            end,

            Value = function(SliderDisplayValue, Precision)
                return Precision and string.format("%." .. Precision .. "f", SliderDisplayValue) or tostring(SliderDisplayValue)
            end,

            Time24Hour = function(SliderDisplayValue)
                local TotalSeconds = math.floor(SliderDisplayValue)
                local Hours = math.floor(TotalSeconds / 3600) % 24
                local Minutes = math.floor((TotalSeconds % 3600) / 60)
                local Seconds = TotalSeconds % 60
                return string.format("%02d:%02d:%02d", Hours, Minutes, Seconds)
            end,

            Time12Hour = function(SliderDisplayValue)
                local TotalSeconds = math.floor(SliderDisplayValue)
                local Hours24 = math.floor(TotalSeconds / 3600) % 24
                local Minutes = math.floor((TotalSeconds % 3600) / 60)
                local Seconds = TotalSeconds % 60
                
                local Hours12 = Hours24 % 12
                if Hours12 == 0 then Hours12 = 12 end
                local Period = Hours24 >= 12 and "PM" or "AM"
                
                return string.format("%02d:%02d:%02d %s", Hours12, Minutes, Seconds, Period)
            end
        }

        local ValueDisplayMethod = DisplayMethods[SliderFunctions.Settings.DisplayMethod] or DisplayMethods.Value
        local FinalValue

        local function SetValue(Val, IgnoreCallback)
            local PosXScale

            if typeof(Val) == "Instance" then
                local Input = Val
                PosXScale = math.clamp((Input.Position.X - SliderBar.AbsolutePosition.X) / SliderBar.AbsoluteSize.X, 0, 1)
            else
                local Value = Val
                PosXScale = (Value - SliderFunctions.Settings.Minimum) / (SliderFunctions.Settings.Maximum - Settings.Minimum)
            end

            local Pos = UDim2.new(PosXScale, 0, 0.5, 0)
            SliderHead.Position = Pos

            FinalValue = PosXScale * (SliderFunctions.Settings.Maximum - SliderFunctions.Settings.Minimum) + Settings.Minimum

            SliderValue.Text = (Settings.Prefix or "") .. ValueDisplayMethod(FinalValue, SliderFunctions.Settings.Precision) .. (Settings.Suffix or "")

            if not IgnoreCallback then
                task.spawn(function()
                    if SliderFunctions.Settings.Callback then
                        SliderFunctions.Settings.Callback(FinalValue)
                    end
                end)
            end

            SliderFunctions.Value = FinalValue
        end

        SetValue(SliderFunctions.Settings.Default, true)

        local function ConnectSliderEvents()
            SliderHead.InputBegan:Connect(function(Input)
                if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
                    if not Utility:IsPremiumHubUser() and Settings.PremiumFeature then
                        return
                    end
                    if IsHidden then
                        return
                    end
                    Dragging = true
                    SetValue(Input)
                end
            end)

            SliderHead.InputEnded:Connect(function(Input)
                if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
                    if not Utility:IsPremiumHubUser() and Settings.PremiumFeature then
                        return
                    end
                    if IsHidden then
                        return
                    end

                    Dragging = false
                    if SliderFunctions.Settings.OnInputComplete then
                        SliderFunctions.Settings.OnInputComplete(FinalValue)
                    end
                end
            end)

            SliderValue.FocusLost:Connect(function(EnterPressed)
                if IsHidden then return end

                local InputText = SliderValue.Text
                local Value, IsPercent = InputText:match("^(%-?%d+%.?%d*)(%%?)$")

                if Value then
                    Value = tonumber(Value)
                    IsPercent = IsPercent == "%"

                    if IsPercent then
                        Value = SliderFunctions.Settings.Minimum + (Value / 100) * (SliderFunctions.Settings.Maximum - SliderFunctions.Settings.Minimum)
                    end

                    local NewValue = math.clamp(Value, SliderFunctions.Settings.Minimum, SliderFunctions.Settings.Maximum)
                    SetValue(NewValue)
                else
                    SliderValue.Text = ValueDisplayMethod(SliderValue)
                end

                if SliderFunctions.Settings.OnInputComplete then
                    SliderFunctions.Settings.OnInputComplete(FinalValue)
                end
            end)

            SliderConnection = Services.UserInputService.InputChanged:Connect(function(Input)
                if Dragging and not IsHidden and (Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch) then
                    SetValue(Input)
                end
            end)
        end

        ConnectSliderEvents()

        local function UpdateSliderBarSize()
            local Padding = SliderElementsUIListLayout.Padding.Offset
            local SliderValueWidth = SliderValue.AbsoluteSize.X
            local SliderNameWidth = SliderName.AbsoluteSize.X
            local TotalWidth = SliderElements.AbsoluteSize.X

            local NewBarWidth = (TotalWidth - (Padding + SliderValueWidth + SliderNameWidth + 20)) / BaseUIScale.Scale
            SliderBar.Size = UDim2.new(SliderBar.Size.X.Scale, NewBarWidth, SliderBar.Size.Y.Scale, SliderBar.Size.Y.Offset)
        end

        UpdateSliderBarSize()

        SliderName:GetPropertyChangedSignal("AbsoluteSize"):Connect(UpdateSliderBarSize)
        Section:GetPropertyChangedSignal("AbsoluteSize"):Connect(UpdateSliderBarSize)

        function SliderFunctions:SetToolTip(Tip)
            if Slider:FindFirstChild("ToolTipFrame") then
                Slider:FindFirstChild("ToolTipFrame"):Destroy()
            end

            if not Tip or Tip == "" then
                return
            end

            local ToolTipFrame = Instance.new("Frame")
            ToolTipFrame.Name = "ToolTipFrame"
            ToolTipFrame.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
            ToolTipFrame.BackgroundTransparency = 1
            ToolTipFrame.BorderSizePixel = 0
            ToolTipFrame.AnchorPoint = Vector2.new(0.5, 1)
            ToolTipFrame.Position = UDim2.new(0.5, 0, 0, -5)
            ToolTipFrame.Visible = false
            ToolTipFrame.ZIndex = 200
            ToolTipFrame.Parent = Slider

            local TooltipCorner = Instance.new("UICorner")
            TooltipCorner.CornerRadius = UDim.new(0, 6)
            TooltipCorner.Parent = ToolTipFrame

            local TooltipStroke = Instance.new("UIStroke")
            TooltipStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            TooltipStroke.LineJoinMode = Enum.LineJoinMode.Round
            TooltipStroke.Color = Color3.fromRGB(255, 255, 255)
            TooltipStroke.Thickness = 0.1
            TooltipStroke.Transparency = 0.2
            TooltipStroke.Parent = ToolTipFrame

            local TooltipText = Instance.new("TextLabel")
            TooltipText.Name = "TooltipText"
            TooltipText.Text = Tip
            TooltipText.FontFace = Font.new(Assets.InterFont)
            TooltipText.TextColor3 = Color3.fromRGB(200, 220, 200)
            TooltipText.TextSize = 12
            TooltipText.TextTransparency = 1
            TooltipText.BackgroundTransparency = 1
            TooltipText.TextXAlignment = Enum.TextXAlignment.Center
            TooltipText.TextYAlignment = Enum.TextYAlignment.Center
            TooltipText.TextWrapped = false
            TooltipText.Size = UDim2.new(1, -12, 1, 0)
            TooltipText.Position = UDim2.new(0, 6, 0, 0)
            TooltipText.Parent = ToolTipFrame

            local TextBounds = Services.TextService:GetTextSize(
                Tip,
                TooltipText.TextSize,
                Enum.Font.SourceSansBold,
                Vector2.new(math.huge, math.huge)
            )

            local TooltipWidth = math.max(80, TextBounds.X + 50)
            local TooltipHeight = math.max(28, TextBounds.Y + 12)
            ToolTipFrame.Size = UDim2.new(0, TooltipWidth, 0, TooltipHeight)

            local function ShowTooltip()
                ToolTipFrame.Visible = true
                ToolTipFrame.BackgroundTransparency = 1
                TooltipText.TextTransparency = 1

                Services.TweenService:Create(
                    ToolTipFrame,
                    TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                    {BackgroundTransparency = 0.1}
                ):Play()

                Services.TweenService:Create(
                    TooltipText,
                    TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                    {TextTransparency = 0}
                ):Play()

                Services.TweenService:Create(
                    TooltipStroke,
                    TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                    {Transparency = 0.8}
                ):Play()
            end

            local function HideTooltip()
                Services.TweenService:Create(
                    ToolTipFrame,
                    TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                    {BackgroundTransparency = 1}
                ):Play()

                Services.TweenService:Create(
                    TooltipText,
                    TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                    {TextTransparency = 1}
                ):Play()

                Services.TweenService:Create(
                    TooltipStroke,
                    TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
                    {Transparency = 1}
                ):Play()

                task.spawn(function()
                    task.wait(0.2)
                    if ToolTipFrame and ToolTipFrame.Parent then
                        ToolTipFrame.Visible = false
                    end
                end)
            end

            SliderHead.MouseEnter:Connect(ShowTooltip)
            SliderHead.MouseLeave:Connect(HideTooltip)
            SliderValue.MouseEnter:Connect(ShowTooltip)
            SliderValue.MouseLeave:Connect(HideTooltip)
        end

        function SliderFunctions:SetHidden(State, Reason)
            if Reason then
                self:SetToolTip(Reason)
            end

            IsHidden = State

            if State then

                if not Settings.PremiumFeature then
                    PreviousNameTransparency = SliderName.TextTransparency
                end
                PreviousValueTransparency = SliderValue.TextTransparency

                Services.TweenService:Create(
                    SliderBar,
                    TweenInfo.new(0.2),
                    { ImageTransparency = 0.9 }
                ):Play()

                Services.TweenService:Create(
                    SliderHead,
                    TweenInfo.new(0.2),
                    { ImageTransparency = 0.9 }
                ):Play()

                if not Settings.PremiumFeature then
                    Services.TweenService:Create(
                        SliderName,
                        TweenInfo.new(0.2),
                        { TextTransparency = 0.9 }
                    ):Play()
                end

                Services.TweenService:Create(
                    SliderValue,
                    TweenInfo.new(0.2),
                    { TextTransparency = 0.9, BackgroundTransparency = 0.99 }
                ):Play()

                Services.TweenService:Create(
                    SliderValueUIStroke,
                    TweenInfo.new(0.2),
                    { Transparency = 0.95 }
                ):Play()

                SliderValue.TextEditable = false
                SliderHead.AutoButtonColor = false

                if SliderConnection then
                    SliderConnection:Disconnect()
                    SliderConnection = nil
                end

            else

                local originalBarTransparency = (not Utility:IsPremiumHubUser() and Settings.PremiumFeature) and 0.6 or 0
                local originalHeadTransparency = (not Utility:IsPremiumHubUser() and Settings.PremiumFeature) and 0.3 or 0

                Services.TweenService:Create(
                    SliderBar,
                    TweenInfo.new(0.2),
                    { ImageTransparency = originalBarTransparency }
                ):Play()

                Services.TweenService:Create(
                    SliderHead,
                    TweenInfo.new(0.2),
                    { ImageTransparency = originalHeadTransparency }
                ):Play()

                if not Settings.PremiumFeature then
                    Services.TweenService:Create(
                        SliderName,
                        TweenInfo.new(0.2),
                        { TextTransparency = PreviousNameTransparency }
                    ):Play()
                end

                local valueTransparency = (not Utility:IsPremiumHubUser() and Settings.PremiumFeature) and 0.8 or 0.1
                local valueEditable = not (not Utility:IsPremiumHubUser() and Settings.PremiumFeature)

                Services.TweenService:Create(
                    SliderValue,
                    TweenInfo.new(0.2),
                    { TextTransparency = valueTransparency, BackgroundTransparency = 0.95 }
                ):Play()

                Services.TweenService:Create(
                    SliderValueUIStroke,
                    TweenInfo.new(0.2),
                    { Transparency = 0.9 }
                ):Play()

                SliderValue.TextEditable = valueEditable
                SliderHead.AutoButtonColor = false

                if not SliderConnection then
                    SliderConnection = Services.UserInputService.InputChanged:Connect(function(Input)
                        if Dragging and not IsHidden and (Input.UserInputType == Enum.UserInputType.MouseMovement or Input.UserInputType == Enum.UserInputType.Touch) then
                            SetValue(Input)
                        end
                    end)
                end
            end
        end

        function SliderFunctions:UpdateName(Name)
            SliderName.Text = Name
        end

        function SliderFunctions:SetVisibility(State)
            Slider.Visible = State
        end

        function SliderFunctions:UpdateValue(Value, IgnoreCallback)
            SetValue(tonumber(Value), IgnoreCallback or false)
        end

        function SliderFunctions:GetValue()
            return FinalValue
        end

        function SliderFunctions:ReturnClass()
            return SliderFunctions.Class
        end

        function SliderFunctions:ReturnTab()
            return SliderFunctions.Tab
        end

        function SliderFunctions:GetState()
            return not IsHidden
        end

        function SliderFunctions:ReturnSettings()
            return Settings
        end

        function SliderFunctions:Destroy()
            if SliderConnection then
                SliderConnection:Disconnect()
            end

            if Slider then
                Slider:Destroy()
            end

            if Flag and WaveLibrary.Options[Flag] then
                WaveLibrary.Options[Flag] = nil
            end
        end

        if SliderFunctions.Settings.Hidden then
            if typeof(SliderFunctions.Settings.Hidden) == "table" then
                SliderFunctions:SetHidden(SliderFunctions.Settings.Hidden[1], SliderFunctions.Settings.Hidden[2])
            else
                SliderFunctions:SetHidden(SliderFunctions.Settings.Hidden)
            end
        end

        if SliderFunctions.Settings.ToolTip then
            SliderFunctions:SetToolTip(Settings.ToolTip)
        end

        local function IsPlaceIdAllowed(PlaceIdSetting)
            if not PlaceIdSetting then return true end

            local CurrentPlaceId = game.PlaceId

            if type(PlaceIdSetting) == "table" then
                for _, PlaceId in pairs(PlaceIdSetting) do
                    if CurrentPlaceId == PlaceId then
                        return true
                    end
                end
                return false
            else
                return CurrentPlaceId == PlaceIdSetting
            end
        end

        local function IsPlaceIdForbidden(PlaceIdSetting)
            if not PlaceIdSetting then return false end

            local CurrentPlaceId = game.PlaceId

            if type(PlaceIdSetting) == "table" then
                for _, PlaceId in pairs(PlaceIdSetting) do
                    if CurrentPlaceId == PlaceId then
                        return true
                    end
                end
                return false
            else
                return CurrentPlaceId == PlaceIdSetting
            end
        end

        if not IsPlaceIdAllowed(Settings.AllowedPlaceId) then
            SliderFunctions:SetHidden(true, "Not in the right PlaceId to use this feature.")
        end

        if IsPlaceIdForbidden(Settings.ForbiddenPlaceId) then
            SliderFunctions:SetHidden(true, "Not in the right PlaceId to use this feature.")
        end

        if Settings.PremiumFeature and not Utility:IsPremiumHubUser() then
            SliderFunctions:SetHidden(true, "Premium Feature")
        end

        if Flag then
            WaveLibrary.Options[Flag] = SliderFunctions
        end

        return SliderFunctions
    end
end
end

