R["Wave/UserInterface/Components/Stat.lua"] = function(...)
return function(Requirements)
    local Section = Requirements.Section
    local WindowFunctions = Requirements.WindowFunctions
    local WaveLibrary = Requirements.WaveLibrary
    local SectionFunctions = Requirements.SectionFunctions

    local function ThemeAttr(Name, Fallback)
        local ok, value = pcall(function()
            return WindowFunctions:GetCurrentThemeAttribute(Name)
        end)
        if ok and value ~= nil then return value end
        return Fallback
    end

    function SectionFunctions:Stat(Settings, Flag)
        Settings = Settings or {}

        local StatFunctions = {
            Settings = Settings,
            Class = "Stat",
            Value = Settings.Value,
            Tab = Requirements.TabName,
        }

        local Accent = ThemeAttr("AccentPrimary", Color3.fromRGB(96, 165, 250))
        local TextPrimary = ThemeAttr("TextPrimary", Color3.fromRGB(236, 236, 241))
        local TextSecondary = ThemeAttr("TextSecondary", Color3.fromRGB(160, 160, 172))

        local Card = Instance.new("Frame")
        Card.Name = "Stat"
        Card.BackgroundColor3 = ThemeAttr("Surface", Color3.fromRGB(26, 26, 32))
        Card.BackgroundTransparency = 0.5
        Card.BorderSizePixel = 0
        Card.Size = UDim2.new(1, 0, 0, 58)
        Card:SetAttribute("NoApplyTheme", true)
        Card.Parent = Section

        local CardCorner = Instance.new("UICorner")
        CardCorner.CornerRadius = UDim.new(0, 10)
        CardCorner.Parent = Card

        local CardStroke = Instance.new("UIStroke")
        CardStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        CardStroke.Color = ThemeAttr("BorderColor", Color3.fromRGB(255, 255, 255))
        CardStroke.Transparency = 0.9
        CardStroke.Parent = Card

        local CardPadding = Instance.new("UIPadding")
        CardPadding.PaddingLeft = UDim.new(0, 14)
        CardPadding.PaddingRight = UDim.new(0, 14)
        CardPadding.Parent = Card

        local Row = Instance.new("UIListLayout")
        Row.FillDirection = Enum.FillDirection.Horizontal
        Row.VerticalAlignment = Enum.VerticalAlignment.Center
        Row.SortOrder = Enum.SortOrder.LayoutOrder
        Row.Padding = UDim.new(0, 12)
        Row.Parent = Card

        if Settings.Icon then
            local IconHolder = Instance.new("Frame")
            IconHolder.Name = "IconHolder"
            IconHolder.Size = UDim2.fromOffset(34, 34)
            IconHolder.BackgroundColor3 = Accent
            IconHolder.BackgroundTransparency = 0.82
            IconHolder.BorderSizePixel = 0
            IconHolder:SetAttribute("NoApplyTheme", true)
            IconHolder.Parent = Card

            local IconCorner = Instance.new("UICorner")
            IconCorner.CornerRadius = UDim.new(0, 9)
            IconCorner.Parent = IconHolder

            local Icon = Instance.new("ImageLabel")
            Icon.Name = "Result_Icon"
            Icon.AnchorPoint = Vector2.new(0.5, 0.5)
            Icon.Position = UDim2.fromScale(0.5, 0.5)
            Icon.Size = UDim2.fromOffset(18, 18)
            Icon.BackgroundTransparency = 1
            Icon.Image = Settings.Icon
            Icon.ImageColor3 = Accent
            Icon:SetAttribute("NoApplyTheme", true)
            Icon.Parent = IconHolder
        end

        local TextColumn = Instance.new("Frame")
        TextColumn.Name = "TextColumn"
        TextColumn.BackgroundTransparency = 1
        TextColumn.AutomaticSize = Enum.AutomaticSize.X
        TextColumn.Size = UDim2.new(0, 0, 1, 0)
        TextColumn.LayoutOrder = 1
        TextColumn.Parent = Card

        local ColumnLayout = Instance.new("UIListLayout")
        ColumnLayout.SortOrder = Enum.SortOrder.LayoutOrder
        ColumnLayout.VerticalAlignment = Enum.VerticalAlignment.Center
        ColumnLayout.Padding = UDim.new(0, 1)
        ColumnLayout.Parent = TextColumn

        local LabelText = Instance.new("TextLabel")
        LabelText.Name = "Result_Label"
        LabelText.FontFace = Font.new(Assets.InterFont, Enum.FontWeight.Medium, Enum.FontStyle.Normal)
        LabelText.Text = string.upper(Settings.Title or Settings.Name or "Stat")
        LabelText.TextColor3 = TextSecondary
        LabelText.TextTransparency = 0.25
        LabelText.TextSize = 11
        LabelText.TextXAlignment = Enum.TextXAlignment.Left
        LabelText.AutomaticSize = Enum.AutomaticSize.XY
        LabelText.BackgroundTransparency = 1
        LabelText:SetAttribute("NoApplyTheme", true)
        LabelText.Parent = TextColumn

        local ValueText = Instance.new("TextLabel")
        ValueText.Name = "Result_Value"
        ValueText.FontFace = Font.new(Assets.InterFont, Enum.FontWeight.Bold, Enum.FontStyle.Normal)
        ValueText.RichText = true
        ValueText.Text = tostring(Settings.Value ~= nil and Settings.Value or "—")
        ValueText.TextColor3 = TextPrimary
        ValueText.TextSize = 19
        ValueText.TextXAlignment = Enum.TextXAlignment.Left
        ValueText.AutomaticSize = Enum.AutomaticSize.XY
        ValueText.BackgroundTransparency = 1
        ValueText.LayoutOrder = 1
        ValueText:SetAttribute("NoApplyTheme", true)
        ValueText.Parent = TextColumn

        function StatFunctions:SetValue(New)
            self.Value = New
            ValueText.Text = tostring(New)
            return self
        end
        StatFunctions.UpdateValue = StatFunctions.SetValue

        function StatFunctions:SetLabel(New)
            LabelText.Text = string.upper(New)
            return self
        end
        StatFunctions.UpdateName = StatFunctions.SetLabel

        function StatFunctions:SetVisibility(State)
            Card.Visible = State
        end

        function StatFunctions:ReturnClass()
            return "Stat"
        end

        function StatFunctions:Destroy()
            Card:Destroy()
        end

        if Flag then
            WaveLibrary.Options[Flag] = StatFunctions
        end

        return StatFunctions
    end
end
end

