R["Wave/UserInterface/Components/Toggle.lua"] = function(...)
return function(Requirements)
    local Section = Requirements.Section
    local WindowFunctions = Requirements.WindowFunctions
    local WaveLibraryUI = Requirements.WaveLibraryUI
    local WaveLibrary = Requirements.WaveLibrary
    local SectionFunctions = Requirements.SectionFunctions
    local BaseUIScale = Requirements.BaseUIScale

    local ComponentManager = Requirements.ComponentManager

    function SectionFunctions:Toggle(Settings, Flag)
        local ToggleFunctions = {
            Settings = Settings,
            Tab = Requirements.TabName,
            IgnoreConfig = Settings.IgnoreConfig,
            Class = "Toggle",
            State = Settings.Default or false,
            IsHidden = false,
            Maid = {},
            Elements = {}
        }

        if not Flag or Flag == "WriteHere" or Flag == "AutoWriteFlag" then
            Flag = string.gsub(Settings.Name, " ", "_")
        end

        local TWEEN_INFO = TweenInfo.new(0.2, Enum.EasingStyle.Sine)
        local TRANSPARENCY = {
            Enabled = {Toggle = 0, Head = 0},
            Disabled = {Toggle = 0.5, Head = 0.05}
        }

        local POSITIONS = {
            Enabled = UDim2.new(1, 0, 0.5, 0),
            Disabled = UDim2.new(0.5, 0, 0.5, 0)
        }

        local ToggleOnColor = WindowFunctions:GetCurrentThemeAttribute("AccentPrimary") or Color3.fromRGB(96, 165, 250)
        local ToggleOffColor = WindowFunctions:GetCurrentThemeAttribute("ToggleColor") or Color3.fromRGB(72, 72, 84)

        -- Keep the knob readable on top of the ON track: a dark knob on a light
        -- accent (e.g. the Dark theme's near-white accent), white otherwise.
        local function ContrastColor(Color)
            local Luminance = 0.299 * Color.R + 0.587 * Color.G + 0.114 * Color.B
            return Luminance > 0.5 and Color3.fromRGB(28, 28, 34) or Color3.fromRGB(255, 255, 255)
        end
        local HeadOnColor = ContrastColor(ToggleOnColor)
        local HeadOffColor = Color3.fromRGB(255, 255, 255)

        local function CreateElements()
            local Elements = {}

            Elements.Toggle = Instance.new("Frame")
            Elements.Toggle.Name = "Toggle"
            Elements.Toggle.AutomaticSize = Enum.AutomaticSize.Y
            Elements.Toggle.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
            Elements.Toggle.BackgroundTransparency = 1
            Elements.Toggle.BorderSizePixel = 0
            Elements.Toggle.Size = UDim2.new(1, 0, 0, 38)
            Elements.Toggle.Parent = Section

            Elements.Highlight = Instance.new("Frame")
            Elements.Highlight.Name = "ToggleHighlight"
            Elements.Highlight.BackgroundColor3 = WindowFunctions:GetCurrentThemeAttribute("HoverColor") or Color3.fromRGB(255, 255, 255)
            Elements.Highlight.BackgroundTransparency = 1
            Elements.Highlight.BorderSizePixel = 0
            Elements.Highlight.AnchorPoint = Vector2.new(0.5, 0.5)
            Elements.Highlight.Position = UDim2.fromScale(0.5, 0.5)
            Elements.Highlight.Size = UDim2.new(1, 16, 1, 2)
            Elements.Highlight.ZIndex = 0
            Elements.Highlight:SetAttribute("NoApplyTheme", true)
            Elements.Highlight.Parent = Elements.Toggle

            local HighlightCorner = Instance.new("UICorner")
            HighlightCorner.CornerRadius = UDim.new(0, 8)
            HighlightCorner.Parent = Elements.Highlight

            Elements.ToggleName = Instance.new("TextLabel")
            Elements.ToggleName.Name = "ToggleName"
            Elements.ToggleName.FontFace = Font.new(Assets.InterFont)
            Elements.ToggleName.Text = Settings.Name
            Elements.ToggleName.RichText = true
            Elements.ToggleName.TextColor3 = WindowFunctions:GetCurrentThemeAttribute("TextPrimary")
            Elements.ToggleName.TextSize = 13
            Elements.ToggleName.TextTransparency = 0.5
            Elements.ToggleName.TextTruncate = Enum.TextTruncate.AtEnd
            Elements.ToggleName.TextXAlignment = Enum.TextXAlignment.Left
            Elements.ToggleName.TextYAlignment = Enum.TextYAlignment.Top
            Elements.ToggleName.AnchorPoint = Vector2.new(0, 0.5)
            Elements.ToggleName.AutomaticSize = Enum.AutomaticSize.Y
            Elements.ToggleName.BackgroundTransparency = 1
            Elements.ToggleName.Position = UDim2.fromScale(0, 0.5)
            Elements.ToggleName.Size = UDim2.new(1, -50, 0, 0)
            Elements.ToggleName.Parent = Elements.Toggle

            if Settings.PremiumFeature then
                Elements.ToggleName.TextTransparency = 0
                local PremiumGradient = Instance.new("UIGradient")
                PremiumGradient.Color = WindowFunctions:GetCurrentThemeAttribute("PremiumGradientColor") or ColorSequence.new({
                    ColorSequenceKeypoint.new(0, Color3.fromRGB(0, 106, 255)),
                    ColorSequenceKeypoint.new(0.2, Color3.fromRGB(163, 201, 255)),
                    ColorSequenceKeypoint.new(0.4, Color3.fromRGB(255, 255, 255)),
                    ColorSequenceKeypoint.new(1, Color3.fromRGB(163, 201, 255))
                })
                PremiumGradient.Parent = Elements.ToggleName
            end

            Elements.ToggleButton = Instance.new("ImageButton")
            Elements.ToggleButton.Name = "ToggleButton"
            Elements.ToggleButton.Image = Assets.ToggleBackground
            Elements.ToggleButton.ImageColor3 = ToggleOffColor
            Elements.ToggleButton.AutoButtonColor = false
            Elements.ToggleButton.AnchorPoint = Vector2.new(1, 0.5)
            Elements.ToggleButton.BackgroundTransparency = 1
            Elements.ToggleButton.BorderSizePixel = 0
            Elements.ToggleButton.Position = UDim2.fromScale(1, 0.5)
            Elements.ToggleButton.Size = UDim2.fromOffset(41, 21)
            Elements.ToggleButton.ImageTransparency = 0.8
            Elements.ToggleButton:SetAttribute("NoApplyTheme", true)
            Elements.ToggleButton.Parent = Elements.Toggle

            local ToggleUIPadding = Instance.new("UIPadding")
            ToggleUIPadding.PaddingBottom = UDim.new(0, 1)
            ToggleUIPadding.PaddingLeft = UDim.new(0, -2)
            ToggleUIPadding.PaddingRight = UDim.new(0, 3)
            ToggleUIPadding.PaddingTop = UDim.new(0, 1)
            ToggleUIPadding.Parent = Elements.ToggleButton

            Elements.TogglerHead = Instance.new("ImageLabel")
            Elements.TogglerHead.Name = "TogglerHead"
            Elements.TogglerHead.Image = Assets.TogglerHead
            Elements.TogglerHead.ImageColor3 = Color3.fromRGB(255, 255, 255)
            Elements.TogglerHead.AnchorPoint = Vector2.new(1, 0.5)
            Elements.TogglerHead.BackgroundTransparency = 1
            Elements.TogglerHead.BorderSizePixel = 0
            Elements.TogglerHead.Position = UDim2.fromScale(0.5, 0.5)
            Elements.TogglerHead.Size = UDim2.fromOffset(15, 15)
            Elements.TogglerHead.ZIndex = 2
            Elements.TogglerHead.ImageTransparency = 0.8
            Elements.TogglerHead:SetAttribute("NoApplyTheme", true)
            Elements.TogglerHead.Parent = Elements.ToggleButton

            return Elements
        end

        local function CreateKeybind()
            local KeybindComponents = ComponentManager.CreateKeybindComponents({
                Ancestor = ToggleFunctions.Elements.Toggle,
                Class = ToggleFunctions.Class,
                Maid = ToggleFunctions.Maid,
                Functions = ToggleFunctions,
                Settings = Settings,
                Flag = Flag
            })

            if KeybindComponents then
                ToggleFunctions.Elements.KeybindButton = KeybindComponents.KeybindButton
                ToggleFunctions.Elements.KeybindLabel = KeybindComponents.KeybindLabel
            end
        end

        local function UpdateToggleState(State)
            local TransparencyValues = State and TRANSPARENCY.Enabled or TRANSPARENCY.Disabled
            local Position = State and POSITIONS.Enabled or POSITIONS.Disabled

            Utility:PropertyTween(ToggleFunctions.Elements.ToggleButton, TWEEN_INFO, {
                ImageTransparency = TransparencyValues.Toggle,
                ImageColor3 = State and ToggleOnColor or ToggleOffColor
            }):Play()

            Utility:PropertyTween(ToggleFunctions.Elements.TogglerHead, TWEEN_INFO, {
                ImageTransparency = TransparencyValues.Head,
                Position = Position,
                ImageColor3 = State and HeadOnColor or HeadOffColor
            }):Play()

            ToggleFunctions.State = State
        end

        local function ToggleTrigger()
            if Settings.Fixed or ToggleFunctions.IsHidden then return end

            ToggleFunctions.State = not ToggleFunctions.State
            UpdateToggleState(ToggleFunctions.State)

            if Settings.Callback then
                if Settings.ToggleOffActive then
                    for _, SignalToDisable in pairs(Settings.ToggleOffActive) do
                    end
                end
                Settings.Callback(ToggleFunctions.State)
            end
        end

        local function SetupConnections()
            ToggleFunctions.Maid.ToggleClick = ToggleFunctions.Elements.ToggleButton.MouseButton1Click:Connect(ToggleTrigger)

            if not Settings.PremiumFeature then
                ToggleFunctions.Maid.ToggleHover = ToggleFunctions.Elements.Toggle.MouseEnter:Connect(function()
                    if ToggleFunctions.IsHidden then return end
                    Utility:QuickTween(ToggleFunctions.Elements.Highlight, {BackgroundTransparency = 0.93})
                    Utility:QuickTween(ToggleFunctions.Elements.ToggleName, {TextTransparency = 0})
                end)

                ToggleFunctions.Maid.ToggleLeave = ToggleFunctions.Elements.Toggle.MouseLeave:Connect(function()
                    if ToggleFunctions.IsHidden then return end
                    Utility:QuickTween(ToggleFunctions.Elements.Highlight, {BackgroundTransparency = 1})
                    Utility:QuickTween(ToggleFunctions.Elements.ToggleName, {TextTransparency = 0.5})
                end)
            end
        end

        local function IsPlaceIdAllowed(PlaceIdSetting)
            if not PlaceIdSetting then return true end
            local CurrentPlaceId = game.PlaceId

            if type(PlaceIdSetting) == "table" then
                for _, PlaceId in pairs(PlaceIdSetting) do
                    if CurrentPlaceId == PlaceId then return true end
                end
                return false
            else
                return CurrentPlaceId == PlaceIdSetting
            end
        end

        local function IsPlaceIdForbidden(PlaceIdSetting)
            if not PlaceIdSetting then return false end
            local CurrentPlaceId = game.PlaceId

            if type(PlaceIdSetting) == "table" then
                for _, PlaceId in pairs(PlaceIdSetting) do
                    if CurrentPlaceId == PlaceId then return true end
                end
                return false
            else
                return CurrentPlaceId == PlaceIdSetting
            end
        end

        function ToggleFunctions:Toggle()
            ToggleTrigger()
        end

        function ToggleFunctions:ServerToggle()
            ToggleFunctions.State = not ToggleFunctions.State
            UpdateToggleState(ToggleFunctions.State)
            if Settings.Callback then
                Settings.Callback(ToggleFunctions.State)
            end
        end

        function ToggleFunctions:UpdateState(State, Callback)
            ToggleFunctions.State = State
            UpdateToggleState(ToggleFunctions.State)
            
            if Callback then
                if Settings.Callback then
                    Settings.Callback(ToggleFunctions.State)
                end
            end
        end

        function ToggleFunctions:GetState()
            return ToggleFunctions.State
        end

        function ToggleFunctions:ReturnHidden()
            return ToggleFunctions.IsHidden
        end

        function ToggleFunctions:ReturnSettings()
            return Settings
        end

        function ToggleFunctions:ReturnClass()
            return ToggleFunctions.Class
        end

        function ToggleFunctions:ReturnTab()
            return ToggleFunctions.Tab
        end

        function ToggleFunctions:UpdateName(Name)
            ToggleFunctions.Elements.ToggleName.Text = Name
        end

        function ToggleFunctions:SetToolTip(Tip)
            if ToggleFunctions.Elements.Toggle:FindFirstChild("ToolTipFrame") then
                ToggleFunctions.Elements.Toggle:FindFirstChild("ToolTipFrame"):Destroy()
            end

            if not Tip or Tip == "" then return end

            local ToolTipFrame = Instance.new("Frame")
            ToolTipFrame.Name = "ToolTipFrame"
            ToolTipFrame.BackgroundColor3 = Color3.fromRGB(18, 18, 18)
            ToolTipFrame.BackgroundTransparency = 1
            ToolTipFrame.BorderSizePixel = 0
            ToolTipFrame.AnchorPoint = Vector2.new(0.5, 1)
            ToolTipFrame.Position = UDim2.new(0.5, 0, 0, -5)
            ToolTipFrame.Visible = false
            ToolTipFrame.ZIndex = 200
            ToolTipFrame.Parent = ToggleFunctions.Elements.Toggle

            local TooltipCorner = Instance.new("UICorner")
            TooltipCorner.CornerRadius = UDim.new(0, 6)
            TooltipCorner.Parent = ToolTipFrame

            local TooltipStroke = Instance.new("UIStroke")
            TooltipStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
            TooltipStroke.LineJoinMode = Enum.LineJoinMode.Round
            TooltipStroke.Color = Color3.fromRGB(255, 255, 255)
            TooltipStroke.Thickness = 0.1
            TooltipStroke.Transparency = 0.2
            TooltipStroke.Parent = ToolTipFrame

            local TooltipText = Instance.new("TextLabel")
            TooltipText.Text = Tip
            TooltipText.FontFace = Font.new(Assets.InterFont)
            TooltipText.TextColor3 = Color3.fromRGB(200, 220, 200)
            TooltipText.TextSize = 12
            TooltipText.TextTransparency = 1
            TooltipText.BackgroundTransparency = 1
            TooltipText.TextXAlignment = Enum.TextXAlignment.Center
            TooltipText.TextYAlignment = Enum.TextYAlignment.Center
            TooltipText.Size = UDim2.new(1, -12, 1, 0)
            TooltipText.Position = UDim2.new(0, 6, 0, 0)
            TooltipText.Parent = ToolTipFrame

            local TextBounds = Services.TextService:GetTextSize(Tip, TooltipText.TextSize, Enum.Font.SourceSansBold, Vector2.new(math.huge, math.huge))
            local TooltipWidth = math.max(80, TextBounds.X + 50)
            local TooltipHeight = math.max(28, TextBounds.Y + 12)
            ToolTipFrame.Size = UDim2.new(0, TooltipWidth, 0, TooltipHeight)

            ToggleFunctions.Maid.TooltipShow = ToggleFunctions.Elements.ToggleButton.MouseEnter:Connect(function()
                ToolTipFrame.Visible = true
                Services.TweenService:Create(ToolTipFrame, TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {BackgroundTransparency = 0.1}):Play()
                Services.TweenService:Create(TooltipText, TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {TextTransparency = 0}):Play()
                Services.TweenService:Create(TooltipStroke, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Transparency = 0.8}):Play()
            end)

            ToggleFunctions.Maid.TooltipHide = ToggleFunctions.Elements.ToggleButton.MouseLeave:Connect(function()
                Services.TweenService:Create(ToolTipFrame, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {BackgroundTransparency = 1}):Play()
                Services.TweenService:Create(TooltipText, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {TextTransparency = 1}):Play()
                Services.TweenService:Create(TooltipStroke, TweenInfo.new(0.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Transparency = 1}):Play()
                task.wait(0.2)
                if ToolTipFrame and ToolTipFrame.Parent then
                    ToolTipFrame.Visible = false
                end
            end)
        end

        function ToggleFunctions:SetHidden(State, Reason)
            if Reason then
                self:SetToolTip(Reason)
            end

            ToggleFunctions.IsHidden = State
            ComponentManager.UpdateKeybindDetection(State, Flag, {
                KeybindButton = ToggleFunctions.Elements.KeybindButton,
                KeybindLabel = ToggleFunctions.Elements.KeybindLabel,
            })

            if State then
                Services.TweenService:Create(ToggleFunctions.Elements.ToggleButton, TweenInfo.new(0.2), {ImageTransparency = 0.9}):Play()

                if not Settings.PremiumFeature then
                    Services.TweenService:Create(ToggleFunctions.Elements.ToggleName, TweenInfo.new(0.2), {TextTransparency = 0.9}):Play()
                end

                if ToggleFunctions.Maid.ToggleClick then
                    ToggleFunctions.Maid.ToggleClick:Disconnect()
                    ToggleFunctions.Maid.ToggleClick = nil
                end
            else
                Services.TweenService:Create(ToggleFunctions.Elements.ToggleButton, TweenInfo.new(0.2), {ImageTransparency = 0.5}):Play()
                
                if not Settings.PremiumFeature then
                    Services.TweenService:Create(ToggleFunctions.Elements.ToggleName, TweenInfo.new(0.2), {TextTransparency = 0.5}):Play()
                end

                ToggleFunctions.Maid.ToggleClick = ToggleFunctions.Elements.ToggleButton.MouseButton1Click:Connect(ToggleTrigger)
            end
        end

        function ToggleFunctions:SetVisibility(State)
            ToggleFunctions.Elements.Toggle.Visible = State
        end

        function ToggleFunctions:Destroy()
            for ConnectionName, Connection in pairs(ToggleFunctions.Maid) do
                if type(Connection) == "userdata" and Connection.Disconnect then
                    Connection:Disconnect()
                end
            end
            
            table.clear(ToggleFunctions.Maid)

            if ToggleFunctions.Elements.Toggle then
                ToggleFunctions.Elements.Toggle:Destroy()
            end

            if Flag and WaveLibrary.Options[Flag] then
                WaveLibrary.Options[Flag] = nil
            end
        end

        ToggleFunctions.Elements = CreateElements()
        CreateKeybind()
        SetupConnections()
        UpdateToggleState(ToggleFunctions.State)

        if Settings.Hidden then
            if typeof(Settings.Hidden) == "table" then
                ToggleFunctions:SetHidden(Settings.Hidden[1], Settings.Hidden[2])
            else
                ToggleFunctions:SetHidden(Settings.Hidden)
            end
        end

        if Settings.Default == true and not Settings.IgnoreDefault and Settings.Callback then
            task.defer(function()
                Settings.Callback(Settings.Default)
            end)
        end

        if Settings.ToolTip then
            ToggleFunctions:SetToolTip(Settings.ToolTip)
        end

        if Settings.PremiumFeature and not Utility:IsPremiumHubUser() then
            ToggleFunctions:SetHidden(true, "Premium Feature")
        end

        if not IsPlaceIdAllowed(Settings.AllowedPlaceId) then
            ToggleFunctions:SetHidden(true, "Not in the right PlaceId to use this feature.")
        end

        if IsPlaceIdForbidden(Settings.ForbiddenPlaceId) then
            ToggleFunctions:SetHidden(true, "Not in the right PlaceId to use this feature.")
        end

        if Flag then
            WaveLibrary.Options[Flag] = ToggleFunctions
        end

        return ToggleFunctions
    end
end
end

R["Wave/UserInterface/Components/Viewport.lua"] = function(...)
return function(Requirements)
	local Section = Requirements.Section
	local WindowFunctions = Requirements.WindowFunctions
	local WaveLibrary = Requirements.WaveLibrary
	local SectionFunctions = Requirements.SectionFunctions

	local RunService = Services.RunService
	local UserInputService = Services.UserInputService

	local function ThemeAttr(Name, Fallback)
		local ok, value = pcall(function()
			return WindowFunctions:GetCurrentThemeAttribute(Name)
		end)
		if ok and value ~= nil then
			return value
		end
		return Fallback
	end

	function SectionFunctions:Viewport(Settings, Flag)
		Settings = Settings or {}

		local Height = Settings.Height or 200
		local HasTitle = Settings.Title ~= nil and Settings.Title ~= ""

		local ViewportFunctions = {
			Settings = Settings,
			Class = "Viewport",
			Tab = Requirements.TabName,
		}

		-- ---- visual container ---------------------------------------------
		local Holder = Instance.new("Frame")
		Holder.Name = "Viewport"
		Holder.BackgroundTransparency = 1
		Holder.AutomaticSize = Enum.AutomaticSize.Y
		Holder.Size = UDim2.new(1, 0, 0, 0)
		Holder.Parent = Section

		local HolderLayout = Instance.new("UIListLayout")
		HolderLayout.Padding = UDim.new(0, 8)
		HolderLayout.SortOrder = Enum.SortOrder.LayoutOrder
		HolderLayout.Parent = Holder

		if HasTitle then
			local HeaderText = Instance.new("TextLabel")
			HeaderText.Name = "HeaderText"
			HeaderText.FontFace = Font.new(Assets.InterFont, Enum.FontWeight.Medium, Enum.FontStyle.Normal)
			HeaderText.Text = Settings.Title
			HeaderText.RichText = true
			HeaderText.TextColor3 = ThemeAttr("HeaderColor", Color3.fromRGB(220, 220, 220))
			HeaderText.TextTransparency = ThemeAttr("HeaderTransparency", 0.3)
			HeaderText.TextSize = 15
			HeaderText.TextXAlignment = Enum.TextXAlignment.Left
			HeaderText.AutomaticSize = Enum.AutomaticSize.Y
			HeaderText.BackgroundTransparency = 1
			HeaderText.Size = UDim2.new(1, 0, 0, 0)
			HeaderText.Parent = Holder
		end

		local ViewportFrame = Instance.new("ViewportFrame")
		ViewportFrame.Name = "ViewportDisplay"
		ViewportFrame.Size = UDim2.new(1, 0, 0, Height)
		ViewportFrame.LayoutOrder = 1
		ViewportFrame.BackgroundColor3 = ThemeAttr("DropdownColor", Color3.fromRGB(20, 20, 26))
		ViewportFrame.BackgroundTransparency = 0.1
		ViewportFrame.BorderSizePixel = 0
		ViewportFrame.Ambient = Color3.fromRGB(170, 170, 180)
		ViewportFrame.LightColor = Color3.fromRGB(255, 255, 255)
		ViewportFrame.LightDirection = Vector3.new(-0.6, -1, -0.4)
		-- Active so the orbit drag is sunk here and never reaches the window's
		-- whole-window drag handler (otherwise rotating also moves the window).
		ViewportFrame.Active = true
		ViewportFrame.Parent = Holder
		ViewportFrame:SetAttribute("NoApplyTheme", true)

		local Corner = Instance.new("UICorner")
		Corner.CornerRadius = UDim.new(0, math.max(ThemeAttr("CornerRadius", 10) - 2, 4))
		Corner.Parent = ViewportFrame

		local Stroke = Instance.new("UIStroke")
		Stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		Stroke.Color = ThemeAttr("BorderColor", Color3.fromRGB(120, 120, 130))
		Stroke.Transparency = ThemeAttr("StrokeTransparency", 0.7)
		Stroke.Parent = ViewportFrame

		local Gradient = Instance.new("UIGradient")
		Gradient.Rotation = 90
		Gradient.Color = ColorSequence.new(Color3.fromRGB(255, 255, 255), Color3.fromRGB(205, 205, 215))
		Gradient.Parent = ViewportFrame

		-- subtle "drag to rotate" hint
		local Hint = Instance.new("TextLabel")
		Hint.Name = "Hint"
		Hint.AnchorPoint = Vector2.new(1, 1)
		Hint.Position = UDim2.new(1, -8, 1, -6)
		Hint.Size = UDim2.fromOffset(120, 14)
		Hint.BackgroundTransparency = 1
		Hint.Text = "drag to rotate"
		Hint.FontFace = Font.new(Assets.InterFont)
		Hint.TextColor3 = Color3.fromRGB(255, 255, 255)
		Hint.TextTransparency = 0.55
		Hint.TextSize = 11
		Hint.TextXAlignment = Enum.TextXAlignment.Right
		Hint.ZIndex = 5
		Hint.Parent = ViewportFrame

		local Camera = Instance.new("Camera")
		Camera.FieldOfView = 50
		Camera.Parent = ViewportFrame
		ViewportFrame.CurrentCamera = Camera

		-- ---- camera / model state -----------------------------------------
		local Connections = {}
		local CurrentModel
		local Target = Vector3.zero
		local Azimuth, Elevation, Distance = math.rad(35), math.rad(12), 12
		local BaseDistance = Distance
		local MinDistance, MaxDistance = 4, 40
		local Dragging, LastPosition = false, nil

		local function UpdateCamera()
			local x = math.cos(Elevation) * math.sin(Azimuth)
			local y = math.sin(Elevation)
			local z = math.cos(Elevation) * math.cos(Azimuth)
			local position = Target + Vector3.new(x, y, z) * Distance
			Camera.CFrame = CFrame.lookAt(position, Target)
		end

		local function SetModel(Model)
			if CurrentModel then
				CurrentModel:Destroy()
				CurrentModel = nil
			end

			if not Model then
				return
			end

			-- Player characters (and some models) are Archivable=false, which makes
			-- :Clone() return nil. Temporarily flip it on the whole tree, then restore.
			local ok, clone = pcall(function()
				local restore = {}
				if not Model.Archivable then
					Model.Archivable = true
					restore[#restore + 1] = Model
				end
				for _, descendant in ipairs(Model:GetDescendants()) do
					if not descendant.Archivable then
						descendant.Archivable = true
						restore[#restore + 1] = descendant
					end
				end
				local result = Model:Clone()
				for _, instance in ipairs(restore) do
					instance.Archivable = false
				end
				return result
			end)
			if not ok or not clone then
				return
			end

			for _, descendant in ipairs(clone:GetDescendants()) do
				if descendant:IsA("BasePart") then
					descendant.Anchored = true
					descendant.CanCollide = false
					descendant.CanQuery = false
					descendant.CanTouch = false
				elseif descendant:IsA("LuaSourceContainer") or descendant:IsA("ParticleEmitter") or descendant:IsA("Sound") then
					descendant:Destroy()
				end
			end

			clone.Parent = ViewportFrame
			CurrentModel = clone

			local center, size
			if clone:IsA("Model") then
				local okBox, cf, sz = pcall(function()
					return clone:GetBoundingBox()
				end)
				if okBox then
					center, size = cf.Position, sz
				end
			elseif clone:IsA("BasePart") then
				center, size = clone.Position, clone.Size
			end

			center = center or Vector3.zero
			size = size or Vector3.new(4, 4, 4)

			-- Recenter to origin so framing is stable no matter where the model
			-- lives in the world (characters sit far from 0,0,0).
			local offset = CFrame.new(-center)
			if clone:IsA("Model") then
				for _, part in ipairs(clone:GetDescendants()) do
					if part:IsA("BasePart") then
						part.CFrame = offset * part.CFrame
					end
				end
			elseif clone:IsA("BasePart") then
				clone.CFrame = offset * clone.CFrame
			end

			Target = Vector3.zero
			Distance = math.clamp(size.Magnitude * 1.4, 5, 1000)
			BaseDistance = Distance
			MinDistance = math.max(Distance * 0.35, 2)
			MaxDistance = Distance * 2.75
			Azimuth, Elevation = math.rad(35), math.rad(12)
			UpdateCamera()
		end

		-- The scrolling section we live in, so we can lock its scroll while the
		-- cursor is over the viewport (wheel = zoom the model, not scroll page).
		local ScrollAncestor
		do
			local parent = Holder.Parent
			while parent and parent ~= game do
				if parent:IsA("ScrollingFrame") then
					ScrollAncestor = parent
					break
				end
				parent = parent.Parent
			end
		end

		-- ---- interaction (mouse + touch orbit, scroll zoom) ----------------
		Connections.Began = ViewportFrame.InputBegan:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				Dragging = true
				LastPosition = input.Position
				WaveLibrary.ViewportCapturingDrag = true -- block window drag (covers touch)
			end
		end)

		-- Hovering a viewport blocks the whole-window drag (covers mouse) and
		-- locks the section scroll so the wheel only zooms the model.
		Connections.Enter = ViewportFrame.MouseEnter:Connect(function()
			WaveLibrary.ViewportHovering = true
			if ScrollAncestor then ScrollAncestor.ScrollingEnabled = false end
		end)
		Connections.Leave = ViewportFrame.MouseLeave:Connect(function()
			WaveLibrary.ViewportHovering = false
			if ScrollAncestor then ScrollAncestor.ScrollingEnabled = true end
		end)

		Connections.Changed = UserInputService.InputChanged:Connect(function(input)
			if Dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) and LastPosition then
				local delta = input.Position - LastPosition
				LastPosition = input.Position
				Azimuth = Azimuth - delta.X * 0.0075
				Elevation = math.clamp(Elevation + delta.Y * 0.0075, -1.45, 1.45)
				UpdateCamera()
			elseif input.UserInputType == Enum.UserInputType.MouseWheel then
				-- only zoom when the cursor is over the viewport
				local position, size = ViewportFrame.AbsolutePosition, ViewportFrame.AbsoluteSize
				local mouse = UserInputService:GetMouseLocation() - Vector2.new(0, 36)
				if mouse.X >= position.X and mouse.X <= position.X + size.X and mouse.Y >= position.Y and mouse.Y <= position.Y + size.Y then
					Distance = math.clamp(Distance - input.Position.Z * (Distance * 0.12), MinDistance, MaxDistance)
					UpdateCamera()
				end
			end
		end)

		Connections.Ended = UserInputService.InputEnded:Connect(function(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
				Dragging = false
				WaveLibrary.ViewportCapturingDrag = false
			end
		end)

		-- ---- culling: only render when actually on-screen ------------------
		local function IsOnScreen()
			if not Holder.Visible or Holder.Parent == nil then
				return false
			end

			local okState, state = pcall(function()
				return WindowFunctions:GetState()
			end)
			if okState and state == false then
				return false
			end

			local position, size = ViewportFrame.AbsolutePosition, ViewportFrame.AbsoluteSize
			if size.X <= 1 or size.Y <= 1 then
				return false
			end

			if ScrollAncestor then
				local sp, ss = ScrollAncestor.AbsolutePosition, ScrollAncestor.AbsoluteSize
				if position.X + size.X < sp.X or position.X > sp.X + ss.X
					or position.Y + size.Y < sp.Y or position.Y > sp.Y + ss.Y then
					return false
				end
			end

			return true
		end

		local OnScreen = true
		local Accumulator = 0
		Connections.Render = RunService.Heartbeat:Connect(function(dt)
			if WaveLibrary.Unloaded then
				ViewportFunctions:Destroy()
				return
			end

			Accumulator = Accumulator + dt
			if Accumulator >= 0.15 then
				Accumulator = 0
				local onScreen = IsOnScreen()
				if OnScreen ~= onScreen then
					OnScreen = onScreen
					-- Optimisation: keep the frame itself visible and just drop
					-- the camera so the 3D scene stops rendering off-screen,
					-- instead of hiding the whole viewport (which made it pop).
					ViewportFrame.CurrentCamera = onScreen and Camera or nil
					if not onScreen then
						WaveLibrary.ViewportHovering = false -- can't be hovering it off-screen
						if ScrollAncestor then ScrollAncestor.ScrollingEnabled = true end
					end
				end
			end

			-- only spend per-frame time when actually drawn
			if OnScreen and Settings.AutoRotate and not Dragging then
				Azimuth = Azimuth + dt * (Settings.RotateSpeed or 0.5)
				UpdateCamera()
			end
		end)

		Connections.Ancestry = Holder.AncestryChanged:Connect(function()
			if Holder.Parent == nil then
				ViewportFunctions:Destroy()
			end
		end)

		-- ---- public API ----------------------------------------------------
		function ViewportFunctions:SetModel(Model)
			SetModel(Model)
			return self
		end

		function ViewportFunctions:Clear()
			SetModel(nil)
			return self
		end

		function ViewportFunctions:GetModel()
			return CurrentModel
		end

		function ViewportFunctions:GetCamera()
			return Camera
		end

		function ViewportFunctions:SetCamera(NewCamera)
			if typeof(NewCamera) == "Instance" and NewCamera:IsA("Camera") then
				NewCamera.Parent = ViewportFrame
				ViewportFrame.CurrentCamera = NewCamera
				Camera = NewCamera
			elseif typeof(NewCamera) == "CFrame" then
				Camera.CFrame = NewCamera
			end
			return self
		end

		function ViewportFunctions:SetAutoRotate(State)
			Settings.AutoRotate = State and true or false
			return self
		end

		function ViewportFunctions:ResetView()
			Azimuth, Elevation, Distance = math.rad(35), math.rad(12), BaseDistance
			UpdateCamera()
			return self
		end

		function ViewportFunctions:SetVisibility(State)
			Holder.Visible = State
			return self
		end

		function ViewportFunctions:ReturnClass()
			return "Viewport"
		end

		function ViewportFunctions:ReturnTab()
			return Requirements.TabName
		end

		function ViewportFunctions:Destroy()
			WaveLibrary.ViewportHovering = false
			WaveLibrary.ViewportCapturingDrag = false
			if ScrollAncestor then ScrollAncestor.ScrollingEnabled = true end
			for _, connection in pairs(Connections) do
				if typeof(connection) == "RBXScriptConnection" then
					connection:Disconnect()
				end
			end
			table.clear(Connections)
			if CurrentModel then
				CurrentModel:Destroy()
				CurrentModel = nil
			end
			if Holder then
				Holder:Destroy()
			end
		end

		UpdateCamera()
		if Settings.Model or Settings.Object then
			SetModel(Settings.Model or Settings.Object)
		end

		if Flag then
			WaveLibrary.Options[Flag] = ViewportFunctions
		end

		return ViewportFunctions
	end
end
end

-- GUI-only: unrelated ContentProvider interception module excluded.

R["Wave/UserInterface/Imports/Icons.lua"] = function(...)
local icons_1 = 'rbxassetid://124334518624683'
