local M = {
	SetIcon = function(self, Image, IconName)
		local IconData = self[IconName]

		if typeof(IconData) ~= 'table' then
			local nearestName = nil
			local nearestDistance = math.huge
	
			for name, value in next, self do
					if typeof(value) ~= "table" or math.abs(#name - #IconName) > 2 then continue end

				local s, t = name, IconName
				local m, n = #s, #t
				local d = {}
	
				for i = 0, m do
					d[i] = {}
					d[i][0] = i
				end
	
				for j = 0, n do
					d[0][j] = j
				end
	
				for i = 1, m do
					for j = 1, n do
						local cost = (s:sub(i, i) == t:sub(j, j)) and 0 or 1
						d[i][j] = math.min(d[i-1][j] + 1, d[i][j-1] + 1, d[i-1][j-1] + cost)
					end
				end
	
				local distance = d[m][n]

				if distance < nearestDistance then
					nearestDistance = distance
					nearestName = name
				end
			end
	
			if nearestName then
				IconData = self[nearestName]
				if typeof(IconData) ~= 'table' then
					return error(debug.traceback(`Argument #2 '{IconName}' is not a valid Icon. Did you mean '{nearestName}'?`))
				end
			else
				return error(debug.traceback(`Argument #2 '{IconName}' is not a valid Icon. No similar names found.`))
			end
		end

		-- Icon sprite atlases load from their ORIGINAL rbxassetid (crisp). They are NOT in
		-- BAC's flagged list (window buttons/acrylic/scrollbar/colorpicker localise separately
		-- via Creator.SafeImage); the thumbnail API caps at 700px so it cannot reproduce a
		-- 1024px atlas without blurring every 64px icon to mush (the removed localiseSheet path).
		Image.ImageRectSize = IconData.ImageRectSize
		Image.ImageRectOffset = IconData.ImageRectOffset
		Image.Image = IconData.Image

		return nil
	end,
	['Close'] = "rbxassetid://9886659671",
	['Min'] = "rbxassetid://9886659276",
	['Max'] = "rbxassetid://9886659406",
	['Restore'] = "rbxassetid://9886659001",
}
