R["Wave/UserInterface/Imports/ServerBrowser/ServerBrowserModule.lua"] = function(...)
-- Server browser: a slide-out panel (mirrors the Terminal's pattern) that lists
-- joinable servers as cards (image + title + description + Join button), with a
-- refresh button in the header. Driven by the script through WindowFunctions.
local ServerBrowser = {}
ServerBrowser.__index = ServerBrowser

local C = {
	Width = 0.375, -- match the terminal's default width
	IconSize = 15,
	HeaderTextSize = 18,
	HeaderHeight = 56,
	CardHeight = 96,
	CardPad = 12,
	ImageSize = 72,
}

local function Attr(WindowFunctions, Name, Fallback)
	local ok, v = pcall(function()
		return WindowFunctions:GetCurrentThemeAttribute(Name)
	end)
	if ok and v ~= nil then
		return v
	end
	return Fallback
end

local function GetIconSheet()
	local sheet = getgenv().__WaveIconSheet
	if sheet == nil then
		local ok, s = pcall(function()
			return Utility:LoadFile("Wave/UserInterface/Imports/Icons.lua")
		end)
		sheet = (ok and type(s) == "table") and s or false
		getgenv().__WaveIconSheet = sheet
	end
	return sheet or nil
end

local function SetLucide(self, Image, Name)
	if self.IconSheet then
		pcall(function()
			self.IconSheet:SetIcon(Image, Name)
		end)
	end
end

function ServerBrowser.new(Parent, TopbarFolder, WaveLibrary, WaveLibraryUI, WindowFunctions)
	local self = setmetatable({}, ServerBrowser)
	self.Parent = Parent
	self.WaveLibrary = WaveLibrary
	self.WaveLibraryUI = WaveLibraryUI
	self.WindowFunctions = WindowFunctions
	self.Cards = {}
	self.RefreshCallback = nil
	self.Open = false
	self.ToggleDebounce = false
	self.IconSheet = GetIconSheet()

	self:CreatePanel()
	self:CreateTopbarIcon(TopbarFolder)
	self:Theme()

	-- Hide cleanly with the window. The panel is a child of Base (so it follows Base.Visible), but its
	-- glow lives outside Base and would otherwise linger -- drop both the instant the window toggles
	-- off, and restore them to the panel's open/closed state when it comes back.
	pcall(function()
		self.Parent:GetPropertyChangedSignal("Visible"):Connect(function()
			local shown = self.Parent.Visible
			self.Panel.Visible = shown and self.Open or false
			if self.Shadow then
				self.Shadow.Visible = shown and self.Open or false
			end
		end)
	end)

	return self
end

function ServerBrowser:CreatePanel()
	local Panel = Instance.new("Frame")
	Panel.Name = "ServerBrowser"
	Panel.AnchorPoint = Vector2.new(0.5, 0.5)
	Panel.Size = UDim2.new(C.Width, 0, 1, 0)
	Panel.Position = UDim2.new(1, 0, 0.5, 0) -- tucked behind the window's right edge
	Panel.BackgroundColor3 = Color3.fromRGB(16, 16, 22)
	Panel.BackgroundTransparency = 0
	Panel.BorderSizePixel = 0
	Panel.ZIndex = -10 -- sit behind the main window
	Panel.Visible = false
	Panel.Parent = self.Parent
	self.Panel = Panel

	local Corner = Instance.new("UICorner")
	Corner.CornerRadius = UDim.new(0, 10)
	Corner.Parent = Panel

	local Stroke = Instance.new("UIStroke")
	Stroke.Name = "ServerStroke"
	Stroke.Color = Color3.fromRGB(255, 255, 255)
	Stroke.Transparency = 0.85
	Stroke.Thickness = 1
	Stroke.Parent = Panel
	self.Stroke = Stroke

	-- wavy wallpaper, same image the terminal / main window use (kept subtle, behind the content)
	local Wallpaper = Instance.new("ImageLabel")
	Wallpaper.Name = "ServerWallpaper"
	Wallpaper.Image = Assets.StyleOneWallpaper
	Wallpaper.Size = UDim2.new(1, 0, 1, 0)
	Wallpaper.Position = UDim2.new(0, 0, 0, 0)
	Wallpaper.BackgroundTransparency = 1
	Wallpaper.ImageTransparency = 0.65
	Wallpaper.ImageColor3 = Color3.fromRGB(32, 32, 32)
	Wallpaper.ScaleType = Enum.ScaleType.Crop
	Wallpaper.ZIndex = 0
	Wallpaper.Parent = Panel
	local WallCorner = Instance.new("UICorner")
	WallCorner.CornerRadius = UDim.new(0, 10)
	WallCorner.Parent = Wallpaper
	self.Wallpaper = Wallpaper

	-- same glow as the main window, theme-driven via WindowFunctions:ApplyShadows
	pcall(function()
		self.Shadow = self.WaveLibrary:CreateShadow({
			Object = self.WaveLibraryUI,
			ReplicateVisible = { self.Parent, Panel },
			ObjectReplication = Panel,
			Gradient = {
				Color = ColorSequence.new(Color3.new(0, 0, 0.2), Color3.new(0.4, 0.6, 1)),
			},
		})
	end)

	-- header: centered title (exactly like the terminal's "Terminal" label) + refresh (right)
	local Title = Instance.new("TextLabel")
	Title.Name = "ServerTitle"
	Title.FontFace = Font.new(Assets.InterFont, Enum.FontWeight.Bold)
	Title.RichText = true
	Title.Text = "Servers"
	Title.TextColor3 = Color3.fromRGB(220, 220, 220)
	Title.TextSize = C.HeaderTextSize
	Title.TextTransparency = 0.5
	Title.TextTruncate = Enum.TextTruncate.SplitWord
	Title.TextXAlignment = Enum.TextXAlignment.Center
	Title.TextYAlignment = Enum.TextYAlignment.Top
	Title.BackgroundTransparency = 1
	Title.AnchorPoint = Vector2.new(0, 0.5)
	Title.AutomaticSize = Enum.AutomaticSize.Y
	Title.Position = UDim2.fromScale(0.05, 0.05)
	Title.Size = UDim2.fromScale(0.9, 0)
	Title.ZIndex = 6
	Title.Parent = Panel
	self.TitleLabel = Title

	-- the little centered bar under the title, same as the terminal's
	local TitleBar = Instance.new("Frame")
	TitleBar.Name = "ServerTitleBar"
	TitleBar.AnchorPoint = Vector2.new(0.5, 0)
	TitleBar.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
	TitleBar.BackgroundTransparency = 0.9
	TitleBar.BorderSizePixel = 0
	TitleBar.Position = UDim2.new(0.5, 0, 0, 42.5)
	TitleBar.Size = UDim2.new(0, 48, 0, 1)
	TitleBar.ZIndex = 6
	TitleBar.Parent = Panel
	self.TitleBar = TitleBar

	local Refresh = Instance.new("ImageButton")
	Refresh.Name = "ServerRefresh"
	Refresh.AnchorPoint = Vector2.new(1, 0.5)
	Refresh.Position = UDim2.fromScale(0.935, 0.05) -- same spot as the terminal's bin icon
	Refresh.Size = UDim2.fromOffset(15, 15) -- same size as the terminal's bin icon
	Refresh.BackgroundTransparency = 1
	Refresh.ImageColor3 = Color3.fromRGB(210, 210, 220)
	Refresh.ImageTransparency = 0.25
	Refresh.ZIndex = 6
	Refresh.Parent = Panel
	SetLucide(self, Refresh, "refresh-cw")
	self.RefreshButton = Refresh

	local Divider = Instance.new("Frame")
	Divider.Name = "ServerDivider"
	Divider.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
	Divider.BackgroundTransparency = 0.9
	Divider.BorderSizePixel = 0
	Divider.Position = UDim2.new(0, 0, 0, 63)
	Divider.Size = UDim2.new(1, 0, 0, 1)
	Divider.ZIndex = 6
	Divider.Parent = Panel
	self.Divider = Divider

	-- scrolling list of cards
	local Scroll = Instance.new("ScrollingFrame")
	Scroll.Name = "ServerList"
	Scroll.Active = true
	Scroll.BackgroundTransparency = 1
	Scroll.BorderSizePixel = 0
	Scroll.Position = UDim2.new(0, 0, 0, 72)
	Scroll.Size = UDim2.new(1, 0, 1, -84)
	Scroll.CanvasSize = UDim2.new()
	Scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
	Scroll.ScrollBarThickness = 2
	Scroll.ScrollBarImageColor3 = Color3.fromRGB(255, 255, 255)
	Scroll.ScrollBarImageTransparency = 0.7
	Scroll.ScrollingDirection = Enum.ScrollingDirection.Y
	Scroll.ZIndex = 6
	Scroll.Parent = Panel
	self.Scroll = Scroll

	local SPad = Instance.new("UIPadding")
	SPad.PaddingLeft = UDim.new(0, 14)
	SPad.PaddingRight = UDim.new(0, 14)
	SPad.PaddingTop = UDim.new(0, 4)
	SPad.PaddingBottom = UDim.new(0, 12)
	SPad.Parent = Scroll

	local SList = Instance.new("UIListLayout")
	SList.FillDirection = Enum.FillDirection.Vertical
	SList.SortOrder = Enum.SortOrder.LayoutOrder
	SList.Padding = UDim.new(0, 10)
	SList.Parent = Scroll
	self.ListLayout = SList

	-- empty-state hint
	local Empty = Instance.new("TextLabel")
	Empty.Name = "ServerEmpty"
	Empty.FontFace = Font.new(Assets.InterFont, Enum.FontWeight.Medium)
	Empty.Text = "No servers yet — hit refresh."
	Empty.TextColor3 = Color3.fromRGB(150, 150, 165)
	Empty.TextSize = 13
	Empty.TextWrapped = true
	Empty.BackgroundTransparency = 1
	Empty.AnchorPoint = Vector2.new(0.5, 0)
	Empty.Position = UDim2.new(0.5, 0, 0, 28)
	Empty.Size = UDim2.new(1, -40, 0, 40)
	Empty.ZIndex = 6
	Empty.Parent = Panel
	self.EmptyLabel = Empty

	-- refresh hover + click
	Refresh.MouseEnter:Connect(function()
		Utility:QuickTween(Refresh, { ImageTransparency = 0 })
	end)
	Refresh.MouseLeave:Connect(function()
		Utility:QuickTween(Refresh, { ImageTransparency = 0.25 })
	end)
	Refresh.MouseButton1Click:Connect(function()
		self:DoRefresh()
	end)
end

function ServerBrowser:CreateTopbarIcon(TopbarFolder)
	local Icon = Instance.new("ImageButton")
	Icon.Name = "ServerIcon"
	Icon.AnchorPoint = Vector2.new(1, 0.5)
	Icon.BackgroundTransparency = 1
	Icon.ImageColor3 = Color3.fromRGB(255, 255, 255)
	Icon.ImageTransparency = 0.7
	Icon.Position = UDim2.fromScale(1, 0.5)
	Icon.Size = UDim2.fromOffset(C.IconSize, C.IconSize)
	Icon.LayoutOrder = -1 -- left of the terminal icon (which is 0) in the right-aligned topbar
	Icon.ZIndex = 5
	Icon.Parent = TopbarFolder
	SetLucide(self, Icon, "server")
	self.TopbarIcon = Icon

	Icon.MouseEnter:Connect(function()
		Utility:QuickTween(Icon, { ImageTransparency = 0 })
	end)
	Icon.MouseLeave:Connect(function()
		Utility:QuickTween(Icon, { ImageTransparency = self.Open and 0.15 or 0.7 })
	end)
	Icon.InputBegan:Connect(function(Input)
		if self.ToggleDebounce then
			return
		end
		if Input.UserInputType == Enum.UserInputType.MouseButton1 or Input.UserInputType == Enum.UserInputType.Touch then
			self.ToggleDebounce = true
			self:SetOpen(not self.Open)
			task.delay(0.3, function()
				self.ToggleDebounce = false
			end)
		end
	end)
end

function ServerBrowser:DoRefresh()
	-- spin the icon once
	pcall(function()
		Utility:PropertyTween(self.RefreshButton, TweenInfo.new(0.45, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Rotation = self.RefreshButton.Rotation - 360 }):Play()
	end)
	if type(self.RefreshCallback) == "function" then
		if self.WaveLibrary and self.WaveLibrary.SafeCallback then
			self.WaveLibrary:SafeCallback(self.RefreshCallback)
		else
			pcall(self.RefreshCallback)
		end
	end
end

function ServerBrowser:SetRefreshCallback(fn)
	self.RefreshCallback = fn
end

function ServerBrowser:SetTitle(text)
	if self.TitleLabel then
		self.TitleLabel.Text = tostring(text)
	end
end

function ServerBrowser:UpdateCount()
	if self.EmptyLabel then
		self.EmptyLabel.Visible = (#self.Cards == 0)
	end
end

function ServerBrowser:AddServer(opts)
	opts = opts or {}

	local Card = Instance.new("Frame")
	Card.Name = "ServerCard"
	Card.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
	Card.BackgroundTransparency = 0.965
	Card.BorderSizePixel = 0
	Card.Size = UDim2.new(1, 0, 0, C.CardHeight)
	Card.LayoutOrder = #self.Cards + 1
	Card.ZIndex = 7
	Card.Parent = self.Scroll

	local CardCorner = Instance.new("UICorner")
	CardCorner.CornerRadius = UDim.new(0, 8)
	CardCorner.Parent = Card

	local CardStroke = Instance.new("UIStroke")
	CardStroke.Name = "CardStroke"
	CardStroke.Color = Color3.fromRGB(255, 255, 255)
