	Image.Position = UDim2.new(0, C.CardPad, 0.5, 0)
	Image.Size = UDim2.fromOffset(C.ImageSize, C.ImageSize)
	Image.ScaleType = Enum.ScaleType.Crop
	Image.Image = opts.Image and tostring(opts.Image) or ""
	Image.ZIndex = 8
	Image.Parent = Card
	local ImageCorner = Instance.new("UICorner")
	ImageCorner.CornerRadius = UDim.new(0, 7)
	ImageCorner.Parent = Image

	local TextLeft = C.CardPad + C.ImageSize + 12

	local TitleL = Instance.new("TextLabel")
	TitleL.Name = "CardTitle"
	TitleL.FontFace = Font.new(Assets.InterFont, Enum.FontWeight.SemiBold)
	TitleL.Text = opts.Title and tostring(opts.Title) or "Server"
	TitleL.TextColor3 = Color3.fromRGB(240, 240, 245)
	TitleL.TextSize = 14
	TitleL.TextXAlignment = Enum.TextXAlignment.Left
	TitleL.TextYAlignment = Enum.TextYAlignment.Top
	TitleL.TextTruncate = Enum.TextTruncate.AtEnd
	TitleL.BackgroundTransparency = 1
	TitleL.Position = UDim2.new(0, TextLeft, 0, 14)
	TitleL.Size = UDim2.new(1, -(TextLeft + 14), 0, 18)
	TitleL.ZIndex = 8
	TitleL.Parent = Card

	local DescL = Instance.new("TextLabel")
	DescL.Name = "CardDescription"
	DescL.FontFace = Font.new(Assets.InterFont, Enum.FontWeight.Medium)
	DescL.Text = opts.Description and tostring(opts.Description) or ""
	DescL.TextColor3 = Color3.fromRGB(165, 165, 180)
	DescL.TextSize = 12
	DescL.TextXAlignment = Enum.TextXAlignment.Left
	DescL.TextYAlignment = Enum.TextYAlignment.Top
	DescL.TextWrapped = true
	DescL.TextTruncate = Enum.TextTruncate.AtEnd
	DescL.BackgroundTransparency = 1
	DescL.Position = UDim2.new(0, TextLeft, 0, 34)
	DescL.Size = UDim2.new(1, -(TextLeft + 14), 0, 30)
	DescL.ZIndex = 8
	DescL.Parent = Card

	-- Join button: styled exactly like a main-UI Button -- transparent with a faint hover wash, dim
	-- text that brightens on hover, and the standard action icon on the right.
	local hoverColor = Attr(self.WindowFunctions, "HoverColor", Color3.fromRGB(255, 255, 255))

	local Join = Instance.new("Frame")
	Join.Name = "CardJoin"
	Join.BackgroundTransparency = 1
	Join.AnchorPoint = Vector2.new(1, 1)
	Join.Position = UDim2.new(1, -12, 1, -12)
	Join.Size = UDim2.fromOffset(52, 26)
	Join.ZIndex = 9
	Join.Parent = Card

	local JoinBG = Instance.new("Frame") -- faint hover wash, same as the main-UI button
	JoinBG.Name = "ButtonBG"
	JoinBG.BackgroundColor3 = hoverColor
	JoinBG.BackgroundTransparency = 1
	JoinBG.BorderSizePixel = 0
	JoinBG.AnchorPoint = Vector2.new(0.5, 0.5)
	JoinBG.Position = UDim2.fromScale(0.5, 0.5)
	JoinBG.Size = UDim2.new(1, 14, 1, 4)
	JoinBG.ZIndex = 9
	JoinBG.Parent = Join
	local JoinBGCorner = Instance.new("UICorner")
	JoinBGCorner.CornerRadius = UDim.new(0, 8)
	JoinBGCorner.Parent = JoinBG

	local JoinInteract = Instance.new("TextButton")
	JoinInteract.Name = "CardJoinInteract"
	JoinInteract.FontFace = Font.new(Assets.InterFont)
	JoinInteract.RichText = true
	JoinInteract.Text = "Join"
	JoinInteract.TextColor3 = Color3.fromRGB(255, 255, 255)
	JoinInteract.TextSize = 13
	JoinInteract.TextTransparency = 0.5
	JoinInteract.TextXAlignment = Enum.TextXAlignment.Right
	JoinInteract.BackgroundTransparency = 1
	JoinInteract.Size = UDim2.fromScale(1, 1)
	JoinInteract.ZIndex = 10
	JoinInteract.Parent = Join
	local JoinInteractPad = Instance.new("UIPadding") -- keep "Join" snug just left of the arrow
	JoinInteractPad.PaddingRight = UDim.new(0, 23)
	JoinInteractPad.Parent = JoinInteract

	local JoinImage = Instance.new("ImageLabel")
	JoinImage.Name = "JoinImage"
	JoinImage.Image = Assets.ButtonImage
	JoinImage.ImageTransparency = 0.5
	JoinImage.AnchorPoint = Vector2.new(1, 0.5)
	JoinImage.BackgroundTransparency = 1
	JoinImage.BorderSizePixel = 0
	JoinImage.Position = UDim2.new(1, -3, 0.5, 0)
	JoinImage.Size = UDim2.fromOffset(15, 15)
	JoinImage.ZIndex = 10
	JoinImage.Parent = Join

	JoinInteract.MouseEnter:Connect(function()
		Utility:QuickTween(JoinBG, { BackgroundTransparency = 0.93 })
		Utility:QuickTween(JoinInteract, { TextTransparency = 0 })
		Utility:QuickTween(JoinImage, { ImageTransparency = 0 })
	end)
	JoinInteract.MouseLeave:Connect(function()
		Utility:QuickTween(JoinBG, { BackgroundTransparency = 1 })
		Utility:QuickTween(JoinInteract, { TextTransparency = 0.5 })
		Utility:QuickTween(JoinImage, { ImageTransparency = 0.5 })
	end)
	JoinInteract.MouseButton1Down:Connect(function()
		Utility:QuickTween(JoinBG, { BackgroundTransparency = 0.86 })
	end)
	JoinInteract.MouseButton1Up:Connect(function()
		Utility:QuickTween(JoinBG, { BackgroundTransparency = 0.93 })
	end)

	local Handle = {
		Instance = Card,
		Image = Image,
		Title = TitleL,
		Description = DescL,
		JoinButton = Join,
	}
	Handle.Callback = opts.Callback or opts.Join or opts.OnJoin

	JoinInteract.MouseButton1Click:Connect(function()
		if type(Handle.Callback) == "function" then
			if self.WaveLibrary and self.WaveLibrary.SafeCallback then
				self.WaveLibrary:SafeCallback(Handle.Callback, Handle)
			else
				pcall(Handle.Callback, Handle)
			end
		end
	end)

	function Handle:SetTitle(t)
		TitleL.Text = tostring(t)
		return self
	end
	function Handle:SetDescription(d)
		DescL.Text = tostring(d)
		return self
	end
	function Handle:SetImage(id)
		Image.Image = tostring(id)
		return self
	end
	function Handle:OnJoin(fn)
		Handle.Callback = fn
		return self
	end
	local browser = self
	function Handle:Remove()
		for i, c in ipairs(browser.Cards) do
			if c == Handle then
				table.remove(browser.Cards, i)
				break
			end
		end
		pcall(function()
			Card:Destroy()
		end)
		browser:UpdateCount()
	end
	Handle.Destroy = Handle.Remove

	table.insert(self.Cards, Handle)
	self:UpdateCount()
	self:ThemeCard(Handle)
	return Handle
end

function ServerBrowser:ClearServers()
	for _, c in ipairs(self.Cards) do
		pcall(function()
			c.Instance:Destroy()
		end)
	end
	self.Cards = {}
	self:UpdateCount()
end

function ServerBrowser:SetOpen(state)
	state = state and true or false
	self.Open = state

	if state then
		-- mutually exclusive with the terminal: close it when we open
		pcall(function()
			if self.WindowFunctions.Terminal and self.WindowFunctions.Terminal.ToggleOutputScreen then
				self.WindowFunctions.Terminal:ToggleOutputScreen(false, self.WindowFunctions)
			end
		end)
	end

	self.Panel.Visible = true
	local goalPos = state and UDim2.new(1.2, 0, 0.5, 0) or UDim2.new(1, 0, 0.5, 0)
	-- Open glides in; close snaps out fast so nothing lingers. Every background / image / stroke fades
	-- (not just text) -- otherwise the card image placeholders stay on screen as dark squares.
	local dur = state and 0.28 or 0.12
	local info = TweenInfo.new(dur, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
	local function fade(obj, props)
		Utility:PropertyTween(obj, info, props):Play()
	end

	fade(self.Panel, { Position = goalPos, BackgroundTransparency = state and 0 or 1 })
	if self.Stroke then
		fade(self.Stroke, { Transparency = state and 0.82 or 1 })
	end
	if self.Shadow then
		fade(self.Shadow, { ImageTransparency = state and (Attr(self.WindowFunctions, "ShadowTransparency", 0) or 0) or 1 })
	end
	if self.Wallpaper then
		fade(self.Wallpaper, { ImageTransparency = state and (Attr(self.WindowFunctions, "WallpaperTransparency", 0.65) or 0.65) or 1 })
	end
	if self.TopbarIcon then
		fade(self.TopbarIcon, { ImageTransparency = state and 0.15 or 0.7 })
	end

	for _, d in ipairs(self.Panel:GetDescendants()) do
		if d == self.Wallpaper then
			-- kept subtle (tweened above); don't let the generic pass force it fully opaque
		elseif d.Name == "ButtonBG" then
			fade(d, { BackgroundTransparency = 1 }) -- the join hover-wash idles invisible
		elseif d.Name == "CardImage" then
			fade(d, { ImageTransparency = state and 0 or 1, BackgroundTransparency = state and 0.35 or 1 })
		elseif d.Name == "ServerCard" then
			fade(d, { BackgroundTransparency = state and 0.965 or 1 })
		elseif d:IsA("UIStroke") then
			if d ~= self.Stroke then
				fade(d, { Transparency = state and 0.9 or 1 })
			end
		elseif d:IsA("Frame") and (d.Name == "ServerTitleBar" or d.Name == "ServerDivider") then
			-- the little bars (theme styling clobbers these, so re-assert on every toggle)
			fade(d, { BackgroundTransparency = state and 0.85 or 1 })
		elseif d.Name == "CardJoinInteract" then
			fade(d, { TextTransparency = state and 0.5 or 1 }) -- main-UI button text idles dim
		elseif d.Name == "JoinImage" then
			fade(d, { ImageTransparency = state and 0.5 or 1 })
		elseif d:IsA("TextLabel") or d:IsA("TextButton") then
			-- the title sits at 0.5 like the terminal's; everything else stays fully legible
			fade(d, { TextTransparency = state and (d.Name == "ServerTitle" and 0.5 or 0) or 1 })
		elseif d:IsA("ImageLabel") or d:IsA("ImageButton") then
			fade(d, { ImageTransparency = state and 0 or 1 })
		end
	end

	-- once closed, hide right after the quick fade so nothing peeks past the window's edge
	if not state then
		local panel = self.Panel
		task.delay(0.14, function()
			if not self.Open and panel then
				panel.Visible = false
			end
		end)
	end
end

-- theme the card to the current palette
function ServerBrowser:ThemeCard(card)
	local WF = self.WindowFunctions
	local border = Attr(WF, "BorderColor", Color3.fromRGB(255, 255, 255))
	local primary = Attr(WF, "TextPrimary", Color3.fromRGB(240, 240, 245))
	local secondary = Attr(WF, "TextSecondary", Color3.fromRGB(165, 165, 180))
	local hover = Attr(WF, "HoverColor", Color3.fromRGB(255, 255, 255))
	pcall(function()
		card.Title.TextColor3 = primary
		card.Description.TextColor3 = secondary
		local bg = card.JoinButton:FindFirstChild("ButtonBG")
		if bg then
			bg.BackgroundColor3 = hover
		end
		local cs = card.Instance:FindFirstChild("CardStroke")
		if cs then
			cs.Color = border
		end
	end)
end

function ServerBrowser:Theme()
	local WF = self.WindowFunctions
	local bg = Attr(WF, "Background", Color3.fromRGB(16, 16, 22))
	local primary = Attr(WF, "HeaderColor", Attr(WF, "TextPrimary", Color3.fromRGB(240, 240, 245)))
	local secondary = Attr(WF, "TextSecondary", Color3.fromRGB(170, 170, 185))
	local border = Attr(WF, "BorderColor", Color3.fromRGB(255, 255, 255))
	-- accent: try a few common names, else a sensible blue
	self.AccentColor = Attr(WF, "Accent", Attr(WF, "AccentColor", Attr(WF, "ElementBorderHighlight", Color3.fromRGB(86, 130, 255))))

	pcall(function()
		self.Panel.BackgroundColor3 = bg
		if self.Stroke then
			self.Stroke.Color = border
		end
		self.TitleLabel.TextColor3 = primary
		self.EmptyLabel.TextColor3 = secondary
		self.RefreshButton.ImageColor3 = secondary
		self.Divider.BackgroundColor3 = border
		self.Divider.BackgroundTransparency = self.Open and 0.85 or 1
		if self.TitleBar then
			self.TitleBar.BackgroundColor3 = border
			self.TitleBar.BackgroundTransparency = self.Open and 0.85 or 1
		end
		if self.Wallpaper then
			self.Wallpaper.ImageColor3 = bg:Lerp(Color3.fromRGB(255, 255, 255), 0.2)
		end
		if self.TopbarIcon then
			self.TopbarIcon.ImageColor3 = primary
		end
	end)
	for _, c in ipairs(self.Cards) do
		self:ThemeCard(c)
	end
end

return ServerBrowser
end

R["Wave/UserInterface/Imports/Settings/InsertConfigSection.lua"] = function(...)
return function(Requirements)
	local WindowFunctions = Requirements.WindowFunctions
	local WaveLibrary = Requirements.WaveLibrary
	local TabFunctions = Requirements.TabFunctions

	function TabFunctions:InsertConfigSection(Side)
		local ConfigSection = TabFunctions:Section({Side = Side})
		
		ConfigSection:Header({Name = "Configuration Settings"})

		local InputPath = nil
		local SelectedConfig = nil
		local AutoloadLabel = nil

		local function GetAutoloadPath()
			return WaveLibrary.Folder .. "/settings/" .. game.GameId .. "/autoload.txt"
		end

		local function ShowNotification(Description)
			WindowFunctions:Notify({
				Title = "Interface",
				Description = Description
			})
		end

		local function ShowErrorNotification(Message, ErrorDetails)
			ShowNotification(Message .. ", return error: " .. ErrorDetails)
		end

		local function RefreshConfigDropdown(ConfigSelection)
			ConfigSelection:ClearOptions()
			ConfigSelection:InsertOptions(WaveLibrary:RefreshConfigList())
		end

		local function UpdateAutoloadLabel(ConfigName)
			AutoloadLabel:UpdateName("Autoload config: " .. ConfigName)
		end

		local function InitializeAutoloadLabel()
			local AutoloadPath = GetAutoloadPath()
			if isfile(AutoloadPath) then
				local ConfigName = readfile(AutoloadPath)
				UpdateAutoloadLabel(ConfigName)
			end
		end

		ConfigSection:Input({
			Name = "Config Name",
			Placeholder = "Name",
			AcceptedCharacters = "All",
			Callback = function(Input)
				InputPath = Input
			end
		})

		local ConfigSelection = ConfigSection:Dropdown({
			Name = "Select Config",
			Multi = false,
			Required = false,
			Options = WaveLibrary:RefreshConfigList(),
			Callback = function(Value)
				SelectedConfig = Value
			end
		})

		ConfigSection:Button({
			Name = "Create Config",
			Callback = function()
				if not InputPath or string.gsub(InputPath, " ", "") == "" then
					ShowNotification("Config name cannot be empty.")
					return
				end

				local Success, ErrorMessage = WaveLibrary:SaveConfig(InputPath)
				if not Success then
					ShowErrorNotification("Unable to save config", ErrorMessage)
					return
				end

				ShowNotification(string.format("Created config %q", InputPath))
				RefreshConfigDropdown(ConfigSelection)
			end
		})

		ConfigSection:Button({
			Name = "Load Config",
			Callback = function()
				local Success, ErrorMessage = WaveLibrary:LoadConfig(ConfigSelection.Value)
				if not Success then
					ShowErrorNotification("Unable to load config", ErrorMessage)
					return
				end

				ShowNotification(string.format("Loaded config %q", ConfigSelection.Value))
			end
		})

		ConfigSection:Button({
			Name = "Overwrite Config",
			Callback = function()
				local Success, ErrorMessage = WaveLibrary:SaveConfig(ConfigSelection.Value)
				if not Success then
					ShowErrorNotification("Unable to overwrite config", ErrorMessage)
					return
				end

				ShowNotification(string.format("Overwrote config %q", ConfigSelection.Value))
			end
		})

		ConfigSection:Button({
			Name = "Delete Config",
			Callback = function()
				local Success, ErrorMessage = WaveLibrary:DeleteConfig(ConfigSelection.Value)
				if not Success then
					ShowErrorNotification("Unable to delete config", ErrorMessage)
					return
				end

				ShowNotification(string.format("Deleted config %q", ConfigSelection.Value))
				RefreshConfigDropdown(ConfigSelection)
			end
		})

		ConfigSection:Button({
			Name = "Delete All Configs",
			Callback = function()
				local Success, Message = WaveLibrary:DeleteAllConfigs()
				if not Success then
					ShowErrorNotification("Unable to delete all configs", Message)
					return
				end

				ShowNotification(Message)
				RefreshConfigDropdown(ConfigSelection)
			end
		})

		ConfigSection:Button({
			Name = "Refresh Config List",
			Callback = function()
				RefreshConfigDropdown(ConfigSelection)
			end
		})

		ConfigSection:Button({
			Name = "Set as autoload",
			Callback = function()
				local ConfigName = ConfigSelection.Value
				writefile(GetAutoloadPath(), ConfigName)
				UpdateAutoloadLabel(ConfigName)
				ShowNotification(string.format("Set %q as autoload", ConfigName))
			end
		})

		AutoloadLabel = ConfigSection:Label({Text = "Autoload config: None"})
		InitializeAutoloadLabel()
	end
end
end

R["Wave/UserInterface/Imports/Settings/InsertGeneralSettings.lua"] = function(...)
return function(Requirements)
	local WindowFunctions = Requirements.WindowFunctions
	local WaveLibrary = Requirements.WaveLibrary
	local TabFunctions = Requirements.TabFunctions

	function TabFunctions:InsertGeneralSettings(Side)
        local SettingsSection = TabFunctions:Section({Side = Side})
        
        local function GetKeybindPath()
            return WaveLibrary.Folder .. "/settings/startup/KeybindSaved.wave"
        end
        
        local function LoadSavedKeybind()
            local KeybindPath = GetKeybindPath()
            if isfile(KeybindPath) then
                local KeybindName = readfile(KeybindPath)
                return Enum.KeyCode[KeybindName]
            end
            return Enum.KeyCode.LeftAlt
        end
        
        local function ShowKeybindNotification(KeybindName)
            WindowFunctions:Notify({
                Title = WindowFunctions.Settings.Title,
                Description = "Successfully Binded Keybind to - " .. KeybindName,
                Lifetime = 3
            })
        end
        
        local SavedKeybind = LoadSavedKeybind()
        
        SettingsSection:Header({Name = "General Settings"})
        
        SettingsSection:Slider({
            Name = "Interface Scale",
            Default = 1,
            Minimum = 0.25,
            Maximum = 1.5,
            DisplayMethod = "Tenths",
            Callback = function(Value)
                WindowFunctions:SetScale(Value)
            end
        }, "Slider")
        
        SettingsSection:Keybind({
            Name = "Interface Keybind",
            Blacklist = false,
            Default = SavedKeybind,
            OnBinded = function(Bind)
                WindowFunctions:SetKeybind(Bind)
                ShowKeybindNotification(tostring(Bind.Name))
            end
        }, "Keybind")
    end
end
end

R["Wave/UserInterface/Imports/Settings/InsertThemeSettings.lua"] = function(...)
return function(Requirements)
	local WindowFunctions = Requirements.WindowFunctions
	local WaveLibraryUI = Requirements.WaveLibraryUI
	local WaveLibrary = Requirements.WaveLibrary
	local TabFunctions = Requirements.TabFunctions
	local ThemeColorSchemes = Requirements.ThemeColorSchemes
	local ThemeTemplates = Requirements.ThemeTemplates
	local PerformanceModes = Requirements.PerformanceModes
	local ThemeUtility = Requirements.ThemeUtility
	local Themes = Requirements.Themes

    local Subtitle = Requirements.Subtitle
    local Exit = Requirements.Exit
	local Minimize = Requirements.Minimize

	local function GetThemeFilePath()
		return WaveLibrary.Folder .. "/settings/startup/ThemeSaved.wave"
	end

	local function GetThemeFolderPath()
		return WaveLibrary.Folder .. "/settings/themes"
	end

	local function GetBackupFolderPath()
		return GetThemeFolderPath() .. "/backups"
	end

	local function EnsureFolderExists(Path)
		if not isfolder(Path) then
			makefolder(Path)
		end
	end

	local function EnsureThemeFoldersExist()
		EnsureFolderExists(WaveLibrary.Folder .. "/settings")
		EnsureFolderExists(WaveLibrary.Folder .. "/settings/startup")
		EnsureFolderExists(GetThemeFolderPath())
	end

	function WindowFunctions:GetThemeNames()
		local Names = {}
		for ThemeName, _ in pairs(Themes) do
			table.insert(Names, ThemeName)
		end
		return Names
	end

	function WindowFunctions:GetTheme(ThemeName)
		if ThemeName == "Glass" then
			ThemeName = "Cherry" -- the Glass theme mirrors Cherry
		end
		return Themes[ThemeName] or Themes.Default
	end

	function WindowFunctions:GetCurrentTheme()
		return CurrentTheme
	end

	function WindowFunctions:GetThemeAttribute(ThemeName, Attribute)
		return self:GetTheme(ThemeName)[Attribute]
	end

	function WindowFunctions:GetCurrentThemeAttribute(Attribute)
		return self:GetTheme(self:GetCurrentTheme())[Attribute]
	end

	function WindowFunctions:CreateCustomTheme(ThemeSettings)
		if not ThemeSettings then
			return false
		end

		for Key, Value in pairs(Themes.Default) do
			if ThemeSettings[Key] == nil then
				ThemeSettings[Key] = Value
			end
		end

		Themes.Custom = ThemeSettings

		if CurrentTheme == "Custom" then
			self:ApplyTheme("Custom")
		end

		return true
	end

	function WindowFunctions:ExportTheme(ThemeName)
		local Theme = Themes[ThemeName] or Themes.Custom
		return Services.HttpService:JSONEncode(Theme)
	end

	function WindowFunctions:ImportTheme(ThemeData, ThemeName)
		local Success, DecodedTheme = pcall(Services.HttpService.JSONDecode, Services.HttpService, ThemeData)

		if not Success then
			return false, "Invalid JSON format"
		end

		if not DecodedTheme.Background or not DecodedTheme.TextPrimary then
			return false, "Invalid theme structure"
		end

		ThemeName = ThemeName or "Custom"
		Themes[ThemeName] = DecodedTheme

		return true, "Theme imported successfully"
	end

	function WindowFunctions:GenerateColorScheme(SchemeType, BaseColor)
		if not ThemeColorSchemes[SchemeType] then
			return false
		end

		local NewColors = ThemeColorSchemes[SchemeType](BaseColor)

		for ColorName, ColorValue in pairs(NewColors) do
			if Themes.Custom[ColorName] then
				Themes.Custom[ColorName] = ColorValue
			end
		end

		return true
	end

	function WindowFunctions:ApplyTemplate(TemplateName)
		local Template = ThemeTemplates[TemplateName]
		if not Template then
			return false
		end

		for Property, Value in pairs(Template) do
			Themes.Custom[Property] = Value
		end

		return true
	end

	function WindowFunctions:SetPerformanceMode(ModeName)
		local Mode = PerformanceModes[ModeName]
		if not Mode then
			return false
		end

		for Setting, Value in pairs(Mode) do
			Themes.Custom[Setting] = Value
		end

		return true
	end

	function WindowFunctions:GenerateRandomTheme()
		local function RandomColor()
			return Color3.fromRGB(math.random(0, 255), math.random(0, 255), math.random(0, 255))
		end

		local function RandomBool()
			return math.random() > 0.5
		end

		Themes.Custom.Background = RandomColor()
		Themes.Custom.Foreground = RandomColor()
		Themes.Custom.AccentPrimary = RandomColor()
		Themes.Custom.AccentSecondary = RandomColor()
		Themes.Custom.TextPrimary = RandomColor()
		Themes.Custom.CornerRadius = math.random(0, 25)
		Themes.Custom.ShadowSize = math.random(0, 50)
		Themes.Custom.GlowSize = math.random(0, 30)
		Themes.Custom.AnimationSpeed = math.random(10, 50) / 100
		Themes.Custom.GradientEnabled = RandomBool()

		return true
	end

	function WindowFunctions:ApplyUICorners(Parent, CornerRadius)
		for _, Child in ipairs(Parent:GetDescendants()) do
			if Child:IsA("UICorner") and not Child:FindFirstAncestor("CustomElementPanel") and not Child:FindFirstAncestor("CheckBoxButton") then
				Child.CornerRadius = UDim.new(0, CornerRadius)
			end
		end
	end

	function WindowFunctions:ApplyUIStrokes(Parent, Theme)
		for _, Child in ipairs(Parent:GetDescendants()) do
			if Child:IsA("UIStroke") and Child.Name ~= "TabSwitcherUIStroke" and Child.Name ~= "MainFrameStroke" and Child.Name ~= "NameStroke" and not Child:FindFirstAncestor("CustomElementPanel") then
				Child.Color = Theme.BorderColor
				if not Child:FindFirstAncestor("CheckBoxButton") then
					Child.Transparency = Theme.StrokeTransparency
				end
				
				Child.Thickness = Theme.StrokeThickness
			end
		end
	end

	function WindowFunctions:ApplyScrollbarStyling(Parent, Theme)
		for _, Child in ipairs(Parent:GetDescendants()) do
			if Child:IsA("ScrollingFrame") and not Child:FindFirstAncestor("CustomElementPanel") then
				Child.ScrollBarImageColor3 = Theme.ScrollbarColor
				Child.ScrollBarImageTransparency = Theme.ScrollbarTransparency
			end
		end
	end

	function WindowFunctions:ApplyTextStyling(Parent, Theme)
		for _, Child in ipairs(Parent:GetDescendants()) do
			if Child:FindFirstAncestor("CustomElementPanel") then
				continue
			end

			if Child:GetAttribute("NoApplyTheme") then
				continue
			end

			if Child:IsA("TextLabel") or Child:IsA("TextButton") or Child:IsA("TextBox") then
				if Child.Name == "Title" or Child.Name == "ParagraphHeader" or Child.Name == "HeaderText" then
					Child.TextColor3 = Theme.HeaderColor
					Child.TextTransparency = Theme.HeaderTransparency
				elseif Child:IsA("TextBox") then
					Child.TextColor3 = Theme.InputFieldColor

					if Child.Name ~= "HeaderInputSearchBox" and Child.Name ~= "SearchBox" then
						Child.BackgroundTransparency = Theme.InputValueBackground or Theme.InputFieldTransparency
					end

					if Child.BackgroundTransparency < 1 then
						Child.BackgroundColor3 = Theme.Foreground
					end

					if Child.PlaceholderText and Child.PlaceholderText ~= "" then
						Child.PlaceholderColor3 = Theme.TextSecondary
					end
				else
					if not Child.Name:find("Result_") then
						Child.TextColor3 = Theme.TextPrimary
					end
				end
			end
		end
	end

	function WindowFunctions:ApplyImageStyling(Parent, Theme)
		local ExcludedNames = {"Wallpaper", "OutputWallpaper", "InformationWallpaper", "ColorWheel", "Toggle", "ToggleButton", "ToggleHead", "TogglerHead", "Banner", "Headshot", "LinkIcon", "InfoIcon"}
		
		for _, Child in ipairs(Parent:GetDescendants()) do
			if Child:FindFirstAncestor("CustomElementPanel") then
				continue
			end

			if Child:IsA("ImageLabel") or Child:IsA("ImageButton") then
				local IsExcluded = false

				for _, ExcludedName in ipairs(ExcludedNames) do
					if Child.Name == ExcludedName then
						IsExcluded = true
						break
					end
				end

				if not IsExcluded then
					Child.ImageColor3 = Theme.TextSecondary
				end
			end
		end
	end

	function WindowFunctions:ApplyComponentStyling(Parent, Theme)
		local ComponentStyles = {
			Toggle = Theme.ToggleColor,
			CheckBoxButton = Theme.AccentPrimary,
			TogglerHead = Theme.TogglerHeadColor,
			SliderBar = Theme.SliderColor,
			RangeBar = Theme.SliderColor,
			SliderHead = Theme.SliderHeadColor,
			Dropdown = Theme.DropdownColor,
			Option = Theme.DropdownColor,
			Button = Theme.ButtonColor,
			InformationGroupHighlight = Theme.AccentPrimary,
			TabSwitcherIndicator = Theme.AccentPrimary,

			Sidebar = function(Child)
				Child.BackgroundTransparency = Theme.SidebarTransparency
				Child.BackgroundColor3 = Theme.SidebarColor
			end,

			Surface = function(Child)
				Child.BackgroundColor3 = Theme.Surface
				Child.BackgroundTransparency = Theme.SurfaceTransparency
			end,

			Section = Theme.Foreground,
			Notification = Theme.NotificationColor,
			ExternalStatus = Theme.StatusColor,
		}

		for _, Child in ipairs(Parent:GetDescendants()) do
			if Child:IsA("GuiObject") and not Child:IsA("ScrollingFrame") and Child.BackgroundTransparency < 1 and not Child:FindFirstAncestor("CustomElementPanel") then
				local Style = ComponentStyles[Child.Name]
				
				if Style then
					if type(Style) == "function" then
						Style(Child)
					elseif Child:IsA("ImageButton") and (Child.Name == "Toggle" or Child.Name == "TogglerHead" or Child.Name == "SliderBar" or Child.Name == "SliderHead") and not Child:FindFirstAncestor("CustomElementPanel") then
						Child.ImageColor3 = Style
					else
						Child.BackgroundColor3 = Style
					end
				end
			end
		end
	end

	function WindowFunctions:ApplyGradients(Parent, Theme)
		if not Theme.GradientEnabled then
			return
		end

		for _, Child in ipairs(Parent:GetDescendants()) do
			if Child.Name == "Background" and Child:IsA("GuiObject") and not Child:FindFirstAncestor("CustomElementPanel") then
				local Gradient = Child:FindFirstChild("UIGradient")
				if not Gradient then
					Gradient = Instance.new("UIGradient")
					Gradient.Parent = Child
				end

				Gradient.Color = ColorSequence.new(Theme.GradientColors)
				Gradient.Rotation = Theme.GradientRotation
			end
		end
	end

	function WindowFunctions:ApplyWallpaper(Base, Theme)
		local function ApplyWallpaperToElement(Element)
			if Element then
				Element.ImageColor3 = Theme.Background:Lerp(Color3.fromRGB(255, 255, 255), 0.2)
				Element.ImageTransparency = Theme.WallpaperEnabled and Theme.WallpaperTransparency or 1
			end
		end

		ApplyWallpaperToElement(Base:FindFirstChild("Wallpaper"))
		
		local Terminal = Base:FindFirstChild("Terminal")
		if Terminal then
			ApplyWallpaperToElement(Terminal:FindFirstChild("OutputWallpaper"))
		end
	end

	function WindowFunctions:ApplyShadows(Theme)
		if not Maid.Shadows then
			return
		end

		for _, Shadow in pairs(Maid.Shadows) do
			Shadow.ImageTransparency = Theme.ShadowTransparency
		end
	end

	function WindowFunctions:ApplyShadowGradients(Theme)
		if not Maid.Shadows then
			return
		end

		for _, Shadow in pairs(Maid.Shadows) do
			if Shadow and typeof(Theme.GlowColor) == "ColorSequence" then
				local ShadowGradient = Shadow:FindFirstChildWhichIsA("UIGradient") or Instance.new("UIGradient")
				ShadowGradient.Color = Theme.GlowColor
				ShadowGradient.Parent = Shadow
				Shadow.ImageColor3 = Color3.fromRGB(255, 255, 255)
			elseif Shadow then
				if Shadow:FindFirstChildWhichIsA("UIGradient") then
					Shadow:FindFirstChildWhichIsA("UIGradient"):Destroy()
				end
				Shadow.ImageColor3 = Theme.GlowColor
			end
		end
	end

	function WindowFunctions:ApplyPremiumGradients(Content, Theme)
		if not Content then
			return
		end

		for _, Element in pairs(Content:GetDescendants()) do
			if Element:IsA("UIGradient") and Element.Parent.Name ~= "Execute" and not Element:FindFirstAncestor("CustomElementPanel") then
				Element.Color = Theme.PremiumGradientColor
			end
		end
	end

	function WindowFunctions:ApplyControlButtons(Theme)
		if not Exit or not Minimize then
			return
		end

		Exit.BackgroundColor3 = Theme.ExitColor
		Minimize.BackgroundColor3 = Theme.MinimizeColor
	end

	function WindowFunctions:ApplyMenuGameCards(GameCardFolder, Theme)
		if not GameCardFolder then
			return
		end

		for _, Card in pairs(GameCardFolder:GetChildren()) do
			if not Card:IsA("GuiObject") then
				continue
			end

			local GlowFrame = Card:FindFirstChild("GlowFrame")
			if GlowFrame then
				GlowFrame.BackgroundColor3 = Theme.MinimizeColor
			end
		end
	end

	function WindowFunctions:AlreadyExistantTheme()
		local ThemeFile = GetThemeFilePath()
		if isfile(ThemeFile) then
			return readfile(ThemeFile)
		end
		return false
	end

	-- One-walk replacement for the chain of ApplyUICorners + ApplyUIStrokes +
	-- ApplyScrollbarStyling + ApplyTextStyling + ApplyImageStyling +
	-- ApplyComponentStyling + ApplyGradients on the same Base. Each of those
	-- did a fresh Base:GetDescendants() and a FindFirstAncestor per element;
	-- this folds them into one pass with a single ancestor check per element.
	-- The standalone Apply* methods are kept for callers that re-style a
	-- single subtree after the fact (e.g. dynamically added components).
	function WindowFunctions:ApplyDescendantStyling(Base, Theme)
		local CornerUDim = UDim.new(0, Theme.CornerRadius)
		local GradientEnabled = Theme.GradientEnabled
		local GradientColors = Theme.GradientColors
		local GradientRotation = Theme.GradientRotation

		local ExcludedImageNames = {
			Wallpaper = true, OutputWallpaper = true, InformationWallpaper = true,
			ColorWheel = true, Toggle = true, ToggleButton = true, ToggleHead = true,
			TogglerHead = true, Banner = true, Headshot = true, LinkIcon = true, InfoIcon = true,
		}
		local ExcludedStrokeNames = {
			TabSwitcherUIStroke = true, MainFrameStroke = true, NameStroke = true,
		}
		local ToggleImageNames = {
			Toggle = true, TogglerHead = true, SliderBar = true, SliderHead = true,
		}
		local ComponentStyles = {
			Toggle = Theme.ToggleColor,
			CheckBoxButton = Theme.AccentPrimary,
			TogglerHead = Theme.TogglerHeadColor,
			SliderBar = Theme.SliderColor,
			RangeBar = Theme.SliderColor,
			SliderHead = Theme.SliderHeadColor,
			Dropdown = Theme.DropdownColor,
			Option = Theme.DropdownColor,
			Button = Theme.ButtonColor,
			InformationGroupHighlight = Theme.AccentPrimary,
			TabSwitcherIndicator = Theme.AccentPrimary,
			Sidebar = function(c)
				c.BackgroundTransparency = Theme.SidebarTransparency
				c.BackgroundColor3 = Theme.SidebarColor
			end,
			Surface = function(c)
				c.BackgroundColor3 = Theme.Surface
				c.BackgroundTransparency = Theme.SurfaceTransparency
			end,
			Section = Theme.Foreground,
			Notification = Theme.NotificationColor,
			ExternalStatus = Theme.StatusColor,
		}

		for _, Child in ipairs(Base:GetDescendants()) do
			-- ONE ancestor check covers every handler below.
			if Child:FindFirstAncestor("CustomElementPanel") then continue end

			local cn = Child.ClassName
			local name = Child.Name

			if cn == "UICorner" then
				if not Child:FindFirstAncestor("CheckBoxButton") then
					Child.CornerRadius = CornerUDim
				end
			elseif cn == "UIStroke" then
				if not ExcludedStrokeNames[name] then
					Child.Color = Theme.BorderColor
					if not Child:FindFirstAncestor("CheckBoxButton") then
						Child.Transparency = Theme.StrokeTransparency
					end
					Child.Thickness = Theme.StrokeThickness
				end
			elseif cn == "ScrollingFrame" then
				Child.ScrollBarImageColor3 = Theme.ScrollbarColor
				Child.ScrollBarImageTransparency = Theme.ScrollbarTransparency
				-- ScrollingFrame is also a GuiObject but original ApplyComponentStyling skipped it.
			else
				-- Text styling
				local isTextClass = (cn == "TextLabel" or cn == "TextButton" or cn == "TextBox")
				if isTextClass and not Child:GetAttribute("NoApplyTheme") then
					if name == "Title" or name == "ParagraphHeader" or name == "HeaderText" then
						Child.TextColor3 = Theme.HeaderColor
						Child.TextTransparency = Theme.HeaderTransparency
					elseif cn == "TextBox" then
						Child.TextColor3 = Theme.InputFieldColor
						if name ~= "HeaderInputSearchBox" and name ~= "SearchBox" then
							Child.BackgroundTransparency = Theme.InputValueBackground or Theme.InputFieldTransparency
						end
						if Child.BackgroundTransparency < 1 then
							Child.BackgroundColor3 = Theme.Foreground
						end
						if Child.PlaceholderText and Child.PlaceholderText ~= "" then
							Child.PlaceholderColor3 = Theme.TextSecondary
						end
					else
						if not name:find("Result_") then
							Child.TextColor3 = Theme.TextPrimary
						end
					end
				end

				-- Image styling
				if cn == "ImageLabel" or cn == "ImageButton" then
					if not ExcludedImageNames[name] then
						Child.ImageColor3 = Theme.TextSecondary
					end
				end

				-- Component styling (any GuiObject with a name in our style table)
				if Child:IsA("GuiObject") and Child.BackgroundTransparency < 1 then
					local Style = ComponentStyles[name]
					if Style then
						if type(Style) == "function" then
							Style(Child)
						elseif cn == "ImageButton" and ToggleImageNames[name] then
							Child.ImageColor3 = Style
						else
							Child.BackgroundColor3 = Style
						end
					end
				end
			end

			-- Background gradients (separate filter, separate target — keep its own check)
			if GradientEnabled and name == "Background" and Child:IsA("GuiObject") then
				local Gradient = Child:FindFirstChild("UIGradient")
				if not Gradient then
					Gradient = Instance.new("UIGradient")
					Gradient.Parent = Child
				end
				Gradient.Color = ColorSequence.new(GradientColors)
				Gradient.Rotation = GradientRotation
			end
		end
	end

	function WindowFunctions:ApplyTheme(ThemeName)
		-- Route through GetTheme so aliases (e.g. Glass -> Cherry) apply to the
		-- actual rendered colours, not just GetCurrentThemeAttribute lookups.
		local Theme = self:GetTheme(ThemeName)
		CurrentTheme = ThemeName

		local Base = WaveLibraryUI:FindFirstChild("Base")
		if not Base then
			return false
		end

		Base.BackgroundColor3 = Theme.Background
		Base.BackgroundTransparency = Theme.BackgroundTransparency

		if not Subtitle:GetAttribute("CustomSubtitle") then
			local ApplySubtitle = "Build - " .. Utility:CheckHubStatus(WindowFunctions:GetCurrentThemeAttribute("AccentPrimary")) .. " | " .. GameLoading
			Subtitle.Text = ApplySubtitle
		end

		local BaseUIStroke = Base:FindFirstChild("BaseUIStroke")
		if BaseUIStroke then
			BaseUIStroke.Transparency = Theme.StrokeTransparency
			BaseUIStroke.Color = Theme.BorderColor
			BaseUIStroke.Thickness = Theme.StrokeThickness
		end

		local BaseUICorner = Base:FindFirstChild("BaseUICorner")
		if BaseUICorner then
			BaseUICorner.CornerRadius = UDim.new(0, Theme.CornerRadius)
		end

		-- Single walk replaces 6 prior Base passes (UICorners + UIStrokes +
		-- Scrollbar + Text + Image + Component + Gradient). Roughly 6x fewer
		-- GetDescendants allocations and per-element ancestor checks at boot.
		self:ApplyDescendantStyling(Base, Theme)
		self:ApplyControlButtons(Theme)
		self:ApplyWallpaper(Base, Theme)
		self:ApplyShadows(Theme)
		self:ApplyShadowGradients(Theme)

		-- Sub-section property pokes only — their descendants are children of
		-- Base, so the single walk above already covered them. (Removing the
		-- 4-per-section recursive Apply* calls = 16 redundant tree walks gone.)
		local Sidebar = Base:FindFirstChild("Sidebar")
		if Sidebar then
			Sidebar.BackgroundColor3 = Theme.SidebarColor
			Sidebar.BackgroundTransparency = Theme.SidebarTransparency
		end

		local Content = Base:FindFirstChild("Content")
		if Content then
			-- UIGradient walk on Content's subtree, separate filter from the
			-- background-gradient pass above, so keep it as its own call.
			self:ApplyPremiumGradients(Content, Theme)

			local ElementsScrolling = Content:FindFirstChild("Elements") and Content.Elements:FindFirstChild("ElementsScrolling")
			if ElementsScrolling and ElementsScrolling:FindFirstChild("Middle") then
				local GameCards = ElementsScrolling:FindFirstChild("Middle")
				self:ApplyMenuGameCards(GameCards, Theme)
			end
		end

		local BottomBar = Base:FindFirstChild("BottomBar")
		if BottomBar then
			BottomBar.BackgroundColor3 = Theme.Background
			BottomBar.BackgroundTransparency = Theme.BackgroundTransparency
		end

		local Terminal = Base:FindFirstChild("Terminal")
		if Terminal then
			Terminal.BackgroundColor3 = Theme.Background
			-- Keep the console solid (no see-through) while still following the
			-- theme colour; it sits over the un-covered screen edge.
			Terminal.BackgroundTransparency = 0
		end

		-- Top-right status bar (sibling of Base in WaveLibraryUI). FPS dot keeps
		-- its own health colour; everything else follows the theme.
		local StatusBar = WaveLibraryUI:FindFirstChild("WaveStatusBar")
		if StatusBar then
			StatusBar.BackgroundColor3 = Theme.Background
			StatusBar.BackgroundTransparency = 0
			local SBStroke = StatusBar:FindFirstChild("StatusStroke")
			if SBStroke then
				SBStroke.Color = Theme.BorderColor
				SBStroke.Transparency = math.clamp(Theme.StrokeTransparency or 0.85, 0.55, 0.92)
			end
			for _, Element in ipairs(StatusBar:GetDescendants()) do
				if Element.Name == "StatusValue" then
					Element.TextColor3 = Theme.HeaderColor or Theme.TextPrimary
				elseif Element.Name == "StatusMuted" then
					Element.TextColor3 = Theme.TextSecondary
				elseif Element.Name == "StatusDivider" then
					Element.BackgroundColor3 = Theme.BorderColor
				elseif Element.Name == "StatusChevron" then
					Element.ImageColor3 = Theme.TextSecondary
				elseif Element.Name == "StatusEyeIcon" then
					Element.ImageColor3 = Theme.TextSecondary
				end
			end
		end

		-- Server browser panel (slide-out, sibling of Base): re-skin to the active theme.
		if self.ServerBrowser and self.ServerBrowser.Theme then
			pcall(function()
				self.ServerBrowser:Theme()
			end)
		end

		-- Dialog subtrees are children of Base; the single-walk above already
		-- restyled their UICorners / Strokes / Text / Component children, so
		-- no separate Dialog walks are needed.

		if ThemeName ~= "Custom" then
			pcall(function()
				EnsureThemeFoldersExist()
				writefile(GetThemeFilePath(), ThemeName)
			end)
		end

		return true
	end

	function WindowFunctions:ApplyCurrentTheme()
		self:ApplyTheme(self:AlreadyExistantTheme() or self:GetCurrentTheme() or "Cobalt")
	end

	function WindowFunctions:SaveTheme(ThemeName)
		ThemeName = ThemeName or "Custom"

		pcall(function()
			EnsureThemeFoldersExist()
			local ThemeData = self:ExportTheme(ThemeName)
			writefile(GetThemeFolderPath() .. "/" .. ThemeName:lower() .. ".json", ThemeData)
		end)

		return true
	end

	function WindowFunctions:LoadTheme(ThemeName)
		ThemeName = ThemeName or "Custom"

		local Success = pcall(function()
			local FilePath = GetThemeFolderPath() .. "/" .. ThemeName:lower() .. ".json"
			if isfile(FilePath) then
				local ThemeData = readfile(FilePath)
				local ImportSuccess, Message = self:ImportTheme(ThemeData, ThemeName)
				if ImportSuccess then
					self:ApplyTheme(ThemeName)
					return true
				end
			end
		end)

		return Success
	end

	function WindowFunctions:BackupThemes()
		pcall(function()
			EnsureFolderExists(GetBackupFolderPath())

			local BackupData = {
				Timestamp = os.time(),
				Themes = Themes,
				Version = "2.0"
			}

			local BackupJSON = Services.HttpService:JSONEncode(BackupData)
			local BackupName = "theme_backup_" .. os.date("%Y%m%d_%H%M%S") .. ".json"
			writefile(GetBackupFolderPath() .. "/" .. BackupName, BackupJSON)
		end)

		return true
	end

	function WindowFunctions:RestoreThemes()
		local Success = pcall(function()
			local BackupFolder = GetBackupFolderPath()
			if isfolder(BackupFolder) then
				local BackupFiles = listfiles(BackupFolder)
				if #BackupFiles > 0 then
					local LatestBackup = BackupFiles[#BackupFiles]
					local BackupData = readfile(LatestBackup)
					local DecodedBackup = Services.HttpService:JSONDecode(BackupData)
					Themes = DecodedBackup.Themes
					return true
				end
			end
		end)

		return Success
	end

	function WindowFunctions:LoadStartupTheme()
		pcall(function()
			local ThemeFile = GetThemeFilePath()

			if isfile(ThemeFile) then
				local SavedTheme = readfile(ThemeFile)
				for ThemeName, _ in pairs(Themes) do
					if ThemeName == SavedTheme then
						self:ApplyTheme(SavedTheme)
						break
					end
				end
			end
		end)
	end

	function TabFunctions:InsertThemeSettings(Side)
        local SettingsSection = TabFunctions:Section({Side = Side})
        
        SettingsSection:Header({Name = "Theme Settings"})
        
        local ThemeNames = WindowFunctions:GetThemeNames()
        
        local ThemeDropdown = SettingsSection:Dropdown({
            Name = "Theme Preset",
			IgnoreConfig = true,
            Multi = false,
            Required = true,
            Search = true,
            Premium = true,
            Options = ThemeNames,
            Default = "Default",
            Callback = function(ThemeName)
				WindowFunctions:ApplyTheme(ThemeName)
            end
        }, "ThemeSelector")
        
        SettingsSection:Divider()
        SettingsSection:Header({Name = "Theme Customization"})
        
        local function SwitchToCustomTheme()
            if WindowFunctions:GetCurrentTheme() ~= "Custom" then
                ThemeDropdown:UpdateSelection("Custom")
            end
        end
        
        local function CreateCategoryDropdown()
            return SettingsSection:Dropdown({
                Name = "Customization Category",
				IgnoreConfig = true,
                Multi = false,
                Required = true,
                Options = {"Colors", "Layout", "Effects", "Typography", "Advanced", "ImportExport"},
                Default = "Colors",
                Callback = function(Category)
                    for Flag, Object in pairs(WindowFunctions:ReturnFeatures()) do
                        if type(Flag) == "string" and Object.SetVisibility and Flag:find("Custom_") then
                            local CategoryPrefix = "Custom_" .. Category
                            Object:SetVisibility(Flag:find(CategoryPrefix) ~= nil)
                        end
                    end
                end
            }, "ThemeCustomizationTab")
        end
        
        local function CreateColorPicker(Name, ThemeKey, Flag)
            return SettingsSection:ColorPicker({
                Name = Name,
				IgnoreConfig = true,
                Default = Themes.Default[ThemeKey],
                Callback = function(Color)
                    SwitchToCustomTheme()
                    Themes.Custom[ThemeKey] = Color
                    WindowFunctions:ApplyTheme("Custom")
                end
            }, Flag):SetVisibility(false)
        end
        
        local function CreateLayoutSlider(Name, ThemeKey, Min, Max, DisplayMethod, Flag)
            return SettingsSection:Slider({
                Name = Name,
                Default = Themes.Default[ThemeKey],
				IgnoreConfig = true,
                Minimum = Min,
                Maximum = Max,
                DisplayMethod = DisplayMethod,
                Callback = function(Value)
                    SwitchToCustomTheme()
                    Themes.Custom[ThemeKey] = Value
                    WindowFunctions:ApplyTheme("Custom")
                end
            }, Flag):SetVisibility(false)
        end
        
        local function CreateEffectSlider(Name, ThemeKey, Min, Max, DisplayMethod, Flag)
            return CreateLayoutSlider(Name, ThemeKey, Min, Max, DisplayMethod, Flag)
        end
        
        local function CreateToggle(Name, ThemeKey, Flag, ApplyTheme)
            return SettingsSection:Toggle({
                Name = Name,
				IgnoreConfig = true,
				IgnoreDefault = true,
                Default = Themes.Default[ThemeKey],
                Callback = function(Value)
                    if ApplyTheme then
                        SwitchToCustomTheme()
                    end
                    Themes.Custom[ThemeKey] = Value
                    if ApplyTheme then
                        WindowFunctions:ApplyTheme("Custom")
                    end
                end
            }, Flag):SetVisibility(false)
        end
        
        local function CreateDropdown(Name, ThemeKey, Options, Flag)
            return SettingsSection:Dropdown({
                Name = Name,
                Multi = false,
                Required = true,
                Options = Options,
                Default = Themes.Default[ThemeKey],
				IgnoreConfig = true,
                Callback = function(Value)
                    SwitchToCustomTheme()
                    Themes.Custom[ThemeKey] = Value
                    WindowFunctions:ApplyTheme("Custom")
                end
            }, Flag):SetVisibility(false)
        end
        
        local CategoryTabs = CreateCategoryDropdown()
        
        local ColorPickers = {
            Background = CreateColorPicker("Background Color", "Background", "Custom_Colors_Background"),
            Foreground = CreateColorPicker("Foreground Color", "Foreground", "Custom_Colors_Foreground"),
            Surface = CreateColorPicker("Surface Color", "Surface", "Custom_Colors_Surface"),
            TextPrimary = CreateColorPicker("Primary Text Color", "TextPrimary", "Custom_Colors_TextPrimary"),
            TextSecondary = CreateColorPicker("Secondary Text Color", "TextSecondary", "Custom_Colors_TextSecondary"),
            TextDisabled = CreateColorPicker("Disabled Text Color", "TextDisabled", "Custom_Colors_TextDisabled"),
            AccentPrimary = CreateColorPicker("Primary Accent Color", "AccentPrimary", "Custom_Colors_AccentPrimary"),
            AccentSecondary = CreateColorPicker("Secondary Accent Color", "AccentSecondary", "Custom_Colors_AccentSecondary"),
            AccentTertiary = CreateColorPicker("Tertiary Accent Color", "AccentTertiary", "Custom_Colors_AccentTertiary"),
            SuccessColor = CreateColorPicker("Success Color", "SuccessColor", "Custom_Colors_SuccessColor"),
            WarningColor = CreateColorPicker("Warning Color", "WarningColor", "Custom_Colors_WarningColor"),
            ErrorColor = CreateColorPicker("Error Color", "ErrorColor", "Custom_Colors_ErrorColor"),
            InfoColor = CreateColorPicker("Info Color", "InfoColor", "Custom_Colors_InfoColor"),
            ShadowColor = CreateColorPicker("Shadow Color", "ShadowColor", "Custom_Colors_ShadowColor"),
            HeaderColor = CreateColorPicker("Header Color", "HeaderColor", "Custom_Colors_HeaderColor"),
            SidebarColor = CreateColorPicker("Sidebar Color", "SidebarColor", "Custom_Colors_SidebarColor"),
            BorderColor = CreateColorPicker("Border Color", "BorderColor", "Custom_Colors_BorderColor"),
            NotificationColor = CreateColorPicker("Notification Color", "NotificationColor", "Custom_Colors_NotificationColor"),
            StatusColor = CreateColorPicker("Status Color", "StatusColor", "Custom_Colors_StatusColor"),
            DialogColor = CreateColorPicker("Dialog Color", "DialogColor", "Custom_Colors_DialogColor"),
            ButtonColor = CreateColorPicker("Button Color", "ButtonColor", "Custom_Colors_ButtonColor"),
            ToggleColor = CreateColorPicker("Toggle Color", "ToggleColor", "Custom_Colors_ToggleColor"),
            TogglerHeadColor = CreateColorPicker("Toggle Head Color", "TogglerHeadColor", "Custom_Colors_TogglerHeadColor"),
            SliderColor = CreateColorPicker("Slider Color", "SliderColor", "Custom_Colors_SliderColor"),
            SliderHeadColor = CreateColorPicker("Slider Head Color", "SliderHeadColor", "Custom_Colors_SliderHeadColor"),
            DropdownColor = CreateColorPicker("Dropdown Color", "DropdownColor", "Custom_Colors_DropdownColor"),
            InputFieldColor = CreateColorPicker("Input Field Color", "InputFieldColor", "Custom_Colors_InputFieldColor"),
            ScrollbarColor = CreateColorPicker("Scrollbar Color", "ScrollbarColor", "Custom_Colors_ScrollbarColor"),
            SelectionColor = CreateColorPicker("Selection Color", "SelectionColor", "Custom_Colors_SelectionColor"),
            HoverColor = CreateColorPicker("Hover Color", "HoverColor", "Custom_Colors_HoverColor"),
            ActiveColor = CreateColorPicker("Active Color", "ActiveColor", "Custom_Colors_ActiveColor"),
            FocusColor = CreateColorPicker("Focus Color", "FocusColor", "Custom_Colors_FocusColor"),
            DisabledOverlay = CreateColorPicker("Disabled Overlay Color", "DisabledOverlay", "Custom_Colors_DisabledOverlay"),
            ParticleColor = CreateColorPicker("Particle Color", "ParticleColor", "Custom_Colors_ParticleColor"),
            MinimizeColor = CreateColorPicker("Minimize Button Color", "MinimizeColor", "Custom_Colors_MinimizeColor"),
            ExitColor = CreateColorPicker("Exit Button Color", "ExitColor", "Custom_Colors_ExitColor")
        }
        
        local LayoutSliders = {
            CornerRadius = CreateLayoutSlider("Corner Radius", "CornerRadius", 0, 25, "Round", "Custom_Layout_CornerRadius"),
            BackgroundTransparency = CreateLayoutSlider("Background Transparency", "BackgroundTransparency", 0, 1, "Hundredths", "Custom_Layout_BackgroundTransparency"),
            SurfaceTransparency = CreateLayoutSlider("Surface Transparency", "SurfaceTransparency", 0, 1, "Hundredths", "Custom_Layout_SurfaceTransparency"),
            StrokeTransparency = CreateLayoutSlider("Stroke Transparency", "StrokeTransparency", 0, 1, "Hundredths", "Custom_Layout_StrokeTransparency"),
            StrokeThickness = CreateLayoutSlider("Stroke Thickness", "StrokeThickness", 0, 5, "Round", "Custom_Layout_StrokeThickness"),
            HeaderTransparency = CreateLayoutSlider("Header Transparency", "HeaderTransparency", 0, 1, "Hundredths", "Custom_Layout_HeaderTransparency"),
            SidebarTransparency = CreateLayoutSlider("Sidebar Transparency", "SidebarTransparency", 0, 1, "Hundredths", "Custom_Layout_SidebarTransparency"),
            InputFieldTransparency = CreateLayoutSlider("Input Field Transparency", "InputFieldTransparency", 0, 1, "Hundredths", "Custom_Layout_InputFieldTransparency"),
            ScrollbarTransparency = CreateLayoutSlider("Scrollbar Transparency", "ScrollbarTransparency", 0, 1, "Hundredths", "Custom_Layout_ScrollbarTransparency"),
            HoverTransparency = CreateLayoutSlider("Hover Transparency", "HoverTransparency", 0, 1, "Hundredths", "Custom_Layout_HoverTransparency"),
            DisabledTransparency = CreateLayoutSlider("Disabled Transparency", "DisabledTransparency", 0, 1, "Hundredths", "Custom_Layout_DisabledTransparency"),
            WallpaperTransparency = CreateLayoutSlider("Wallpaper Transparency", "WallpaperTransparency", 0, 1, "Hundredths", "Custom_Layout_WallpaperTransparency")
        }
        
        local EffectsSliders = {
            ShadowTransparency = CreateEffectSlider("Shadow Transparency", "ShadowTransparency", 0, 1, "Hundredths", "Custom_Effects_ShadowTransparency"),
            GlowTransparency = CreateEffectSlider("Glow Transparency", "GlowTransparency", 0, 1, "Hundredths", "Custom_Effects_GlowTransparency"),
            ShadowSize = CreateEffectSlider("Shadow Size", "ShadowSize", 0, 50, "Round", "Custom_Effects_ShadowSize"),
            GlowSize = CreateEffectSlider("Glow Size", "GlowSize", 0, 50, "Round", "Custom_Effects_GlowSize"),
