end
end

R["Wave/UserInterface/Imports/Terminal/TerminalModule.lua"] = function(...)
local TerminalModule = {}
TerminalModule.__index = TerminalModule

local TerminalConstants = {
	DefaultWidth = 0.375,
	MinWidth = 250,
	MaxWidth = 1920,
	SnapRange = 20,
	ToggleDebounceTime = 0.3,
	FadeOutDelay = 0.2,
	MessageGroupingWindow = 2,
	LogTextSize = 13,
	HeaderTextSize = 18,
	IconSize = 15,
	ContextMenuWidth = 160,
	ContextMenuHeight = 90,
	ContextMenuItemHeight = 30,
	DividerThickness = 1,
	CornerRadius = 10,
	ContentTopOffset = 80,
	ScrollBarThickness = 1
}

local TweenSettings = {
	DefaultTransparency = 0.9,
	HoverTransparency = 0.85,
	ActiveTransparency = 0,
	EasingStyle = Enum.EasingStyle.Sine
}

local OutputSettings = {
	ShowTimestamps = true,
	ShowIcons = true,
	SupportTables = true,
	AutoScroll = true,
	MaxTableDepth = 3,
	TruncateStrings = 50,
	MaxTableSize = 100,
	MaxLogEntries = 100
}

function TerminalModule.new(Parent, TopbarFolder, WaveLibrary, WaveLibraryUI, WindowFunctions)
	local self = setmetatable({}, TerminalModule)
	
	self.ResizingOutput = false
	self.DefaultOutputWidth = 0
	self.InitialMouseX = 0
	self.InitialOutputWidth = 0
	self.InitialLeftEdge = 0
	self.TerminalOffset = 0
	self.ToggleDebounce = false
	self.PrintLogs = true
	self.LastMessage = nil
	self.LastMessageCount = 0
	self.LastOutputResult = nil
	self.LastMessageTime = 0
	
	self:CreateUI(Parent, TopbarFolder, WaveLibrary, WaveLibraryUI)
	self:SetupEventHandlers(WindowFunctions)
	self:InitializeLogging(WindowFunctions)
	
	return self
end

function TerminalModule:CreateUI(Parent, TopbarFolder, WaveLibrary, WaveLibraryUI)
	self.Terminal = self:CreateTerminalFrame(Parent, WaveLibrary)
	self.ShadowContainer = self:CreateShadow(Parent, WaveLibrary, WaveLibraryUI)
	self.OutputTab = self:CreateOutputTab()
	self.OutputTabDivider = self:CreateDivider(UDim2.new(0.5, 0, 0, 42.5), UDim2.new(0, 48, 0, 1), 0.5)
	self.ClearLogsButton = self:CreateIconButton("ClearLogsIcon", Assets.IconClearLogs, UDim2.fromScale(0.935, 0.05))
	self.StopLogsButton = self:CreateIconButton("StopLogsIcon", Assets.IconStopLogs, UDim2.fromScale(0.85, 0.05))
	self.DividerInteract = self:CreateDividerInteract()
	self.OutputContent = self:CreateScrollingFrame()
	self.OutputWallpaper = self:CreateWallpaper()
	self.OutputUIScale = self:CreateUIScale()
	self.OutputUICorner = self:CreateUICorner()
	self.OutputUIStroke = self:CreateUIStroke()
	self.OutputDivider = self:CreateDivider(UDim2.new(0, 0, 0, 63), UDim2.new(1, 0, 0, 1), 0)
	self.OutputUIListLayout = self:CreateListLayout()
	self.OutputIcon = self:CreateTopbarIcon(TopbarFolder)
	self.OutputInteract = self:CreateTopbarInteract()
	
	self.DefaultOutputWidth = self.Terminal.AbsoluteSize.X
end

-- Docks an optimized model viewport inside the terminal panel. Returns the
-- viewport handle (SetModel / Clear / GetCamera / SetAutoRotate / ...).
function TerminalModule:CreateModelViewport(Options)
	Options = Options or {}

	if self.ModelViewport then
		if Options.Model or Options.Object then
			self.ModelViewport:SetModel(Options.Model or Options.Object)
		end
		self.ModelViewport:SetVisible(true)
		return self.ModelViewport
	end

	local BuildViewport = Utility:LoadFile("Wave/UserInterface/Imports/Terminal/ViewportEngine.lua")
	if not BuildViewport then
		return nil
	end

	local Holder = Instance.new("Frame")
	Holder.Name = "TerminalModelViewport"
	Holder.BackgroundTransparency = 1

	if Options.Inline == false then
		-- overlay the whole content area
		Holder.Position = UDim2.new(0, 14, 0, 74)
		Holder.Size = UDim2.new(1, -28, 1, -88)
		Holder.ZIndex = 12
		Holder.Parent = self.Terminal
	else
		-- flow inline with the logs, so log lines appear above and below it
		Holder.Size = UDim2.new(1, -40, 0, Options.Height or 190)
		Holder.LayoutOrder = Options.LayoutOrder or 0
		Holder.Parent = self.OutputContent
	end

	self.ModelViewport = BuildViewport(Holder, Options)
	return self.ModelViewport
end

function TerminalModule:HideModelViewport()
	if self.ModelViewport then
		self.ModelViewport:SetVisible(false)
	end
end

function TerminalModule:CreateTerminalFrame(Parent, WaveLibrary)
	local Terminal = Instance.new("Frame")
	Terminal.Name = "Terminal"
	Terminal.AnchorPoint = Vector2.new(0.5, 0.5)
	Terminal.Size = UDim2.new(TerminalConstants.DefaultWidth, 0, 1, 0)
	Terminal.Position = Utility:SaveOpened() and UDim2.new(1.2, 0, 0.5, 0) or UDim2.new(1, 0, 0.5, 0)
	Terminal.BackgroundColor3 = Color3.fromRGB(15, 15, 15)
	-- Solid: the terminal sits over the screen edge and is mostly empty, so any
	-- see-through reads as washed-out. The theme sets the real colour later.
	Terminal.BackgroundTransparency = 0
	Terminal.BorderColor3 = Color3.fromRGB(0, 0, 0)
	Terminal.BorderSizePixel = 0
	Terminal.Parent = Parent
	Terminal.ZIndex = -5
	Terminal.Visible = Utility:SaveOpened()
	
	return Terminal
end

function TerminalModule:CreateShadow(Base, WaveLibrary, WaveLibraryUI)
	-- Same glow as the main window (registered in Maid.Shadows, so its
	-- transparency follows the theme via WindowFunctions:ApplyShadows).
	return WaveLibrary:CreateShadow({
		Object = WaveLibraryUI,
		ReplicateVisible = {Base, self.Terminal},
		ObjectReplication = self.Terminal,
		Gradient = {
			Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, Color3.new(0, 0, 0.2)),
				ColorSequenceKeypoint.new(1, Color3.new(0.4, 0.6, 1))
			})
		}
	})
end

