-- =====================================================================
--  Bootstrap: stand up the globals + loaders Wave expects
-- =====================================================================
local genv = (getgenv and getgenv()) or _G

-- Services first (Utility references the Services global).
genv.Services = R["Wave/Modules/Services.lua"]()

-- Utility, then repoint its file loaders at the Registry.
genv.Utility = R["Wave/Modules/Utility.lua"]()

local function StripHub(File)
	if type(File) ~= "string" then return File end
	File = File:gsub("\\", "/")
	File = File:gsub("^Wave%-Hub/", "")
	return File
end

function genv.Utility:LoadFile(File, _Param)
	local key = StripHub(File)
	local mod = R[key]
	if not mod then
		warn("[WaveFluent] module not in bundle: " .. tostring(File))
		return nil
	end
	return mod()
end

function genv.Utility:ReadFile(File)
	local key = StripHub(File)
	return R[key] and R[key] or nil
end

function genv.Utility:ListManager(Location, KeepExtension)
	local prefix = StripHub(Location)
	if prefix:sub(-1) ~= "/" then prefix = prefix .. "/" end
	local results = {}
	for key in next, R do
		if key:sub(1, #prefix) == prefix then
			local name = key:match("[^/]+$") or key
			if not KeepExtension then name = name:match("^(.*)%.") or name end
			results[name] = key
		end
	end
	return results
end

function genv.Utility:ListFiles(Location)
	local prefix = StripHub(Location)
	if prefix:sub(-1) ~= "/" then prefix = prefix .. "/" end
	local results = {}
	for key in next, R do
		if key:sub(1, #prefix) == prefix then results[#results + 1] = key end
	end
	return results
end

function genv.Utility:CheckFile(File)
	return R[StripHub(File)] ~= nil
end

-- Remaining globals Wave reads while building a window.
genv.Maid = R["Wave/Modules/Maid.lua"]().New()
pcall(function() genv.Sound = R["Wave/Modules/Sound.lua"]() end)
genv.Assets = R["Assets/UI-Icons.lua"]()

-- GUI-only preview: deliberately omit anti-cheat-facing AssetCloak hooks.

genv.HiddenMode = false
genv.SubWindows = {}
if genv.GameLoading == nil then genv.GameLoading = "Universal" end
if genv.GameData == nil then genv.GameData = {} end
pcall(function()
	if genv.VirtualInputMachine == nil then
		genv.VirtualInputMachine = Instance.new("VirtualInputManager")
	end
end)

genv.WaveUserInterface = R["Wave/UserInterface/WaveUI.lua"]()

local WaveUserInterface = genv.WaveUserInterface


-- =====================================================================
--  Fluent Renewed compatible adapter (Fluent API -> Wave backend)
-- =====================================================================
-- Fluent Renewed -> Wave adapter.
-- A 1:1-as-possible Fluent API over Wave. Supports stock Fluent Renewed AND the
-- custom fork: Window:Divider/Minimize/Maximize, Tab:Left/Right/Section, short
-- element aliases (Tab:Toggle / Section:Button), every element method
-- (:OnChanged/:SetValue/:SetTitle/:SetDesc/:Destroy/...), styled+range sliders,
-- Toggle:Keybind, every Wave theme, and full unload/close.
--
-- The packer prepends the inlined Wave UI + bootstrap; we use the globals it set.

local WaveUserInterface = WaveUserInterface or (getgenv and getgenv().WaveUserInterface)
local genv = (getgenv and getgenv()) or _G

-- Forward-declared LOCAL so every closure captures it as an upvalue.
local Library

-- Active splash-loader controller for the window currently being built.
-- Every element/tab creation calls activeSplash:bump() so the splash can tell
-- when the build has gone quiet (last element + its config value settled) and
-- reveal the UI then, instead of guessing with a fixed timer.
local activeSplash

local function warnf(...)
	warn("[WaveFluent]", ...)
end

-- Fluent passes (flag, opts) for most elements but (opts) for buttons; normalize.
local function normArgs(a, b)
	if type(a) == "table" then
		return nil, a
	end
	return a, (type(b) == "table" and b) or {}
end

local function tip(o)
	return o.Tooltip or o.Tip or o.ToolTip or o.Description
end

-- Lucide / Phosphor / Fluent icon name -> { Image, ImageRectOffset, ImageRectSize },
-- resolved once through the bundled icon sheet and cached. rbxasset / rbxthumb /
-- http / numeric ids (and nil) pass straight through.
local IconLib
local function getIconLib()
	if IconLib == nil then
		local cached = genv.__WaveIconSheet
		if cached ~= nil then
			IconLib = cached
		else
			local ok, lib = pcall(function()
				return genv.Utility and genv.Utility:LoadFile("Wave/UserInterface/Imports/Icons.lua")
			end)
			IconLib = (ok and type(lib) == "table") and lib or false
			genv.__WaveIconSheet = IconLib
		end
	end
	return IconLib or nil
end

local function resolveIcon(icon)
	if type(icon) ~= "string" or icon == "" then
		return nil
	end
	if icon:match("^%d+$") then
		return { Image = "rbxassetid://" .. icon }
	end
	if icon:match("^rbxasset") or icon:match("^rbxthumb") or icon:match("^http") then
		return { Image = icon }
	end
	local lib = getIconLib()
	if not lib then
		return nil
	end
	local data = lib[icon]
	if type(data) == "table" and data.Image then
		return { Image = data.Image, ImageRectOffset = data.ImageRectOffset, ImageRectSize = data.ImageRectSize }
	elseif type(data) == "string" then
		return { Image = data }
	end
	-- fall back to the sheet's built-in fuzzy matcher (handles close / mistyped names)
	local ok, res = pcall(function()
		local tmp = Instance.new("ImageLabel")
		lib:SetIcon(tmp, icon)
		local out = { Image = tmp.Image, ImageRectOffset = tmp.ImageRectOffset, ImageRectSize = tmp.ImageRectSize }
		tmp:Destroy()
		return out
	end)
	if ok and res and res.Image and res.Image ~= "" then
		return res
	end
	return nil
end

local MOUSE = {
	MB1 = Enum.UserInputType.MouseButton1,
	MB2 = Enum.UserInputType.MouseButton2,
	MB3 = Enum.UserInputType.MouseButton3,
	LeftMousebutton = Enum.UserInputType.MouseButton1,
	RightMousebutton = Enum.UserInputType.MouseButton2,
}
local function toKeyEnum(v)
	if typeof(v) == "EnumItem" then
		return v
	end
	if type(v) == "string" then
		if MOUSE[v] then
			return MOUSE[v]
		end
		local ok, e = pcall(function()
			return Enum.KeyCode[v]
		end)
		if ok and e then
			return e
		end
	end
	return Enum.KeyCode.Unknown
end

local CreatedAtCounter = 0
local function newStamp()
	CreatedAtCounter = CreatedAtCounter + 1
	return { CreatedAt = CreatedAtCounter }
end

-- :OnChanged registration shared by value elements.
local function attachChanged(el)
	el._changed = {}
	function el:OnChanged(fn)
		if type(fn) == "function" then
			table.insert(self._changed, fn)
			Library:SafeCallback(fn, self.Value)
		end
		return self
	end
	function el:_fireChanged(...)
		for _, fn in ipairs(self._changed) do
			Library:SafeCallback(fn, ...)
		end
	end
end

-- Generic SetTitle/SetDesc/SetVisible/Destroy delegating to the Wave element.
local function attachCommon(el)
	-- Mark build activity: each created element pushes the splash's "last
	-- loaded" timestamp forward, so the reveal waits for the genuinely last one.
	if activeSplash then activeSplash:bump() end
	local wave = el._wave
	function el:SetTitle(text)
		pcall(function()
			if wave.UpdateName then
				wave:UpdateName(text)
			elseif wave.UpdateHeader then
				wave:UpdateHeader(text)
			end
		end)
		return self
	end
	el.SetName = el.SetTitle
	function el:SetDesc(text)
		self.Description = text
		pcall(function()
			if wave.SetToolTip then
				wave:SetToolTip(text)
			end
		end)
		return self
	end
	el.SetDescription = el.SetDesc
	function el:SetVisible(state)
		pcall(function()
			if wave.SetVisibility then
				wave:SetVisibility(state ~= false)
			end
		end)
		return self
	end
	el.SetVisibility = el.SetVisible
	function el:Destroy()
		pcall(function()
			if wave.Destroy then
				wave:Destroy()
			elseif wave.Remove then
				wave:Remove()
			end
		end)
		if self.Flag and Library.Options[self.Flag] == self then
			Library.Options[self.Flag] = nil
		end
	end
	el.Remove = el.Destroy
	return el
end

-- Dual signal: supports Sig:Connect(fn) AND Lib:OnUnload(fn) call forms.
-- Splash loader shown the instant CreateWindow is called. A small spinning
-- ring + "Loading…" caption fade in over a dimmed backdrop while the heavy
-- Wave window build runs synchronously underneath (RenderStepped keeps
-- ticking during script execution, so the ring keeps animating during the
-- freeze). When the build finishes and Wave's reveal kicks in, the splash
-- fades out so the two animations overlap and the window feels like it's
-- materialising out of the loader rather than popping into view.
--
-- Two-call API: build immediately, hide() runs the exit tween + destroys.
local function buildSplashLoader()
	local Players = game:GetService("Players")
	local TS = game:GetService("TweenService")

	local parentHost
	local ok, host = pcall(function() return gethui and gethui() end)
	if ok and host then
		parentHost = host
	else
		local lp = Players.LocalPlayer
		parentHost = (lp and lp:FindFirstChildOfClass("PlayerGui")) or game:GetService("CoreGui")
	end

	local gui = Instance.new("ScreenGui")
	gui.Name = "WaveSplash"
	gui.ResetOnSpawn = false
	gui.IgnoreGuiInset = true
	gui.DisplayOrder = 250 -- above the Wave window so it covers the reveal
	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	pcall(function() gui.Parent = parentHost end)

	local Backdrop = Instance.new("Frame")
	Backdrop.Name = "Backdrop"
	Backdrop.Size = UDim2.fromScale(1, 1)
	Backdrop.BackgroundColor3 = Color3.fromRGB(8, 8, 12)
	Backdrop.BackgroundTransparency = 1 -- fades in
	Backdrop.BorderSizePixel = 0
	Backdrop.Parent = gui

	-- 72px centred container holds the spinning ring + dot
	local Container = Instance.new("Frame")
	Container.AnchorPoint = Vector2.new(0.5, 0.5)
	Container.Position = UDim2.fromScale(0.5, 0.5)
	Container.Size = UDim2.fromOffset(72, 72)
	Container.BackgroundTransparency = 1
	Container.Parent = Backdrop

	-- Static faint background ring
	local Ring = Instance.new("Frame")
	Ring.Size = UDim2.fromScale(1, 1)
	Ring.BackgroundTransparency = 1
	Ring.Parent = Container
	local RingCorner = Instance.new("UICorner")
	RingCorner.CornerRadius = UDim.new(1, 0)
	RingCorner.Parent = Ring
	local RingStroke = Instance.new("UIStroke")
	RingStroke.Thickness = 3
	RingStroke.Color = Color3.fromRGB(255, 255, 255)
	RingStroke.Transparency = 1 -- fades to 0.82
	RingStroke.Parent = Ring

	-- Rotator with an orbiting bright dot. Rotating the Rotator's Rotation
	-- property carries the dot around the ring. Pure-frame spinner — no
	-- external asset needed, works on every executor.
	local Rotator = Instance.new("Frame")
	Rotator.AnchorPoint = Vector2.new(0.5, 0.5)
	Rotator.Position = UDim2.fromScale(0.5, 0.5)
	Rotator.Size = UDim2.fromScale(1, 1)
	Rotator.BackgroundTransparency = 1
	Rotator.Parent = Container

	local Dot = Instance.new("Frame")
	Dot.AnchorPoint = Vector2.new(0.5, 0.5)
	Dot.Position = UDim2.new(0.5, 0, 0, 0) -- top centre
	Dot.Size = UDim2.fromOffset(10, 10)
	Dot.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
	Dot.BackgroundTransparency = 1 -- fades in
	Dot.Parent = Rotator
	local DotCorner = Instance.new("UICorner")
	DotCorner.CornerRadius = UDim.new(1, 0)
	DotCorner.Parent = Dot
	-- Subtle bloom around the dot so it reads as the head of an arc trail.
	local DotGlow = Instance.new("UIStroke")
	DotGlow.Thickness = 2
	DotGlow.Color = Color3.fromRGB(160, 195, 255)
	DotGlow.Transparency = 1
	DotGlow.Parent = Dot

	-- "Loading…" caption with a soft typewriter tail.
	local Caption = Instance.new("TextLabel")
	Caption.AnchorPoint = Vector2.new(0.5, 0)
	Caption.Position = UDim2.new(0.5, 0, 0.5, 50)
	Caption.Size = UDim2.fromOffset(160, 18)
	Caption.BackgroundTransparency = 1
	Caption.Text = "Loading"
	Caption.TextColor3 = Color3.fromRGB(235, 240, 250)
	Caption.TextTransparency = 1
	Caption.TextSize = 13
	Caption.Font = Enum.Font.GothamMedium
	Caption.Parent = Backdrop

	-- Animate the ring spin (one full turn per 0.95s, linear, infinite).
	local spinAlive = true
	task.spawn(function()
		while spinAlive and Rotator.Parent do
			local tween = TS:Create(Rotator, TweenInfo.new(0.95, Enum.EasingStyle.Linear), {
				Rotation = Rotator.Rotation + 360,
			})
			tween:Play()
			tween.Completed:Wait()
		end
	end)

	-- Caption dot-cycle: "Loading" → "Loading." → "Loading.." → "Loading..."
	task.spawn(function()
		local dots = { "", ".", "..", "..." }
		local i = 1
		while spinAlive and Caption.Parent do
			Caption.Text = "Loading" .. dots[i]
			i = (i % #dots) + 1
			task.wait(0.32)
		end
	end)

	-- Fade-in.
	local fadeIn = TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
	TS:Create(Backdrop,   fadeIn, { BackgroundTransparency = 0.45 }):Play()
	TS:Create(RingStroke, fadeIn, { Transparency = 0.82 }):Play()
	TS:Create(Dot,        fadeIn, { BackgroundTransparency = 0 }):Play()
	TS:Create(DotGlow,    fadeIn, { Transparency = 0.4 }):Play()
	TS:Create(Caption,    fadeIn, { TextTransparency = 0.2 }):Play()

	-- Controller: tracks build activity so callers can reveal on "quiet",
	-- and exposes hide() for the fade-out + cleanup.
	local controller = {
		hidden = false,
		elementCount = 0,
	}
	-- os.clock is unavailable in some sandboxes; fall back to tick/0.
	local clock = (os and os.clock) or tick or function() return 0 end
	controller.lastActivity = clock()

	function controller:bump()
		self.elementCount = self.elementCount + 1
		self.lastActivity = clock()
	end

	function controller:hide()
		if self.hidden then return end
		self.hidden = true
		spinAlive = false
		local out = TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
		TS:Create(Backdrop,   out, { BackgroundTransparency = 1 }):Play()
		TS:Create(RingStroke, out, { Transparency = 1 }):Play()
		TS:Create(Dot,        out, { BackgroundTransparency = 1 }):Play()
		TS:Create(DotGlow,    out, { Transparency = 1 }):Play()
		TS:Create(Caption,    out, { TextTransparency = 1 }):Play()
		-- Subtle scale-down on the spinner as it fades.
		TS:Create(Container,  out, { Size = UDim2.fromOffset(56, 56) }):Play()
		task.delay(0.45, function() pcall(function() gui:Destroy() end) end)
	end

	-- Watch for the build to go quiet, then reveal. "Quiet" = no new element
	-- loaded for QUIET seconds AFTER at least one element exists -> the last
	-- element (and its applied config value) has settled. A hard ceiling
	-- guarantees the splash never hangs (e.g. a window with zero elements).
	function controller:watch()
		task.spawn(function()
			local QUIET = 1.0      -- gap that means "nothing else is loading"
			local MIN_SHOW = 0.35  -- keep the spinner up at least this long (no flash)
			local MAX_WAIT = 12    -- absolute safety ceiling
			local startedAt = clock()
			while not self.hidden do
				task.wait(0.05)
				local now = clock()
				local elapsed = now - startedAt
				local quietFor = now - self.lastActivity
				if elapsed >= MAX_WAIT then break end
				if elapsed >= MIN_SHOW and self.elementCount > 0 and quietFor >= QUIET then
					break
				end
			end
			-- Stop routing element bumps to this (now finished) splash.
			if activeSplash == self then activeSplash = nil end
			self:hide()
		end)
	end

	return controller
end

local function makeSignal()
	local cbs = {}
	local sig = {}
	function sig:Connect(fn)
		if type(fn) == "function" then
			table.insert(cbs, fn)
		end
		return {
			Disconnect = function()
				for i, f in ipairs(cbs) do
					if f == fn then
						table.remove(cbs, i)
						break
					end
				end
			end,
		}
	end
	sig.Once = sig.Connect
	function sig:Fire(...)
		for _, fn in ipairs(cbs) do
			if Library and Library.SafeCallback then
				Library:SafeCallback(fn, ...)
			else
				pcall(fn, ...)
			end
		end
	end
	return setmetatable(sig, {
		__call = function(_, a, ...)
			local fn = (type(a) == "function") and a or ...
			return sig:Connect(fn)
		end,
	})
end

local BASES = {
	"Button", "Toggle", "Slider", "Dropdown", "Colorpicker",
	"Keybind", "Input", "Paragraph", "Divider", "Label", "Viewport",
	"Segmented", "Stat", "Callout", "Image",
}

-- =====================================================================
--  Section facade
-- =====================================================================
local function makeSection(waveSection)
	local S = { _wave = waveSection, Type = "Section" }

	function S:CreateToggle(flag, o)
		flag, o = normArgs(flag, o)
		local el = { Type = "Toggle", Value = o.Default or o.Value or false, Flag = flag, Instance = newStamp() }
		attachChanged(el)
		local wave = waveSection:Toggle({
			Name = o.Title or o.Name or "Toggle",
			Default = o.Default or o.Value or false,
			ToolTip = tip(o),
			Callback = function(state)
				el.Value = state
				Library:SafeCallback(o.Callback, state)
				el:_fireChanged(state)
			end,
		}, flag)
		el._wave = wave
		attachCommon(el)
		function el:SetValue(v)
			pcall(function()
				wave:UpdateState(v and true or false, true)
			end)
			return self
		end
		function el:GetState()
			return el.Value
		end
		function el:Keybind(kflag, kopts)
			kopts = kopts or {}
			return S:CreateKeybind(kflag, {
				Title = kopts.Title or ((o.Title or "Toggle") .. " Bind"),
				Default = kopts.Default or kopts.Value,
				Mode = kopts.Mode or "Toggle",
				ChangedCallback = kopts.ChangedCallback,
				Callback = function()
					el:SetValue(not el.Value)
				end,
			})
		end
		if flag then
			Library.Options[flag] = el
		end
		return el
	end

	function S:CreateButton(a, b)
		local _, o = normArgs(a, b)
		local el = { Type = "Button", Instance = newStamp() }
		local wave = waveSection:Button({
			Name = o.Title or o.Name or "Button",
			ToolTip = tip(o),
			Callback = function()
				Library:SafeCallback(o.Callback or o.Func)
			end,
		})
		el._wave = wave
		el.Description = o.Description
		attachCommon(el)
		return el
	end

	function S:CreateSlider(flag, o)
		flag, o = normArgs(flag, o)
		local isRange = (o.Style == "Range") or (o.Range == true) or (type(o.Default or o.Value) == "table")

		if isRange then
			local d = type(o.Default or o.Value) == "table" and (o.Default or o.Value) or {}
			local lo = d.Min or d[1] or o.Min or 0
			local hi = d.Max or d[2] or o.Max or 100
			local el = { Type = "RangeSlider", Flag = flag, Instance = newStamp() }
			el.Value = { Min = lo, Max = hi, lo, hi }
			el.MinValue, el.MaxValue = lo, hi
			attachChanged(el)
			local wave = waveSection:RangeSlider({
				Name = o.Title or o.Name or "Range",
				ToolTip = tip(o),
				Minimum = o.Min or o.Minimum or 0,
				Maximum = o.Max or o.Maximum or 100,
				DefaultMin = lo,
				DefaultMax = hi,
				Precision = o.Rounding or o.Precision,
				Callback = function(mn, mx)
					el.Value = { Min = mn, Max = mx, mn, mx }
					el.MinValue, el.MaxValue = mn, mx
					Library:SafeCallback(o.Callback or o.Changed, el.Value)
					el:_fireChanged(el.Value)
				end,
			}, flag)
			el._wave = wave
			attachCommon(el)
			function el:SetValue(v)
				if type(v) == "table" then
					pcall(function()
						wave:UpdateRange(v.Min or v[1], v.Max or v[2])
					end)
				end
				return self
			end
			if flag then
				Library.Options[flag] = el
			end
			return el
		end

		local el = { Type = "Slider", Value = o.Default or o.Value or o.Min or 0, Flag = flag, Instance = newStamp() }
		attachChanged(el)
		local wave = waveSection:Slider({
			Name = o.Title or o.Name or "Slider",
			ToolTip = tip(o),
			Default = o.Default or o.Value,
			Minimum = o.Min or o.Minimum or 0,
			Maximum = o.Max or o.Maximum or 100,
			Precision = o.Rounding or o.Precision,
			Callback = function(v)
				el.Value = v
				Library:SafeCallback(o.Callback or o.Changed, v)
				el:_fireChanged(v)
			end,
		}, flag)
		el._wave = wave
		attachCommon(el)
		function el:SetValue(v)
			pcall(function()
				wave:UpdateValue(v)
			end)
			return self
		end
		if flag then
			Library.Options[flag] = el
		end
		return el
	end

	function S:CreateDropdown(flag, o)
		flag, o = normArgs(flag, o)
		local el = {
			Type = "Dropdown",
			Value = o.Default or o.Value,
			Flag = flag,
			Multi = o.Multi or false,
			CustomDisplayer = nil,
			Instance = newStamp(),
		}
		attachChanged(el)
		local wave = waveSection:Dropdown({
			Name = o.Title or o.Name or "Dropdown",
			ToolTip = tip(o),
			Options = o.Values or o.Options or {},
			Default = o.Default or o.Value,
			Multi = o.Multi or false,
			Required = (o.AllowNull == false) or (o.AutoDeselect == false),
			Search = o.Search or o.Searchable or false,
			Callback = function(sel)
				el.Value = sel
				Library:SafeCallback(o.Callback or o.Changed, sel)
				el:_fireChanged(sel)
			end,
		}, flag)
		el._wave = wave
		attachCommon(el)
		function el:SetValue(v)
			pcall(function()
				wave:UpdateSelection(v)
			end)
			return self
		end
		function el:SetValues(list)
			pcall(function()
				local current = {}
				for opt in next, wave:GetOptions() do
					current[#current + 1] = opt
				end
				if #current > 0 then
					wave:RemoveOptions(current)
				end
				if list and #list > 0 then
					wave:InsertOptions(list)
				end
			end)
			return self
		end
		el.SetOptions = el.SetValues
		function el:GetActiveValues()
			if el.Multi then
				local out = {}
				if type(el.Value) == "table" then
					for v, on in next, el.Value do
						if on then
							out[#out + 1] = v
						end
					end
				end
				return out
			end
			return el.Value ~= nil and 1 or 0
		end
		-- Fluent-style "fire on load": the native dropdown selects a default but only fires its
		-- Callback on user click (and skips string defaults). Applying the selection here -- during
		-- construction, while no :OnChanged handlers are registered yet -- selects the default of any
		-- type (index / string / list), resolves el.Value, and fires the options Callback once.
		-- :OnChanged handlers fire themselves on registration, so nothing double-fires.
		if (o.Default or o.Value) ~= nil then
			pcall(function()
				wave:UpdateSelection(o.Default or o.Value)
			end)
		end
		if flag then
			Library.Options[flag] = el
		end
		return el
	end

	function S:CreateColorpicker(flag, o)
		flag, o = normArgs(flag, o)
		local el = {
			Type = "Colorpicker",
			Value = o.Default or o.Value or Color3.new(1, 1, 1),
			Transparency = o.Transparency or 0,
			Flag = flag,
			Instance = newStamp(),
		}
		attachChanged(el)
		local wave = waveSection:ColorPicker({
			Name = o.Title or o.Name or "Colorpicker",
			ToolTip = tip(o),
			Default = o.Default or o.Value or Color3.new(1, 1, 1),
			Alpha = type(o.Transparency) == "number" and o.Transparency or nil,
			Callback = function(color, alpha)
				el.Value = color
				if alpha ~= nil then
					el.Transparency = alpha
				end
				Library:SafeCallback(o.Callback or o.Changed, color, alpha)
				el:_fireChanged(color, alpha)
			end,
		}, flag)
		el._wave = wave
		attachCommon(el)
		function el:SetValueRGB(color, transparency)
			pcall(function()
				wave:SetColor(color)
			end)
			if type(transparency) == "number" then
				pcall(function()
					wave:SetAlpha(transparency)
				end)
			end
			return self
		end
		-- Fork's SetValue takes HSV {Hue,Sat,Vib}; also accept a Color3.
		function el:SetValue(a, t)
			if typeof(a) == "Color3" then
				el:SetValueRGB(a, t)
			elseif type(a) == "table" then
				local h = a.Hue or a[1] or 0
				local s = a.Sat or a[2] or 0
				local v = a.Vib or a[3] or 0
				el:SetValueRGB(Color3.fromHSV(h, s, v), t)
			end
			return self
		end
		if flag then
			Library.Options[flag] = el
		end
		return el
	end

	function S:CreateKeybind(flag, o)
		flag, o = normArgs(flag, o)
		local el = {
			Type = "Keybind",
			Value = o.Default or o.Value,
			Mode = o.Mode or "Toggle",
			Toggled = false,
			Flag = flag,
			Instance = newStamp(),
			_clicks = {},
		}
		attachChanged(el)
		local function press()
			if el.Mode == "Toggle" then
				el.Toggled = not el.Toggled
			else
				el.Toggled = true
			end
			Library:SafeCallback(o.Callback, el.Toggled)
			for _, fn in ipairs(el._clicks) do
				Library:SafeCallback(fn, el.Toggled)
			end
		end
		local wave = waveSection:Keybind({
			Name = o.Title or o.Name or "Keybind",
			ToolTip = tip(o),
			Default = toKeyEnum(o.Default or o.Value),
			Callback = function()
				press()
			end,
		}, flag)
		el._wave = wave
		attachCommon(el)
		function el:GetState()
			if el.Mode == "Always" then
				return true
			end
			return el.Toggled
		end
		function el:OnClick(fn)
			if type(fn) == "function" then
				table.insert(el._clicks, fn)
			end
			return el
		end
		function el:DoClick()
			press()
			return el
		end
		function el:SetValue(key, mode)
			if mode then
				el.Mode = mode
			end
			local e = toKeyEnum(key)
			el.Value = e
			pcall(function()
				wave:Bind(e)
			end)
			Library:SafeCallback(o.ChangedCallback, e)
			el:_fireChanged(e)
			return el
		end
		function el:GetBind()
			local ok, b = pcall(function()
				return wave:GetBind()
			end)
			return (ok and b) or el.Value
		end
		if flag then
			Library.Options[flag] = el
		end
		return el
	end

	function S:CreateInput(flag, o)
		flag, o = normArgs(flag, o)
		local el = { Type = "Input", Value = o.Default or o.Value or "", Flag = flag, Instance = newStamp() }
		attachChanged(el)
		local wave = waveSection:Input({
			Name = o.Title or o.Name or "Input",
			Default = o.Default or o.Value,
			Placeholder = o.Placeholder,
			AcceptedCharacters = o.Numeric and "Numeric" or "All",
			Callback = function(text)
				el.Value = text
				Library:SafeCallback(o.Callback, text)
				el:_fireChanged(text)
			end,
		}, flag)
		el._wave = wave
		attachCommon(el)
		function el:SetValue(t)
			pcall(function()
				wave:UpdateText(tostring(t))
			end)
			return self
		end
		if flag then
			Library.Options[flag] = el
		end
		return el
	end

	function S:CreateParagraph(flag, o)
		flag, o = normArgs(flag, o)
		local el = { Type = "Paragraph", Value = o.Content or o.Body or o.Value or "", Flag = flag, Instance = newStamp() }
		attachChanged(el)
		local wave = waveSection:Paragraph({
			Header = o.Title or o.Header or "",
			Body = o.Content or o.Body or o.Value or "",
		}, flag)
		el._wave = wave
		attachCommon(el)
		function el:SetContent(text)
			el.Value = text
			pcall(function()
				wave:UpdateBody(text)
			end)
			el:_fireChanged(text)
			return self
		end
		el.SetValue = el.SetContent
		function el:SetTitle(text)
			pcall(function()
				wave:UpdateHeader(text)
			end)
			return self
		end
		if flag then
			Library.Options[flag] = el
		end
		return el
	end

	function S:CreateDivider(label)
		if type(label) == "table" then
			label = label.Title or label.Text or label.Label or label.Name
		end
		local el = { Type = "Divider" }
		el._wave = waveSection:Divider({ Text = label })
		attachCommon(el)
		return el
	end

	function S:CreateLabel(o)
		local text = type(o) == "table" and (o.Title or o.Text or o.Name) or o
		local el = { Type = "Label", _wave = waveSection:Label({ Name = text }) }
		attachCommon(el)
		return el
	end

	function S:CreateViewport(flag, o)
		flag, o = normArgs(flag, o)
		local el = { Type = "Viewport", Flag = flag, Instance = newStamp() }
		local wave = waveSection:Viewport({
			Title = o.Title or o.Name,
			Height = o.Height,
			Model = o.Model or o.Object,
			AutoRotate = o.AutoRotate,
			RotateSpeed = o.RotateSpeed,
		}, flag)
		el._wave = wave
		attachCommon(el)
		function el:SetModel(m)
			pcall(function() wave:SetModel(m) end)
			return self
		end
		function el:Clear()
			pcall(function() wave:Clear() end)
			return self
		end
		function el:GetModel()
			local ok, m = pcall(function() return wave:GetModel() end)
			return ok and m or nil
		end
		function el:SetAutoRotate(state)
			pcall(function() wave:SetAutoRotate(state) end)
			return self
		end
		function el:ResetView()
			pcall(function() wave:ResetView() end)
			return self
		end
		function el:GetCamera()
			local ok, cam = pcall(function() return wave:GetCamera() end)
			return ok and cam or nil
		end
		function el:SetCamera(cam)
			pcall(function() wave:SetCamera(cam) end)
			return self
		end
		if flag then
			Library.Options[flag] = el
		end
		return el
	end

	function S:CreateSegmented(flag, o)
		flag, o = normArgs(flag, o)
		local el = { Type = "Segmented", Value = o.Default, Flag = flag, Instance = newStamp() }
		attachChanged(el)
		local wave = waveSection:Segmented({
			Name = o.Title or o.Name,
			Options = o.Values or o.Options,
			Default = o.Default,
			Callback = function(v)
				el.Value = v
				Library:SafeCallback(o.Callback, v)
				el:_fireChanged(v)
			end,
		}, flag)
		el._wave = wave
		attachCommon(el)
		function el:SetValue(v)
			pcall(function() wave:SetValue(v) end)
			return self
		end
		if flag then
			Library.Options[flag] = el
		end
		return el
	end

	function S:CreateStat(flag, o)
		flag, o = normArgs(flag, o)
		local el = { Type = "Stat", Value = o.Value, Flag = flag, Instance = newStamp() }
		local wave = waveSection:Stat({ Title = o.Title or o.Name, Value = o.Value, Icon = o.Icon }, flag)
		el._wave = wave
		attachCommon(el)
		function el:SetValue(v)
			el.Value = v
			pcall(function() wave:SetValue(v) end)
			return self
		end
		function el:SetLabel(t)
			pcall(function() wave:SetLabel(t) end)
			return self
		end
		if flag then
			Library.Options[flag] = el
		end
		return el
	end

	function S:CreateCallout(flag, o)
		flag, o = normArgs(flag, o)
		local el = { Type = "Callout", Flag = flag, Instance = newStamp() }
		local wave = waveSection:Callout({
			Title = o.Title or o.Name,
			Content = o.Content or o.Text or o.Description,
			Style = o.Style,
		}, flag)
		el._wave = wave
		attachCommon(el)
		function el:SetContent(t)
			pcall(function() wave:SetContent(t) end)
			return self
		end
		el.SetValue = el.SetContent
		if flag then
			Library.Options[flag] = el
		end
		return el
	end

	function S:CreateImage(flag, o)
		flag, o = normArgs(flag, o)
		local image = o.Image or o.Url
		if not image and type(flag) == "string" and (flag:find("rbxasset") or flag:find("http")) then
			image, flag = flag, nil
		end
		local el = { Type = "Image", Flag = flag, Instance = newStamp() }
		local wave = waveSection:Image({
			Image = image,
			Height = o.Height,
			AspectRatio = o.AspectRatio,
			Transparency = o.Transparency,
		}, flag)
		el._wave = wave
		attachCommon(el)
		function el:SetImage(i)
			pcall(function() wave:SetImage(i) end)
			return self
		end
		el.SetValue = el.SetImage
		if flag then
			Library.Options[flag] = el
		end
		return el
	end

	-- short + Add* aliases for every element
	for _, bse in ipairs(BASES) do
		local target = "Create" .. bse
		S["Add" .. bse] = function(self, ...)
			return self[target](self, ...)
		end
		S[bse] = function(self, ...)
			return self[target](self, ...)
		end
	end
	S.CreateColorPicker = S.CreateColorpicker
	S.AddColorPicker = S.AddColorpicker
	S.ColorPicker = S.Colorpicker

	return S
end

-- =====================================================================
--  Tab facade
-- =====================================================================
local function makeTab(waveTab)
	local T = { _wave = waveTab, Type = "Tab" }
	local defaultSec, sectionCount = nil, 0

	local function sectionWith(side, title)
		local ws = waveTab:Section({ Side = side, DisplayTitle = title })
		if title and title ~= "" then
			pcall(function()
				ws:DisplayTitle()
			end)
		end
		return makeSection(ws)
	end

	local function getDefault()
		if not defaultSec then
			defaultSec = sectionWith("Left", nil)
		end
		return defaultSec
	end

	-- forward every element method to the default section
	local function fwd(name)
		return function(_, ...)
			local d = getDefault()
			return d[name](d, ...)
		end
	end
	for _, bse in ipairs(BASES) do
		T["Create" .. bse] = fwd("Create" .. bse)
		T["Add" .. bse] = fwd("Create" .. bse)
		T[bse] = fwd("Create" .. bse)
	end
	T.CreateColorPicker = T.CreateColorpicker
	T.AddColorPicker = T.CreateColorpicker
	T.ColorPicker = T.Colorpicker

	function T:Left(title)
		return sectionWith("Left", title)
	end
	T.AddLeft, T.CreateLeft = T.Left, T.Left

	function T:Right(title)
		return sectionWith("Right", title)
	end
	T.AddRight, T.CreateRight = T.Right, T.Right

	function T:Section(title)
		sectionCount = sectionCount + 1
		local side = (sectionCount % 2 == 1) and "Left" or "Right"
		return sectionWith(side, title)
	end
	T.CreateSection, T.AddSection = T.Section, T.Section

	return T
end

-- =====================================================================
--  Library
-- =====================================================================
Library = {
	Version = "Wave",
	Options = {},
	Themes = { "Cobalt" },
	Theme = "Cobalt",
	UseAcrylic = true,
	Acrylic = true,
	Transparency = true,
	Loaded = true,
	MinimizeKey = Enum.KeyCode.RightControl,
	MinimizeKeybind = nil,
	Window = nil,
	CreatedWindow = nil,
	DialogOpen = false,
}

Library.OnUnload = makeSignal()
Library.PostUnload = makeSignal()
Library.ThemeChanged = makeSignal()

-- live Unloaded flag, reads Wave's real state so ported loops stop on close
setmetatable(Library, {
	__index = function(t, k)
		if k == "Unloaded" then
			if rawget(t, "_unloaded") then
				return true
			end
			return (WaveUserInterface and WaveUserInterface.Unloaded) and true or false
		end
		return nil
	end,
})

function Library:SafeCallback(fn, ...)
	if type(fn) ~= "function" then
		return
	end
	local args = table.pack(...)
	local ok, err = pcall(function()
		return fn(table.unpack(args, 1, args.n))
	end)
	if not ok then
		warnf("callback error:", err)
	end
end

function Library:Notify(opts)
	opts = opts or {}
	local desc = opts.Content or opts.Description or ""
	if opts.SubContent and opts.SubContent ~= "" then
		desc = (desc ~= "" and (desc .. "\n") or "") .. opts.SubContent
	end
	local w = rawget(self, "_waveWindow")
	if w then
		local ok, res = pcall(function()
			return w:Notify({ Title = opts.Title or "Notification", Description = desc, Lifetime = opts.Duration })
		end)
		if ok then
			return res
		end
		warnf("Notify failed:", res)
	end
	return nil
end

function Library:SetTheme(name)
	self.Theme = name
	local w = rawget(self, "_waveWindow")
	if w then
		pcall(function()
			w:ApplyTheme(name)
		end)
	end
	self.ThemeChanged:Fire(name)
end

function Library:GetCurrentTheme()
	local w = rawget(self, "_waveWindow")
	if w then
		local ok, t = pcall(function()
			return w:GetCurrentTheme()
		end)
		if ok and t then
			return t
		end
	end
	return self.Theme
end

function Library:ToggleAcrylic(state)
	self.UseAcrylic, self.Acrylic = state, state
	local w = rawget(self, "_waveWindow")
	if w then
		pcall(function()
			w:SetAcrylicBlurState(state)
		end)
	end
end

function Library:ToggleTransparency(state)
	self.Transparency = state
end

function Library:OnUnloadCallback(fn)
	return self.OnUnload:Connect(fn)
end

function Library:Unload()
	rawset(self, "_unloaded", true)
	local w = rawget(self, "_waveWindow")
	if w then
		pcall(function()
			w:Unload()
		end)
	end
	self.OnUnload:Fire()
	self.PostUnload:Fire()
end
Library.Destroy = Library.Unload
Library.Close = Library.Unload

-- Library.Utilities — minimal versions of Fluent's helpers
Library.Utilities = {}
function Library.Utilities:Truncate(number, decimals, round)
	local factor = 10 ^ (decimals or 0)
	if round then
		return math.round(number * factor) / factor
	end
	return math.floor(number * factor) / factor
end
function Library.Utilities:Round(number, factor)
	return self:Truncate(number, factor, true)
end
function Library.Utilities:Prettify(v)
	if typeof(v) == "EnumItem" then
		return (tostring(v):gsub("Enum.%w+%.", ""):gsub("(%l)(%u)", "%1 %2"))
	elseif type(v) == "number" then
		return self:Round(v, 2)
	end
	return tostring(v)
end
function Library.Utilities:GetOS()
	return "Windows"
end
function Library.Utilities:Clone(x)
	return x, true
end
function Library.Utilities:GetIcon()
	return nil
end

function Library:CreateWindow(opts)
	opts = opts or {}
	-- Show the splash loader BEFORE the heavy Wave build runs. The single
	-- task.wait() yields exactly one frame so the splash gets a chance to
	-- render before the build freezes the main thread. RenderStepped keeps
	-- the spinner rotating throughout the freeze, so users see continuous
	-- motion instead of a stalled UI. Devs can opt out with Splash = false.
	--
	-- activeSplash is read by attachCommon (every element) so the splash knows
	-- when the build is genuinely done (config-applied last element settled),
	-- rather than revealing on a blind timer.
	local splash
	if opts.Splash ~= false then
		splash = buildSplashLoader()
		activeSplash = splash
		task.wait()
	else
		activeSplash = nil
	end
	local waveWindow = WaveUserInterface:Window({
		Title = opts.Title or "Wave",
		Subtitle = opts.SubTitle or opts.Subtitle,
		Size = opts.Size,
		DragStyle = 2,
		DisabledWindowControls = {},
		AcrylicBlur = opts.Acrylic ~= false,
		-- floating show/hide button that stays visible when minimized (opt out
		-- with ToggleButton = false in your CreateWindow options)
		ToggleButton = opts.ToggleButton ~= false,
		-- top-right status bar: live FPS + @username + game name (opt out with
		-- StatusBar = false)
		StatusBar = opts.StatusBar ~= false,
	})
	genv.WaveLibrary = waveWindow
	rawset(self, "_waveWindow", waveWindow)

	-- Start the activity watcher: the splash reveals the UI once element/config
	-- loading goes quiet (see controller:watch), so the reveal is tied to the
	-- real end of the build, not a fixed delay. The window's own reveal anim
	-- runs underneath in the meantime, so when the splash lifts the UI is
	-- already in place and the fade-out reads as a smooth reveal.
	if splash then
		splash:watch()
	end

	pcall(function()
		waveWindow.OnUnloaded(function()
			rawset(Library, "_unloaded", true)
			Library.OnUnload:Fire()
			Library.PostUnload:Fire()
			-- Defensive: if the user unloads before the splash finished
			-- (rare, but cheap to guard), kill the splash too.
			if splash then pcall(function() splash:hide() end) end
		end)
	end)

	self.UseAcrylic = opts.Acrylic ~= false
	self.Theme = opts.Theme or self.Theme
	if opts.MinimizeKey then
		self.MinimizeKey = opts.MinimizeKey
		pcall(function()
			waveWindow:SetKeybind(opts.MinimizeKey)
		end)
	end

	local W = {
		_wave = waveWindow,
		_currentGroup = waveWindow:TabGroup(),
		_tabs = {},
		_order = {},
		_themed = false,
		_pendingTheme = opts.Theme or "Cobalt", -- default theme when a script doesn't specify one
		Type = "Window",
	}
	self.CreatedWindow = W

	local function wireThemes()
		if W._themed then
			return
		end
		W._themed = true
		pcall(function()
			waveWindow:Initialize()
		end)
		pcall(function()
			local names = waveWindow:GetThemeNames()
			if type(names) == "table" and #names > 0 then
				table.sort(names)
				Library.Themes = names
			end
		end)
		if W._pendingTheme then
			pcall(function()
				waveWindow:ApplyTheme(W._pendingTheme)
			end)
		end
	end

	function W:CreateTab(tabOpts)
		tabOpts = tabOpts or {}
		local tabSettings = { Name = tabOpts.Title or "Tab" }
		local icon = resolveIcon(tabOpts.Icon)
		if icon then
			tabSettings.Image = icon.Image
			tabSettings.ImageRectOffset = icon.ImageRectOffset
			tabSettings.ImageRectSize = icon.ImageRectSize
		end
		local waveTab = W._currentGroup:Tab(tabSettings)
		local T = makeTab(waveTab)
		table.insert(W._order, waveTab)
		if tabOpts.Title then
			W._tabs[tabOpts.Title] = waveTab
		end
		if #W._order == 1 then
			pcall(function()
				waveTab:Select()
			end)
			wireThemes()
		end
		return T
	end
	W.AddTab, W.Tab = W.CreateTab, W.CreateTab

	function W:Divider(label)
		if type(label) == "table" then
			label = label.Title or label.Text or label.Label or label.Name
		end
		W._currentGroup = waveWindow:TabGroup(label)
		return W
	end
	W.AddDivider, W.CreateDivider, W.TabDivider = W.Divider, W.Divider, W.Divider

	function W:Minimize()
		pcall(function()
			waveWindow:SetWindowState(not waveWindow:GetState())
		end)
	end
	function W:Maximize()
		-- Wave has no maximize-to-viewport; best-effort no-op.
	end

	function W:Dialog(d)
		d = d or {}
		local buttons = {}
		for _, b in ipairs(d.Buttons or {}) do
			local cb = b.Callback
			buttons[#buttons + 1] = {
				Name = b.Title or b.Name or "OK",
				Callback = function()
					Library.DialogOpen = false
					Library:SafeCallback(cb)
				end,
			}
		end
		Library.DialogOpen = true
		local ok, res = pcall(function()
			return waveWindow:Dialog({
				Title = d.Title,
				Description = d.Content or d.Description,
				Buttons = buttons,
			})
		end)
		if not ok then
			Library.DialogOpen = false
			warnf("Dialog failed:", res)
		end
		return ok and res or nil
	end

	function W:Notify(n)
		return Library:Notify(n)
	end

	function W:TerminalViewport(opts)
		opts = opts or {}
		local ok, handle = pcall(function()
			return waveWindow:TerminalViewport({
				Model = opts.Model or opts.Object,
				AutoRotate = opts.AutoRotate,
				RotateSpeed = opts.RotateSpeed,
			})
		end)
		return ok and handle or nil
	end

	-- Server browser: a slide-out panel (icon left of the terminal) listing joinable servers.
	-- W:AddServer{ Image = "rbxassetid://..", Title = .., Description = .., Callback = function(card) end }
	function W:AddServer(s)
		s = s or {}
		local handle
		pcall(function()
			handle = waveWindow:AddServer({
				Image = s.Image or s.Thumbnail or s.Icon,
				Title = s.Title or s.Name,
				Description = s.Description or s.Desc or s.SubTitle or s.Subtitle,
				Callback = s.Callback or s.Join or s.OnJoin or s.Func,
			})
		end)
		return handle
	end
	W.CreateServer, W.Server = W.AddServer, W.AddServer

	function W:ClearServers()
		pcall(function()
			waveWindow:ClearServers()
		end)
		return self
	end

	function W:OnServerRefresh(fn)
		pcall(function()
			waveWindow:SetServerRefresh(fn)
		end)
		return self
	end
	W.SetServerRefresh = W.OnServerRefresh

	function W:SetServerTitle(t)
		pcall(function()
			waveWindow:SetServerTitle(t)
		end)
		return self
	end

	function W:ToggleServerBrowser(state)
		pcall(function()
			waveWindow:ToggleServerBrowser(state)
		end)
		return self
	end
	function W:OpenServerBrowser()
		return W:ToggleServerBrowser(true)
	end
	function W:CloseServerBrowser()
		return W:ToggleServerBrowser(false)
	end

	function W:SelectTab(i)
		local t
		if type(i) == "number" then
			t = W._order[i]
		elseif type(i) == "string" then
			t = W._tabs[i]
		elseif type(i) == "table" then
			t = i._wave or i
		end
		if t then
			pcall(function()
				t:Select()
			end)
		end
	end

	function W:Unload()
		return Library:Unload()
	end
	W.Destroy, W.Close = W.Unload, W.Unload

	return W
end

Library.Window = Library.CreateWindow
Library.AddWindow = Library.CreateWindow

return Library
